_IDLE_FAIL_WARN_EVERY_S = 3600.0


def _env_cooldown_s(name: str, default: int) -> int:
    """A positive whole number of seconds from the environment, else
    ``default`` (a malformed value never breaks the import)."""
    try:
        f = float(os.environ.get(name, "") or default)
        if not math.isfinite(f):          # "inf" / "1e400" raised OverflowError at import (§4LI review)
            return default
        v = int(f)
        return v if v > 0 else default
    except ValueError:
        return default


def _self_model_on(args, ctx) -> bool:
    _sm = getattr(ctx, "self_model", None)
    return _sm is not None and bool(getattr(_sm, "enabled", False))


def _workspace_model_on(args, ctx) -> bool:
    _wm = getattr(ctx, "workspace_model", None)
    return _wm is not None and bool(getattr(_wm, "enabled", False))


#: §4NN: the IDLE SCHEDULER's jobs, in tick order — what
#: `GhostAgent.biological_watchdog` / `_biological_tick` run while the owner
#: is away (those Python names are historical: the loop was called the
#: "biological daemon"). Each row is (label, operator text, "does THIS boot run
#: it?"). The label is the one `_biological_tick` appends to `_idle_ran`
#: ("memory-journal" excepted: phase 1 logs itself); a test pins that the two
#: agree, so the boot line cannot list a job that no longer exists.
IDLE_SCHEDULER_JOBS = (
    ("memory-journal", "memory-journal consolidation",
     lambda args, ctx: getattr(ctx, "journal", None) is not None),
    ("maintenance", "maintenance",
     lambda args, ctx: getattr(args, "no_dream", False) is not True),
    ("store-hygiene", "store-hygiene",
     lambda args, ctx: getattr(ctx, "skill_memory", None) is not None),
    ("tidy", "workspace tidy",
     lambda args, ctx: getattr(ctx, "project_store", None) is not None),
    ("autoadvance", "project autoadvance (autopilot projects only)",
     lambda args, ctx: (getattr(args, "autoadvance_idle", False) is True
                        and getattr(ctx, "project_store", None) is not None)),
    ("selfhood-narrative", "self narrative", _self_model_on),
    ("stale-questions", "stale open questions", _self_model_on),
    ("workspace-narrative", "workspace narrative", _workspace_model_on),
    ("failure-replay", "failure replay + regression suite (when an owner failure "
                  "or a due test exists)",
     lambda args, ctx: True),
)


def idle_scheduler_jobs(args, ctx) -> List[str]:
    """Operator text of the idle-scheduler jobs this boot runs (§4NN)."""
    out = []
    for _label, text, enabled in IDLE_SCHEDULER_JOBS:
        try:
            if enabled(args, ctx):
                out.append(text)
        except Exception:  # noqa: BLE001 — a boot line must never fail boot
            continue
    return out


#: §4PQ (operator 2026-10-16: "right now it's not clear what each does"):
#: what each idle job is FOR, said on the Idle Cycle line beside its outcome.
IDLE_JOB_PURPOSE = {
    "maintenance": ("project activity digests, file descriptions, daily store backup, "
                    "memory-graph cleanup and store consistency checks"),
    "store-hygiene": "repairs the lesson index and removes expired temporary video transcripts",
    "tidy": "deletes leftover screenshots and scratch files in project workspaces",
    "autoadvance": "one unattended step on a project you put on autopilot",
    "selfhood-narrative": "rewrites the agent's running diary",
    "stale-questions": "lists its open questions older than 3 days",
    "workspace-narrative": "rewrites the running summary of the workspace",
    "failure-replay": "replays one of your past failures or runs your regression tests",
}


def idle_cycle_line(ran, notes, idle_min: float) -> str:
    """One Idle Cycle line: per job, what it is for and what it did.
    ``ran`` holds job names (a failed job reads ``name(failed)``)."""
    parts = []
    for job in ran:
        name = str(job)
        failed = name.endswith("(failed)")
        base = name[:-len("(failed)")] if failed else name
        purpose = IDLE_JOB_PURPOSE.get(base, "")
        note = str((notes or {}).get(base) or "").strip()
        # r1 m5: the phase's warning is rate-limited (once an hour), so the
        # line points at the log, and a step that went on after a failed
        # part (autoadvance's classifier fallback) keeps its outcome
        outcome = (("had an error (see the log)" + (f"; then {note}" if note else ""))
                   if failed else note)
        text = base + (f" ({purpose})" if purpose else "")
        parts.append(text + (f": {outcome}" if outcome else ""))
    return f"idle {idle_min:.0f}m — ran " + " | ".join(parts)


def _store_hygiene_note(orphans, healed, temp_docs, failed=()) -> str:
    """The store-hygiene job's outcome in words (§4PQ)."""
    o = orphans if isinstance(orphans, int) else 0
    h = healed if isinstance(healed, int) else 0
    td = temp_docs if isinstance(temp_docs, dict) else {}
    rm, mk = list(td.get("removed") or []), list(td.get("marked") or [])
    bad = [f"{x} FAILED" for x in (failed or ())]
    if not (o or h or rm or mk):
        return "; ".join(bad) if bad else "nothing to fix"
    bits = []
    if o:
        bits.append(f"{o} orphaned lesson-index entr{'y' if o == 1 else 'ies'} dropped")
    if h:
        bits.append(f"{h} lesson(s) re-indexed")
    if rm:
        bits.append(f"{len(rm)} expired video transcript(s) removed")
    if mk:
        bits.append(f"{len(mk)} video transcript(s) marked temporary")
    return "; ".join([", ".join(bits)] + bad)


def _idle_phase_failed(agent, ran: list, phase: str, err) -> None:
    now = time.time()
    seen = getattr(agent, "_idle_fail_warned", None)
    if not isinstance(seen, dict):
        seen = agent._idle_fail_warned = {}
    if now - seen.get(phase, 0.0) >= _IDLE_FAIL_WARN_EVERY_S:
        seen[phase] = now
        logger.warning("idle phase %s failed: %s: %s", phase, type(err).__name__, err)
    else:
        logger.debug("idle phase %s failed again: %s", phase, err)
    try:
        if phase in ran:
            ran[ran.index(phase)] = f"{phase}(failed)"
        elif f"{phase}(failed)" not in ran:
            ran.append(f"{phase}(failed)")
    except Exception:  # noqa: BLE001
        pass


def _idle_anchor_path(ctx):
    md = getattr(ctx, "memory_dir", None)
    if not isinstance(md, (str, Path)) or not str(md):
        return None
    return Path(str(md)).parent / "idle_cooldowns.json"


def _sync_idle_anchors(agent, ctx) -> None:
    """Load the persisted ``_last_*_at`` anchors once (a missing/min anchor
    takes the stored time), then write them back whenever they changed.
    Never raises: a lost anchor only means one extra run."""
    path = _idle_anchor_path(ctx)
    if path is None:
        return
    try:
        if not getattr(agent, "_idle_anchors_loaded", False):
            agent._idle_anchors_loaded = True
            if path.is_file():
                for k, v in (json.loads(path.read_text()) or {}).items():
                    if isinstance(k, str) and k.startswith("_last_") and k.endswith("_at"):
                        _cur = getattr(agent, k, datetime.datetime.min)
                        _stored = datetime.datetime.fromisoformat(str(v))
                        # §4MI: a seed computed at boot must not discard a
                        # LATER persisted anchor — the later of the two is
                        # the truth
                        # r2 review: never adopt an anchor from the FUTURE
                        # (clock skew, a DST fall-back, a hand edit) — it
                        # would hold the phase for the size of the skew
                        if _stored > datetime.datetime.now() + datetime.timedelta(minutes=5):
                            continue
                        if (not isinstance(_cur, datetime.datetime)
                                or _cur == datetime.datetime.min or _stored > _cur):
                            setattr(agent, k, _stored)
        cur = {k: v.isoformat() for k, v in vars(agent).items()
               if k.startswith("_last_") and k.endswith("_at")
               and isinstance(v, datetime.datetime) and v != datetime.datetime.min}
        blob = json.dumps(cur, sort_keys=True)
        if blob != getattr(agent, "_idle_anchors_saved", None):
            tmp = path.with_suffix(".json.tmp")
            tmp.write_text(blob)
            os.replace(tmp, path)
            agent._idle_anchors_saved = blob
    except Exception as e:  # noqa: BLE001
        logger.debug("idle anchors not synced: %s", e)


def _call_mutated_world(fname: str, t_args: dict, is_mutating: bool) -> bool:
    """True when a SUCCESSFUL dispatch of this call changed state the pre-flight
    repeat-failure guard reasons about — the trigger for its world-changed
    reset (`RecentFailureGuard.note_world_changed`).

    Pure (no I/O, no self) so the predicate is unit-testable in isolation
    rather than buried in the dispatch loop. `is_mutating` alone is the wrong
    signal for `execute` (blanket-True there — every ls/grep/curl probe would
    reset the guard), so that path uses the command heuristic; script-content
    executions (no `command` arg) conservatively don't count.
    """
    if fname == "file_system":
        return bool(is_mutating)
    if fname == "manage_services":
        # Service identity/op lives across several arg keys — union them,
        # matching the tool's own arg-healing.
        op = str(t_args.get("action") or t_args.get("operation")
                 or t_args.get("op") or "").strip().lower()
        return op not in _SERVICE_READONLY_OPS
    if fname == "execute":
        return looks_mutating_command(
            str(t_args.get("command") or t_args.get("cmd") or ""))
    if fname == "manage_composed_skills":
        # ONLY the named `action` param: the tool reads no `operation`/`op`
        # alias, so honouring one here would let `operation='delete'` (which
        # the tool rejects as a missing-action error) be scored a mutation.
        return (str(t_args.get("action") or "").strip().lower()
                in _COMPOSED_SKILL_MUTATING_ACTIONS)
    return False


# Headroom reserved for the per-turn injection that `_compose_injection`
# adds to the shipped payload AFTER history pruning — tool schemas (~7-8k
# tok), hydrated playbook/memory, continuity + workspace blocks, the
# project briefing, and the scratchpad. Pruning history to the full
# `max_context` and THEN adding this overshoots the model window → HTTP 400
# → destructive emergency recovery (2026-07-20). Prune and steer against
# `max_context - this` so the assembled payload stays within budget.
_INJECTION_RESERVE_TOKENS = 24000

# Adaptive sampling profiles for coding sub-tasks. The classifier + routing
# stay wired (so per-sub-task tuning is a one-line change away), but all three
# profiles are pinned to the model-card thinking-mode values (temp=1.0, top_p=0.95,
# top_k=20; §4RG, was the Qwen3.6 coding value 0.6) — the recommended sampling for this model. The earlier spread
# (creative temp=0.8/top_k=40, precise temp=0.3/top_p=0.90/top_k=10) drifted
# coding turns off the model-card values; collapsing them to the "balanced"
# baseline keeps every coding turn on-spec while preserving the mechanism.
_CODING_TASK_PROFILES = {
    "creative":  {"temperature": 1.0, "top_p": 0.95, "top_k": 20, "min_p": 0, "presence_penalty": 0},
    "precise":   {"temperature": 1.0, "top_p": 0.95, "top_k": 20, "min_p": 0, "presence_penalty": 0},
    "balanced":  {"temperature": 1.0, "top_p": 0.95, "top_k": 20, "min_p": 0, "presence_penalty": 0},
}

_CREATIVE_KEYWORDS = {"design", "architect", "brainstorm", "creative", "alternative", "refactor", "naming", "generate", "invent"}
_PRECISE_KEYWORDS = {"sql", "query", "select", "insert", "update", "delete", "migrate", "schema", "exact", "precise", "security", "auth", "encrypt", "regex"}


class _FinalStream:
    """§4SB r6: the streamed final's drain with a close that works BEFORE its
    first step. An async generator closed before it ever ran executes no
    `finally`: a client that hung up between handle_chat's return and the
    route's first pull left the turn registered and the drained rows booked
    read with nothing answering them. `aclose()` on an unstarted stream runs
    the tail (the §4SB hand-back + the unregister); a started one closes as
    before. Iterates like the generator it wraps."""
    __slots__ = ("_gen", "_tail", "_started")

    def __init__(self, gen, tail):
        self._gen, self._tail, self._started = gen, tail, False

    def __aiter__(self):
        return self

    async def __anext__(self):
        self._started = True
        return await self._gen.__anext__()

    async def aclose(self):
        if not self._started:
            self._started = True
            try:
                self._tail()
            except Exception:  # noqa: BLE001
                pass
        await self._gen.aclose()
    # (r8: no __del__ — on the route an unstarted wrapper stays reachable through
    #  registry → turn.task → result until the route's own close ran its tail, and
    #  a finalizer taking the registry lock from a GC thread could block it; the
    #  route closes `content` explicitly: its streaming `finally` on every ending
    #  it reaches, and (r9) its tap `finally` when the turn finished untaken)


async def _stream_or_abort_frames(it):
    """Drain an SSE stream; convert a RAISE into the abort frames it should
    have been.

    ⚠ WHY (§4BV R7 lens B, fixed 2026-08-19). The FINAL-generation drain in
    `stream_wrapper` iterates `stream_chat_completion` with NO enclosing
    handler — AST-verified, not read off the indentation. Any raise there
    (`_do_stream_chat_completion` still re-raises on HTTP 4xx/5xx and on the
    generic path) skipped the ENTIRE durable tail: episode, hydration judge,
    trajectory, project work_log, verifier spawn, lesson outcomes. The client
    got routes.py's error event, but the turn vanished from every persistent
    record — the worst possible outcome for a turn that already streamed
    most of an answer.

    The fix is a conversion, not a swallow: the loop body ALREADY parses an
    upstream `{"error": …}` frame (sets `stream_aborted`, appends the
    truncation marker to the durable content, logs "Stream Aborted"), and it
    captures `data: [DONE]` to release AFTER the tail (§4AT-A). So a raise
    becomes exactly those two frames and every existing mechanism does its
    job. Cancellation is deliberately untouched — `CancelledError` and
    `GeneratorExit` are `BaseException`, and a cancelled turn must still
    cancel.

    ⚠ ONLY the final-generation site iterates through this. `handle_chat`'s
    internal drain is wrapped in a try whose handlers DEPEND on the raise —
    one of them runs the emergency context prune on a 400 mentioning
    "context". Wrapping that site would silently delete that recovery;
    `tests/test_stream_durable_tail.py` pins both directions.
    """
    try:
        async for _chunk in it:
            yield _chunk
    except Exception as _sx:                          # noqa: BLE001
        _msg = f"stream raised {type(_sx).__name__}: {str(_sx)[:200]}"
        logger.warning("final-generation stream converted a raise into an "
                       "abort frame: %s", _msg)
        yield f"data: {json.dumps({'error': _msg})}\n\n".encode("utf-8")
        yield b"data: [DONE]\n\n"


def _classify_coding_task(query: str) -> str:
    """Classify a coding task for adaptive sampling. Returns 'creative', 'precise', or 'balanced'."""
    if not query:
        return "balanced"
    words = set(query.lower().split())
    creative_hits = len(words & _CREATIVE_KEYWORDS)
    precise_hits = len(words & _PRECISE_KEYWORDS)
    if creative_hits > precise_hits and creative_hits > 0:
        return "creative"
    if precise_hits > creative_hits and precise_hits > 0:
        return "precise"
    return "balanced"


# Queries matching any of these trigger the EXTENDED thinking budget.
# Intentionally narrow: the default stays TIGHT so conversational turns
# and simple tool calls don't pay the extra token cost. Extended is for
# genuine multi-step reasoning where the anti-paralysis cap hurts more
# than it helps (see prompts.py THINK_BUDGET_EXTENDED).
_EXTENDED_THINK_KEYWORDS = {
    "debug", "debugging", "traceback", "error",
    "optimize", "optimization", "tune", "tuning",
    "algorithm", "complexity", "proof", "prove",
    "refactor", "architecture", "architect",
    "explain", "why", "analyze", "analysis",
    "sql", "query", "explain analyze", "vacuum", "cte",
    "race condition", "deadlock", "concurrency",
}


# Tools whose output is state-change confirmation (not evidence of work
# the verifier can assess). When one of these is the last tool this
# turn, the verifier's "is the claim supported by evidence" question
# degenerates to "does 'I built a parser' follow from '{exited: …}'"
# — always REFUTED. Skip or look further back.
# Defect-reopen churn brake (2026-07-18, Rick Dangerous). A DONE project
# can be reopened by a user bug report (add_task's DONE→ACTIVE semantic),
# and with --autoadvance-idle ON a reopened project immediately becomes
# advanceable — so a report/refute/reopen/advance/rollup cycle can grind
# turns indefinitely on a finished project. Cap reopens per rolling
# window; past the cap the report is surfaced LOUDLY for the operator
# instead of silently re-entering the grinder.
_DEFECT_REOPEN_CAP = 2
_DEFECT_REOPEN_WINDOW_S = 86_400.0

# Edit-churn brake (2026-07-25, req 646e9b7e): N successive successful
# mutations of the SAME file with no intervening run/render is the
# "16 blind edits before the first browser load" anti-pattern — the turn
# burned half its 40-turn budget stacking unverified patches. After
# _EDIT_CHURN_STEER_AFTER consecutive unverified edits of one target, a
# steer demands verification before further edits; execute/browser/
# manage_services success resets the counters. Bounded to
# _EDIT_CHURN_MAX_STEERS injections per request so an ignoring model
# doesn't get an ever-growing message tail. A .md/.txt target is never
# counted (§4QB-c, EDIT_CHURN_EXEMPT_SUFFIXES: prose has nothing to run).
_EDIT_CHURN_STEER_AFTER = 3
_EDIT_CHURN_MAX_STEERS = 2
_EDIT_CHURN_VERIFY_TOOLS = frozenset({
    "execute", "browser", "manage_services", "managed_services",
})

# ── Meta-task ("checklist") nudge intent detection (§4BE, 2026-08-13) ──
# The nudge tells the model "you have not fulfilled the learning/profile
# INSTRUCTIONS IN THE USER'S REQUEST". Arming it on a bare keyword made that
# sentence a LIE on every measured turn: the old test was
# `any(k in text for k in ["learn","skill","profile","lesson",…])`, so
# "Define a composed SKILL", "show me all custom SKILLS" and "what have you
# LEARNED today" all armed it. Measured on the live trajectory corpus:
# **59 of 59** real turns that armed the nudge contained NO learning
# instruction — a 100% false-positive rate — and it fired 39 times, 10 of
# them on 2026-08-12 alone.
#
# The damage is not just a wasted turn. Production trace req 32a8101d: the
# model reasoned "there's no explicit learning or profile instruction in
# their message… But the system is requiring it", called `learn_skill` to
# silence the nudge, and minted a junk lesson that vector-dedup then
# reinforced to freq=11 — i.e. the false nudge writes into the corpus that
# retrieval later injects. req 207e0702 shows the other failure mode: the
# same nudge drove a repetition loop the thinking guard had to abort.
#
# So the predicate now requires an IMPERATIVE DIRECTIVE to record something,
# not a mention of the topic. Deliberately narrow — a missed true positive
# costs one un-nudged turn (the model can still call learn_skill on its own),
# while a false positive corrupts the lesson corpus.
_META_TASK_DIRECTIVE_RE = re.compile(
    r"\b(?:"
    # Inherently MEMORY-ish verbs: "learn/remember/memorize THIS".
    # a QUESTION is not a directive ("do you remember that we discussed…")
    r"(?<!do you )(?<!can you )(?<!did you )"
    r"(?:learn|remember|memori[sz]e)\s+"
    # ⚠ THE SUBJECT DECIDES, and the first cut had it backwards (round-2
    # review NEW-3). "remember that YOU/YOUR/THE/IT …" is a constraint on
    # how to do the current task ("remember that you use TOR", "remember
    # that the sandbox has no network") — nothing to record. "remember that
    # I/my/we/our …" is a USER FACT and is exactly what the profile store
    # is for; excluding those (as the first cut did) dropped the most
    # natural genuine phrasings, e.g. "remember that I use zsh".
    # "that time" is the rhetorical "remember that time when…".
    # ⚠ ALLOWLIST, not a denylist (round-4 review). A closed list of
    # EXCLUDED subjects leaked every subject outside it — "remember that
    # TOR must be used", "remember that this repo uses ripgrep". For the
    # "remember that X" form the subject must be FIRST-PERSON, which is
    # what makes it a user fact worth recording; everything else is a task
    # constraint. ("remember this/it/the following" is unaffected.)
    r"(?:(?=that\s+(?:i|we|my|our)\b)|(?!that\b))"
    r"(?:this|that|it|the\s+following|these|from\s+this)"
    # Storage verbs are ambiguous — "save it to the knowledge base" is a
    # DOCUMENT write, not a lesson (live false positive: the youtube
    # project request said "transcribe it, save it to the knowledge base"
    # and armed the nudge). Require the destination NOT to be a data store.
    r"|(?:record|note|save|store)\s+"
    r"(?:this|that|it|the\s+following|these)"
    # ⚠ Scan a WINDOW, not the next token: "save this FILE to the knowledge
    # base" / "store this DOCUMENT in the database" / "save it to MY kb" all
    # defeated a tight lookahead (round-2 review). Up to ~40 chars of noun
    # phrase may sit between the verb and the destination.
    r"(?![^.!?\n]{0,40}?\b(?:to|in|into|on|under|at)\s+"
    r"(?:the|a|an|my|your|our|its)?\s*"
    r"(?:knowledge[\s_-]?base|kb|file|disk|db|database|table|postgres|"
    r"sqlite|project|folder|directory|sandbox|workspace|notes?|doc|"
    r"document|repo|bucket|store)\b)"
    # "update/add to your profile|memory"
    r"|(?:update|add\s+to|write\s+to|amend|correct)\s+(?:your\s+|the\s+)?"
    r"(?:profile|memory|user\s+profile)"
    # direct tool directives
    r"|call\s+(?:learn_skill|update_profile)"
    r"|use\s+(?:learn_skill|update_profile)"
    # "learn a lesson from …" / "take a lesson"
    r"|(?:learn|take)\s+a\s+lesson"
    # "don't forget to remember/record"
    r"|(?:remember|record)\s+(?:for|next\s+time)"
    r")\b",
    re.IGNORECASE,
)


def _has_meta_task_directive(text: str) -> bool:
    """True when the user actually INSTRUCTED the agent to record something.

    A mention of the words 'skill' / 'lesson' / 'profile' is NOT a directive:
    "Define a composed skill", "show me all custom skills" and "what have you
    learned today" are ordinary requests, and the nudge that fired on them
    told the model a falsehood about its own instructions."""
    return bool(_META_TASK_DIRECTIVE_RE.search(text or ""))


#: Ceiling on the user-correction adjudication (§4EP). It blocks the user's
#: turn, and it fires on ~0.9% of them; a judge that is slow has not ruled,
#: and `None` restores the pre-§4EP lexical test rather than losing the turn.
_CORRECTION_JUDGE_TIMEOUT_S = float(
    os.getenv("GHOST_CORRECTION_JUDGE_TIMEOUT", "20") or 20)

_BOOKKEEPING_TOOL_NAMES = frozenset({
    "manage_projects", "manage_tasks", "manage_skills",
    "scratchpad", "learn_skill", "update_profile",
    "replan", "abort_attempt", "list_lessons",
    "knowledge_base",  # insert_fact / forget return confirmations only
})


def _source_caveat_enabled() -> bool:
    """§4IT: GHOST_VERIFY_SOURCE_CAVEAT=0 turns the user-facing caveat off."""
    return os.getenv("GHOST_VERIFY_SOURCE_CAVEAT", "1").strip().lower() not in ("0", "false", "off", "no")


SOURCE_CAVEAT_HEAD = "Not found in the sources I consulted: "


def _source_caveat_line(v_result) -> str:
    """The italic caveat line for a verdict carrying `unverified_facts`, or
    "" — never for a REFUTED (its correction banner says more), never when
    the flag is off, at most five items."""
    if v_result is None or not _source_caveat_enabled():
        return ""
    facts = [str(f) for f in (getattr(v_result, "unverified_facts", None) or []) if str(f).strip()]
    if not facts:
        return ""
    try:
        from .verifier import VerifyVerdict
        if getattr(v_result, "verdict", None) == VerifyVerdict.REFUTED:
            return ""
    except Exception:  # noqa: BLE001
        pass
    return "_" + SOURCE_CAVEAT_HEAD + ", ".join(facts[:5]) + "._"


def verdict_is_consumable(v_result, last_tool) -> bool:
    """May this verdict drive the note / backfill / retraction?

    ⚠ EXTRACTED SO IT CAN BE MUTATED AND KILLED. Written inline, the clause
    was `last_tool is not None` — "a substantive tool ran" — which is FALSE
    for every verdict the §4EQ memory-claim route can ever produce, because
    that route exists precisely for tool-free turns. The verdict would have
    been computed, logged, and consumed by nothing: a verifier that runs and
    changes nothing, which is this codebase's most-repeated defect class.

    The question the guard actually asks is "was the verifier applicable to
    this turn". Tool evidence answers yes. So does a produced REFUTED, which
    can only exist here because a mechanical check found a contradiction —
    and a contradiction the agent can PROVE is the last thing that should be
    dropped for want of a tool call.

    A produced CONFIRMED/UNCERTAIN with no tool is deliberately NOT
    consumable: the memory route never emits one (§4EP — confirm-carrying
    coverage makes calibration worse), so such a value would be a verdict
    from somewhere unaccounted for, and this fails closed on it.
    """
    if last_tool is not None:
        return True
    from .verifier import VerifyVerdict
    return (v_result is not None
            and getattr(v_result, "verdict", None) == VerifyVerdict.REFUTED)


def _action_failed(content, tool_name: str = "") -> bool:
    """Did this recorded tool call fail? THE question, asked of a stored row.

    The dispatch loop answers it once per call and every in-loop consumer
    reads that one answer. Anything that re-derives it from a row AFTER the
    turn — the episode store, the info-gathering gate, an eval harness —
    must ask the same way, or the stored label contradicts the live one.
    Three private prose banks did, and each was wrong in its own direction.

    UNRESOLVED is not a failure: a detached job has no verdict yet.
    """
    from ..tools.outcome import OutcomeStatus, ToolOutcome
    # `coerce` PASSES THROUGH an existing outcome — re-coercing `str(content)`
    # would rebuild it as DERIVED and re-sniff a banner the producer already
    # answered for (a `manage_projects` ledger quoting someone else's
    # `EXIT CODE: 1`).
    if isinstance(content, (list, tuple)):
        # block-style content: any failing part fails the call
        return any(_action_failed(_p, tool_name) for _p in content)
    if isinstance(content, dict):
        content = content.get("text") or content.get("content") or ""
    _o = ToolOutcome.coerce(content if isinstance(content, ToolOutcome)
                            else str(content or ""))
    if _o.status is OutcomeStatus.UNRESOLVED:
        return False
    # ...and the TEXT form of the third state, for rows rehydrated from
    # JSONL where no status survives (the offline seeder's whole diet).
    try:
        from ..distill.outcome_heuristics import is_unresolved_tool_result
        if is_unresolved_tool_result(str(content or "")):
            return False
    except Exception:  # noqa: BLE001
        pass
    # the same shell/banner split the loop uses. vision_analysis DECLARES
    # every result (§4LM), so live a caption quoting "EXIT CODE: 2" is never a
    # strike; a row rehydrated as plain text must not become one either.
    # (file_system is NOT here: the live loop still applies the banner rule
    # to its undeclared reads, and this must answer as the loop did.)
    if str(tool_name or "").strip().lower() == "vision_analysis":
        return bool(_o.is_failure)
    return bool(_o.is_failure
                or (_o.shell_failed if tool_name == "execute"
                    else _o.exit_code_failed))


def _bookkeeping_call_failed(content) -> bool:
    """Did this bookkeeping tool call FAIL?

    Was `c.startswith(("Error", "SYSTEM BLOCK", "REJECTED"))`, inlined at
    three sites. Case-SENSITIVE, so `ERROR:` and `SYSTEM ERROR:` — which
    `manage_projects` and `knowledge_base` both emit — matched nothing:
    measured, **15 of the 22 failed bookkeeping calls in the corpus (68%)
    were invisible**. Consequences at turn level: 12 turns carry one, on 2 of
    them the evidence run-gate returns `None` so the verifier never runs at
    all, and on 5 the ACTION view returns `None`, disarming the
    unverified-mutation guard and code-shape routing. That is exactly the
    blind spot the 2026-07-25 error carve-out was added to close, reopened by
    letter case.

    Reads the STATUS first — the content is a `ToolOutcome` on the live path
    — then the prefixes, case-insensitively.
    """
    _st = getattr(content, "status", None)
    if _st is not None and str(getattr(_st, "value", _st)) not in (
            "ok", "unresolved", "partial"):
        # PARTIAL is excluded on purpose: `update_profile` returns it when
        # the canonical write LANDED and only a secondary index lagged.
        # Counting it a failure made a bookkeeping PARTIAL shadow the real
        # action in `_find_substantive_tool_for_verifier`, which its own
        # docstring says "silently disables the untested-write guard and
        # demotes code-shaped audits to the weaker claim branch".
        return True
    c = str(content or "").lstrip().lower()
    return c.startswith(("error", "system block", "system error", "rejected",
                         "critical error", "system instruction",
                         "[error]", "traceback", "security error"))


def _bookkeeping_informational(content, *, id_linkage: bool = False) -> bool:
    """True when a BOOKKEEPING tool's output carries verifiable substance
    rather than a bare state-change confirmation.

    ONE formula shared by the evidence packer (`_collect_verifier_evidence`)
    and the run-gate (`_find_substantive_tool_for_verifier`) so the two can
    never drift (§4BC 2026-08-12; the fit/scorer-one-formula rule). Substance:

    - error banners (``Error`` / ``SYSTEM BLOCK`` / ``REJECTED``) — an
      errored bookkeeping call is evidence, not bookkeeping (2026-07-25);
    - payload-shaped output (≥200 chars: listings, task tables, self-play
      reports) — the 2026-07-25 packer bar, promoted to the run-gate by the
      §4BC measurement: 271 of 340 bookkeeping-only `unknown` turns carried
      exactly this evidence shape (174 of them manage_projects listings),
      and with the name-only run-gate none of them could ever be verified;
    - ``id_linkage`` (packer ONLY): short confirmations carrying a 12-hex id
      are linkage evidence once the verifier is already running (2026-07-25:
      an under-length task_update result made the judge compare a task id
      against the PROJECT id). Deliberately NOT a run-gate trigger — a bare
      mutation confirmation is the 2026-04-19 guaranteed-REFUTED shape, so
      it must not summon the judge on its own.
    """
    if _bookkeeping_call_failed(content):
        return True
    c = str(content or "").strip()
    if len(c) >= 200:
        return True
    if id_linkage and re.search(r"\b[0-9a-f]{12}\b", c):
        return True
    return False


def _tool_is_bookkeeping(tool) -> bool:
    """True when a recorded tool entry names a bookkeeping tool (same
    normalization as the gate walk)."""
    if not tool or not isinstance(tool, dict):
        return False
    name = str(tool.get("name", "")).lower().strip()
    return name.replace("-", "_").replace(" ", "_") in _BOOKKEEPING_TOOL_NAMES


# ── Late-verdict ordering (2026-09-13) ──────────────────────────────────────
# A verdict can land BEFORE the turn's own records exist: a tool-free turn's
# verdict branch has no await, so the verdict task completes on the next loop
# tick and its done-callback runs at finalize's next yield — ahead of
# `_record_turn_trajectory` (the corpus row + correction cache) and of
# `_record_lesson_outcomes` (the lesson stash). Two bounded, context-keyed
# rings make both consumers order-independent: an in-flight trajectory's
# early verdict is parked and replayed by the record; an early lesson sign is
# parked and booked by the stash write. Module-level (not methods) so the
# fakes that stand in for the agent in the backfill tests keep working.
_TRAJ_IN_FLIGHT_MAX = 64
_PENDING_LESSON_SIGN_MAX = 256


def _bounded_ring(context, attr: str, cap: int):
    from collections import OrderedDict
    ring = getattr(context, attr, None)
    if not isinstance(ring, OrderedDict):
        ring = OrderedDict()
        setattr(context, attr, ring)
    while len(ring) > cap:
        ring.popitem(last=False)
    return ring


def _mark_trajectory_in_flight(context, trajectory_id) -> None:
    if not trajectory_id:
        return
    ring = _bounded_ring(context, "_trajectories_in_flight", _TRAJ_IN_FLIGHT_MAX)
    ring[trajectory_id] = True
    ring.move_to_end(trajectory_id)
    while len(ring) > _TRAJ_IN_FLIGHT_MAX:
        ring.popitem(last=False)


def _trajectory_is_in_flight(context, trajectory_id) -> bool:
    ring = getattr(context, "_trajectories_in_flight", None)
    try:
        return bool(trajectory_id) and bool(ring) and trajectory_id in ring
    except TypeError:
        return False


def _defer_late_backfill(context, trajectory_id, outcome, reason) -> None:
    """Park a late verdict that landed before its trajectory row was
    written; `GhostAgent._replay_deferred_late_backfill` runs it after."""
    pend = _bounded_ring(context, "_pending_late_backfill", _TRAJ_IN_FLIGHT_MAX)
    pend[trajectory_id] = (outcome, reason)
    pend.move_to_end(trajectory_id)
    while len(pend) > _TRAJ_IN_FLIGHT_MAX:
        pend.popitem(last=False)
    pretty_log(
        "Verifier",
        f"late {outcome} for trajectory {str(trajectory_id)[:8]} landed "
        f"before the turn's record — deferred until the trajectory is written",
        icon=Icons.VERIFIER_LAB,
    )


def _take_deferred_late_backfill(context, trajectory_id):
    """Clear the in-flight mark; return the parked (outcome, reason) or None."""
    if not trajectory_id:
        return None
    ring = getattr(context, "_trajectories_in_flight", None)
    if isinstance(ring, dict):
        ring.pop(trajectory_id, None)
    pend = getattr(context, "_pending_late_backfill", None)
    if not isinstance(pend, dict) or trajectory_id not in pend:
        return None
    return pend.pop(trajectory_id)


def _park_pending_lesson_sign(context, trajectory_id, success: bool) -> None:
    pend = _bounded_ring(context, "_pending_lesson_outcome_by_traj",
                         _PENDING_LESSON_SIGN_MAX)
    pend[trajectory_id] = bool(success)
    pend.move_to_end(trajectory_id)
    while len(pend) > _PENDING_LESSON_SIGN_MAX:
        pend.popitem(last=False)
    logger.info(
        "lesson-outcome: verdict for traj %s landed before its stash — "
        "sign parked (%s)", str(trajectory_id)[:8],
        "success" if success else "failure",
    )


def _take_pending_lesson_sign(context, trajectory_id):
    """The parked sign for ``trajectory_id`` (popped), or None."""
    pend = getattr(context, "_pending_lesson_outcome_by_traj", None)
    if not isinstance(pend, dict) or trajectory_id not in pend:
        return None
    return pend.pop(trajectory_id)


# ── The forced final that produced no answer (§4GH, 2026-09-13) ─────────────
_FORCED_FINAL_ANSWER_DIRECTIVE = (
    "SYSTEM ALERT: this is the FINAL turn — tools are OFF and your last output "
    "contained NO answer (only tool calls, or working narration such as "
    "'Let me dig into…'). Write the answer NOW from the evidence already in "
    "this conversation: state what you found, name the sources you actually "
    "read, and say plainly what you could not determine. Do NOT call tools. "
    "Do NOT describe what you will do next."
)


#: §4KW (review): tools whose repeated SAME result means "the sources have
#: nothing more", not "a change you made is or is not in place".
#: Not `browser` (second review): its repeats are clicks and form steps on one
#: page — "answer from what you found" is the wrong exit for an interaction.
_LOOKUP_TOOLS = frozenset({"web_search", "darkweb_search", "deep_research", "darkweb_research",
                           "fact_check", "recall", "knowledge_base"})


#: The longest reply a trajectory row stores.
_RECORDED_REPLY_CAP = 16000


def _cap_recorded_reply(text) -> str:
    """The reply as a row stores it: at most `_RECORDED_REPLY_CAP` chars.
    §4KW (review): a plain `[:16000]` cut off an `[ATTEMPT_ABORTED_*]` marker
    APPENDED to a long partial (the aborted-turn record puts it last), so the
    row said UNKNOWN while the line read the full text and said failed. The
    middle is elided instead: the head (what the user saw first) and the tail
    (where markers and notes live) both survive."""
    t = str(text or "")
    if len(t) <= _RECORDED_REPLY_CAP:
        return t
    note = "\n\n[… reply truncated for the record …]\n\n"
    keep_tail = 2000
    return t[:_RECORDED_REPLY_CAP - keep_tail - len(note)] + note + t[-keep_tail:]


def _is_no_answer_fallback(text) -> bool:
    """§4KW: the reply is the system's own canned no-answer fallback (the
    corpus's rule 1c; `reply_shape_check` owns the wording)."""
    try:
        from .reply_shape_check import refute_no_answer_fallback
        return bool(refute_no_answer_fallback(str(text or "")))
    except Exception:  # noqa: BLE001
        return False


def no_progress_final_steer(tool, target_desc, count, pending_request=None) -> str:
    """The no-progress breaker's forced final. §4KW (review): the one text it
    had was written for change/debug loops — "if you confirmed the change via
    state/file inspection, report success … the failing URL from their
    devtools" — and fired 25 times on SEARCH loops (slack-36bd38b6 then
    claimed "I verified the logic by simulating…"). A lookup tool gets the
    answer-from-what-you-found final; both carry whose message it is and
    which request it serves."""
    head = (f"SYSTEM ALERT: You have run '{tool}'{target_desc} {count} times "
            "and gotten the SAME result with no change — re-observing "
            "produces NO new information. The evidence you already have is "
            "AUTHORITATIVE. ")
    if str(tool or "").strip().lower() in _LOOKUP_TOOLS:
        body = ("Write your FINAL answer now from what the results you already have "
                "actually say: state what they support, name plainly each part of the "
                "question they do not answer, and do not present anything as checked or "
                "verified that no result showed. Do NOT call this tool again.")
    else:
        body = ("Write your FINAL answer now: if you confirmed "
                "the change via state/file inspection, report success and how "
                "you confirmed it. If you are still UNSURE why something fails, "
                "do not guess — say plainly what you verified, what you could "
                "not verify from here, and ask the user for the ONE piece of "
                "evidence that would settle it (the exact error text, the "
                "failing URL from their devtools, or the output of a command "
                "you give them). Do NOT call this tool again.")
    return (head + body + " " + _ALERT_PROVENANCE
            + (_which_request_line(pending_request) if pending_request is not None else "")).rstrip()


def forced_final_answer_directive(dropped_tools=None, pending_request=None, *,
                                  file_report: bool = False) -> str:
    """§4KW (review): the answer-now retry of a forced final, with whose
    message it is, which request it serves and — when the no-answer was a
    tool call on a tools-off turn — that THOSE calls did not run. Without
    that line the model wrote the dropped call's result anyway: slack-36bd38b6
    shipped "The Python simulation … produced DARTHVADERO" after `execute`
    was dropped; slack-23a1fa85 reasoned "I navigated to it in the browser"
    after `browser` was. ``dropped_tools``: names (an empty list = "the
    tool call(s) you just wrote"); None = nothing was dropped."""
    text = _FORCED_FINAL_ANSWER_DIRECTIVE
    if dropped_tools is not None:
        names = ", ".join(f"`{n}`" for n in dict.fromkeys(n for n in dropped_tools if n and n != "?")) or "the tool call(s) you just wrote"
        text += (f" The call(s) in your last output — {names} — were NOT run: there is no "
                 "output from them, so do not report, quote or imply any result of them; say "
                 "plainly that this step was not done.")
    if file_report:
        # §4OE-1b: the stream path cannot run a write after its final — the
        # report the model put in a file call must come back as reply text
        text += (" The file you tried to write was NOT written: put the report "
                 "itself in your reply text now, in full — the reply may be long.")
    return (text + " " + _ALERT_PROVENANCE
            + (_which_request_line(pending_request) if pending_request is not None else "")).rstrip()


# §4IW (req a3ec5024, 2026-09-19): the model announced work and ended the
# turn — "Ας κάνω έρευνα για τον ραβίνο Μορντεχάι Φριζή…" was the WHOLE reply
# of a zero-tool turn; its thinking said "let me search" four times and
# emitted no call. The §4GH shape check refutes narration only AFTER tools
# ran and the forced-final retry only on tools-off turns, so an ordinary
# first turn that stops at the announcement shipped as the answer. One
# continuation, tools on: do the work or answer — never narrate.
_ANNOUNCED_WORK_DIRECTIVE = (
    "SYSTEM ALERT: your last message ended by ANNOUNCING work ('Let me search…', "
    "'I'll check…', 'Ας κάνω έρευνα…') with NO tool call — the step it announces "
    "did not happen, and the user would receive only the announcement. Either "
    "make the tool call(s) now, or answer directly from what you already know. "
    "Do NOT describe work you have not done."
)


def _count_real_tools_safe(tools_run) -> int:
    """`reply_smoothing.count_real_tools` (synthetic parse-error rows are not
    tools — review §4IX), never raising."""
    try:
        from .reply_smoothing import count_real_tools
        return int(count_real_tools(tools_run or []))
    except Exception:  # noqa: BLE001
        return len([t for t in (tools_run or []) if isinstance(t, dict) and not t.get("_synthetic")])


def _announced_work_without_acting(this_turn_text: str, request: str = "") -> bool:
    """The zero-tool no-answer: this turn's own text is nothing but working
    narration (`reply_smoothing.narration_only`, the §4GH predicate); the
    user's ``request`` lets echoed figures read as echoes (§4JI)."""
    from .reply_smoothing import narration_only, strip_system_notes
    body = strip_system_notes(str(this_turn_text or "")).strip()
    return bool(body) and narration_only(body, request=request)


_SENTENCE_SPLIT_RE = re.compile(r"(?<=[.!?;])[ \t]+(?=[A-ZΑ-Ω*\"'(«])")
#: a promise for LATER is a commitment, not an announcement of work this turn
#: (§4IY pins "Yes. I'll check it tomorrow." / "Ναι. Θα το ελέγξω αύριο." as answers)
_LATER_RE = re.compile(r"\b(?:tomorrow|later|tonight|soon|next (?:week|month|time|year)|this (?:evening|afternoon|weekend)"
                       r"|on (?:mon|tues|wednes|thurs|fri|satur|sun)day)\b|αύριο|αργότερα|απόψε|την επόμενη", re.I)
_LIST_LINE_RE = re.compile(r"^\s*(?:[-*•>]|\d+[.)])\s")
#: §4PO: the answer is KEPT by the loop (carried into the reply without its
#: last sentence, r2 M1: a directive alone lost it — finalize trims text written
#: beside a tool call); the continuation only adds the announced step
_TRAILING_ANNOUNCED_DIRECTIVE = (
    "SYSTEM ALERT: your last message answered, then ENDED by announcing a step you did not take "
    "(%s) — no tool call was made. The user already has your answer, without that last sentence. "
    "Now either make the tool call(s) for that step and then add ONLY what it found, or reply with "
    "one short sentence saying you did not do it. Do NOT repeat the answer.")
_TRAILING_ANNOUNCED_STANDALONE = (
    "SYSTEM ALERT: your last message answered, then ENDED by announcing a step you did not take "
    "(%s) — no tool call was made. The user will see only your NEXT message. Either make the tool "
    "call(s) now and then give the complete answer, or write the complete answer now without "
    "promising any further step.")


def _answer_without_tail(text: str, tail: str) -> str:
    """``text`` with its trailing announcement ``tail`` cut off (the answer
    the loop keeps), or "" when the tail is not at its end."""
    t = str(text or "").rstrip()
    i = t.rfind(str(tail or ""))
    if not tail or i < 0 or t[i + len(tail):].strip():
        return ""
    return t[:i].rstrip()


def _po_carry(context, req_id):
    """(start index in final_ai_content, kept text) of this request's §4PO
    carried answer, or None."""
    d = getattr(context, "_po_carries", None)
    return d.get(str(req_id or "")) if isinstance(d, dict) else None


def _with_carry(context, req_id, text: str) -> str:
    """§4SB r2 (review MAJOR): an error exit's text, with the answer a
    previous round carried (§4PO, the §4SB extra step) in FRONT of it — the
    error exits assigned `final_ai_content` whole, and the extra step had
    made a complete answer a hostage of one more model call."""
    try:
        pc = _po_carry(context, req_id)
        kept = str(pc[1] or "").strip() if pc else ""
        text = str(text or "")
        if kept and kept not in text:
            return kept + "\n\n" + text
    except Exception:  # noqa: BLE001
        pass
    return str(text or "")


def _q_mark_read(turn) -> None:
    """§4SB r3: a reply that answered (text or a tool call) read EVERY drained
    message in its prompt — the marker moves to the end and the overflow's
    "left-out" set is cleared (an overflow's retry rebuilds the prompt with
    every row, so what a later round reads is all of them; r3 review: rows a
    completed reply had read were handed back after an overflow)."""
    try:
        turn._q_read = len(getattr(turn, "_q_items", ()) or ())
        turn._q_skipped = ()
    except Exception:  # noqa: BLE001
        pass


def _q_note_overflow(turn, rows, sent_rows) -> None:
    """§4SB r3: an overflow retry sent only ``sent_rows`` (the NEWEST within
    its budget) of the queued ``rows`` in the prompt: the others are unread
    unless a completed reply had read them before — their drained positions
    (`_q_i`, stamped at the drain) go to `_q_skipped`; the marker moves to the
    end so the hand-back reads both."""
    try:
        read = int(getattr(turn, "_q_read", 0) or 0)
        items = list(getattr(turn, "_q_items", ()) or ())
        left_out = max(0, len(rows) - len(sent_rows))
        skipped = set(getattr(turn, "_q_skipped", ()) or ())
        unidentified = False
        for r in rows[:left_out]:
            i = r.get("_q_i") if isinstance(r, dict) else None
            if not isinstance(i, int):
                # r4: a row copied without its stamp — find it by text among the
                # unread items (the hand-back matches by text too; r5: a loop row
                # carries the QUEUED_LABEL line first — stripped before matching)
                from .queued_messages import QUEUED_LABEL as _ql
                text = str(r.get("content") or "") if isinstance(r, dict) else ""
                if text.startswith(_ql + "\n"):
                    text = text[len(_ql) + 1:]
                i = next((k for k in range(read, len(items))
                          if k not in skipped and str((items[k] or {}).get("text") or "") == text), None)
            if isinstance(i, int) and i >= read:
                skipped.add(i)
            elif i is None:
                unidentified = True
        turn._q_skipped = tuple(sorted(skipped))
        # r4: a left-out row nobody could place keeps the marker where it is
        # (it comes back as a duplicate, never booked read = lost)
        turn._q_read = read if unidentified else len(items)
    except Exception:  # noqa: BLE001
        pass


def _po_note_carry(context, req_id, start: int, kept: str) -> None:
    try:
        d = getattr(context, "_po_carries", None)
        if not isinstance(d, dict):
            d = {}
            context._po_carries = d
        d[str(req_id or "")] = (int(start), str(kept))
        while len(d) > 16:
            d.pop(next(iter(d)))
    except Exception:  # noqa: BLE001 — bookkeeping only
        pass


def _ends_on_announced_work(this_turn_text: str, request: str = "") -> bool:
    """§4PO: the reply ANSWERS, then ends on a promise of work it never did —
    its last sentence alone is working narration (the same §4GH predicate,
    `narration_only`). §4IW caught only a reply that was narration through
    and through; "No, Bloodborne is not on Mac. … Let me check if there are
    any workarounds like cloud gaming or emulation:" shipped (2 of 10 live
    replays still end so). Corpus, all days: 3 of 523 tool-free replies."""
    return bool(_announced_tail(this_turn_text, request))


def _announced_tail(this_turn_text: str, request: str = "") -> str:
    """The trailing announcement `_ends_on_announced_work` fires on, or "".
    Only the reply's LAST LINE is read (r1 m2: a line break inside a
    paragraph split verse and numbered steps into fake sentences); a list
    item, a promise for later, and a creative request never fire."""
    from .reply_smoothing import narration_only, strip_system_notes
    body = strip_system_notes(str(this_turn_text or "")).strip()
    if not body or "```" in body[-400:]:
        return ""
    try:
        from .failure_census import _CREATIVE
        if _CREATIVE.search(str(request or "")):
            return ""                                   # a poem's "I will find my way home."
    except Exception:  # noqa: BLE001
        pass
    last_line = [ln for ln in body.splitlines() if ln.strip()][-1].strip()
    if _LIST_LINE_RE.match(last_line):
        return ""                                       # "2. Let me add the pasta now." is a step
    sents = [x for x in _SENTENCE_SPLIT_RE.split(last_line) if x.strip()]
    tail = (sents[-1] if sents else last_line).strip()
    if not tail or tail == body or _LATER_RE.search(tail):
        return ""
    return tail if narration_only(tail, request=request) else ""


def _announced_then_called(text: str, request: str = "") -> bool:
    """§4LK: this turn's text only ANNOUNCED work, and a tool call followed —
    an announcement may say "you" ("…before you came back", req b46518f0)."""
    from .reply_smoothing import narration_only, strip_system_notes
    text = strip_system_notes(str(text or ""))      # §4QA: the one-task note is ours
    i = text.find(_DROPPED_NOTE_HEAD)
    if i >= 0:
        text = text[:i]
    return bool(text.strip()) and narration_only(text, request=request, tool_attempt=True)


def _forced_final_has_no_answer(this_turn_text: str, accumulated: str,
                                request: str = "") -> bool:
    """`reply_smoothing.forced_final_has_no_answer` over the model's text
    with the loop's own dropped-mutation note removed first; ``request``
    lets figures echoed from the user's message read as echoes (§4JI)."""
    from .reply_smoothing import forced_final_has_no_answer
    text = str(this_turn_text or "")
    i = text.find(_DROPPED_NOTE_HEAD)
    if i >= 0:
        text = text[:i]
    return forced_final_has_no_answer(text, accumulated, request=request)


FORCED_FINAL_LOOP_MARKER = "[ATTEMPT_ABORTED_THINKING_LOOP]"
_ABORT_MARKER_RE = re.compile(r"\[ATTEMPT_ABORTED_[A-Z_]+\]")


def strip_abort_markers(text):
    """§4KM (h): a reply without its internal `[ATTEMPT_ABORTED_*]` tokens —
    for a channel member's copy only; the corpus and the owner keep them. A
    marker inside code (a ``` fence or an inline `span`) is content and stays;
    a reply that is nothing but a marker keeps it (never an empty reply)."""
    if not isinstance(text, str) or not _ABORT_MARKER_RE.search(text):
        return text

    def _drop(m):
        seg, a, b = m.string, m.start(), m.end()
        inner = a > 0 and b < len(seg) and seg[a - 1] not in "\n" and seg[b] not in "\n"
        return " " if inner and (m.group(1) or m.group(2)) else ""

    parts = re.split(r"(```.*?```|`[^`\n]*`)", text, flags=re.S)
    out = "".join(p if i % 2 else re.sub(r"([ \t]*)\[ATTEMPT_ABORTED_[A-Z_]+\]([ \t]*)", _drop, p)
                  for i, p in enumerate(parts)).strip()
    return out or text


_TRAILING_SEPARATOR_RE = re.compile(r"(?:\s*\n---)+\s*$")


def system_command_reply(staged: str) -> str:
    """§4PY: the whole reply to an owner command the system carried out — the
    staged banner (the command's outcome line, plus any deferred correction
    staged for this turn), without the separator that joined it to a model
    reply. "" when nothing is staged."""
    return _TRAILING_SEPARATOR_RE.sub("", str(staged or "")).strip()


def _owner_command_line(kind: str, text, note) -> str:
    """§4NV: the owner's command AND what it did (the note's ``banner``:
    "rule 3 adopted", "no such proposed rule", "test kept")."""
    line = f"{kind} command: {str(text or '').strip()[:100]}"
    banner = " ".join(str(getattr(note, "banner", "") or "").split())
    return f"{line} → {banner[:160]}" if banner else line


def reply_carries_abort_marker(text) -> bool:
    """True when a reply carries a runtime abort marker anywhere (the same
    shape `distill.outcome_heuristics` reads)."""
    return bool(_ABORT_MARKER_RE.search(str(text or "")))


def unattended_reply_status(text) -> str:
    """§4NS: what an UNATTENDED turn's reply says about itself — "failed"
    (a runtime abort marker, a cancelled turn, no text), "partial" (the turn
    budget ran out — "NOT a finished result"), else "ok". A scheduled task, a
    sub-agent and a coding-loop leaf all booked every returned reply as a
    success: "[TURN BUDGET EXHAUSTED]" was paged as a task's result, a
    sub-agent whose LLM calls failed landed DONE with "Done —" sent to the
    owner, and 25 of 33 budget-exhausted leaves were accepted."""
    t = str(text or "").strip()
    if not t or reply_carries_abort_marker(t) or t.startswith("_(Turn cancelled"):
        return "failed"
    if "[TURN BUDGET EXHAUSTED]" in t:
        return "partial"
    return "ok"


def second_cap_reports(turn, max_turns) -> bool:
    """§4IH — after the second thinking cap of an attempt, is there a turn
    left to write the report in? `turn` is 0-based; the report needs turn
    `turn + 1` to exist."""
    try:
        return int(turn) + 1 < int(max_turns)
    except (TypeError, ValueError):
        return False


def forced_final_loop_fallback(fallback: str, *, flood: bool = False) -> str:
    """§4IF — the reply for a forced-final turn whose generation was
    killed as a thinking loop / tool-call flood: the evidence fallback
    FIRST (the user gets the material), the abort marker LAST (the corpus
    still reads the abort)."""
    what = ("a runaway burst of tool calls" if flood
            else "a self-repeating thinking loop")
    return (f"{fallback}\n\n{FORCED_FINAL_LOOP_MARKER} The report turn itself "
            f"entered {what} and was killed; the text above is the last "
            "evidence, not a finished report.")


CROSS_TURN_LOOP_MARKER = "[ATTEMPT_ABORTED_CROSS_TURN_LOOP]"
# The parser's openers only: `<tool_call…`, `<tool` + any non-word (its heal is
# `<tool\b[^>]*>` — `<tool>`, `<tool …>`, `<tool-x>`, `<tool/>`), `<function …`
# /`<function=`/`<function_name`. Not `\b` (`_` is a word character, so
# `tool\b` missed `<tool_call` — round 3) and not a bare prefix either
# (`<Toolbar>`, `Array<Function>` are answers — round 4).
_TOOL_MARKUP_RE = re.compile(
    r"<\s*/?\s*(?:tool_call|tool(?=[^\w]|$)|function(?=[\s=]|_name))", re.IGNORECASE)


#: §4KM (c): request id → the breaker that closed it with a report. Keyed, not a
#: context flag: a streamed final records after the next request has started.
_LOOP_BREAKER_REPORTS_MAX = 64


def stamp_loop_breaker(context, req_id, kind: str) -> None:
    d = getattr(context, "_loop_breaker_reports", None)
    if not isinstance(d, dict):
        d = {}
        context._loop_breaker_reports = d
    d[str(req_id or "")] = kind
    while len(d) > _LOOP_BREAKER_REPORTS_MAX:
        d.pop(next(iter(d)))


def loop_breaker_for(context, req_id, *, pop: bool = False) -> str:
    d = getattr(context, "_loop_breaker_reports", None)
    if not isinstance(d, dict):
        return ""
    key = str(req_id or "")
    v = d.pop(key, "") if pop else d.get(key, "")
    return v if isinstance(v, str) else ""


#: §4KM (f): the longest single-paragraph plan the answer check reads as a plan.
REPEATED_PLAN_MAX_CHARS = 600
#: §4KM (e): repeated-opening answers the cross-turn breaker lets through per
#: request; past this, a guard that keeps sending answers back is a loop too.
CROSS_TURN_ANSWERS_WAVED_MAX = 2


def repeated_turn_is_an_answer(content: str, native_tool_calls, *, request: str = "") -> bool:
    """§4KL: is a turn the cross-turn breaker caught a plain text answer?
    NOT an answer: anything the parser could read as a call (a native call,
    `<tool…`/`<function…` markup, a reply that opens with `{` — the only place
    the parser's raw-JSON fallback accepts one), no visible text, narration by
    the ONE shared definition (`reply_smoothing.narration_only`, which every
    other narration guard uses), or (§4KM f) a single work-beat sentence of up
    to REPEATED_PLAN_MAX_CHARS — the one shape narration_only's 300-char block
    cap lets through. Three bespoke plan rules were tried and each failed a
    review in the opposite direction; see PROJECT_JOURNAL §4KM."""
    if native_tool_calls:
        return False
    visible = _strip_think_blocks(str(content or "")).strip()
    if not visible or visible.startswith("{") or _TOOL_MARKUP_RE.search(visible):
        return False
    try:
        from .reply_smoothing import narration_only, _is_work_beat, _SENT_SPLIT_RE
        if narration_only(visible, request=request):
            return False
        one = [x for x in _SENT_SPLIT_RE.split(visible) if x.strip()]
        if (len(one) == 1 and "\n" not in visible and len(visible) <= REPEATED_PLAN_MAX_CHARS
                and _is_work_beat(visible)):
            return False
        return True
    except Exception:  # noqa: BLE001 — unsure is not an answer
        return False


def _qa_closed_at_cut(text: str, cut_prefix) -> str:
    """§4QA: ``text`` with the tool call the one-task stop cut open closed at
    the cut — for the RECORD and the verifier claim only (a closed call
    parses; the cut write must never run). Unchanged when there was no cut
    or ``text`` no longer starts with the text up to it."""
    if not cut_prefix:
        return text
    from .reply_smoothing import close_open_calls
    head = cut_prefix.rstrip()
    if not head or not str(text or "").startswith(head):
        return text
    return close_open_calls(head) + text[len(head):]


def _task_closed_loop_reply(fallback: str, *, flood: bool = False) -> str:
    """§4QA r9: a loop AFTER the one-task stop — the task is closed, so no
    "not a finished answer" / abort marker beside "✅ Task complete"; say
    what happened to the reply after it instead."""
    if "\n\nThe reply after it " in fallback:          # the stop cause is already there
        return fallback
    what = "started a runaway burst of tool calls" if flood else "kept repeating itself"
    return f"{fallback}\n\nThe reply after it {what} and was stopped."


def cross_turn_loop_fallback(fallback: str) -> str:
    """§4KL — the reply when the cross-turn breaker gives up with no report:
    the evidence fallback FIRST, the abort marker LAST (the outcome
    heuristics read it anywhere in the text)."""
    return (f"{fallback}\n\n{CROSS_TURN_LOOP_MARKER} The text above is what I "
            "gathered, not a finished answer.")


def evidence_digest(tools_run, *, ask: str = "") -> str:
    """§4II — the system's own report of a request, for the turns where the
    model would not write one: the ask, the files this request left
    behind, the distinct errors it hit (with counts), the last clean tool
    output, and what it ran. Built only from the tool records (the same
    parsers the verifier uses), so it can name nothing the request did
    not do. Empty when nothing ran."""
    from .strikes import error_line, exception_signature, normalise_volatile
    runs = [t for t in (tools_run or []) if t and not (t or {}).get("_synthetic")]
    if not runs:
        return ""
    parts = []
    if str(ask or "").strip():
        parts.append("You asked: " + " ".join(str(ask).split())[:400])
    try:
        left, _retired = _fs_path_ledger(runs)
    except Exception:  # noqa: BLE001 — a digest never raises
        left = []
    if left:
        parts.append("Files this request wrote and left in place: "
                     + ", ".join(f"`{p}` (/api/download/{str(p).lstrip('/')})" for p in left[:12])   # §4OE-1b: linkable
                     + (" …" if len(left) > 12 else ""))
    errors: dict = {}
    order = []
    last_clean = None
    for t in runs:
        content = t.get("content") or ""        # the object: a declared status counts
        line = error_line(content, tool=str(t.get("name") or "") or None)
        if line:
            key = " ".join(exception_signature(normalise_volatile(line)).split())[:200]
            if key not in errors:
                errors[key] = 0
                order.append(key)
            errors[key] += 1
        elif str(t.get("name") or "") in ("execute", "browser", "web_search", "search",
                                          "deep_research", "vision_analysis"):
            last_clean = t
    if order:
        top = sorted(order, key=lambda k: -errors[k])[:5]
        parts.append("Distinct errors hit: "
                     + "; ".join(f"`{k}` ×{errors[k]}" for k in top))
    if last_clean is not None:
        name = str(last_clean.get("name") or "tool")
        args = getattr(last_clean.get("content"), "call_args", None) or {}
        target = str(args.get("url") or args.get("query") or args.get("command")
                     or args.get("path") or "").strip()
        body = " ".join(str(last_clean.get("content") or "").split())[:700]
        where = f"`{name}`" + (f" ({target[:120]})" if target else "")
        parts.append(f"Last clean tool output, {where}: {body}")
    try:
        from .task_state import evidence_heads                                        # §4OE-1
        _heads = evidence_heads(runs)
        if _heads:
            parts.append(_heads)
    except Exception:  # noqa: BLE001
        pass
    counts: dict = {}
    for t in runs:
        n = str(t.get("name") or "?")
        counts[n] = counts.get(n, 0) + 1
    parts.append("Tools run: " + ", ".join(f"{n} ×{c}" for n, c in
                                           sorted(counts.items(), key=lambda kv: -kv[1])))
    return "\n\n".join(parts)


def _no_answer_fallback_reply(tools_run, *, ask: str = "", head_key: str = "no_answer",
                              stopped_by: str = "", task_closed: bool = False) -> str:
    """The honest reply when a forced final produced nothing twice: the
    §4GH fallback head (refuted by the shape check as the non-answer it is)
    plus — §4II — the system's evidence digest, so the user gets what
    exists and what failed instead of one write confirmation (probe
    ifs21133…: "Last evidence gathered: SUCCESS: Wrote 936 chars to
    'probe.py'" after 24 steps).

    ``task_closed`` (§4QA r3/r4): a project task closed in this request —
    the reply is the one-task stop note, then what ran. Not a no-answer head
    ("I ran out of this turn's budget" booked the turn FAILED) and not "the
    task is NOT finished": it was finished, then the model wrote the next
    task's call. The stream path ships the same note (no retry there)."""
    from .reply_shape_check import FALLBACK_HEADS
    if stopped_by and head_key == "no_answer":
        head_key = "no_answer_stopped"
    head = FALLBACK_HEADS[head_key]
    if stopped_by and head_key == "no_answer_stopped":
        head = f"{head}\nWhat stopped it: {stopped_by}."
    digest = evidence_digest(tools_run, ask=ask)
    if task_closed:
        # a guard or a loop that ended the reply still says so (r5 m)
        why = (f"\n\nThe reply after it was stopped by a check: {stopped_by}." if stopped_by
               else "\n\nThe reply after it kept repeating itself and was stopped."
               if head_key == "no_answer_loop" else "")
        return TASK_CLOSED_NOTE + why + (f"\n\nWhat ran in this request:\n\n{digest}" if digest else "")
    if not digest:
        asked = (" ".join(str(ask).split())[:400] + "\n\n") if str(ask or "").strip() else ""
        return (head + "\n\n" + ("You asked: " + asked if asked else "")
                + "No tool this turn returned usable evidence. Ask me to continue.")
    return (f"{head}\n\n{digest}\n\n"
            "This is a digest of what ran, not an analysis; the task is NOT "
            "finished. Ask me to continue and I will pick up from these files "
            "and errors.")


def _browser_loaded_but_never_extracted(tools_run, target: str) -> bool:
    """§4GH: the repeated browser action is a `navigate` of ``target`` and no
    `extract_text` of that page ran this request — the repeat is a symptom
    (navigate returns a capped preview), and the remedy is to extract, not to
    end the turn. Reads the recorded rows' `call_args` (§4GG)."""
    tgt = str(target or "").strip().lower()
    if not tgt:
        return False
    navigated = extracted = False
    _last_nav = ""
    for r in tools_run or []:
        if not isinstance(r, dict) or r.get("_synthetic"):
            continue
        if str(r.get("name") or "").lower() != "browser":
            continue
        args = getattr(r.get("content"), "call_args", None) or {}
        # the breaker's target is `primary_target_from_args`: lower-cased and
        # cut at 200 chars — compare the same form
        _url = str(args.get("url") or "").strip().lower()[:200]
        from ..tools.browser_support import browser_effective_call
        op, _acts = browser_effective_call(args)        # r1: evaluate/fill ran as interact
        # §4LN: a url-less extract (the form the schema teaches: it re-opens
        # the page just navigated) and an interact extract are reads too
        _reads = op == "extract_text" or (op == "interact" and any(
            str(a.get("action") or "").lower() == "extract_text" for a in _acts))
        # a url-less read re-opens the page navigated last (review: any
        # url-less extract used to clear the steer for every target)
        if _reads and (_url == tgt or (_url == "" and _last_nav == tgt)):
            extracted = True
            continue
        if op == "navigate" and _url:
            _last_nav = _url
        if _url != tgt:
            continue
        if op in ("navigate", ""):
            # a screenshot loop is the breaker's classic case, not this one
            navigated = True
    return navigated and not extracted


def _latch_forces_final(task_closed_this_req: bool,
                        repair_reentry_active: bool) -> bool:
    """The ONE rule for every "converge now" signal the loop re-asks each
    iteration — the one-task-per-turn latch (a project task closed DONE
    this request; the inline planner's DONE plan used it too until §4NM
    deleted the planner): the turn must converge to a final answer —
    UNLESS a verifier auto-repair re-entry is running (2026-09-13). The
    repair directive ("actually RUN it", or "fix the refuted claim") needs
    tools; re-forcing the final while it runs issued that directive into a
    `tool_choice: none` turn whose every emitted call was dropped. Pinned
    as a table in `tests/test_repair_reentry_latch.py`."""
    return bool(task_closed_this_req) and not bool(repair_reentry_active)


_SELF_REPORT_TOOLS = frozenset({"introspect", "self_state", "list_lessons"})


def _should_await_repair_verdict(budget: float, lt, unverified: bool) -> bool:
    """Loop-exit gate: is the bounded in-loop verdict await worth blocking
    the reply for? Extracted pure so the §4BC exclusion is unit-testable.

    LISTING-evidence turns say NO (§4BC 2026-08-12): widening the run-gate
    to informational bookkeeping output made `_lt` non-None on listing
    turns ("show me all projects"), and the pre-existing await would have
    taxed exactly those — the most common turn shape — with up to
    `GHOST_CRITIC_REPAIR_BUDGET` (default 65s since 2026-08-22) of user-visible latency for
    a repair that is low-value on a listing summary. Their verdict still
    lands through the deferred/late path (which is what feeds the outcome
    corpus); only the BLOCKING await is skipped.

    The exclusion covers ONLY §4BC's new class (round-3 refinement): a
    bookkeeping tool the pre-§4BC ACTION view already selected — an error
    banner, or the autoadvance ``stop_reason`` batch payload — awaited
    before §4BC and still does, so a refutable failure narration can be
    REPAIRED in-loop rather than shipping and correcting next turn. The
    mutation-guard re-entry (`unverified`) and substantive-tool awaits are
    unchanged."""
    if not (budget > 0 and lt is not None and not unverified):
        return False
    # §4LE: a SELF-REPORT (the agent describing its own state) has no outside
    # evidence to repair it from — "good morning ghost" waited 35 s of 60 on
    # this verdict; it still lands through the deferred/late path
    if str(lt.get("name", "")).lower().strip() in _SELF_REPORT_TOOLS:
        return False
    if not _tool_is_bookkeeping(lt):
        return True
    _raw = lt.get("content", "")
    if _bookkeeping_call_failed(_raw):
        return True
    _c = str(_raw).lstrip()
    _name = str(lt.get("name", "")).lower().strip()
    return (_name.replace("-", "_").replace(" ", "_") == "manage_projects"
            and '"stop_reason"' in _c)


def _find_substantive_tool_for_verifier(
        tools_run: Optional[list], *,
        include_informational_bookkeeping: bool = True) -> Optional[dict]:
    """Return the most recent tool whose output carries verifiable
    evidence (execute output, file content, search results, etc.).

    TWO SEMANTICS, one walk (§4BC round-2 fresh-eye review, 2026-08-12):

    - ``include_informational_bookkeeping=True`` (default) — EVIDENCE view:
      payload-shaped bookkeeping output (≥200 chars) qualifies, so a
      bookkeeping-only listing turn can run the verifier at all.
    - ``include_informational_bookkeeping=False`` — ACTION view: the
      pre-§4BC selection, exactly (bookkeeping skipped unless it ERRORED or
      carries the autoadvance ``stop_reason`` payload). Consumers that ask
      "what did this turn last actually DO" — the unverified-mutation guard,
      code-shape verdict routing, overflow recovery, the UI fallback — MUST
      use this view: under the evidence view a trailing task-table would
      shadow the file write / execute that precedes it, silently disabling
      the req_C0 untested-write guard and demoting code-shaped audits to the
      weaker claim branch (the round-2 review's two MAJORs).

    Walks ``tools_run`` from the end and skips entries whose name is
    in ``_BOOKKEEPING_TOOL_NAMES`` — those produce state-change
    confirmations, not evidence, and feeding them to the verifier
    guarantees a REFUTED verdict (2026-04-19 trace blast radius:
    verifier marked an otherwise-successful run at 10% because the
    evidence slot held `{"exited": "..."}`). When every tool this
    turn was bookkeeping, returns ``None`` so the caller skips the
    verifier entirely — no evidence, no verdict.

    Also skips entries flagged ``_synthetic=True``. Those are
    error/nudge messages the agent loop synthesises when the model
    malforms a tool call (parse errors, invalid JSON args, unknown
    tool, idempotency blocks, etc.). They are NOT real tool output —
    feeding them to the verifier produces "Evidence is irrelevant to
    the claim" REFUTEDs that leak as a user-visible
    ``**Verifier note:**`` line at the end of an otherwise-clean
    conversational reply.
    """
    if not tools_run:
        return None
    for tool in reversed(tools_run):
        if not tool:
            continue
        if tool.get("_synthetic"):
            continue
        name = str(tool.get("name", "")).lower().strip()
        # Handle normalization aliases (agent.py has
        # "managetasks" → "manage_tasks" mapping elsewhere).
        collapsed = name.replace("-", "_").replace(" ", "_")
        if collapsed in _BOOKKEEPING_TOOL_NAMES:
            # NOT `str(...)`: that discards the status before the gate
            # below can read it.
            _c = tool.get("content", "")
            # Informational bookkeeping output IS a reason to run the
            # verifier (§4BC 2026-08-12). This covers the two prior
            # carve-outs and one new class, all via the shared predicate:
            # - error banners (2026-07-25 audit: three describe_file errors
            #   in a row, reply claimed success at 0.95, verifier skipped
            #   "by design" — the exact blind spot where self-report goes
            #   unchecked);
            # - payload-shaped output ≥200 chars (NEW): listings and
            #   reports are the same evidence shape the packer has trusted
            #   since 2026-07-25, but the name-only run-gate meant a
            #   bookkeeping-ONLY turn ("show me all projects") could never
            #   be verified at all — measured cost: 271 of the corpus's 340
            #   bookkeeping-only `unknown` turns, ~57% of all real-turn
            #   unknowns tracing to this gate, and 15-26 unresolved rows
            #   per A/B arm.
            # Bare short confirmations ("SUCCESS: Profile updated.") keep
            # skipping — the 2026-04-19 blast radius (a confirmation in the
            # evidence slot guarantees a REFUTED). The packer-only
            # id-linkage case stays out of the run-gate for the same
            # reason. The ACTION view (include_informational_bookkeeping=
            # False) keeps only the error carve-out here.
            if include_informational_bookkeeping:
                if _bookkeeping_informational(_c):
                    return tool
            elif _bookkeeping_call_failed(_c):
                return tool
            # An autoadvance BATCH OUTCOME is a substantive completion/
            # failure claim, not a state-change confirmation (2026-08-01
            # Mini AI: the turn's only tool was manage_projects autoadvance
            # whose output said "project done" over a FAILED ledger — the
            # run gate skipped, so no verdict, no repair, and the false
            # completion reached the user unchecked). stop_reason is the
            # batch payload's signature key; short mutation confirmations
            # without it keep skipping.
            if collapsed == "manage_projects" and '"stop_reason"' in _c:
                return tool
            continue
        return tool
    return None


def trajectory_task_kind(context) -> str:
    """The trajectory row's ``task_kind``: "probe" for a diagnostic probe,
    "internal" for an internal turn (an explicit kind — bench, leaf — wins
    over it), else the context's explicit kind, else "user_request". Every
    reader that filters ``task_kind == "user_request"`` excludes the rest by
    construction. isinstance gate, not truthiness: a MagicMock context
    auto-vivifies the attribute."""
    _origin = turn_origin(context)
    _tk = getattr(context, "trajectory_task_kind", None)
    _tk = _tk if isinstance(_tk, str) and _tk else None
    if _origin == "probe":
        return "probe"
    if _origin == "internal" and not _tk:
        return "internal"
    return _tk or "user_request"


def turn_origin(context) -> str:
    """"user" or "sim" — which POPULATION this turn belongs to.

    Stamped on the request-started log line so the durable record can be split
    by origin. Self-play, dream and subagent turns enter through the SAME
    `handle_chat` as a human request and logged an identical line, so until
    2026-08-11 nothing downstream could tell them apart:
    `liveness._count_user_turns` counted all of them, and on 08-11 reported 28
    user turns on a box whose true count was ZERO — while the ledgers it exists
    to interpret (foresight, rrf, trajectories) were correctly silent because
    their own simulation gates had excluded those very turns. The denominator
    and the ledgers were counting opposite populations.

    Derived from the read-only skill store, which is what dream builds its
    isolated context with — the SAME derivation as the §4K foresight gate and
    finalize's `is_simulation`. Deliberately not a second definition: a private
    notion of "is this real traffic" that can drift from the gates' notion is
    how the two came to disagree in the first place.

    §4BF Track 1b: an EXPLICIT label on the context wins — bench-bank runs
    ride the same read-only isolation as self-play but are a third
    population ("bench", externally graded), and inheriting "sim" would
    fold them into the population the flywheel exists to be distinguished
    from. This is an override set by the bench path, not a second
    heuristic — the read-only derivation stays the one inference.
    """
    # §4FB (2026-09-06): a DIAGNOSTIC PROBE is a fourth population, decided
    # by the request id the route stamped (`X-Ghost-Origin: probe` →
    # "probe-" prefix) and read through the contextvar handle_chat sets
    # first thing — inherited by the turn's background work, so a probe's
    # late verifier, judge and trajectory writer all see the same answer.
    # Checked FIRST: a probe is a probe whatever context it runs in, and no
    # bench/sim context ever carries a probe-prefixed id. Every consumer
    # that gates on `== "user"` (calibration booking, selfhood, foresight,
    # feedback, lesson credit …) therefore excludes diagnostics for free.
    try:
        from ..utils.logging import (ORIGIN_PROBE, is_probe_request_id,
                                     request_id_context)
        if is_probe_request_id(request_id_context.get()):
            return ORIGIN_PROBE
    except Exception:  # noqa: BLE001 — the predicate must never raise
        pass
    label = getattr(context, "turn_origin_label", None)
    if isinstance(label, str) and label:
        return label
    if getattr(getattr(context, "skill_memory", None), "is_read_only", False) is True:
        return "sim"
    # §4KW (fresh review): a background-job wake, a scheduled task or a watch
    # callback (`job-`/`sched-`/`sub-` ids) is the agent talking to itself —
    # it was recorded as `user_request`, booked calibration and could teach,
    # while `is_internal_request` said internal. AFTER the explicit label and
    # the sim derivation (second review: sub-agents are "sim", coding leaves
    # keep their own kind).
    try:
        from ..utils.logging import request_id_context
        from .autonomous_activity import is_internal_request
        if is_internal_request(request_id_context.get()):
            return "internal"
    except Exception:  # noqa: BLE001
        pass
    return "user"


def _query_has_tokens(text) -> bool:
    """§4KW: does the request carry a significant token? A request of "?" or
    an emoji is non-empty but token-less, and `credit_recent_retrievals`
    then falls back to crediting every recent lesson (third review)."""
    try:
        from ..memory.skills import _trigger_token_set
        return bool(_trigger_token_set(str(text or "")))
    except Exception:  # noqa: BLE001
        return False


def _owner_sentence_for(value: str, episode: str, cue: str = None) -> str:
    """§4QM: the owner's OWN clause (raw words) of ``episode`` that states
    ``value``, for the ledger — the field's predicate cue first, then the
    widest coverage (`attribution.owner_clause_for`); "" when none does."""
    try:
        from ..memory.attribution import owner_clause_for
        return owner_clause_for(str(value or ""), str(episode or ""), cue=cue)
    except Exception:  # noqa: BLE001
        return ""


def turn_may_teach(context) -> bool:
    """§4KD/§4KJ: may THIS turn write to the playbook? False for a
    diagnostic probe (§4FB/§4FS) and for a MEMBER's turn (real traffic, so
    `turn_origin` still says "user", but a non-owner's prompt must not
    become the owner's lesson). The writer itself has the same rule as a
    backstop (`memory.skills.playbook_writes_blocked`). No client name
    appears here: the role header is the only multi-user signal."""
    try:
        # (§4LA) sim and bench too — they were kept out only because isolation
        # nulled the store handle
        if turn_origin(context) in ("probe", "internal", "sim", "bench"):
            return False
        from ..utils.logging import requester_is_member
        return not requester_is_member()
    except Exception:  # noqa: BLE001 — a predicate that cannot decide does not teach (§4LA: failed open)
        return False


def rubric_shadow_eligible(context, traj) -> bool:
    """Is this turn one the verifier DECLINED, on real traffic?

    §4CU. The rubric shadow exists for exactly one population — the turns
    §4CS item D measured as machine-undecidable: real user turns that ran
    no tool, so nothing was executed to check and
    `_find_substantive_tool_for_verifier` correctly returns None. Anything
    else already has, or can have, a verdict from the evidence path, and
    shadowing it would be measuring the rubric against a judge rather than
    against the gap.

    Extracted module-level for the §4CT reason: a gate written inline in a
    4,000-line coroutine can only be pinned by a source-shape proxy, and
    §4BN watched those stay green through a commented-out block, a moved
    helper, a nested helper and a literal `False`.

    Four conditions, and each one is load-bearing:

    * **the feature is ON** — default OFF, checked FIRST so a disabled
      build does no work at all;
    * **real traffic** — `turn_origin`, the canonical predicate, so this
      population cannot drift from the one the liveness denominator and
      the yield view interpret. Self-play and dream turns reach this same
      record site;
    * **no tool ran** — the declined bucket. A turn WITH tool output is
      the verifier's own population;
    * **still unknown** — a turn already resolved (by the inline verdict
      or a human label) needs no shadow, and grading it would spend a
      call to re-answer a settled question.

    ⚠ `context is None` must NOT be eligible. `turn_origin(None)` answers
    "user" by its own correct default, so the absence of a context would
    otherwise read as real traffic — the §4CT fail-open verbatim, in the
    favourable direction, which is the one that has to be withheld.
    """
    try:
        from .rubric_grader import shadow_enabled
        if not shadow_enabled():
            return False
        return _declined_real_turn(context, traj)
    except Exception:                                       # noqa: BLE001
        return False


def knowledge_shadow_eligible(context, traj) -> bool:
    """§4MF: the same declined population as the rubric shadow, for the
    correctness check (`core/knowledge_shadow`), under its own switch."""
    try:
        from .knowledge_shadow import enabled
        return enabled() and _declined_real_turn(context, traj)
    except Exception:                                       # noqa: BLE001
        return False


def _declined_real_turn(context, traj) -> bool:
    """A real OWNER turn that ran no tool and has no verdict yet — the
    population the verifier declines (see `rubric_shadow_eligible`)."""
    try:
        if context is None or traj is None:
            return False
        if turn_origin(context) != "user":
            return False
        from .queued_messages import changed_mid_turn as _cmt
        if _cmt(traj):
            return False        # §4RZ s4-r9: never judged — its request is not its ask
        from ..utils.logging import requester_is_member as _is_member
        if _is_member():
            return False        # the rubric-shadow ledger is the owner's (§4KJ R10)
        if str(getattr(traj, "task_kind", "") or "") != "user_request":
            return False
        if getattr(traj, "tool_calls", None):
            return False
        outcome = str(getattr(traj, "outcome", "") or "").lower()
        if outcome not in ("", "unknown"):
            return False
        return bool(str(getattr(traj, "user_request", "") or "").strip()
                    and str(getattr(traj, "final_response", "") or "").strip())
    except Exception:                                       # noqa: BLE001
        return False


def _turn_had_tool_failure(tools_run: Optional[list]) -> bool:
    """True when ANY tool output this turn looks like a failure.

    This is the HIGH-STAKES flag for the verifier's CONFIRM escalation
    (verifier._escalate_confirm): when a tool failed, a CONFIRMED verdict is
    the only thing keeping the turn out of a structural FAILED label
    (`resolve_turn_outcome` rule 3 outranks rule 4 since the 2026-07-31
    honest-failure decision), so that particular CONFIRMED is worth a
    main-model second opinion.

    Still ANY-failure and still worth escalating after the 2026-08-04 shape
    rule (`resolve_turn_outcome` rule 2b): that rule only covers the subset
    where EVERY call failed AND the reply never said so. The far larger
    "some calls failed, the reply reads clean" population is exactly what
    this escalation exists for, and the shape rule cannot reach it.

    Uses the SAME sniffer the trajectory corpus uses to decide "this tool
    call failed" (`outcome_heuristics.looks_like_tool_error`) rather than a
    second local rule — a duplicated failure definition is how the corpus
    and the operator line came to disagree before. Synthetic entries (parse
    errors, blocked calls, malformed tool calls) are INCLUDED: they are real
    strikes on `execution_failure_count`, which is the counter rule 4 reads.

    Deliberately ANY-failure rather than "the last call failed": rule 4's own
    trigger (`execution_failure_count > 0 and last_was_failure`) is a subset,
    so this never misses a load-bearing case. Live cost on the corpus
    (2026-08-04): 140 of 1488 turns (9.4%) have a failed tool call at all,
    61 of which (4.1%) ended `outcome=passed` — that is the escalation's
    firing rate, roughly 2 extra main-model calls a day.
    """
    if not tools_run:
        return False
    from ..distill.outcome_heuristics import looks_like_tool_error
    from ..tools.outcome import OutcomeStatus
    for tool in tools_run:
        if not tool:
            continue
        content = tool.get("content", "") or ""
        if _designed_stop_result(content):
            continue      # §4MK: asking the user is not a failed call (it paid a main-model escalation)
        # Read the STATUS when the content carries one. `str(...)` threw it
        # away — the same defect `_reconstruct_tool_calls` was fixed for, in
        # this same file, over this same `tools_run_this_turn` list. The
        # sniffer cannot see a refusal (`SYSTEM INSTRUCTION: …`, `SYSTEM
        # BLOCK: …`), so a turn whose only failures were refused mutations
        # looked clean and the CONFIRM escalation never fired: measured, 15
        # turns, 8% of the true high-stakes population.
        #
        # OR, never override — exactly as the corpus reconstruction does. An
        # OK status must not suppress the sniffer's own evidence (a non-zero
        # `EXIT CODE:` banner), and UNRESOLVED is not a verdict at all.
        _st = getattr(content, "status", None)
        if _st is not None and _st not in (OutcomeStatus.OK,
                                           OutcomeStatus.UNRESOLVED):
            return True
        if looks_like_tool_error(str(content), tool.get("name") or ""):
            return True
    return False


# Newest-heavy evidence budget splits for _collect_verifier_evidence,
# indexed by (item count - 1). A single-tool turn keeps the FULL budget —
# behaviourally identical to the old single-output evidence path. The
# 4-way split exists for the claim-relevance path (an older evidence-
# bearing output pulled in alongside the newest three).
_EVIDENCE_BUDGET_WEIGHTS = ([1.0], [0.65, 0.35], [0.5, 0.3, 0.2],
                            [0.4, 0.25, 0.2, 0.15],
                            [0.32, 0.22, 0.18, 0.15, 0.13],
                            [0.28, 0.2, 0.16, 0.14, 0.12, 0.1],
                            # §4IT: two rows past the positional maximum, so the
                            # claim pull has slots on the widest turns — §4HO's
                            # sixth positional slot had filled the table and
                            # switched the pull off exactly where it matters
                            # (a 36-tool research turn: "6 items of 36", no pull)
                            [0.25, 0.18, 0.15, 0.13, 0.11, 0.1, 0.08],
                            [0.22, 0.17, 0.14, 0.12, 0.11, 0.09, 0.08, 0.07])
#: How many items the claim pull may add past the positional picks, chosen
#: greedily by MARGINAL coverage — the claim tokens no picked item carries,
#: IDF-weighted — so the second pull brings the source of a different part
#: of the answer, not a second copy of the first.
_EVIDENCE_CLAIM_PULLS = 2

# §4HO (2026-09-16, req 11a466ff) — the budget follows the turn. A fixed
# 4,000 chars over three positional slots plus one pull gave a 21-tool
# research turn five items at ~800 chars each — a deep_research whose head
# is a SOURCE-FAILURES notice and a blocked fetch, three searches, the PDF
# receipt — and never reached the search result that carried the number
# the judge then refuted as "not in the evidence". Scale with the number
# of substantive candidates (a floor per quoted item), more slots on wide
# turns, and never let a page the site refused take a slot while a live
# candidate remains. `verify_claim` caps at the same maximum.
_EVIDENCE_BUDGET_MIN = 4000
_EVIDENCE_BUDGET_MAX = 12000
_EVIDENCE_BUDGET_PER_CANDIDATE = 600
_EVIDENCE_ITEMS_MAX = 6
_EVIDENCE_DEAD_HEAD_RE = re.compile(r"STATUS:\s*BLOCKED\b")


def _evidence_is_dead(tool) -> bool:
    """A candidate whose head says the site refused the fetch (§4HH)."""
    return bool(_EVIDENCE_DEAD_HEAD_RE.search(str((tool or {}).get("content", ""))[:240]))


def _evidence_budget_for(tools_run) -> tuple:
    """(budget_chars, max_items) for this turn's evidence digest."""
    n = len(_evidence_candidates(tools_run))
    budget = max(_EVIDENCE_BUDGET_MIN,
                 min(_EVIDENCE_BUDGET_MAX, _EVIDENCE_BUDGET_PER_CANDIDATE * n))
    items = 3 if n <= 6 else 4 if n <= 12 else 5 if n <= 20 else _EVIDENCE_ITEMS_MAX
    return budget, items

_EVIDENCE_LABEL_RE = re.compile(r"(?m)^\[([^\]\n]{1,80})\] ")


def _log_evidence_digest(claim_evidence: str, tools_run, budget: int, max_items: int) -> str:
    """§4HS: one INFO line saying what the judge was handed — items packed
    out of how many candidates, chars against the budget. Returns the line
    (empty when there was nothing to pack). Labels are counted only for
    names that are actually candidates, so a body line that happens to
    start with "[x] " is not an item."""
    text = str(claim_evidence or "")
    if not text.strip():
        return ""
    cands = _evidence_candidates(tools_run)
    names = {str(t.get("name", "tool"))[:80] for t in cands}
    n_items = sum(1 for m in _EVIDENCE_LABEL_RE.finditer(text) if m.group(1) in names)
    # max_items bounds the POSITIONAL picks; the claim pull (§4GW/§4HC) may
    # add one more, so the line names the rule rather than a false ceiling.
    line = (f"evidence digest — {n_items} item(s) of {len(cands)} candidate(s), "
            f"{len(text)} chars (budget {budget}, positional ≤{max_items} + claim pull)")
    try:
        from ..utils.logging import Icons, pretty_log
        pretty_log("Verifier", line, icon=Icons.VERIFIER_LAB, durable_only=True)   # §4NV
    except Exception:  # noqa: BLE001 — an instrument never breaks a verdict
        pass
    return line


# §4HC — how far back the claim-relevance scan may look. Ten was the
# whole window; a research turn runs 30+ tools and its sources sit early.
_EVIDENCE_DEEP_WINDOW = 40

# Token-set Jaccard above which two outputs are the SAME evidence twice.
# Measured on the live turn: same-image OCR pairs 0.69 and 0.60, every
# genuinely different pair below 0.30 — 0.5 sits in open water.
_EVIDENCE_DUP_JACCARD = 0.5

def _trim_corrections(queue) -> list:
    """§4LH final review: one queue, capped at ``_CORRECTION_MAX`` — member
    research refutes (bound to an answer by ``|r<tag>``) evicted the OWNER's
    pending correction. Each side keeps its own newest ``_CORRECTION_MAX``."""
    q = list(queue or [])
    # by WHO the correction is for (§4LK review: every correction is bound
    # now, so splitting on the binding put the owner's with the members')
    bound = [c for c in q if isinstance(c, dict) and c.get("member")]
    rest = [c for c in q if not (isinstance(c, dict) and c.get("member"))]
    keep = {id(c) for c in rest[-_CORRECTION_MAX:]} | {id(c) for c in bound[-_CORRECTION_MAX:]}
    return [c for c in q if id(c) in keep]


def _reply_norm(text) -> str:
    """A reply's words, normalised to survive the Slack round trip and the
    notes added around a shipped reply: system notes and either banner markup
    stripped, image markdown and Slack :shortcodes: removed, links reduced to
    their labels, URLs dropped, then letters and digits only, lower case."""
    try:
        from .reply_smoothing import strip_system_notes
        t = strip_system_notes(str(text or ""))
    except Exception:  # noqa: BLE001
        t = str(text or "")
    t = re.sub(r"\A\s*(?:⚠️|ℹ️|:warning:|:information_source:)[^\n]{0,2000}\n(?:[^\n]{0,2000}\n){0,6}?\s*-{3,}\s*\n", "", t)
    t = re.sub(r"!\[[^\]\n]{0,300}\]\([^)\s]{0,500}\)", " ", t)          # images (Slack drops them)
    t = re.sub(r":[a-z0-9_+-]{1,40}:", " ", t)                             # Slack emoji shortcodes
    t = re.sub(r"<https?://[^|>]*\|([^>]*)>", r"\1", t)
    t = re.sub(r"\[([^\]\n]{0,300})\]\(https?://[^)\s]+\)", r"\1", t)
    t = re.sub(r"https?://\S+", " ", t)
    return re.sub(r"[\W_]+", "", t.lower())


#: how much of a reply's opening identifies it
_REPLY_KEY_CHARS = 120


def _reply_tag(text) -> str:
    """§4LH/§4LK: a short tag of a reply's opening words. A queued correction
    carries the tag AND the opening itself (``|k``) of the answer it corrects;
    it surfaces only in a thread whose history CONTAINS that answer — a header
    put before it or a note after it (the clarify question, a digest, the
    "not run" note) no longer breaks the match (§4LK review)."""
    core = _reply_norm(text)[:_REPLY_KEY_CHARS]
    if not core:
        return ""
    import hashlib
    return hashlib.sha1(core.encode("utf-8")).hexdigest()[:10] + "|k" + core


#: §4LH: batches whose text-alongside is narration, not an answer.
_PRE_TOOL_LOOKUP_TOOLS = frozenset({
    "web_search", "darkweb_search", "deep_research", "darkweb_research", "browser",
    "fact_check", "news_headlines", "recall", "knowledge_base", "query_document",
})


def _all_lookup_calls(tool_calls) -> bool:
    names = []
    for tc in tool_calls or []:
        fn = (tc.get("function") if isinstance(tc, dict) else None) or {}
        names.append(str(fn.get("name") or (tc.get("name") if isinstance(tc, dict) else "") or ""))
    return bool(names) and all(n in _PRE_TOOL_LOOKUP_TOOLS for n in names)


#: §4OG-4 (e): the one kind of batch whose text-alongside IS the answer — a
#: memory write ("Saved that." / the profile fact) at the end of a reply
_PRE_TOOL_BOOKKEEPING_TOOLS = frozenset({"remember", "update_profile", "forget", "reset_all", "learn_skill"})


def _narration_batch(tool_calls) -> bool:
    """§4OG-4 (e): text written beside THIS batch is working narration — every
    tool kind except a memory-write-only batch. Recording lookup batches only
    (§4LH) left the coding probe's reply opening with five superseded status
    notes written beside file_system/execute/manage_projects calls (§4OF)."""
    names = []
    for tc in tool_calls or []:
        fn = (tc.get("function") if isinstance(tc, dict) else None) or {}
        names.append(str(fn.get("name") or (tc.get("name") if isinstance(tc, dict) else "") or ""))
    return bool(names) and not all(n in _PRE_TOOL_BOOKKEEPING_TOOLS for n in names)


#: §4LH: the tools a member's turn may run whose output is the open web —
#: nothing of the owner's. A member turn that ran only these is verified.
_MEMBER_RESEARCH_TOOLS = frozenset({"web_search", "darkweb_search"})


def _member_research_turn(tools_run) -> bool:
    """True when every real tool this turn ran is open-web research (and at
    least one ran). ``GHOST_VERIFY_MEMBER_RESEARCH=0`` restores the old
    "members are never verified"."""
    if os.environ.get("GHOST_VERIFY_MEMBER_RESEARCH", "1") == "0":
        return False
    names = [str(t.get("name") or "") for t in (tools_run or [])
             if isinstance(t, dict) and not t.get("_synthetic")]
    return bool(names) and all(n in _MEMBER_RESEARCH_TOOLS for n in names)


# Tools whose output comes from OUTSIDE the agent's own writes. Anything
# else (file_system, report_pdf, workspace, manage_projects, …) may be the
# deliverable echoing itself and ranks BELOW these for the claim pull —
# still eligible, so a turn with no external tool behaves as before.
_EXTERNAL_EVIDENCE_TOOLS = frozenset({
    # §4LG: + darkweb_research and fact_check — their outputs ranked below
    # the outside-world tools in the digest and could not be pulled in as
    # support for the claim they were the source of
    "darkweb_research", "fact_check",
    "browser", "web_search", "darkweb_search", "deep_research", "execute",
    "vision_analysis", "news_headlines", "query_document", "knowledge_base",
    "database", "postgres_admin", "recall", "system_utility",
})


_RECEIPT_HEAD_RE = re.compile(r"^\s*(?:SUCCESS:|POST-EDIT VIEW|Wrote |Written |Saved |Created |Applied |File (?:written|saved|created)|Deleted |Moved |Copied )", re.IGNORECASE)


def _looks_like_receipt(tool) -> bool:
    """The agent's own write receipt or the deliverable's echo — not a read
    of a source. A `file_system` READ carries the file's text, not a receipt
    head (review §4IY)."""
    name = str((tool or {}).get("name", "")).lower().strip().replace("-", "_").replace(" ", "_")
    body = str((tool or {}).get("content", ""))
    if name in ("report_pdf", "workspace", "manage_projects", "workspace_track", "notify_operator"):
        return True
    return bool(_RECEIPT_HEAD_RE.match(body[:120]))


def _evidence_is_external(tool) -> bool:
    name = str((tool or {}).get("name", "")).lower().strip()
    return name.replace("-", "_").replace(" ", "_") in _EXTERNAL_EVIDENCE_TOOLS


def _claim_overlap_scorer(claim_tokens, candidates):
    """Score a candidate by the claim tokens it shares, each weighted by
    how RARE that token is across this turn's candidates (log N/df).

    Raw overlap counts ranked every source alike on "revolut", "breach",
    "government" — words in all 38 outputs of the live turn — so four
    near-identical OCRs of one card out-scored the one browser extraction
    that carried the claim's distinctive strings ("legalmail", "InfoCert",
    "Milan") and the sentence refuting it. A judge needs the source the
    claim's DISTINCTIVE content came from; rarity is what points at it.
    Same lesson as the §4AP BM25 fallback: a match without IDF matches
    everything. Returns ``(score_fn, raw_overlap_fn, near_duplicate_fn)``.
    """
    import math
    toks = [(_claim_tokens(str(t.get("content", ""))[:24000])) for t in candidates]      # §4IY: two same-site pages share ~15k of nav
    n = max(1, len(toks))
    df = {}
    for ts in toks:
        for w in (claim_tokens & ts):
            df[w] = df.get(w, 0) + 1
    weight = {w: math.log((n + 1) / (df.get(w, 0) + 1)) + 0.05 for w in claim_tokens}
    by_id = {id(t): ts for t, ts in zip(candidates, toks)}

    def score(tool) -> float:
        ts = by_id.get(id(tool))
        if ts is None:
            ts = _claim_tokens(str(tool.get("content", ""))[:24000])
        return sum(weight.get(w, 0.0) for w in (claim_tokens & ts))
    score.weight_of = lambda w: weight.get(w, 0.0)      # §4IT: the marginal pull sums per-token weights

    def raw(tool) -> int:
        ts = by_id.get(id(tool))
        if ts is None:
            ts = _claim_tokens(str(tool.get("content", ""))[:24000])
        return len(claim_tokens & ts)

    def near_duplicate(tool, others) -> bool:
        """True when `tool` re-states an already-picked item. Two OCRs of
        one image sat at Jaccard 0.69 / 0.60 in the live turn and every
        genuinely different pair under 0.30 — a second copy of the same
        evidence buys the judge nothing and costs a slot."""
        ts = by_id.get(id(tool))
        if ts is None:
            ts = _claim_tokens(str(tool.get("content", ""))[:24000])
        for o in others:
            os_ = by_id.get(id(o))
            if os_ is None:
                os_ = _claim_tokens(str(o.get("content", ""))[:24000])
            union = len(ts | os_)
            if union and len(ts & os_) / union >= _EVIDENCE_DUP_JACCARD:
                return True
        return False

    return score, raw, near_duplicate


_EVIDENCE_CLAIM_STOPWORDS = frozenset({
    "the", "a", "an", "and", "or", "of", "to", "in", "on", "for", "with",
    "is", "are", "was", "were", "be", "been", "it", "its", "this", "that",
    "i", "you", "your", "have", "has", "had", "now", "then", "will",
    "can", "not", "no", "task", "project", "done", "complete", "completed",
    "successfully", "verified", "user",
    # Greek function words (§4IT): the tokenizer reads Unicode words now, and
    # without these every Greek reply overlaps every Greek source on "και/του/της"
    "και", "του", "της", "των", "τον", "την", "τους", "τις", "στο", "στη", "στην",
    "στον", "στα", "στις", "στους", "για", "από", "με", "που", "είναι", "ήταν",
    "έχει", "έχουν", "αυτό", "αυτή", "αυτά", "ένα", "μια", "μία", "δεν", "θα",
    "να", "ως", "πως", "ότι", "όπως", "επίσης", "ενώ", "αλλά", "μετά", "πριν",
    "κατά", "προς", "υπό", "ακόμη", "ακόμα", "πολύ", "εδώ", "εκεί", "μέσω",
})

#: A claim token: a Unicode word of three or more letters (Greek replies
#: produced NO tokens under the old `[a-zA-Z_]` rule — the claim pull had
#: nothing to match the source on, req probe-012ca9ec §4IT), or a bare
#: year — the item that carries the claim's "2009" is the item to pull.
_CLAIM_TOKEN_RE = re.compile(r"[^\W\d_]\w{2,}|(?<!\d)(?:1[89]|2[0-9])\d{2}(?!\d)")


# The inverted-trim guard (2026-07-25) moved to core.reply_smoothing in
# §4FV so the two delivery paths and `treat_reply` cannot drift apart; the
# name stays here because both finalize sites and a pin import it from
# agent.
from .reply_smoothing import is_narration_only_trim as _is_narration_only_trim


def _build_memory_arc(history, ai_text, *, tools_run, user_text=None) -> str:
    """The smart-memory arc for one turn: the last four user/assistant
    messages plus the DELIVERED reply, fenced code stripped, 500 chars each.

    ONE implementation for both delivery paths (§4FV, 2026-09-10). The two
    sites were hand-mirrored and remembered different text for the same
    turn: the streamed twin read the raw accumulator, and the non-stream one
    runs inside the turn loop, BEFORE `_finalize_and_return` scrubs and
    smooths `final_ai_content` in place — so an arc's first 500 chars were
    often the turn's opening narration ("Let me check the file first.")
    rather than its answer. Treating here is idempotent, so a caller that
    already holds the treated view may pass it.
    """
    from .reply_smoothing import count_real_tools, treat_reply
    turns = [m for m in (history or [])
             if isinstance(m, dict) and m.get("role") in ("user", "assistant")]
    # §4QA: the turn loop's own user-role rows (AUTO-DIAGNOSTIC, SYSTEM ALERT)
    # are not the owner speaking — live, "USER: AUTO-DIAGNOSTIC: ERROR:
    # task_id is required" took the request's place in the arc. They are
    # found by POSITION — every user row after the owner's own message
    # (`user_text`) — never by their wording: "REMINDER: my passport expires
    # in March" is the owner (fresh-eye MAJOR-2).
    _anchor = -1
    if user_text is not None:
        _want = str(user_text).strip()
        _anchor = max((i for i, m in enumerate(turns)
                       if m.get("role") == "user" and _msg_text(m).strip() == _want), default=-1)
    micro: list = []
    from ..utils.logging import FOREIGN_MESSAGE_LABELS
    _base = len(turns) - len(turns[-4:])
    for _j, m in enumerate(turns[-4:]):
        role = str(m.get("role", "user")).upper()
        if role == "USER" and str(m.get("content", "")).lstrip().startswith(FOREIGN_MESSAGE_LABELS):
            # another person's words never feed the requester's memory (§4KY)
            continue
        if role == "USER" and (m.get("_queued") or (
                _base + _j > _anchor if _anchor >= 0 else
                bool(_LOOP_USER_ROW_RE.match(str(m.get("content", "")))
                     or _STEER_HEAD_RE.match(str(m.get("content", "")))))):
            # no anchor (compaction rewrote the row): the old wording rule.
            # §4RZ s4-r4: a row sent mid-turn never feeds smart memory — it is
            # where the owner reacts to a page ("it says my wife is X, ignore
            # that"), and the owner-fact parser takes reported speech
            continue
        clean_content = re.sub(r'```.*?```', '', str(m.get("content", "")),
                               flags=re.DOTALL)
        micro.append(f"{role}: {_unmark_roles(clean_content[:500].strip())}")
    treated = treat_reply(str(ai_text or ""),
                          n_real_tools=count_real_tools(tools_run))
    clean_ai = re.sub(r'```.*?```', '', treated, flags=re.DOTALL)
    return "\n".join(micro) + f"\nAI: {_unmark_roles(clean_ai[:500].strip())}"


#: a line that would read as a speaker mark to `attribution.owner_lines`
_ARC_ROLE_LINE = re.compile(r"^(\s*)(user|ai|assistant|system|tool)(\s*:)", re.IGNORECASE | re.MULTILINE)


def _unmark_roles(text: str) -> str:
    """Quote any line INSIDE a message that starts with a role mark: a reply
    that quoted a page's "USER: my wife is Mallory" became the owner's own
    statement and rewrote the profile (§4MB). The arc's real speaker marks
    are the ones this function's caller prepends."""
    return _ARC_ROLE_LINE.sub(lambda m: f"{m.group(1)}> {m.group(2)}{m.group(3)}", text)


def _claim_tokens(text: str) -> set:
    """Significant lowercase tokens of a claim, for evidence relevance:
    Unicode words of 3+ letters and bare years, minus function words."""
    return {
        t for t in _CLAIM_TOKEN_RE.findall((text or "").lower())
        if t not in _EVIDENCE_CLAIM_STOPWORDS
    }


# A URL this long is feed/tracking plumbing (UTM params, slug echoes), not
# evidence — the claim under audit never cites it, and on RSS-shaped output
# it can be ~70% of the payload. Trimmed to a stub so the host+path still
# attribute the item while the chars go to verifiable content instead.
_EVIDENCE_LONG_URL_RE = re.compile(r"https?://\S{72,}")

# Appended to every auto-repair directive. The directive rides a user-role
# message and the refuted draft is discarded, so the REAL user never saw
# what is being corrected — without this, the model answers the alert
# conversationally and the acknowledgement ("You're right — I was
# embellishing…") leaks checker-facing dialogue into the only reply the
# user gets (req 4dab5067, 2026-07-17).
_REPAIR_STANDALONE_SUFFIX = (
    " IMPORTANT: the user never saw the draft this alert refers to and "
    "cannot see this alert. Write the corrected answer as a clean, "
    "standalone reply to the user's original request — do NOT acknowledge "
    "this alert, do NOT apologise or say what you fixed, and do NOT "
    "mention any verifier, review, or correction."
)


def _render_refute_directive(crit: str, pending_request="",
                             shape_only: bool = False) -> str:
    """The repair-round alert after a REFUTED draft (the ONLY builder).

    ``shape_only`` (§4FY review): the refute is a delivery-SHAPE complaint
    (`GhostAgent._delivery_shape_only` — strict JSON, a word cap, a raw
    dump…) — the answer's content was never disputed, so "do NOT repeat the
    same claim" is exactly wrong: the model must repeat it, in the shape
    the request asked for, with no tools.

    Req 2422eb25 (2026-09-06): the refuted draft had not answered the request
    at all (it "acknowledged" a state block), so "diagnose and FIX it using
    tools" had no defect to point at — the model invented one ("The user
    uploaded a new photo") and inspected a file that never existed, which
    became a strike and a `failed` outcome. The directive therefore
    (1) restates WHICH request is being answered and that nothing new has
    arrived, (2) says the repair may need NO tool call when the evidence
    already in the conversation answers it, and only then (3) asks for a
    tool-grounded diagnosis. ``pending_request`` is the loop's
    ``last_user_content``; the quote is bounded by ``_pending_request_head``.
    """
    which = _which_request_line(pending_request)
    if shape_only:
        return (
            "SYSTEM ALERT — the verifier REFUTED the SHAPE of your previous "
            f"answer, not its content: {str(crit or '').strip()}. {which} "
            "Re-send the SAME answer in exactly the form that request asked "
            "for — no preamble, no explanation, no extra lines or sentences "
            "— and make NO tool calls. If your previous answer said the task "
            "could not be done, keep saying so, as briefly as the form allows: "
            "NEVER invent a value, number or result to satisfy the format."
        )
    return (
        "SYSTEM ALERT — the verifier REFUTED your previous answer: "
        f"{str(crit or '').strip()}. Do NOT repeat the same claim. {which} "
        + ("No new file or task has arrived beyond the user's messages named above — do not "
           "invent one. If " if _queued_delivered_any() else
           "No new file, message or task has arrived — do not invent one. If ") +
        "the evidence already in this conversation answers that request, "
        "answer it now from that evidence with NO new tool calls. Only if a "
        "claim genuinely needs checking, diagnose the underlying problem and "
        "FIX it using tools (run / test / inspect the ACTUAL result), then "
        "give a corrected final answer grounded in that evidence."
    )


# ── The per-turn <system_state_update> block is a USER-ROLE message, and the
# transcript therefore claims the human spoke. That role is forced: the live
# Ornith/Qwen template raises "System message must be at the beginning" for a
# system-role tail, and a role:"tool" message renders as a user turn too. Since
# §4ET Fix 2 (2026-09-04) the block rides ALONE on the trailing message of
# every turn >= 2 (folding it onto the tool result re-prefilled that result
# every turn), and the model read that lone message as a fresh human turn with
# no question in it: req 2422eb25 (2026-09-06) held the finished vision
# description, replied with a 330-char "acknowledging the update" instead,
# was REFUTED, and the repair turn invented a filename from the block's
# CURRENT TIME. Two earlier requests since that deploy (48187b80, 0c7c2bb5)
# show the same "state update but no new user message" reasoning and only
# recovered by luck; before the deploy no thinking line ever read the block
# as a human turn. Every block is therefore built HERE and opens by saying
# whose message it is NOT and which request is still pending — the exact two
# facts the model went looking for and could not find.
# tests/test_volatile_block_provenance.py enumerates the module tree so no
# other site can assemble a block without that header.
_VOLATILE_BLOCK_OPEN = "<system_state_update>"
_VOLATILE_BLOCK_CLOSE = "</system_state_update>"
#: The pending-request line is a bounded, single-line QUOTE of the request
#: head — enough to re-identify the request, never a second copy of it.
_PENDING_REQUEST_HEAD_CHARS = 160


def _pending_request_head(request_text) -> str:
    """One bounded line naming the request the turn is still serving.

    Whitespace-collapsed (a multi-line request must not break the block's
    line structure) and cut at ``_PENDING_REQUEST_HEAD_CHARS`` with an
    ellipsis, so a pasted document costs a fixed ~40 tokens, not a re-prefill
    of itself on every turn.
    """
    text = " ".join(str(request_text or "").split())
    if len(text) > _PENDING_REQUEST_HEAD_CHARS:
        text = text[:_PENDING_REQUEST_HEAD_CHARS].rstrip() + "…"
    return text


def _live_request_reminder(request) -> str:
    """The AUTO-DIAGNOSTIC's closing re-anchor on the live request (req 43,
    2026-07-17: after the diagnostic flood the model re-ran the PREVIOUS
    request's flow); §4RZ step 2: with what the user added mid-turn."""
    if not request:
        return ""
    return ("\n\nREMINDER — the CURRENT user request you are "
            f"working on: \"{str(request)[:300]}\"." + _queued_added_line() + " "
            "Continue that task from where it stands; do NOT "
            "restart earlier requests' flows.")


#: `verify_visual` cuts the symptom at 1,000 characters; `current_ask` fits the
#: additions inside it (s2-r7: a long request pushed them past the cut)
_VISUAL_SYMPTOM_CHARS = 1000


def _queued_delivered_any() -> bool:
    from .queued_messages import delivered as _d
    return bool(_d())


def _which_request_line(pending_request) -> str:
    """The one sentence that names the request a runtime alert is about —
    shared by the refute directive (req 2422eb25) and, since §4KV, every
    forced-report alert and the thinking-loop steer: an alert is a user-role
    message, and a model that is not told which request it serves answers
    the alert, or the conversation, instead."""
    from .queued_messages import added_line as _added
    head = _pending_request_head(pending_request)
    added = _added()
    if added:                   # §4RZ step 2: not "unchanged" — the user added to it
        return ((f'THE REQUEST YOU ARE ANSWERING: "{head}".' if head
                 else "The request you are answering is the user's most recent one.") + added)
    return (f'THE REQUEST YOU ARE ANSWERING (unchanged): "{head}".' if head
            else "The request you are answering is the user's most recent "
                 "one (unchanged).")


def _render_volatile_block(dynamic_state: str, pending_request="") -> str:
    """The ONLY assembler of a ``<system_state_update>`` block.

    ``dynamic_state`` is the per-turn state (CURRENT TIME, scrapbook, plan
    focus …); ``pending_request`` is the CURRENT request's text (the
    request-loop's ``last_user_content``, NOT the first message of a session
    with history). The block opens with its provenance — not from the user,
    nothing new was sent, this request is still pending — before any state,
    so it is the first thing read on the message the model would otherwise
    mistake for a human turn.
    """
    from .queued_messages import added_line as _added
    head = _pending_request_head(pending_request)
    added = _added()
    if added:
        # §4RZ step 2: the user DID send something while the turn ran
        pending = (f'PENDING REQUEST: "{head}"' if head
                   else "PENDING REQUEST: the user's most recent request (not this block)")
        opening = (f"(Automated runtime state — NOT a message from the user. {pending}.{added} "
                   "Continue from where the work stands; when the request and those messages "
                   "are answered, reply to the user.)\n")
    else:
        if head:
            pending = f'PENDING REQUEST (unchanged): "{head}"'
        else:
            pending = "PENDING REQUEST: the user's most recent request (not this block)"
        opening = ("(Automated runtime state — NOT a message from the user. The user has "
                   "sent NOTHING new since their request and there is no new question "
                   f"here. {pending} — continue that request from where it stands; when "
                   "it is fully answered, reply to the user.)\n")
    return (
        f"{_VOLATILE_BLOCK_OPEN}\n"
        + opening +
        f"{str(dynamic_state or '').strip()}\n"
        "(CRITICAL: This is internal system state. Do NOT acknowledge or "
        "comment on this block in your thoughts. Focus entirely on the "
        "pending request.)\n"
        f"{_VOLATILE_BLOCK_CLOSE}"
    )


# ── §4RC: the state block is shown whole ONCE per request, then stays put.
# It used to be rebuilt as the trailing message of every turn, so each tool
# turn dropped the previous copy and re-processed a new one: ~650 tokens at
# the median, 1.4k at p90 and 5k on coding turns (10-07 → 10-24: 18.4M chars
# on later turns ≈ 10 h of 27B prompt processing). With GHOST_STATE_ANCHOR=1
# the request's first (whole) block is re-inserted where it was shown, and
# each later turn's trailing message — never kept — carries every section
# that changed since that block. A turn therefore re-processes at most what
# it did before, minus the sections that never changed, and the history
# holds exactly one block (reviews r1–r3: every scheme that KEPT changes
# piled up copies on coding requests and re-read history at a reset). The
# trailing message is still a <system_state_update> (provenance header, the
# pending request), so the model's view of "whose message is last" is
# unchanged.
STATE_ANCHOR_ENV = "GHOST_STATE_ANCHOR"
#: The one block kept in place counts against the history budget
#: (``_state_anchor_extra_tokens``) and the read headroom.
_STATE_ANCHOR_MAX_REQUESTS = 32


def _state_anchor_enabled() -> bool:
    return os.environ.get(STATE_ANCHOR_ENV, "0").strip() == "1"


def _msg_fingerprint(msgs) -> str:
    """Role + content of every request message an anchored block was shown
    after. Any change before it (r4: compression summarising an earlier
    request's tool output kept the message right before the block) means
    the prompt diverges there anyway, and the block is shown whole again —
    what the old layout cost."""
    h = hashlib.sha1()
    for m in msgs:
        try:
            raw = json.dumps([m.get("role"), m.get("content")], sort_keys=True,
                             ensure_ascii=False, default=str)
        except Exception:  # noqa: BLE001
            raw = repr(m)
        h.update(raw.encode("utf-8", "ignore"))
        h.update(b"\x00")
    return h.hexdigest()[:16]


def _state_sections(parts, sandbox_root) -> dict:
    """The turn's state as ordered named sections, host sandbox paths
    scrubbed per section; joined, the text the block always had."""
    out = {}
    for key, text in parts:
        out[key] = out.get(key, "") + _scrub_host_sandbox_paths(text or "", sandbox_root)
    return out


def _state_sections_pinned(sections: dict, final_directive, playbook) -> dict:
    """Under the pin the final-answer directive and the playbook ride the
    front of the block (unscrubbed, as before); joined, the pinned block."""
    return {"final_directive": (final_directive + "\n") if final_directive else "",
            "playbook": playbook or "", **sections}


_STATE_CHANGES_INTRO = ("(Changes since the state update at the start of this request — "
                        "every section not listed here is unchanged.)\n")
_STATE_NO_CHANGE = "(No change since the state update at the start of this request.)"


_LISTING_COUNT_RE = re.compile(r"^(\d+) entries under ", re.M)
_LISTING_SIGS_RE = re.compile(r"^(.*?\.py)  \[(?:def|class) ")


def _listing_entries(text: str):
    """The entry lines of a sandbox listing keyed by path, in order —
    empty when it has none, is capped (a capped listing drops entries past
    the cap, so a missing one need not be gone), or does not parse to the
    count it states (review: names with two spaces or a newline collided,
    and a deletion vanished from the diff)."""
    out: dict = {}
    m = _LISTING_COUNT_RE.search(text)
    if not m or "more files NOT shown" in text:
        return out
    for ln in text.splitlines():
        if ln.startswith("  ") and ln.strip() and not ln.startswith("  ..."):
            sig = _LISTING_SIGS_RE.match(ln[2:])
            out[sig.group(1) if sig else ln[2:]] = ln
    return out if len(out) == int(m.group(1)) else {}


def _listing_changes(base: str, cur: str) -> str:
    """§4RW-d: the sandbox listing as the entries added, changed or removed
    since the request's first block — that block still holds the rest. A
    write used to put the whole listing (8.6k chars on the owner's 134-file
    workspace) back on every later turn. "" when no diff can be trusted."""
    old, new = _listing_entries(base), _listing_entries(cur)
    if not old or not new:
        return ""
    added = [ln for p, ln in new.items() if p not in old]
    changed = [ln for p, ln in new.items() if p in old and old[p] != ln]
    removed = [p for p in old if p not in new]
    count = next((ln for ln in cur.splitlines() if " entries under " in ln), "")
    lines = ["CURRENT SANDBOX STATE — changes to the listing shown at the start of this "
             "request (every other entry there still holds):"]
    if count:
        lines.append(count)
    if added:
        lines += ["Added:"] + added
    if changed:
        lines += ["Changed:"] + changed
    if removed:
        lines.append("Removed: " + ", ".join(f"`{p}`" for p in removed))
    return "\n".join(lines) + "\n\n"


def _state_changes(base: dict, sections: dict) -> str:
    """§4RC: every section that differs from the request's first block
    (``base``), at its current value, plus one line per section that went
    away. Sent each turn and never kept (r3: keeping changes, even only
    the rarer ones, piled up copies on coding requests), so a turn
    re-processes at most what the old layout did, minus the sections that
    never changed. §4RW-d: the sandbox listing goes as its entry changes
    when those are shorter."""
    out = []
    for k, t in sections.items():
        if not t or base.get(k) == t:
            continue
        if k.startswith("sandbox_state") and base.get(k):
            d = _listing_changes(base[k], t)
            if d and len(d) < len(t):
                t = d
        out.append(t)
    for key, text in base.items():
        if text and not sections.get(key):
            first = next((ln.strip() for ln in text.splitlines() if ln.strip()), key)
            out.append(f'(The earlier "{first[:80]}" section no longer applies.)\n')
    if not out:
        return _STATE_NO_CHANGE
    return _STATE_CHANGES_INTRO + "\n".join(x.rstrip("\n") + "\n" for x in out)


# ── §4KV: the label between the injected context and the user text it rides on.
# The pinned <session_context> block is prefixed onto the FIRST user message
# (a position that never moves, for the KV cache) and used to be followed by
# "[USER INSTRUCTION]" unconditionally. In a conversation with history the
# first user message is NOT the instruction: req slack-124c85b8 (2026-10-01)
# was the twelfth message of a Slack thread, the block told the model to
# "focus entirely on the user instruction", the message under that label was
# the thread's opening question from five hours earlier — and turn 1 set out
# to answer it ("The user wants to know if George Delaportas is a genius").
# The label now says what the message IS: the instruction only when its text
# is the pending request; otherwise a line that is true of any message.
_INSTRUCTION_LABEL = "[USER INSTRUCTION]"
_CONVERSATION_START_LABEL = (
    "[CONVERSATION START — the request to answer now is the user's MOST RECENT "
    "message (quoted as PENDING REQUEST in the state update at the end), which "
    "is not necessarily this one]")
_NEWEST_MESSAGE_LABEL = (
    "[NEWEST MESSAGE — the request to answer is the one quoted above as "
    "PENDING REQUEST]")


_NEWEST_MESSAGE_ADDED_LABEL = (
    "[NEWEST MESSAGE — the request to answer is the one quoted above as PENDING "
    "REQUEST, with the messages the user sent while you worked]")
_QUEUED_CARRIER_LABEL = (
    "[NEWEST MESSAGE — sent by the user while you worked: part of the request "
    "quoted above as PENDING REQUEST]")


def _message_text(content) -> str:
    """The text of a message's content (a string, or the text parts of a
    structured list), whitespace-collapsed — the form two copies of one
    request are compared in."""
    if isinstance(content, list):
        content = " ".join(str(i.get("text", "")) for i in content
                           if isinstance(i, dict) and i.get("type") == "text")
    return " ".join(str(content or "").split())


def _carrier_label(carrier_content, pending_request, otherwise: str, *,
                   holds_request: bool = False) -> str:
    """The label for the message an injected block is prefixed onto:
    ``[USER INSTRUCTION]`` when that message is the pending request (or
    ``pending_request`` is None — a caller that names none), else
    ``otherwise``.

    ``holds_request``: the caller knows only ONE user message arrived. Then
    the carrier is the request if it merely CONTAINS the request's text — a
    request whose image part was flattened into an "[Image attached …]" note
    no longer equals it. Containment is not trusted without that knowledge
    (in a thread, the newest "ok" is contained in half the earlier
    messages), and the count is not trusted without containment (the first
    user-role message can be a translated tool row, or what an emergency
    prune left).

    Both ``otherwise`` labels are true of ANY message, so a comparison that
    fails because the request was rewritten on the way in costs a weaker
    label, never a false one; an earlier message with the request's exact
    text gets the instruction label, which is harmless — it is the same
    instruction."""
    if pending_request is None:                  # a caller that names no request
        return _INSTRUCTION_LABEL
    want = _message_text(pending_request)
    have = _message_text(carrier_content)
    from .queued_messages import QUEUED_LABEL as _QL, delivered as _qd
    if _qd() and otherwise != _CONVERSATION_START_LABEL:
        # §4RZ step 2: only once something was delivered (a request that
        # merely starts with the label text is still the request), and never
        # for the first message (a queued row is never it; s2-r2: its label
        # flipped mid-request — a re-prefill)
        if have.startswith(_QL):                  # the user's mid-turn message
            return _QUEUED_CARRIER_LABEL
        if otherwise == _NEWEST_MESSAGE_LABEL:    # a tool row: name the additions too
            otherwise = _NEWEST_MESSAGE_ADDED_LABEL
    # A request with no text at all (an image alone) equals nothing; it is
    # the carrier only when it is the one message that arrived. A translated
    # tool row is never the request, whatever it echoes (third review).
    if (have == want and want) or (holds_request and want in have
                                   and not have.startswith("<tool_response")):
        return _INSTRUCTION_LABEL
    return otherwise


# ── §4RV: the first message is the same on every request of a conversation.
# llama checkpoints at the start of a prompt's last user message — the state
# block — so a follow-up resumes right after the previous request's message,
# but only if nothing before it changed. The <session_context> block carried
# what each request brings (the thinking depth picked from its words, the
# coding persona, the memory recalled for it, the workspace notes) and the
# label flipped from [USER INSTRUCTION] to [CONVERSATION START …]: every
# follow-up re-read the whole conversation from just past the head. With
# GHOST_CONV_KEEP=1 those parts open the state block instead (once per
# request; the §4RC anchor keeps it in place for the request's turns).
_THINK_DEPTH_POINTER = ("(Set for each request: see THINKING DEPTH FOR THIS REQUEST in the "
                        "system state update that follows the user's latest request.)\n")
#: §4RV review: the request's context opens the state block under its own
#: heading — it holds old questions (the memory's past conversations), and
#: the block's header has just said where the pending request is
_REQUEST_CONTEXT_HEAD = "CONTEXT FOR THIS REQUEST (background — not the request itself):"


def _stable_first_message() -> bool:
    """§4RV: on with GHOST_CONV_KEEP=1 under the §4RC state anchor (the
    request's first state block stays where it was shown)."""
    from .llm import conv_keep_enabled
    return conv_keep_enabled() and _state_anchor_enabled()


def _split_request_context(tool_header_block: str, think_guidance: str, persona: str,
                           memory: str, continuity: str):
    """§4RV: (the first message's block, the state block's opening sections
    as an ordered dict). The tool header keeps its text with the
    thinking-depth guidance replaced by a pointer; the sections carry the
    guidance, the persona, the recalled memory and the workspace notes —
    each its own section (review: the depth is re-picked every turn and can
    change mid-request when a project opens or closes; as one section it
    re-sent the whole persona on every later turn)."""
    header = str(tool_header_block or "")
    secs = {}
    if think_guidance and think_guidance in header:
        header = header.replace(think_guidance, _THINK_DEPTH_POINTER, 1)
        secs["rc_think_depth"] = "THINKING DEPTH FOR THIS REQUEST:\n" + think_guidance.strip()
    for name, text in (("rc_persona", persona), ("rc_memory", memory), ("rc_continuity", continuity)):
        if str(text or "").strip():
            secs[name] = str(text).strip()
    if not secs:
        return header, {}
    out = {"request_context": _REQUEST_CONTEXT_HEAD + "\n\n"}
    out.update({k: v + "\n\n" for k, v in secs.items()})
    return header, out


def _squeeze_evidence_noise(text: str) -> str:
    """Collapse zero-entailment-value bulk (long tracking URLs) in a tool
    output before it competes for the verifier's evidence budget."""
    return _EVIDENCE_LONG_URL_RE.sub(lambda m: m.group(0)[:64] + "…", text)


def _project_ledger_evidence(context, tools_run: Optional[list],
                             cap: int = 1000, project_id=None) -> str:
    """A LIVE project-ledger snapshot for the verifier's evidence, when the
    turn touched ``manage_projects``.

    The 2026-08-01 Mini AI turn ended with the agent relaying "the project
    is done" while the store said project=FAILED with a FAILED task — and
    the verifier CONFIRMED it at 95%, because its evidence held only the
    turn's tool outputs (whose final autoadvance text itself claimed
    completion). The ledger is the ground truth the claim is about; give
    the judge the actual rows. Read at verify time (post-mutation), capped,
    best-effort — returns "" whenever there is nothing project-shaped to
    add."""
    mp_contents: list = []
    for t in tools_run or []:
        if not t or t.get("_synthetic"):
            continue
        if str(t.get("name", "")).lower().strip() == "manage_projects":
            mp_contents.append(str(t.get("content", "")))
    if not mp_contents:
        return ""
    store = getattr(context, "project_store", None)
    if store is None:
        return ""
    # The project(s) the turn ACTUALLY operated on: the switched-current
    # project plus any project id the manage_projects outputs mention —
    # the tool accepts an explicit project_id without changing
    # current_project_id (the autoadvance path pins it deliberately), so
    # snapshotting only `current` could judge claim B against ledger A.
    pids: list = []
    cur = project_id if project_id else getattr(context, "current_project_id", None)   # the turn's own id when captured (§4IY)
    if cur:
        pids.append(str(cur).lower())
    try:
        for c in mp_contents:
            for tok in re.findall(r"\b[0-9a-f]{12}\b", c[:8000]):
                if tok in pids:
                    continue
                if store.get_project(tok):
                    pids.append(tok)
                if len(pids) >= 2:
                    break
            if len(pids) >= 2:
                break
    except Exception:
        pass
    blocks = []
    for pid in pids[:2]:
        try:
            proj = store.get_project(pid)
            if not proj:
                continue
            tasks = store.list_tasks(pid)
        except Exception:
            continue
        parts = [
            f"project {pid} \"{(proj.get('title') or '')[:40]}\" "
            f"status={proj.get('status')}"
        ]
        for t in tasks[:12]:
            line = (f"task {str(t.get('id', ''))[:12]} {t.get('status')} "
                    f"\"{(t.get('description') or '')[:60]}\"")
            fr = " ".join((t.get("failure_reason") or "").split())
            if fr and str(t.get("status", "")).upper() == "FAILED":
                line += f" (failure: {fr[:120]})"
            parts.append(line)
        if len(tasks) > 12:
            parts.append(f"(+{len(tasks) - 12} more tasks)")
        blocks.append("; ".join(parts))
    if not blocks:
        return ""
    # §4FD: task TITLES read like imperatives ("Execute ... starting with
    # 'What it means to BE ghost'") and a judge took one for a constraint.
    # Say what the block is, in the block.
    return ("[project ledger (live) — task titles and statuses, NOT user "
            "constraints] " + " || ".join(blocks))[:cap]


#: §4HZ — how much of the session's EARLIER evidence the absence rule may
#: consult (newest first). Chars, not items: a long session's tool outputs
#: run to megabytes and only a bounded tail is worth scanning for an atom.
_PRIOR_EVIDENCE_CHARS = 60_000


#: §4IT: the turn's tool outputs, whole and uncut, joined for the caveat's
#: "nowhere in the sources" test — the packed digest is a 12 KB selection, and
#: a year the packer left out is not a year the sources lacked. Bounded so a
#: pathological turn cannot hand the verifier megabytes.
_RAW_SOURCES_CHARS = 600_000
#: A body line that would read as a packer block label to `claim_binding.evidence_blocks`.
_LABEL_SHAPED_LINE_RE = re.compile(r"(?m)^(\s*)(\[[a-z][\w .\-]{0,39}\] )")


def _raw_turn_sources(tools_run_this_turn) -> str:
    """Each output as a `[tool] body` block — the packer's own label shape
    (`claim_binding.evidence_blocks` reads it back), so a consumer can tell
    an external source from the agent's own write receipt or command echo
    (§4IU self-review: the appeal splices only EXTERNAL lines)."""
    parts = []
    total = 0
    # newest first under the cap (review §4IX: the cut used to drop the NEWEST
    # outputs — the ones the final answer usually rests on), then chronological
    for t in reversed(list(tools_run_this_turn or [])):
        try:
            if isinstance(t, dict) and t.get("_synthetic"):
                continue                   # a parse-error / rejected-call row is the loop's, not a source (§4IY)
            body = str(t.get("content", "") if isinstance(t, dict) else getattr(t, "content", "") or "")
            name = str(t.get("name", "") if isinstance(t, dict) else getattr(t, "name", "") or "")
        except Exception:  # noqa: BLE001
            continue
        if not body:
            continue
        # a body line shaped like a packer label ("[0] OK goto …", "[edit]") would split the block
        # for every reader of `evidence_blocks` (§4IY): neutralise it
        body = _LABEL_SHAPED_LINE_RE.sub(lambda m: m.group(1) + "· " + m.group(2), body)
        label = re.sub(r"[^\w .\-]", "_", name)[:40] or "tool"
        room = _RAW_SOURCES_CHARS - total - len(label) - 4          # "[label] " + the joining newline
        if room <= 0:
            break
        parts.append(f"[{label}] {body[:room]}")
        total += min(len(body), room) + len(label) + 4
    parts.reverse()
    return "\n".join(parts)


_STEER_HEAD_RE = re.compile(r"^\s*(?:SYSTEM ALERT|AUTO-DIAGNOSTIC|SYSTEM ERROR|SYSTEM OBSERVATION|SYSTEM:|\[SYSTEM)", re.IGNORECASE)


#: §4MK: how much of the user's request the judges see. 1,000 cut "is my
#: migration plan correct?" (2,956 chars) before DB6 and the plan was refuted
#: for "DB5, DB6 … not present in the evidence".
JUDGE_REQUEST_CHARS = 4000
#: §4MK: the earlier-turn block the judges see (tool outputs + system banners)
EARLIER_EVIDENCE_JUDGE_CHARS = 3000
_EARLIER_EVIDENCE_HEAD = ("[EARLIER IN THIS CONVERSATION — tool outputs and system notices from previous "
                          "turns (NOT the assistant's own words). A fact found here was not invented.]")


def _earlier_turn_judge_evidence(prior: str) -> str:
    """§4MK CRIT: the judges never saw earlier turns, so a fact the agent
    learned from an earlier tool output or a SYSTEM notice ("While you were
    away — Chess Coach v4 → FAILED") was refuted as invented, the owner got a
    false correction, and reflection wrote a "hallucinated" lesson. Only
    what is not the agent's voice: earlier TOOL outputs, and the leading
    system banner blocks of earlier replies — never the replies themselves
    (§4KK: the agent's own words made invented figures "supported")."""
    try:
        from .autonomous_activity import _BANNER_HEADS, _BANNER_SEP
    except Exception:  # noqa: BLE001
        _BANNER_HEADS, _BANNER_SEP = ("**While you were away**",), "\n\n---\n\n"
    out, total = [], 0
    for blk in re.split(r"(\[assistant\][\s\S]*?\[/assistant\])", str(prior or "")):
        if not blk.strip():
            continue
        if blk.startswith("[assistant]"):
            body = blk[len("[assistant]"):-len("[/assistant]")].lstrip()
            banners = []
            for _ in range(4):
                if body.startswith(_BANNER_HEADS) and _BANNER_SEP in body:
                    head, body = body.split(_BANNER_SEP, 1)
                    banners.append(head)
                    body = body.lstrip()
                else:
                    break
            blk = "\n".join(banners)
            if not blk:
                continue
        piece = blk.strip()
        out.append(piece)
        total += len(piece)
        if total >= EARLIER_EVIDENCE_JUDGE_CHARS:
            break
    text = "\n".join(out)[:EARLIER_EVIDENCE_JUDGE_CHARS]
    return f"{_EARLIER_EVIDENCE_HEAD}\n{text}" if text.strip() else ""


def _with_earlier_turn_evidence(evidence, messages, tools_run_this_turn, last_user_content: str = "") -> str:
    try:
        extra = _earlier_turn_judge_evidence(_prior_turn_evidence(messages, tools_run_this_turn, last_user_content))
    except Exception:  # noqa: BLE001
        extra = ""
    return f"{evidence}\n\n{extra}" if extra else evidence


def _prior_turn_evidence(messages, tools_run_this_turn, last_user_content: str = "") -> str:
    """The session's evidence BEFORE this turn: earlier tool outputs and
    earlier assistant replies, newest first, bounded by
    `_PRIOR_EVIDENCE_CHARS`. This turn's own tool outputs are excluded (they
    are the digest), so the objection rule can tell "absent from this turn"
    from "absent from the session". Never fed to a judge — read only by
    `objection.resolve_issue`'s absence proof (req 30419cf0: "~149 points",
    computed one turn earlier, was upheld as invented)."""
    try:
        own = {str((t or {}).get("content", ""))[:400]
               for t in (tools_run_this_turn or []) if isinstance(t, dict)}
        parts: list = []
        total = 0
        # §4IU R2 (probe-b83968f4): "prior" is PRIOR TURNS. The list the loop
        # hands over also carries THIS turn's assistant messages — the model's
        # narration and `<thinking>` — and a year the model wrote there
        # ("1848–1898") read as "carried over from the session", silencing the
        # caveat for exactly the facts it invented. Everything after the last
        # user message is this turn's own voice, not evidence.
        msgs = list(messages or [])
        user_idx = [i for i, m in enumerate(msgs) if isinstance(m, dict) and m.get("role") == "user"]
        last_user = user_idx[-1] if user_idx else -1
        # §4IX (fresh-eye review): the loop's own steers ride user-role messages
        # (SYSTEM ALERT, the forced-final and announced-work directives, repair
        # notes), so "the last user message" is often ours — this turn's
        # narration then came back as prior evidence. The boundary is the
        # message that carries the REAL request when the caller knows it.
        def _text_of(c) -> str:
            return c if isinstance(c, str) else " ".join(
                x.get("text", "") for x in (c or []) if isinstance(x, dict) and x.get("type") == "text")
        real = str(last_user_content or "").strip()[:200]
        _matched = False
        if real:
            # EXACT head, not containment (review §4IY): the AUTO-DIAGNOSTIC and repair steers
            # quote the request verbatim, and a short request is a substring of any directive
            for i in reversed(user_idx):
                if str(_text_of(msgs[i].get("content")) or "").strip()[:200] == real:
                    last_user = i
                    _matched = True
                    break
        if not _matched:
            # no hint (an image-only request) or no row matched it (compaction
            # rewrote it): the marked request row (§4RZ step 3), else the newest
            # user message that is neither one of our steers nor one the user
            # sent mid-turn (this turn's narration came back as prior evidence)
            _marked = next((i for i in user_idx if msgs[i].get("_request")), None)
            if _marked is not None:
                last_user = _marked
            else:
                for i in reversed(user_idx):
                    if not msgs[i].get("_queued") and \
                            not _STEER_HEAD_RE.match(str(_text_of(msgs[i].get("content")) or "")):
                        last_user = i
                        break
        for m in reversed(msgs[:last_user] if last_user >= 0 else msgs):
            if not isinstance(m, dict) or m.get("role") not in ("tool", "assistant"):
                continue
            c = m.get("content")
            if not isinstance(c, str) or not c.strip():
                continue
            if c[:400] in own:
                continue
            # §4IV: an earlier reply of OURS is labelled so the binder's echo
            # rule can tell it from a tool output — it still proves a fact was
            # carried over (no absence conviction), it vouches for nothing
            parts.append(f"[assistant] {c}\n[/assistant]" if m.get("role") == "assistant" else c)
            total += len(c)
            if total >= _PRIOR_EVIDENCE_CHARS:
                break
        return "\n".join(parts)[:_PRIOR_EVIDENCE_CHARS]
    except Exception:  # noqa: BLE001 — an instrument never breaks a verdict
        return ""


def _evidence_candidates(tools_run: Optional[list]) -> list:
    """The substantive tool outputs of a turn, newest first, bounded by the
    deep window — the packer's candidate set, shared with the budget rule
    so both count the same things (§4HO)."""
    candidates: list = []
    for tool in reversed(tools_run or []):
        if not tool:
            continue
        if tool.get("_synthetic"):
            continue
        name = str(tool.get("name", "")).lower().strip()
        collapsed = name.replace("-", "_").replace(" ", "_")
        if collapsed in _BOOKKEEPING_TOOL_NAMES:
            # INFORMATIONAL bookkeeping output IS evidence (2026-07-25
            # audit): the verifier refuted "Two lessons learned" and "All 9
            # tasks complete" — both TRUE — because list_lessons/task_list
            # outputs were excluded here, so the judge literally could not
            # see the data behind the claim. Keep excluding the short
            # state-change confirmations (the 2026-04-19 blast radius:
            # `{"exited": …}` in the evidence slot guarantees a REFUTED),
            # but pack substantial read output and error text. Since §4BC
            # (2026-08-12) the run-gate shares this predicate — informational
            # bookkeeping output also RUNS the verifier — with ONE remaining
            # divergence, id_linkage: short confirmations CARRYING a 12-hex
            # id are linkage evidence once the verifier is already running
            # (2026-07-25: the verifier refuted a correct close because the
            # task_update result naming task d8a307dd196f was under the
            # length bar, so it "compared" the task id against the PROJECT
            # id and called the mismatch an error), but a bare id
            # confirmation must not summon the judge on its own.
            _c = tool.get("content", "")
            if not _bookkeeping_informational(_c, id_linkage=True):
                continue
        candidates.append(tool)  # newest-first
        if len(candidates) >= _EVIDENCE_DEEP_WINDOW:  # bounded deep window for the claim scan
            break
    return candidates


#: The refusal's own vocabulary never counts as overlap between a reply and a
#: refused page — every refused page says "blocked"; only subject words do.
_REFUSAL_VOCAB = frozenset({"blocked", "block", "blocks", "blocking", "refused", "refuse", "denied", "forbidden",
                            "status", "fetch", "fetched", "site", "sites", "page", "pages", "website", "cloudflare",
                            "captcha", "access", "error", "request", "server", "http", "returned"})
_CLAIMS_REFUSAL_RE = re.compile(
    r"cloudflare|captcha|paywall|bot[- ]protection|rate[- ]limited|access\s+(?:was\s+)?denied"
    r"|\b(?:returned|got|gave|with|hit|failed\s+with)\s+(?:an?\s+)?(?:HTTP\s*)?(?:403|429)\b"
    r"|\b(?:HTTP|status|error)\s*(?:code\s*)?(?:403|429)\b|\b(?:403|429)\s+(?:forbidden|errors?|responses?)\b"
    r"|\b(?:site|page|server|request|fetch|website|domain)\w*\s+(?:was\s+|were\s+|is\s+|got\s+)?"
    r"(?:blocked|blocking|blocks|refused|denied|forbidden)\b"
    r"|\bblocked\s+(?:by|me|us|the\s+(?:request|fetch|page|crawler|agent))\b|\bblocks?\s+(?:automated|bots?|scrap\w*|crawl\w*)"
    r"|μπλ[οό]κ\w*|απαγορε[υύ]\w*|απέρριψ\w*|αρνήθηκ\w*", re.IGNORECASE)


def _collect_verifier_evidence(tools_run: Optional[list],
                               max_items: int = 3,
                               budget: int = 4000,
                               claim_text: str = "") -> str:
    """Build the EVIDENCE string for the verifier's ``verify_claim`` gate
    from the last ``max_items`` substantive tool outputs — not just the
    single most recent one — plus, when ``claim_text`` is given, the older
    output that best SUPPORTS the claim (claim-conditioned selection,
    2026-07-25): on the dark-theme turn the 🌙→☀️ observation lived in a
    mid-turn click result, but a failed click + re-navigate + task close
    pushed it outside the newest-3 window and the verifier refuted a true
    claim as "evidence only shows the initial state". Positional windows
    miss mid-turn evidence; the claim's own tokens say which older output
    matters.

    Why: the final answer of a multi-source research turn synthesises
    MANY tool outputs, but the gate used to judge it against only the
    LAST substantive output (4000 chars). Whichever tool happened to run
    last decided the verdict: on the 2026-07-16 souvlaki turn (req
    738c/73) the last fetch was a 403 while the answer came from two
    EARLIER successful loads — the verifier truthfully reported "evidence
    does not support the claim" about the sliver it was shown and REFUTED
    a correct answer.

    Selection mirrors ``_find_substantive_tool_for_verifier`` exactly
    (synthetic and bookkeeping entries skipped), so "no evidence here"
    keeps meaning the same thing to both. Output is chronological (the
    judge reads the turn the way it happened), each item prefixed with
    ``[tool_name]`` so the prompt can attribute failures to a single
    tool, and budgets are newest-heavy (the final answer usually leans
    most on the latest evidence) with unused slack redistributed to
    still-truncated items — a tiny newest output must not starve a
    large older one. Long tracking URLs are trimmed first; they carry
    no entailment value. Total length is capped at ``budget``
    INCLUDING labels/separators, so ``verify_claim``'s own ``[:4000]``
    guard never truncates the newest item away. Returns ``""`` when no
    substantive tool exists — callers fall back / skip exactly as the
    single-tool path does.
    """
    candidates = _evidence_candidates(tools_run)
    if not candidates:
        return ""
    # §4HO: positional slots go to LIVE candidates; a refused page (STATUS:
    # BLOCKED) is quoted only when nothing else is there.
    _live = [t for t in candidates if not _evidence_is_dead(t)]
    _dead = [t for t in candidates if _evidence_is_dead(t)]
    picked = (_live + _dead)[:max_items] if _live else candidates[:max_items]   # live first, a refused page only in a slot no live one wants (§4IY)
    # §4HC: the positional picks keep the NEWEST item unconditionally (it
    # is where a failure gets attributed), but a later positional slot
    # holding a SELF-AUTHORED output ("SUCCESS: Applied 1 SEARCH block",
    # a PDF confirmation) yields to the best not-yet-picked EXTERNAL output
    # that overlaps the claim. Live, all three positional slots were the
    # deliverable's own write receipts: they proved the file was written and
    # nothing about whether what it said was true.
    if claim_text and len(picked) > 1:
        _ct0 = _claim_tokens(claim_text)
        if _ct0:
            _score0, _raw0, _dup0 = _claim_overlap_scorer(_ct0, candidates)
            _ext_pool = sorted(
                ((_score0(t), i, t) for i, t in enumerate(candidates)
                 if _evidence_is_external(t) and t not in picked and _raw0(t) > 1
                 and (not _live or not _evidence_is_dead(t))),        # §4IX: a refused page never takes a slot while a live one exists
                key=lambda x: (-x[0], x[1]))
            _ext_pool = [t for _, _, t in _ext_pool]
            for slot in range(1, len(picked)):
                if not _evidence_is_external(picked[slot]) and (
                        _looks_like_receipt(picked[slot]) or (_ext_pool and _score0(_ext_pool[0]) > _score0(picked[slot]))):
                    # §4IY: a `file_system` READ of config.py is a source too — only a write receipt
                    # / echo yields its slot unconditionally; a read yields to an external item
                    # that out-scores it on the claim
                    while _ext_pool and _dup0(_ext_pool[0], picked):
                        _ext_pool.pop(0)
                    if _ext_pool:
                        picked[slot] = _ext_pool.pop(0)
    # Claim-conditioned pull: an OLDER output whose text overlaps the claim
    # (≥2 significant tokens) is the evidence the claim leans on — add the
    # best such item as a 4th slot rather than letting a failed retry or a
    # bookkeeping-adjacent tail displace it.
    claim_pulled = None
    if claim_text and len(candidates) > max_items:
        ct = _claim_tokens(claim_text)
        if ct:
            # §4HC: rank by (EXTERNAL origin, overlap), not overlap alone.
            # Overlap alone systematically selects the agent's OWN writes:
            # the tool that shares the most tokens with a report is the
            # file_system op that wrote that report. Live (req c16679f1)
            # the three newest items and the claim-pulled fourth were all
            # the deliverable echoing itself, while the browser extraction
            # — whose text read "That is Revolut receiving and answering.
            # The sender is still unnamed." — scored 64 to the report's 89
            # and sat eleven tools back, outside the old 10-deep window.
            # The judge CONFIRMED at 0.95. An external source that
            # overlaps the claim is evidence; the claim's own echo is not.
            _score, _raw, _dup = _claim_overlap_scorer(ct, candidates)
            # §4IT: up to `_EVIDENCE_CLAIM_PULLS` items, each the best by the
            # claim tokens the ALREADY-PICKED items do not carry (the first
            # pull is the plain overlap ranking; a second pull that re-covers
            # the same tokens is worth nothing to the judge).
            _tok_cache = {}
            def _toks(t):
                k = id(t)
                if k not in _tok_cache:
                    _tok_cache[k] = _claim_tokens(str(t.get("content", ""))[:24000])
                return _tok_cache[k]
            pulled = []
            for _round in range(_EVIDENCE_CLAIM_PULLS):
                if len(picked) >= len(_EVIDENCE_BUDGET_WEIGHTS):
                    break
                covered = set()
                for t in picked:
                    covered |= (ct & _toks(t))
                remaining = ct - covered
                best, best_key = None, (False, 0.0)
                for tool in candidates:
                    if tool in picked:
                        continue
                    if _raw(tool) <= 1 or _dup(tool, picked) or (_live and _evidence_is_dead(tool)):   # §4IX: never pull a dead page over live ones
                        continue
                    marginal = _toks(tool) & remaining
                    if _round > 0 and (len(marginal) <= 1 or (not _evidence_is_external(tool) and _looks_like_receipt(tool))):
                        continue                      # nothing new for the judge — or the claim's own echo (§4HC; a READ with new coverage still qualifies, §4IY)
                    sc = _score(tool) if _round == 0 else sum(_score.weight_of(w) for w in marginal)
                    key = (_evidence_is_external(tool), sc)
                    if key > best_key:
                        best, best_key = tool, key
                if best is None:
                    break
                picked.append(best)
                pulled.append(best)
            claim_pulled = pulled[0] if pulled else None
    # A reply about a site that refused it rests on the refused page: quote
    # the most claim-relevant one as ONE extra item, never in place of live
    # evidence (refute audit 2026-09-25, req d066a356 — "Cloudflare 403s"
    # refuted after the digest dropped all four 403 results; review R16: the
    # first cut reclassified every dead page as live).
    if (claim_text and _CLAIMS_REFUSAL_RE.search(claim_text) and not any(_evidence_is_dead(t) for t in picked)
            and len(picked) < len(_EVIDENCE_BUDGET_WEIGHTS)):
        _dead_pages = [t for t in candidates if _evidence_is_dead(t)]
        if _dead_pages:
            # BOTH: the reply describes a refusal, and the refused page shares
            # its words. Overlap alone quoted a refused page whose TITLE carried
            # a success claim's tokens (§4IX); the regex alone missed most real
            # refusals and fired on unrelated text (review R17)
            _dct = _claim_tokens(claim_text) - _REFUSAL_VOCAB      # subject words only (review R18)
            if _dct:
                def _draw(t):
                    return len(_dct & _claim_tokens(str(t.get("content", ""))[:4000]))
                _best_dead = max(_dead_pages, key=lambda t: (_draw(t), -_dead_pages.index(t)))
                if _draw(_best_dead) >= 1:          # one SUBJECT word (refusal vocabulary excluded)
                    # its STATUS line only, labelled: a refused page's title or
                    # snippet is never a source for the facts in it (review R18)
                    _url = re.search(r"https?://[^\s)\]>\"']+", str(_best_dead.get("content", "")))
                    picked.append({**_best_dead, "content": "[refused page — the site blocked this fetch; nothing here "
                                                            "is a source for facts] STATUS: BLOCKED"
                                                            + (f" {_url.group(0)[:200]}" if _url else "")})
    if not picked:
        return ""
    picked.reverse()  # chronological: oldest → newest
    weights = _EVIDENCE_BUDGET_WEIGHTS[len(picked) - 1]
    labels = [f"[{str(t.get('name', 'tool'))[:80]}] " for t in picked]
    bodies = [_squeeze_evidence_noise(str(t.get("content", "")))
              for t in picked]
    # Pass 1 — weighted caps. weights are newest-first; picked is
    # oldest-first — walk them from opposite ends so the NEWEST output
    # gets the biggest slice. Each cap covers its label and the joining
    # separator, so the assembled string can never exceed `budget`.
    caps = [max(1, int(budget * w) - len(lbl) - 2)
            for lbl, w in zip(labels, reversed(weights))]
    granted = [min(len(b), c) for b, c in zip(bodies, caps)]
    # Pass 2 — redistribute slack. A weighted slice its item doesn't fill
    # is dead budget under one-pass allocation: on the 2026-07-17
    # naftemporiki turn (req 4dab5067) a 106-char weather report — the
    # NEWEST tool — held 65% of the budget while the 4KB headlines feed
    # was cut mid-item #4, and the verifier then REFUTED the answer's
    # items #5–#10 as "not in the evidence". Unused chars go to
    # still-truncated items, newest first.
    spare = sum(c - g for c, g in zip(caps, granted))
    # Claim-pulled slot drinks first (2026-07-25, req f59a793d false LATE
    # REFUTED): that slot exists BECAUSE its content overlaps the claim, yet
    # newest-first redistribution gave ~1.2KB of slack to a boilerplate
    # server.js head while the fork-provenance keys at the TAIL of the
    # claim-relevant briefing sat just past its 580-char cap — the judge
    # then truthfully called the claim unsubstantiated. Newest-first still
    # applies to whatever slack remains.
    if claim_pulled is not None and spare > 0:
        for i, t in enumerate(picked):
            if t is claim_pulled:
                need = len(bodies[i]) - granted[i]
                if need > 0:
                    take = min(need, spare)
                    granted[i] += take
                    spare -= take
                break
    for i in reversed(range(len(picked))):
        if spare <= 0:
            break
        need = len(bodies[i]) - granted[i]
        if need > 0:
            take = min(need, spare)
            granted[i] += take
            spare -= take
    parts = [lbl + _slice_evidence_body(b, g, claim_text)
             for lbl, b, g in zip(labels, bodies, granted)]
    return "\n\n".join(parts)


# Marker appended to any tool body the packer had to cut. Two jobs, both
# measured (2026-08-06, verify_bench degraded-evidence arm at 0.485-0.625
# false-refute): the judge could not previously TELL that an output was
# cut — `b[:g]` truncated SILENTLY — so "X is not in the evidence" was a
# literally correct observation about a body whose supporting span the
# packer had removed, and the rubric's "truncated evidence is UNCERTAIN at
# most, never REFUTED" rule had nothing to trigger on. The marker is
# machine-detectable (`evidence_was_truncated`) so the verifier can act on
# it, and self-describing so the judge can reason about it.
_EVIDENCE_TRUNCATION_MARK = "…[PACKER CUT"

# Per-process nonce, and why it is REQUIRED (fresh-eye MAJOR, 2026-08-06):
# a bare substring test is forgeable by the evidence itself, and this
# agent reads its own source and greps its own log routinely — a probe
# proved a plain `file_system` read of agent.py produced a digest that
# "was truncated", silently disarming REFUTED on exactly the
# self-modification turns. The nonce is minted at import and never
# written to disk by the packer's own path, so echoed text (a source
# read, an old trajectory, another process's log) cannot match it.
# Fail-closed by construction: an unrecognised mark simply means the
# guard does not fire and the refute stands.
# ⚠ "Never written to disk" took a SECOND mechanism to make true
# (2026-08-07 review): verify prompts embed the digest, and
# GHOST_LLM_RECORD=1 stores prompts verbatim — so the LIVE nonce was
# sitting in $GHOST_HOME/system/llm_recordings/, and a same-process
# grep of that directory re-armed the guard (severity 0.95, refute
# silently downgraded, zero calls). `llm_recording.record` now scrubs
# the marker's "#<nonce>:" form before writing. Any new sink that
# persists raw LLM payloads must do the same.
_PACKER_NONCE = uuid.uuid4().hex[:8]
_TRUNCATION_MARK_RE = re.compile(
    re.escape(_EVIDENCE_TRUNCATION_MARK)
    + r"#([0-9a-f]{8}): (\d+) of (\d+) chars shown")


def evidence_was_truncated(evidence: str) -> bool:
    """True when THIS PROCESS's packer cut at least one tool body out of
    this digest — i.e. absence of a fact from it is not evidence of
    fabrication. Nonce-checked; see `_PACKER_NONCE`."""
    return evidence_truncation_severity(evidence) > 0.0


def evidence_truncation_severity(evidence: str) -> float:
    """FRACTION of the digest's SOURCE text this process's packer
    removed (0.0 = nothing cut / not ours).

    Severity, not a boolean, because "the fact is absent" means
    different things at different cut depths: absent from a digest that
    kept 95% of its source is decent evidence of fabrication, absent
    from one that kept 20% is nearly no evidence at all. The consumer
    (`verifier._guard_truncated_absence`) requires a SUBSTANTIAL cut
    before excusing an absence complaint — measured need: even after
    narrowing the absence regex, 21.6% of real refute issue-sets are
    all-absence, and several are genuine fabrication catches
    ("'Vasilis' is not mentioned in the evidence").

    ⚠ GLOBAL missing fraction, not max-per-body (2026-08-07 review).
    `max` over per-body fractions armed the guard on ORDINARY turns: an
    even 3×1500-char research digest at budget 4000 measured 0.35
    "severity" although ~87% of the source was visible, and one deeply
    cut body excused absence complaints about the four INTACT bodies
    beside it. sum(cut)/sum(source) is the honest "how much of what the
    tools returned can we not see" number: the same 3×1500 turn scores
    ~0.13 (below the floor), while a digest that really lost half its
    source still arms the guard. Per-body attribution (matching the
    cited atom to ITS body) would be stricter still, but the digest does
    not delimit bodies reliably; the global fraction at least fails in
    the ESCALATE direction, never the free-excuse one."""
    text = str(evidence or "")
    missing = 0
    marker_chars = 0
    for m in _TRUNCATION_MARK_RE.finditer(text):
        if m.group(1) != _PACKER_NONCE:
            continue
        try:
            shown, total = int(m.group(2)), int(m.group(3))
        except (TypeError, ValueError):
            continue
        if total > shown >= 0:
            missing += total - shown
            marker_chars += len(m.group(0))
    if missing <= 0:
        return 0.0
    kept = max(0, len(text) - marker_chars)
    return missing / (kept + missing)


def _slice_evidence_body(body: str, granted: int, claim_text: str) -> str:
    """Cut ``body`` to ``granted`` chars — but keep the part the CLAIM
    actually leans on, and say so.

    Head-only truncation (`body[:granted]`) drops the claim's supporting
    span whenever it sits past the cut, which is precisely how a true
    claim gets refuted for "not in the evidence". When the claim's
    significant tokens appear beyond the head, this keeps a head window
    AND the best-overlapping later window, joined by an elision mark.
    The marker is always inside the granted budget, so the assembled
    digest can still never exceed the caller's cap."""
    if granted >= len(body):
        return body

    # Deliberately TERSE (2026-08-06): the first version ran ~110 chars,
    # which did not fit the granted budget on short bodies — so the cut
    # went unmarked and the guard stayed dark on exactly the small-
    # evidence cases (caught by the bench's own fault fixture). The
    # rubric in the adjudicate + rebuttal prompts already explains what
    # a cut means; the mark only has to be unforgeable and countable.
    #
    # ⚠ The mark is built LAST, from the count of source chars that
    # actually survived (2026-08-07 review): the first version wrote
    # "{granted} of {total}" while only granted−len(mark) chars survived
    # (−len(gap) more on the claim-window path), so the self-describing
    # marker the judge reads was not literally true and severity was
    # understated by 1-2pp. `mark_budget` (the widest the mark can get)
    # is reserved up front, which also closes the cap-violation band a
    # `room = max(40, …)` floor used to open: output length is now
    # ≤ granted for EVERY granted.
    def _mk(kept: int) -> str:
        return (f"\n{_EVIDENCE_TRUNCATION_MARK}#{_PACKER_NONCE}: {kept} of "
                f"{len(body)} chars shown]")

    mark_budget = len(_mk(len(body)))
    # Budget invariant beats the marker: on tiny grants the mark alone
    # would overshoot the caller's cap (measured +146 at granted=1).
    # Drop the mark rather than break the cap — the guard then simply
    # does not fire, which is the fail-closed direction.
    if granted < mark_budget + 40:
        return body[:max(0, granted)]
    room = granted - mark_budget
    ct = _claim_tokens(claim_text) if claim_text else set()
    # the claim's figures ("£3.1bn", "29.46", "1,284") — the line that carries THE number the
    # answer rests on must out-score a token-dense header (fresh-eye review §4IY)
    cnums = set(re.findall(r"\d[\d,]*(?:\.\d+)?", claim_text or "")) - {"", "0"} if claim_text else set()
    _GAP = "\n…[gap]…\n"
    if (ct or cnums) and len(body) > room + 200:
        head_room = max(40, int(room * 0.6))
        # The separator is part of the budget — subtracting a token 1
        # here overshot `granted` by its full width (caught by the
        # bounded-length assertion in tests/test_escalation_discipline).
        win_room = room - head_room - len(_GAP)
        if win_room >= 80:
            # Score fixed-width windows over the REMAINDER for claim
            # overlap; keep the best one alongside the head.
            best_i, best_score = None, 0
            step = max(80, win_room // 2)
            for i in range(head_room, len(body) - 1, step):
                seg = body[i:i + win_room]
                score = len(ct & _claim_tokens(seg)) + 3 * sum(1 for n in cnums if n in seg)
                # LAST max wins, not first: with `>` the earliest
                # max-scoring window won and could start early enough
                # that the decisive literal fell off its end (measured
                # non-monotonic: kept at granted 800 and 1000, lost at
                # 900).
                if score >= best_score and score > 0:
                    best_i, best_score = i, score
            if best_i is not None:
                # ⚠ Count the chars that actually SURVIVE (round-2
                # review): a tail window can be shorter than win_room
                # (and the last-max-wins rule prefers late windows), so
                # `head_room + win_room` overstated the marker's
                # shown-count by up to a full window — which understated
                # severity by up to ~14pp and could drop a genuinely
                # ≥25%-cut digest below the floor, letting the absence
                # rule uphold over "intact" evidence that was not.
                seg = body[best_i:best_i + win_room]
                return (body[:head_room] + _GAP + seg
                        + _mk(head_room + len(seg)))
    return body[:room] + _mk(room)


# Mutation-verb markers in a file_system SUCCESS message. A file READ
# returns the file's CONTENT (no SUCCESS:/verb), so it is correctly NOT
# flagged — only write/replace confirmations are.
_FILE_MUTATION_MARKERS = (
    "wrote", "written", "replaced", "replace applied",
    "auto-promoted", "search/replace", "overwrote", "overwritten",
    "edited",                                  # §4KC operation='edit'
    "appended",                                # §4NU write append=true (a file built in parts)
)


def _verifier_note_block(issues_str: str) -> str:
    """Build the user-facing REFUTED annotation as ONE strippable block.

    SINGLE-BLOCK INVARIANT (§4BF R2/R3): issues/reasoning are raw LLM
    strings; a blank line inside the note pushes its tail past
    ``strip_system_notes``' end-anchored no-``\\n\\n`` regex, and the
    surviving digits displace the graded answer on text-graded bench
    turns (label noise in BOTH directions — the R1 CRIT recurring
    through the writer). The strip's contract is "the note is one
    block"; this builder — the ONLY author of the marker — enforces it.
    Module-level so the invariant is behaviorally pinned
    (tests/test_track2_flip_ii.py); the sole call site is the post-loop
    verifier consumption gate.
    """
    flat = re.sub(r"\s*\n\s*", " ", str(issues_str or "")).strip()
    return f"\n\n---\n**Verifier note:** {flat}"


#: Confirmation shapes of a TARGETED edit — a region of an existing file
#: changed in place. Operator decision (2026-09-23, after §4KC's probes): the
#: unverified-mutation gate is narrowed to WHOLE-FILE writes, the shape it
#: was written for (req_C0: a 33-minute build finishing on an untested
#: `write`). A one-line edit of a library module has nothing to "run", and
#: the repair round it forced ended every such turn `failed · 0.17`. An
#: UNRECOGNISED SUCCESS that carries a mutation marker is still guarded — a
#: reworded message must not silently disarm the gate (§4GL pin).
_TARGETED_EDIT_RES = (
    re.compile(r"^SUCCESS: (?:Exact|Flexible) match found and replaced in '"),
    re.compile(r"^SUCCESS: Fuzzy match \("),
    re.compile(r"^SUCCESS: Anchor match — replaced the block spanning"),
    re.compile(r"^SUCCESS: Applied \d+ SEARCH/REPLACE blocks to '"),
    re.compile(r"^SUCCESS: Streaming replace applied to '"),
    re.compile(r"^SUCCESS: edited — replaced \d+ occurrence"),
)


#: A whole-file write SMALLER than this does not trip the gate. req_C0 was a
#: 33-minute build of thousands of chars; a 69-char three-line helper is not
#: that shape, and "run it" for one is a footer on a correct reply (operator
#: decision, 2026-09-23). The size is the tool's own `Wrote N chars` figure;
#: the replace→write auto-promote (a complete module, size unstated) and an
#: unrecognised SUCCESS keep the guard, conservatively.
UNVERIFIED_WRITE_MIN_CHARS = 2048
_FS_WROTE_SIZE_RE = re.compile(r"^SUCCESS: Wrote (\d+) chars to '")


def _below_write_threshold(head_lines) -> bool:
    """True when EVERY confirmation in the leading run is a `Wrote N chars`
    line with N below the threshold — nothing there is the req_C0 shape.
    Any other shape in the run (auto-promote, unrecognised) keeps the
    guard."""
    seen = False
    for ln in head_lines:
        m = _FS_WROTE_SIZE_RE.match(ln)
        if not m:
            return False
        seen = True
        if int(m.group(1)) >= UNVERIFIED_WRITE_MIN_CHARS:
            return False
    return seen


#: The reason the unverified-mutation gate books a turn `failed` with when
#: NO verdict exists yet. It is a PRIOR, not a refutation — so it carries the
#: structural-failure prefix, which is the one class `resolve_turn_outcome`
#: lets a strong LATE verdict lift. Measured 2026-09-23 (reqs 07c0c588,
#: 3b827526): the gate booked `failed · 0.17`, the verifier then landed
#: CONFIRMED 100% with FILE-ARTIFACT present, and the corpus row stayed
#: `failed` forever because it had been stamped "verifier refuted".
UNVERIFIED_MUTATION_REASON = (
    "structural failure:unverified mutation — finalised on an untested file "
    "write/replace; the change was never run or screenshotted")


def _backfilled_failure_reason(verifier: Optional[str], verifier_reason: str,
                               traj) -> str:
    """The `failure_reason` a consolidated FAILED row is stamped with.

    A verifier-backfilled FAILED that is really the unverified-mutation
    PRIOR keeps its structural-class reason so a later CONFIRMED can lift
    it; a genuine refutation is "verifier refuted" and never lifts; a
    FAILED with no verifier signal names its structural cause.
    """
    from ..distill.outcome_heuristics import (
        is_structural_reason, structural_cause_for_trajectory,
        structural_reason)
    if verifier == "failed":
        if verifier_reason and is_structural_reason(verifier_reason):
            return verifier_reason
        return "verifier refuted"
    return structural_reason(structural_cause_for_trajectory(traj))


def interruption_marker(req_id, remaining_s: Optional[float] = None) -> str:
    """§4MS r1: a cancel at or past the request's deadline is the AGENT
    being too slow (the interface's 1800 s client timeout reads like a
    disconnect: fd89fd6d +1800 s, 2ba9ed1d) — a real failure, kept as an
    abort. Earlier, it was cut from outside: an interruption."""
    try:
        # §4RD r2: a caller past the request's END (the streamed drain — its
        # request clock is already closed) passes the remaining time it kept
        if remaining_s is None:
            from ..utils.logging import request_remaining_s
            remaining_s = request_remaining_s(str(req_id or ""))
        rem = remaining_s
        if rem is not None and float(rem) <= 5.0:
            return "[ATTEMPT_ABORTED_TURN]"
    except Exception:  # noqa: BLE001
        pass
    return TURN_INTERRUPTED_MARKER


class _NoOwnerSeed(Exception):
    """§4MS: no owner failure to replay and no regression test due — the
    self-play slot has nothing to do this tick."""


def _owner_wrote(phrase: str, owner_fold: str) -> bool:
    """§4NG: the folded phrase occurs in the owner's folded words as WHOLE
    words ("ai" is not in "said", "it" is not in "with"). The owner text is
    stripped of its own "USER:" marks first."""
    if not phrase:
        return False
    text = re.sub(r"(?m)^\s*user\s*:\s*", " ", owner_fold or "")
    return re.search(r"(?<!\w)" + re.escape(phrase) + r"(?!\w)", text) is not None


class _SlotBusy(Exception):
    """§4MW r2: another self-play slot body is running."""


class _ProofLegRan(Exception):
    """§4MW/§4NE: the self-play slot ran one failure-replay stage or one
    regression-suite step (the slot's work for this tick is done)."""


#: §4MS: the wall cap of one idle job (a replay stage, a regression step,
#: the reaction judge) — a self-play tick once ran 2,140 s unbounded
IDLE_JOB_CAP_S = 900.0

#: §4MO: the loop's own pre-dispatch blocks that ASK the user (clarify-first;
#: an image retry that drops or replaces a subject with no photo). A batch
#: holding one ends the tool phase. The TOOL's own first "no photo" is not
#: here: it allows one respelled retry, as its text says.
_ASK_THE_USER_STOPS = frozenset({"clarify_first", "subject_photo_missing"})
#: §4NT: the direct answer when clarify-first stops a costly call (Greek for
#: a Greek message — the model used to answer in the conversation's language)
CLARIFY_FIRST_REPLY = ("Nothing was generated. What would you like — a change to the last "
                       "image, a new one, or something else?")
CLARIFY_FIRST_REPLY_EL = ("Δεν δημιουργήθηκε τίποτα. Τι θα ήθελες — αλλαγή στην τελευταία "
                          "εικόνα, μια καινούργια ή κάτι άλλο;")


#: §4NT r5: the fixed question itself, ENDING a previous reply (Slack prefixes
#: "[my earlier reply …]", a digest may be put in front) is (a) proof that an
#: image turn ran — it carries no link, and after a restart there is no
#: record — and (b) not "our question" that an "ok" answers.
def _is_our_clarify_question(text) -> bool:
    """The reply ENDS with the fixed question (r5: a substring test also
    caught a model reply saying "Nothing was generated. Want me to retry?")."""
    t = str(text or "").rstrip()
    return t.endswith(CLARIFY_FIRST_REPLY) or t.endswith(CLARIFY_FIRST_REPLY_EL)


def clarify_first_reply(user_text, messages=None) -> str:
    """Greek when the message has Greek letters, or when it has none and the
    previous reply has more Greek letters than Latin ones (only a
    low-information message reaches here: "emp1", "ok", "?")."""
    _el = re.compile(r"[\u0370-\u03ff\u1f00-\u1fff]")
    t = str(user_text or "")
    if _el.search(t):
        return CLARIFY_FIRST_REPLY_EL
    prev = _last_assistant_text(messages, user_text) if messages else ""
    if len(_el.findall(prev)) > len(re.findall(r"[A-Za-z]", prev)):
        return CLARIFY_FIRST_REPLY_EL
    return CLARIFY_FIRST_REPLY

#: §4MO r2: synthetic rows that already book a strike (`_strike_synthetic`)
#: — not counted again as a "blocked batch"
#: §4NU: one wording for every place that tells the model how to write a big
#: file (cut-off message, XML truncation hint; the schema says the same)
BIG_FILE_GUIDANCE = (
    "One reply carries at most ~16k–64k tokens INCLUDING your thinking (fewer the longer the "
    "conversation; 16k is about 40 KB of code, much less for Greek text). Do not draft a whole "
    "file in your thinking — write it. Write a big file in PARTS, each split at a line boundary: the first "
    "with file_system operation='write' and more_parts=true, each next one (~15 KB of "
    "code) with operation='write', append=true and more_parts=true, and the LAST one with "
    "append=true only (the file is checked then) — add at the END with append=true, never with "
    "an 'edit'. Or split the work into several smaller "
    "files (e.g. index.html + style.css + app.js). For a long script, write it in parts the "
    "same way, then run the file with execute.")

_STRUCK_BLOCK_CODES = frozenset({"tool_disabled", "tool_call_parse_error", "bad_json_arguments",
                                 "tool_call_cut_off",
                                 "empty_write_blocked", "constraint_violation",
                                 "invocation_error", "unknown_tool"})

#: Tool refusals that cannot change within the request (§4LV): retrying is
#: pointless, so the turn loop ends the tool phase on the first one.

_DEAD_END_REFUSALS = frozenset({"not_owner_write", "confirm_dead_end",
                                "forget_not_confirmed", "reset_not_confirmed"})


def _defuse_tool_text(content) -> str:
    """A tool result's text with chat-template control tags made inert, for
    the sites that wrap it in the agent's own ``<tool_response>`` tags (§4MB)."""
    from ..utils.prompt_safety import defuse_text
    return defuse_text(str(content if content is not None else ""), "tool")


#: a request that bounds the reply's length or form (§4ME F5)
_FORMAT_BOUND_RE = re.compile(
    # explicit length/form asks only: "exactly", "just the", "only the" read
    # as ordinary phrasing ("what exactly went wrong") and held the banner
    # for good (§4ME review)
    r"\b(?:one|1|single|two|2|three|3)[\s-]+(?:line|word|sentence|paragraph)s?\b|\bbriefly\b|"
    r"\bno preamble\b|\b(?:reply|answer|respond)(?: with)? only\b|\bjust (?:say|answer|reply)\b|"
    r"\bin \d+ words\b|μία? (?:γραμμή|λέξη|πρόταση)|σύντομα", re.IGNORECASE)


#: world-fact predicates whose value is a moving target (§4ME F3; the one
#: definition lives in memory/graph.py since §4MM — every writer applies it)
from ..memory.graph import TRANSIENT_WORLD_PREDICATE as _TRANSIENT_WORLD_PREDICATE  # noqa: E402,F401 — tests import it from here
from ..memory.graph import is_moving_target_world_fact as _is_moving_target_world_fact  # noqa: E402


#: a status question — what has happened / where are we — not a request for
#: more work (§4MF: "progress report" ran the full work loop for 37 minutes).
#: STRICT, by review: whole phrases at word boundaries, a short message, and
#: no work verb anywhere in it ("build a progress bar", "is it ready? then
#: deploy it", "τι γίνεται με τον καιρό" all matched the first cut).
_STATUS_QUESTION_RE = re.compile(
    r"(?<!\w)(?:progress (?:report|update)|status (?:update|report)|what(?:'s| is) the status|"
    r"where are we(?: at| with (?:it|this|that|the \w+))?|how(?:'s| is) it going|how far along|"
    r"are you (?:done|finished)|is it (?:done|finished|ready)|what have you done so far|"
    r"πώς πάει|πως παει|σε τι φάση είμαστε|σε τι φαση ειμαστε|τελείωσες|τελειωσες)(?!\w)",
    re.IGNORECASE)
#: any of these in the message makes it a WORK request, whatever else it asks
_WORK_VERB_RE = re.compile(
    r"(?<!\w)(?:then|if so|and (?:then )?(?:run|deploy|push|fix|build|add|write|make|start|continue)|"
    r"build|deploy|push|fix|add|write|make|create|implement|generate|run|benchmark|check|"
    r"stop|cancel|kill|continue|resume|φτιάξε|φτιαξε|γράψε|γραψε|τρέξε|τρεξε|πρόσθεσε|προσθεσε|"
    r"συνέχισε|συνεχισε|σταμάτα|σταματα)(?!\w)", re.IGNORECASE)
#: tools that START work — refused on a status question while work is live.
#: Reading stays open (file_system, jobs status/log, manage_tasks list,
#: manage_projects, workspace, introspect).
_WORK_TOOLS = frozenset({"execute", "browser", "web_search", "deep_research", "darkweb_search",
                         "darkweb_research", "image_generation", "deploy", "manage_services",
                         "create_skill", "probe_model"})


def status_only_refusal_text() -> str:
    """§4SB: the status-only gate's refusal. The gate is set from the FIRST
    ask; a message sent mid-turn ("also restart it") never grants (§4RZ s4:
    deny→allow is forbidden) — but the text must not claim the user asked
    only for status once they added an instruction: name it, and ask for it
    as a new message."""
    try:
        from .queued_messages import delivered as _qd
        added = _qd()
    except Exception:  # noqa: BLE001
        added = ()
    if not added:
        return ("Not run: the user asked for a STATUS / progress report. Answer from "
                "what is already known — the project's tasks and work log, the jobs' "
                "state, files already written. Start no new work; offer to continue "
                "if they want.")
    newest = " ".join(str(added[-1] or "").split())[:80]
    return (f"Not run: this request began as a STATUS question, so no new work starts in it, "
            f"even though the user added '{newest}' while it ran. Answer from what is known "
            f"and ask the user to send that instruction as a new message.")


def is_status_question(text: str) -> bool:
    t = str(text or "").strip()
    return (len(t) <= 80 and bool(_STATUS_QUESTION_RE.search(t))
            and not _WORK_VERB_RE.search(t))


def has_live_work(context) -> bool:
    """A bound project or a running background job: something to report on."""
    try:
        if getattr(context, "current_project_id", None):
            return True
        from .jobs import get_job_registry, STATUS_RUNNING
        reg = get_job_registry(context)
        return bool(reg and reg.list(status=STATUS_RUNNING))
    except Exception:  # noqa: BLE001
        return False


def _tool_row_as_user_text(m) -> str:
    """A tool row re-sent as user text in the agent's own ``<tool_response>``
    wrapper. The row may come from the CLIENT's history (never through this
    process's dispatcher), so its text is defused here too (§4MB)."""
    return (f"<tool_response name=\"{m.get('name', 'unknown')}\">\n"
            f"{_defuse_tool_text(m.get('content'))}\n</tool_response>")


def _postmortem_tool_line(t_msg) -> str:
    """One tool row for a stored episode. Content from OUTSIDE (a page, a
    document, a transcript) is never quoted: an episode is replayed into
    later prompts, and a planted "rule" in a page became a lesson (§4MB).
    Its failures are the agent's own text and stay."""
    content = t_msg.get("content", "")
    try:
        from ..utils.provenance import is_untrusted_source
        from ..tools.outcome import ToolOutcome as _TOp
        out = content if isinstance(content, _TOp) else _TOp.coerce(str(content or ""))
        args = getattr(content, "call_args", None)
        outside = (t_msg.get("_outside") if "_outside" in t_msg
                   else is_untrusted_source(t_msg.get("name", ""), args))
        if outside and not out.is_failure:
            return "(ok — content from outside, not quoted)"
    except Exception:  # noqa: BLE001
        pass
    return str(content or "")[:200]


def _scratch_hidden_namespaces(req_id) -> tuple:
    """Scratchpad namespaces this request's prompt must NOT show. Background
    work's notes (the `bg` scope) stay out of an owner turn's prompt (§4LX);
    a request that WRITES into `bg` — by the same classification the
    scratchpad tool writes with, `request_kind` — sees them (§4LZ: bench and
    replay turns wrote there and then could not see their own notes)."""
    from ..utils.logging import request_kind
    return () if request_kind(str(req_id or "")) in ("background", "job", "test") else ("bg",)


def _notify_delivered(t) -> bool:
    """Did this tool row really SEND an operator notification? (§4LZ B2:
    three sites read "content doesn't start with Error" — a pre-flight
    block, a disabled tool or a probe dry-run counted as delivered, and the
    stored promise was spent without a ping.) The declared status decides;
    synthetic rows (guards, blocks) never count."""
    if not isinstance(t, dict) or t.get("_synthetic"):
        return False
    if str(t.get("name", "")).lower().strip() != "notify_operator":
        return False
    content = t.get("content")
    try:
        from ..tools.outcome import ToolOutcome as _TOn, OutcomeStatus as _OSn
        out = content if isinstance(content, _TOn) else _TOn.coerce(str(content or ""))
        if out.status is not _OSn.OK:
            return False
    except Exception:  # noqa: BLE001
        pass
    text = str(content or "").lstrip()
    return not text.startswith(("Error", "PROBE", "SYSTEM"))


def _dead_end_reply(refusal: str) -> str:
    """The direct answer for a request whose write was refused outright:
    the refusal's reason, without the tool-facing parts ("Error:", "STOP:
    do not retry…")."""
    t = re.sub(r"^\s*(?:Error:\s*)+", "", str(refusal or "")).strip()
    t = re.split(r"\s*STOP\b", t, maxsplit=1)[0].strip()
    t = t.rstrip(" .—-") + "."
    return f"Not done: {t}"


#: §4PN: a forget / reset_all refused ONLY because the user has not answered
#: the preview yet (the preview and the confirm were made in one request)
_CONFIRM_WAIT_CODES = frozenset({"forget_not_confirmed", "reset_not_confirmed"})
#: §4PS: the code a refusal takes once the takeover answered it (a designed stop)
_CONFIRM_WAIT_SHOWN = {"forget_not_confirmed": "forget_wait_shown", "reset_not_confirmed": "reset_wait_shown"}
_CONFIRM_WAIT_RE = re.compile(r"the user has not answered yet", re.I)
_PREVIEW_HEAD_RE = re.compile(r"^\s*PREVIEW — nothing was deleted\.\s*", re.M)


#: a preview token as `memory._store_plan` mints it (secrets.token_hex(4))
_PLAN_TOKEN_RE = re.compile(r"[0-9a-f]{8}")
_TRAILER_RE = re.compile(r"(?:^|\n)Show this list to the user\.|(?:^|[ \n])Ask the user to\s+confirm\.")


def _quiet_kb_result(res) -> bool:
    """A knowledge_base result that neither changed anything nor answered
    anything the owner asked: a forget/reset PREVIEW, or a REFUSAL. A read
    (a document answer) is not quiet — the owner asked for it (r2 M2), and a
    FAILED deletion may have run part-way (r2 m2)."""
    if _PREVIEW_HEAD_RE.match(str(res or "")):
        return True
    # only the forget/reset flow's own refusals (r3 m2: a refused INGEST is
    # work the owner asked for, and the model must say it did not happen)
    return (getattr(getattr(res, "status", None), "value", None) == "rejected"
            and str(getattr(res, "reason_code", "") or "").startswith(("forget_", "reset_")))


def _confirm_wait_reply(refusal, rows, call_args=None, code: str = "forget_not_confirmed",
                        batch=None) -> str:
    """§4PN: the direct answer when a forget / reset_all was refused because
    the USER has not seen the preview yet — the preview's own list and one
    question that says exactly what "yes" will do — or "" (the caller keeps
    the model-written wrap-up). Census + gold 10-16: all 3 such turns in 14
    days told the owner the item was deleted or about to be. The project
    wait (its own question) was right 4/4 and is not touched.

    Takes over ONLY a turn whose every real call — the rows so far AND
    every call of this batch, which all ran before any result is processed
    (r2 M1) — was a knowledge_base preview or refusal (r1 M3/M5: an earlier
    deletion, a write, or an answer the owner asked for must not be hidden
    by "Nothing has been deleted yet"), and shows ONLY the preview the
    refused call named — by its token, or the one preview of that kind when
    the call gave none (r1 M4) — and only when the request holds exactly
    one preview of that kind (r3 M1). ``batch``: (tool name, result) per call."""
    if not _CONFIRM_WAIT_RE.search(str(refusal or "")):
        return ""
    want_reset = code == "reset_not_confirmed"
    previews = []
    for t in list(rows or []):
        if not isinstance(t, dict) or t.get("_synthetic"):
            continue
        if str(t.get("name") or "").strip().lower() != "knowledge_base" or not _quiet_kb_result(t.get("content")):
            return ""                                   # other work this turn: the model reports it
        if _PREVIEW_HEAD_RE.match(str(t.get("content") or "")):
            previews.append(str(t.get("content") or ""))
    for name, res in list(batch or []):
        # (r3 m1: a call blocked before dispatch has no slot here at all — a
        # None result is a tool that RAN and returned nothing: not quiet)
        if str(name or "").strip().lower() != "knowledge_base" or not _quiet_kb_result(res):
            return ""                                   # a later call in this batch did something
        if _PREVIEW_HEAD_RE.match(str(res)) and str(res) not in previews:
            previews.append(str(res))
    kind_previews = [p for p in previews
                     if bool(re.match(r"\s*PREVIEW — nothing was deleted\.\s*reset_all\b", p)) == want_reset]
    # r3 M1: exactly ONE preview of this kind in the request — the owner's
    # "yes" next turn resolves to the NEWEST live preview, so with two the
    # list shown could differ from the list deleted
    if len(kind_previews) != 1:
        return ""
    token = str((call_args or {}).get("confirm") or "").strip().strip("'\"").strip()
    named = kind_previews
    if _PLAN_TOKEN_RE.fullmatch(token) and f"confirm='{token}'" not in kind_previews[0]:
        return ""                                       # the refused call named another preview
    if len(named) != 1 or "[TRUNCATED" in named[0]:
        return ""                                       # cannot say exactly what "yes" deletes
    preview = named[0]
    cut = [m.start() for m in _TRAILER_RE.finditer(preview)]
    if not cut:
        return ""
    shown = _PREVIEW_HEAD_RE.sub("", preview[:cut[-1]], count=1).strip()     # the LAST trailer (r1 M2)
    if not shown:
        return ""
    # model-facing advice in the sweep's notes is not for the owner
    shown = re.sub(r"\s*Re-issue with [^\n]*", "", shown)
    shown = shown.replace("Notes from the search:", "Notes:")
    shown = shown.replace("(kept unless the user picks them by number)", "(kept unless you pick them by number)")
    if want_reset:
        shown = re.sub(r"^reset_all would erase", "Resetting the memory would erase", shown, count=1)
        ask = "Reply **yes** to go ahead, or tell me to stop. This stays open for an hour."
    else:
        shown = re.sub(r"^forget (.+?) would remove:", r"Forgetting \1 would remove:", shown, count=1)
        main = shown.split("\nAlso found", 1)[0].split("\nNotes:", 1)[0]
        # numbered 1..N without a gap (r2 m4: a label's own "3. …" line is not an item)
        defaults = []
        for d in re.findall(r"(?m)^(\d+)\. ", main):
            if int(d) == len(defaults) + 1:
                defaults.append(d)
        extra = bool(re.search(r"(?m)^Also found", shown))
        if not defaults:                                 # "yes" alone selects nothing (r1 M1)
            ask = "Nothing is selected by default: reply with the numbers of the ones to delete."
        else:
            which = (f"item {defaults[0]}" if len(defaults) == 1
                     else f"items {defaults[0]}–{defaults[-1]}")
            ask = (f"Reply **yes** to delete {which}"
                   + (", or give the numbers of exactly the ones to delete (any from either group)." if extra
                      else ", or give the numbers of exactly the ones to delete." if len(defaults) > 1
                      else ", or tell me to keep it.")
                   )
        ask += " This stays open for an hour."
    from .receipt_marks import CONFIRM_WAIT_REPLY_HEAD as _CWH  # §4QO: one home for the literal
    return f"{_CWH}\n\n{shown}\n\n{ask}"


#: shell-like tool names a model reaches for — the work runs through `execute`
_SHELL_LIKE_TOOLS = frozenset({"git", "bash", "sh", "shell", "terminal", "zsh", "cmd", "run_command",
                               "python", "pip", "npm", "curl", "docker"})


def _unknown_tool_message(name, available) -> str:
    """§4LL: "Unknown tool 'git'" named no way forward. Say what to use: a
    shell-like name runs through `execute`; anything else gets the list."""
    n = str(name or "").strip()
    names = sorted(str(k) for k in (available or {}) if not str(k).startswith("_"))
    # §4LV: a member's turn lists only what a member may call, and is never
    # told to use `execute` (members cannot) — and the list is WHOLE: cut at
    # 40, `web_search` and `workspace` fell off the end
    try:
        from ..utils.logging import requester_is_member
        if requester_is_member():
            names = [k for k in names if k in _MEMBER_ALLOWED_TOOLS]
    except Exception:  # noqa: BLE001
        pass
    if n.lower() in _SHELL_LIKE_TOOLS and "execute" in names:
        return (f"Error: there is no '{n}' tool. Run it as a shell command through execute, "
                f"e.g. execute(command=\"{n.lower()} …\").")
    return f"Error: Unknown tool '{n}'. Available tools: {', '.join(names)}."


def _unverified_mutation_note(last_tool, request, tools_run, reply=""):
    """(note, failed) for a turn whose final substantive action was a file
    write never run or rendered — ("", False) otherwise. ONE wording for
    both delivery paths (§4LK: the streamed path had none — a streamed final
    after an untested write was neither flagged nor labelled failed).
    Untested BY REQUEST ("don't run it") is said, not failed (§4KW).

    §4PH: the last-tool shape is a PROXY any later tool cleared (write →
    `ls` → "tested, it works" shipped clean; a file whose only run FAILED
    shipped under "all tests pass"). When it does not fire, the CLAIM arm
    reads `reply` against the turn's write/run ledger (`core.code_claims`):
    a works/tested/verified claim about a code file this request wrote and
    never ran — or whose last run after the final write failed — gets the
    same note-and-failed treatment, at any write size (the operator's
    small-write exemption was about a footer on a correct write with no
    claim, not about a false statement)."""
    if not _is_unverified_mutation(last_tool):
        if reply:
            try:
                from .code_claims import unbacked_claim_note
                return unbacked_claim_note(reply, tools_run,
                                           forbids_running=request_forbids_running(request))
            except Exception as _cc_exc:  # noqa: BLE001 — never costs the reply
                logger.debug("code-claim arm skipped: %s", _cc_exc)
        return "", False
    if request_forbids_running(request):
        # (fresh review) the model may have run an EARLIER version anyway —
        # then say so, not "as you asked"
        _ran_code = any(
            isinstance(_t, dict) and not _t.get("_synthetic")
            and str(_t.get("name", "")).lower() == "execute"
            for _t in (tools_run or []))
        return (("\n\n---\n*Not re-run after the last edit (you asked not to run it) — the "
                 "final version is untested.*") if _ran_code else
                "\n\n---\n*Not run, as you asked — the change is untested.*"), False
    return ("\n\n---\n**⚠ Unverified:** the final action "
            "was a file write that was never executed or "
            "rendered, so I cannot confirm it works. Treat "
            "this as INCOMPLETE — run/preview it before "
            "relying on it."), True


def _is_unverified_mutation(tool: Optional[dict]) -> bool:
    """True when ``tool`` is a SUCCESSFUL file write/replace — i.e. the
    turn's final substantive action mutated a file but the turn ended
    without ever running or rendering it.

    The verifier gate uses this to refuse a clean "success" finish on an
    untested change: the req_C0 failure was a 33-minute build that
    "finished" immediately after a `file_system` write that was never
    executed or screenshotted, yet reported C=0.96. Conservative — fires
    only for the ``file_system`` tool AND only on a write/replace SUCCESS
    confirmation, so a file READ (which also carries evidence) is not
    mistaken for a mutation."""
    if not tool or not isinstance(tool, dict):
        return False
    name = str(tool.get("name", "")).lower().replace("-", "_").replace(" ", "_")
    if name not in ("file_system", "filesystem", "file"):
        return False
    # The confirmation LINE, and only a SUCCESS one: a REJECTED edit whose
    # nearest-region echo happened to contain "successfully edited" booked
    # the turn as an unverified mutation over a file nothing touched
    # (fresh-eye §4KC round 2).
    _raw = str(tool.get("content", "")).lstrip()
    if _raw.startswith("[FAILURE BANNER]"):
        _raw = _raw.split("\n", 1)[1] if "\n" in _raw else ""
    if not _raw.lstrip().upper().startswith("SUCCESS"):
        return False
    _head = _raw.split("\n", 1)[0].strip()
    if any(rx.match(_head) for rx in _TARGETED_EDIT_RES):
        return False                    # a targeted edit is not the gate's shape
    # the markers are looked for OUTSIDE the quoted path (§4LL review:
    # "Copied 'edited_photo.jpg'", "Downloaded '…/Replaced_logo.png'")
    content = re.sub(r"'[^']*'", "''", _head).lower()
    if not any(marker in content for marker in _FILE_MUTATION_MARKERS):
        return False
    # the leading run of SUCCESS lines, like `_written_paths_from_confirmation`
    _run = []
    for ln in _raw.split("\n"):
        ln = ln.strip()
        if not ln.startswith("SUCCESS"):
            break
        _run.append(ln)
    if _below_write_threshold(_run):
        return False                    # small whole-file writes are not req_C0
    # ⚠ ONLY A RUNNABLE ARTIFACT CAN BE RUN (§4GL, req cf45e352). This gate
    # used to fire on the TOOL NAME alone, so every successful file write
    # demanded that the file be "run or rendered" before the turn could
    # finish clean. A prose deliverable has nothing to run and nothing to
    # render, so writing the report a request ASKED FOR could never satisfy
    # it — and the turn was booked `failed` at confidence 0.15 with a note
    # telling the operator to "run/preview it before relying on it".
    #
    # Measured on req cf45e352 (2026-09-14): an eight-minute OSINT
    # investigation produced a 10.9 KB forensic report and a 4.4 KB standalone
    # answer that correctly REFUSED to attribute, and was recorded as a
    # failure. The knock-on is what makes it expensive rather than cosmetic:
    # six lessons were filed `present-on-FAILURE` (the outcome-gated loop
    # prunes on that), and the self-model moved to "stuck: 3 of my last 5
    # verdict-bearing turns failed". The gate has fired six times.
    #
    # The original defect it was written for (req_C0: a 33-minute build finishing on
    # an untested code write at C=0.96) is untouched — code and markup still
    # have to be executed or rendered. Unknown or extensionless names still
    # fire, so a `Makefile` or a `Dockerfile` keeps the guard; only the
    # explicitly inert kinds are exempt.
    _paths = _written_paths_from_confirmation(_raw)
    if _paths and all(_is_inert_artifact(q) for q in _paths):
        return False
    return True


#: Written artifacts that cannot be "run or rendered" by construction: prose,
#: notes, reports, structured data. Demanding execution of these is demanding
#: the impossible, and the turn fails for having produced what was asked for
#: (§4GL). Anything NOT named here — including an extensionless name — still
#: fires the gate, so the conservative default is preserved.
_INERT_ARTIFACT_SUFFIXES = frozenset({
    ".md", ".markdown", ".rst", ".txt", ".text", ".log",
    ".csv", ".tsv", ".json", ".jsonl", ".ndjson",
    ".yaml", ".yml", ".toml", ".ini", ".cfg", ".conf",
    ".xml", ".rtf", ".org", ".adoc",
})


#: config dotfiles and lockfiles have no extension to splitext but are inert
#: (§4LL review: a 2 KB .gitignore or .env write was flagged "never run")
_INERT_ARTIFACT_NAMES = frozenset({
    ".gitignore", ".gitattributes", ".dockerignore", ".editorconfig", ".env", ".env.example",
    ".prettierrc", ".npmrc", ".nvmrc", ".python-version", "license", "readme", "changelog",
})


def _is_inert_artifact(path: str) -> bool:
    """True when ``path`` names a file that cannot be executed or rendered."""
    import os as _os
    p = str(path).strip().strip("'\"").lower()
    base = _os.path.basename(p)
    return (_os.path.splitext(p)[1] in _INERT_ARTIFACT_SUFFIXES
            or base in _INERT_ARTIFACT_NAMES or base.endswith(".lock"))


def _written_paths_from_confirmation(content: str) -> list:
    """Every path a file_system WRITE confirmation names, via the SAME
    anchored patterns the deliverable bookkeeping uses — so a reworded
    message goes blind in one place, not two, and the existing
    producer/parser parity tripwire covers both."""
    out = []
    # The LEADING RUN of `SUCCESS:` lines only. Everything after the first
    # line that is not one is the tool echoing file content (a POST-EDIT
    # VIEW, a nearest-region snippet — each opens with a blank line or a
    # `---` header), whose text is data, not a confirmation (§4KC r2: an
    # echoed "SUCCESS: Wrote …" inside an edited file reached this parser).
    # A run, not just the head, because a mixed confirmation lists one
    # runnable artifact after an inert one and the gate must keep it.
    for line in str(content or "").split("\n"):
        line = line.strip()
        if not line.startswith("SUCCESS"):
            break
        m = _FS_WROTE_PAIR_RE.match(line)
        if m:
            out.extend([m.group(1), m.group(2)])
            continue
        for rx in _FS_PRODUCE_RES:
            m = rx.match(line)
            if m:
                out.append(m.group(1))
                break
    return out


# ── file_system SUCCESS-message parsing ──────────────────────────────
# Both ground-truth overrides below (WEB-EXEC entry page, FILE-ARTIFACT
# re-read) learn what a request touched by parsing the file tool's own
# SUCCESS confirmations — turn records carry (name, content), not the
# original call arguments. So the parse mirrors the message shapes
# `tools/file_system.py` emits, one anchored pattern per shape, and it
# respects ORDER: a scratch file written and then deleted in the same
# request is not a deliverable.
#
# ⚠ WHY (2026-08-26, the GlassOS webOS refute). The previous parse
# matched any quoted token containing a dot, in EVERY file_system SUCCESS
# message — including `SUCCESS: Deleted 'probe.py'.`. So a scratch probe
# the agent wrote, ran, and then tidied up was collected as a produced
# file, re-read, found missing, and REFUTED (0.9) a turn whose real
# deliverable (webos/index.html, 25KB, rendered and clicked) was on disk
# the whole time — overriding a text verdict of CONFIRMED 0.95. Three
# properties made it worse than one bad verdict:
#   • `tools_run_this_turn` accumulates across the whole REQUEST, so the
#     poison survived into the auto-repair round AND the post-reply
#     re-verify;
#   • no repair round could ever clear it — the "missing deliverable" was
#     a file the agent had deliberately removed;
#   • `tools/execute.py`'s inline-`python -c` block message PRESCRIBES
#     `file_system(write, path="probe.py")`, so the agent was refuted for
#     obeying another subsystem's instruction.
# Only the operator's human label (`_human_label_locked`) stopped the late
# REFUTED from backfilling a correct turn into the corpus as a FAILURE.
#
# ⚠ THE KEY IS NORMALISED, NOT LITERAL. `_get_safe_path` resolves
# `/workspace/x`, `./x` and `x` to the SAME file, and the write
# confirmation prints two spellings while the delete prints one — so
# string-equal bookkeeping lets the incident reproduce verbatim whenever
# the model spells the delete differently from the write (8 of 135 write confirmations in the
# trajectory corpus capture a `/workspace/…` filename). Keys are
# normalised and case-folded (the sandbox is a bind mount on a
# case-insensitive host FS), and a removed DIRECTORY retires everything
# produced beneath it — a scratch *directory* is the same tidy-up idiom.

_FS_PATH_PREFIXES = ("/workspace/", "workspace/", "./")

# One anchored pattern per confirmation shape in tools/file_system.py.
# `'(.+?)'\.`-style captures (rather than `'([^']+)'`) tolerate an
# apostrophe in a filename and any trailing clause the tool appends.
# ⚠ Reword a message there and its pattern here goes silently blind —
# tests/test_grounded_file_verify.py::TestProducerParserParity is the
# tripwire that makes such a reword fail loudly.
_FS_RETIRE_RE = re.compile(r"^SUCCESS: Deleted '(.+?)'\.")
_FS_MOVED_RE = re.compile(r"^SUCCESS: Renamed/Moved '(.+?)' to '(.+?)'\.")
_FS_DEST_RE = re.compile(
    r"^SUCCESS: (?:Downloaded|Copied) '.+?' to '(.+?)'(?: \([^)]*\))?\.")   # §4PE: the download receipt's "(N bytes, type)"
# ⚠ The `Wrote` confirmation prints TWO spellings of one file: the model's
# `filename` and the resolved `rel_str`. Under a project-scoped sandbox those
# differ by the whole `projects/<pid>/` head — `projects/abc/probe.py` and
# `probe.py` — and the tool then advertises the SECOND one as "Script-side
# path (from sandbox cwd)", which is the spelling the model uses to delete
# it. Registering only the first left the delete uncancelled and reproduced
# the GlassOS false refute verbatim. 53 of the 135 real write
# confirmations in the corpus (39%) print a pair this did not collapse
# — a different statistic from the resolver's 39%, which is a
# coincidence of two unrelated measurements. Both slots name one entry.
_FS_WROTE_PAIR_RE = re.compile(
    # §4NU: `write` with append=true confirms in the same shape
    r"^SUCCESS: (?:Wrote|Appended) \d+ chars to '(.+?)'\. "
    r"Script-side path \(from sandbox cwd\): '(.+?)'\.")
_FS_PRODUCE_RES = (
    re.compile(r"^SUCCESS: (?:Wrote|Appended) \d+ chars to '(.+?)'\."),
    # §4SH: an empty last part finishing a file written in parts
    re.compile(r"^SUCCESS: Finished '(.+?)' — written in parts, nothing added now;"),
    # §4KC operation='edit' — path LAST and end-anchored, so a filename
    # containing `' — replaced` cannot plant a phantom path.
    re.compile(r"^SUCCESS: edited — replaced \d+ occurrence\S* of old_string "
               r"\(line[^)]*\) in '(.+?)'\.$"),
    # §4OC: the same line with its call tag — the path is GREEDY and the tag strict
    # (the tag's «…» cannot occur inside old_string: `_old_head` neutralises them),
    # so a filename holding `'.` is still read whole and the tag cannot plant a path
    re.compile(r"^SUCCESS: edited — replaced \d+ occurrence\S* of old_string "
               r"\(line[^)]*\) in '(.+)'\. \(This call's old_string began «[^«»\n]*»"
               r"(?:, ended «[^«»\n]*»)?\.\)$"),
    # the lenient form LAST: a tag without «» (the parity test renders every slot
    # as a plain token) — a real message always matched the strict one above
    re.compile(r"^SUCCESS: edited — replaced \d+ occurrence\S* of old_string "
               r"\(line[^)]*\) in '(.+?)'\. \(This call's old_string [^\n]*\.\)$"),
    re.compile(r"^SUCCESS: auto-promoted operation='replace' to 'write' "
               r"for '(.+?)' because"),
    re.compile(r"^SUCCESS: Streaming replace applied to '(.+?)' "
               r"\(\d+ line\(s\) modified\)\."),
    re.compile(r"^SUCCESS: Applied \d+ SEARCH/REPLACE blocks to '(.+?)'\."),
    re.compile(r"^SUCCESS: (?:Exact|Flexible) match found and replaced "
               r"in '(.+?)'\."),
    re.compile(r"^SUCCESS: Fuzzy match \([^)]*\) found and replaced "
               r"in '(.+?)'\."),
    re.compile(r"^SUCCESS: Anchor match — replaced the block spanning "
               r"lines .+? in '(.+?)' \("),
)
# The web subset the execution probe can load, and the entry-page subset
# whose disappearance must not be certified in silence.
_WEB_EXT_RE = re.compile(r"\.(?:html?|js|mjs|cjs)$", re.IGNORECASE)
_HTML_EXT_RE = re.compile(r"\.html?$", re.IGNORECASE)


def _fs_norm(path) -> str:
    """Bookkeeping key: the sandbox-relative, case-folded spelling."""
    p = str(path).strip()
    for pfx in _FS_PATH_PREFIXES:
        if p.startswith(pfx):
            p = p[len(pfx):]
            break
    return p.lstrip("/").rstrip("/").casefold()


# ⚠ Evidence over names. The first gate listed `workspace` (a READ-ONLY
# reporting tool) and `system_utility` (weather/diagnostics) — each silently
# neutralised real turns' absence checks — while an arbitrarily-named
# composed skill embedding an `execute` step walked past it. A shell run is
# recognised by the record itself: the execute tool's own result header,
# which composed-skill records embed verbatim for their shell steps.
# `manage_projects` is still NOT here — its removal paths (DONE-flip sweep,
# hard delete) stamp the store instead (see workspace_cleanup._mark_removal
# and ProjectStore.delete_project).
_REMOVAL_CAPABLE_NAMES = ("execute",)
# ⚠ ANCHORED at line start: the execute tool's own result header begins a
# line; a web page or recalled document merely QUOTING CI output mid-text
# must not disarm the absence check. Retrieval surfaces are excluded
# outright — browser PAGE TEXT and knowledge/recall bodies embed third-
# party text verbatim at line start, and none of them can run a shell.
# Residual accepted limit (fail-OPEN only — a missed refute, never a false
# one): a retrieval-free tool whose content carries an adversarial header
# at line start.
_SHELL_EVIDENCE_RE = re.compile(r"^--- (?:COMMAND|EXECUTION) RESULT ---",
                                re.MULTILINE)
_RETRIEVAL_SURFACE_NAMES = ("browser", "web_search", "knowledge_base",
                            "recall", "vision_analysis", "introspect")


#: §4PH (R3-5): the shapes that can REMOVE a file — a shell `rm`/`mv`, a
#: Python unlink/rmtree, a git clean. An execute that ran none of these
#: (`python report.py`, the ordinary write→run shape) cannot explain a
#: missing deliverable, and must not disarm the absence refute.
_REMOVAL_SHAPE_RE = re.compile(
    r"(?<![\w.\-/])(?:rm|rmdir|unlink|mv|shred|rename|truncate"
    r"|git\s+(?:clean|checkout|stash|reset|rm|mv))\b"
    r"|\bfind\b[^\n|;]*-delete\b|\brsync\b[^\n|;]*--delete"
    r"|\bos\.(?:remove|unlink|rename|replace|rmdir|removedirs)\b"
    r"|\bshutil\.(?:rmtree|move)\b|\bsend2trash\b"
    r"|\.(?:unlink|rename|rmdir)\(|\bfs\.(?:unlink|rm|rename|rmdir)\w*\("
    r"|\b(?:make|cargo|npm\s+run|yarn|gradle|mvn)\s+clean\b",
    re.I)                   # r3: `.replace(` is str.replace almost always; `make clean` is a tidy-up


def _is_removal_capable(name: str, content: str, args=None) -> bool:
    if name in _REMOVAL_CAPABLE_NAMES or "execute" in name:
        # §4PH (R3-5): judged by WHAT RAN, not by the tool's name. A record
        # without its call arguments (a legacy row) keeps the fail-open
        # reading (a missed refute, never a false one).
        if isinstance(args, dict) and args:
            blob = " ".join(str(args.get(k) or "") for k in ("command", "content", "filename"))
            return bool(_REMOVAL_SHAPE_RE.search(blob))
        return True
    if name in _RETRIEVAL_SURFACE_NAMES:
        return False
    return bool(_SHELL_EVIDENCE_RE.search(content[:4000]))


def _keys_removable_after_write(tools_run: Optional[list]) -> set:
    """Normalised keys of written files a LATER shell/script step could have
    removed.

    ⚠ Closes the ledger's oldest stated limit. A `SUCCESS: Wrote …`
    confirmation proves the file WAS produced; a later absence proves only
    that something removed it. When a removal-capable tool ran AFTER the
    write, "deliberate tidy-up the ledger cannot see" is at least as likely
    as "failed delivery" — the GlassOS incident, one tool over — so the
    missing-refute is downgraded to a logged skip for exactly those keys.
    ORDER is the evidence: an execute that ran before the write proves
    nothing, and those keys still refute.
    """
    exec_after: set = set()
    decided: set = set()
    exec_seen = False
    # ⚠ a pair-write's two spellings are ONE file: group them first, decide
    # by representative — otherwise a post-exec rewrite under one spelling
    # left the other spelling "removable" for the same bytes.
    rep: dict = {}
    for t in tools_run or []:
        if not isinstance(t, dict) or str(t.get("name", "")) != "file_system":
            continue
        c = str(t.get("content", ""))
        if c.startswith("[FAILURE BANNER]"):
            c = c.split("\n", 1)[1] if "\n" in c else ""
        m = _FS_WROTE_PAIR_RE.match(c.split("\n", 1)[0][:4000]) \
            if c.startswith("SUCCESS") else None
        if m:
            k1, k2 = _fs_norm(m.group(1)), _fs_norm(m.group(2))
            if k1 and k2 and k1 != k2:
                canon = rep.get(k1, rep.get(k2, k1))
                rep[k1] = rep[k2] = canon
    for t in reversed(tools_run or []):
        if not isinstance(t, dict) or t.get("_synthetic"):
            continue
        name = str(t.get("name", ""))
        if name != "file_system":
            if _is_removal_capable(name, str(t.get("content", "")),
                                   getattr(t.get("content"), "call_args", None)):
                # success or not: a script that failed AFTER its `rm` still
                # removed the file.
                exec_seen = True
            continue
        content = str(t.get("content", ""))
        if content.startswith("[FAILURE BANNER]"):
            content = content.split("\n", 1)[1] if "\n" in content else ""
        if not content.startswith("SUCCESS"):
            continue
        head = content.split("\n", 1)[0][:4000].strip()
        produced = []
        m = _FS_WROTE_PAIR_RE.match(head)
        if m:
            produced = [m.group(1), m.group(2)]
        else:
            m = _FS_MOVED_RE.match(head) or _FS_DEST_RE.match(head)
            if m:
                produced = [m.group(m.lastindex)]
            else:
                for _rx in _FS_PRODUCE_RES:
                    m = _rx.match(head)
                    if m:
                        produced = [m.group(1)]
                        break
        for p_ in produced:
            k = _fs_norm(p_)
            k = rep.get(k, k)
            if not k or k in decided:
                continue
            # ⚠ decide each key exactly ONCE, at its LAST produce — which is
            # the first time the reversed walk meets it. Deciding on every
            # produce let an EARLIER write of a re-written file add the key
            # even though the last write postdated every exec, silently
            # widening the downgrade to files the script could not have
            # removed.
            decided.add(k)
            if exec_seen:
                exec_after.add(k)
    # expand back to every spelling in each removable group
    for k2, canon in rep.items():
        if canon in exec_after:
            exec_after.add(k2)
    return exec_after


def _fs_wrote_pair_alts(tools_run: Optional[list]) -> dict:
    """{model spelling -> [tool-resolved spellings]} from Wrote-pair lines.

    ⚠ For RESOLUTION, not just cancellation. The ledger keeps the model's
    `filename` spelling; the tool's `rel_str` is where the file actually
    landed relative to the scoped dir. When the two diverge beyond the
    normalised prefixes, resolving only the model's spelling read a present
    file as MISSING — the claim-deeper shape an adversarial lens reproduced
    after the suffix arm covering it was deleted. The alternate spelling is
    the tool's own statement of the real location; try it before declaring
    a pair-written file absent.
    """
    out: dict = {}
    for t in tools_run or []:
        if not isinstance(t, dict) or t.get("_synthetic"):
            continue
        if str(t.get("name", "")) != "file_system":
            continue
        content = str(t.get("content", ""))
        if content.startswith("[FAILURE BANNER]"):
            content = content.split("\n", 1)[1] if "\n" in content else ""
        if not content.startswith("SUCCESS"):
            continue
        m = _FS_WROTE_PAIR_RE.match(content.split("\n", 1)[0][:4000].strip())
        if m and _fs_norm(m.group(1)) != _fs_norm(m.group(2)):
            out.setdefault(m.group(1), []).append(m.group(2))
    return out


def _fs_path_ledger(tools_run: Optional[list]) -> tuple:
    """-> (left_behind, retired) for this request's file_system calls.

    ``left_behind`` are the paths it produced and did not remove, in
    first-production order, deduplicated by normalised key (the original
    spelling is what comes back, since the consumers re-map prefixes
    themselves). ``retired`` are the paths it produced and then deleted
    or renamed away — kept, rather than discarded, so a consumer can tell
    "this request produced no web page" apart from "this request produced
    one and then removed it". A silent empty list is how a ground-truth
    check goes inoperative without anyone noticing.

    Only the confirmation LINE is parsed. Everything after the first
    newline is the tool echoing the edited source back (POST-EDIT VIEW,
    REPLACED BLOCK, a syntax-error excerpt), whose quoted strings are
    code, not paths.

    Former limits, all closed downstream (§4DI): a file removed by a shell
    `rm` through `execute` is still invisible to THIS parse, but the
    verdict's missing-refute is order-gated on it (`_keys_removable_after_
    write`); a workspace sweep racing the re-read is explained by the
    sweep's own store mark (`_mark_sweep`, recency-gated); and a `[FAILURE
    BANNER]` prefix used to drop a record whole — the parse reads past it.
    """
    alive: dict = {}        # normalised key -> [original spelling, is_alive]
    alias: dict = {}        # a second spelling of one file -> its primary key

    def _alias(secondary, primary_raw):
        k2, k1 = _fs_norm(secondary), _fs_norm(primary_raw)
        if k2 and k1 and k2 != k1:
            # ⚠ A SET, not a single key. The script-side spelling is a bare
            # relative path, so two projects writing `probe.py` map the same
            # alias; last-write-wins retired whichever wrote last, which is a
            # coin flip. Retiring every candidate is the safe direction: it
            # can silence an absence check (the path moves to the
            # emptiness-only arm) but can never manufacture the false REFUTE
            # this whole change exists to remove.
            alias.setdefault(k2, set()).add(k1)

    def _produce(raw):
        key = _fs_norm(raw)
        if not key:
            return
        if key in alive:
            alive[key][1] = True
        else:
            alive[key] = [raw, True]

    def _retire(raw):
        key = _fs_norm(raw)
        if not key:
            return
        # Retire through the alias table: the spelling used to delete a file
        # is routinely the one the write message advertised second.
        # ⚠ A DIRECT hit wins over the alias table. The alias key is a bare
        # spelling and can name a real file at the sandbox root: deleting
        # `probe.py` when the request wrote BOTH `probe.py` and
        # `projects/aaa/probe.py` retired the project's file too, though it
        # is still on disk. If the deleted spelling names something this
        # request produced under that very name, that is what was deleted.
        direct = [k for k in alive if k == key or k.startswith(key + "/")]
        if direct:
            for k in direct:
                alive[k][1] = False
            return
        targets = set()
        for k2, k1s in alias.items():
            if k2 == key or k2.startswith(key + "/"):
                targets.update(k1s)
        # (No subtree test here: `_alias` only ever maps FILE paths, so an
        # alias target can never be a parent of another live key. The
        # directory case is handled by `direct` above, which does test the
        # subtree. A mutation survivor showed this arm was dead code.)
        for k in alive:
            if k in targets:
                alive[k][1] = False

    for t in tools_run or []:
        if not isinstance(t, dict) or t.get("_synthetic"):
            continue
        # ⚠ The canonical name ONLY. `_canonicalise_tool_name` rewrites a
        # hallucinated "filesystem"/"file" to "file_system" BEFORE dispatch,
        # and the record is built from the rewritten name — so alias
        # branches here were dead. Worse than dead: the Context Shield's
        # edge-condense exemption (`fname not in ["file_system", …]`) lists
        # only the canonical name, so a record that somehow arrived under an
        # alias would be parsed here and condensed there, failing the SUCCESS
        # gate and vanishing whole — the exact failure the banner strip above
        # exists to prevent, through a channel no test could see. Two name
        # lists that must agree are one list too many.
        if str(t.get("name", "")) != "file_system":
            continue
        content = str(t.get("content", ""))
        # ⚠ A `[FAILURE BANNER] <first error line>\n` prefix can be prepended
        # to a tool result containing "Traceback"/"Error"/"SYSTEM ERROR" —
        # the trigger is not gated on the tool, though it also requires the
        # error line to have been truncated out of the head — and the
        # banner-prefixed text is what gets recorded. A successful edit whose
        # echoed POST-EDIT VIEW carries that word would then fail the SUCCESS
        # gate and the whole record would be dropped, silencing FILE-ARTIFACT
        # and WEB-EXEC on a turn that really did write files. The op still
        # succeeded, so the confirmation underneath is still the truth; read
        # past the banner. ⚠ No instance exists in 1,263 recorded file_system
        # results — this is a cheap guard against a reachable shape, not a
        # fix for an observed incident.
        if content.startswith("[FAILURE BANNER]"):
            content = content.split("\n", 1)[1] if "\n" in content else ""
        if not content.startswith("SUCCESS"):
            continue
        head = content.split("\n", 1)[0][:4000].strip()
        # ⚠ FOUR OVERLAPPING GUARDS keep an echoed confirmation inert: the
        # SUCCESS fast-path above, this confirmation-line split, `re.match`
        # anchoring at offset 0, and the `^` every pattern carries. The split
        # and the anchoring EACH suffice alone; the SUCCESS fast-path alone
        # does NOT — with the others gone it lets `_FS_RETIRE_RE` find an
        # echoed `SUCCESS: Deleted '…'` in the body and retire a live
        # deliverable. So a single-edit mutant on the split or an anchor
        # cannot fail a test, and that survival is redundancy, not missing
        # coverage — proven by the multi-edit mutant in
        # scripts/mutate_fs_ledger.py that strips every copy at once.
        # The behaviour is pinned by
        # `test_a_confirmation_echoed_inside_an_edited_file_is_inert`, whose
        # failure world is CONSTRUCTED, not observed: the file tool is
        # confined by `_get_safe_path` to <GHOST_HOME>/sandbox and cannot
        # reach this repo, and no file in the live sandbox contains such a
        # string. What is verified is the mechanism — a replace whose echoed
        # REPLACED BLOCK carries a confirmation line does retire a live
        # deliverable once the guards are gone. Do not read the comment as a
        # report of something that happened.
        m = _FS_RETIRE_RE.match(head)
        if m:
            _retire(m.group(1))
            continue
        m = _FS_MOVED_RE.match(head)
        if m:
            _retire(m.group(1))
            _produce(m.group(2))
            continue
        m = _FS_DEST_RE.match(head)
        if m:
            # Destination only: a Downloaded source is a URL, and a Copied
            # source was not produced by this request.
            _produce(m.group(1))
            continue
        # ⚠ No URL filter in this branch, on purpose. `Downloaded 'url' to
        # 'file'` is the only confirmation that ever quotes a URL, and it is
        # dispatched above, so a `"://" not in …` guard here would be
        # unreachable code that no test could exercise. An earlier draft had
        # one; mutation showed it survived everything, and dead guard code
        # reads as defence.
        m = _FS_WROTE_PAIR_RE.match(head)
        if m:
            _produce(m.group(1))
            _alias(m.group(2), m.group(1))
            continue
        for _rx in _FS_PRODUCE_RES:
            m = _rx.match(head)
            if m:
                _produce(m.group(1))
                break
    return ([o for o, ok in alive.values() if ok],
            [o for o, ok in alive.values() if not ok])


def _web_artifacts_written(tools_run: Optional[list]) -> list:
    """Web files (html/js) this request produced and did not remove.

    Feeds the verifier's execution check: a turn that WROTE web files must
    have its entry page actually loaded before a CONFIRMED is credible."""
    return [p for p in _fs_path_ledger(tools_run)[0] if _WEB_EXT_RE.search(p)]


def _retired_entry_pages(tools_run: Optional[list]) -> list:
    """HTML pages this request produced and then removed.

    The WEB-EXEC probe has no claim-prose leg — the written list is its
    only input — so dropping a removed page from that list would also
    disarm its inconclusive confidence cap, and a turn that renamed its
    only page to `index.html.bak` would be certified at full confidence.
    Deliberately narrow to `.html/.htm`: a retired `.js`/`.py` scratch
    file must NOT cap a turn whose deliverable was never a web page."""
    return [p for p in _fs_path_ledger(tools_run)[1] if _HTML_EXT_RE.search(p)]


def _files_mutated_this_turn(tools_run: Optional[list]) -> list:
    """ALL files this request produced and did not remove, any extension.

    Feeds the FILE-ARTIFACT ground-truth check alongside the answer-text
    claims: `_claimed_deliverable_files` only sees files the prose says were
    *created* ("wrote/saved/generated ..."), so a file the turn EDITED but
    described as "updated"/"fixed" was never re-checked — the 2026-07-19
    index.html marker-leak corruption shipped behind a CONFIRMED (100%)
    precisely because the corrupted file was an unclaimed edit."""
    return _fs_path_ledger(tools_run)[0]


# ── Deliverable-file ground-truth check ──────────────────────────────
# The #1 most-retrieved real lesson (ret=55) is the agent "prematurely
# declared task completion ... without showing the actual content" — it
# claims a file deliverable that is missing or empty in the sandbox. A
# text/vision verifier can't catch this (the claim reads fine); re-reading
# the file is hard ground truth. This is the general, non-web form of the
# web-exec override's "execute, don't trust" philosophy.
_DELIVERABLE_EXT = (
    r"md|markdown|txt|text|csv|tsv|json|jsonl|ya?ml|py|js|ts|sh|bash|sql|"
    r"html?|xml|ini|toml|cfg|conf|log|pdf|xlsx?|docx?|pptx?|png|jpe?g|svg|"
    r"tex|rs|go|java|c|cpp|rb|php|ipynb"
)
# A COMPLETION verb (past/perfect — the agent DID produce it, not a present-
# tense description of what a script does) followed within a short window by
# a filename. Anchoring on completion verbs keeps input files the agent only
# READ out of the candidate set and avoids "the script writes to X" (present
# tense) false positives.
_CLAIMED_FILE_RE = re.compile(
    r"\b(?:saved|wrote|written|created|generated|produced|exported|stored|"
    r"placed|dumped)\b"
    r"[^\n`'\"]{0,60}?"
    # ⚠ The capture MUST be able to include a leading "/" and a URL scheme.
    # It used to start at `[A-Za-z0-9]`, so a captured name could never begin
    # with "/" and the `://` was always eaten by the gap above — which made
    # BOTH filters below unreachable code. `Wrote /etc/hosts.conf` yielded
    # `etc/hosts.conf`, `Generated … https://example.com/guide.md` yielded
    # `example.com/guide.md`, and a `/api/download/…` markdown link yielded
    # `api/download/…`. Each then went into the hard, absence-refuting leg of
    # the ground-truth check. Two of the three FILE-ARTIFACT refutes
    # recoverable from the record were exactly this, on turns that ran no
    # file tool at all.
    # The optional leading `~` / `$VAR` group exists so those fragments are
    # CAPTURED (and then rejected by `_sandbox_shaped`) instead of the
    # capture restarting mid-path: `~/notes.md` used to yield `/notes.md` —
    # a legitimate-looking sandbox-root spelling for a file that lives in
    # the operator's home.
    # ⚠ the `~` branch is GREEDY: `~/.config/app/x.json` used to fail the
    # head char class at the dot, and the capture restarted mid-path as a
    # legitimate-looking relative `config/app/x.json`. Consuming the whole
    # home-relative form keeps it one rejectable token.
    r"[`'\"]?((?:~[A-Za-z0-9._/\-]*|\$\{?[A-Za-z_0-9]+\}?)?"
    r"(?:[A-Za-z][A-Za-z0-9+.\-]*://)?/?"
    r"[A-Za-z0-9][A-Za-z0-9._/\-]*\.(?:" + _DELIVERABLE_EXT + r"))\b",
    re.IGNORECASE,
)
# The download route the tools themselves instruct the model to emit —
# `report_pdf` and the image tools tell it to reply with
# `[title](/api/download/<rel>)`. The link is a URL, but `<rel>` is a REAL
# sandbox-relative path pointing at a real artifact that no other arm covers
# (`_fs_path_ledger` parses only `file_system` confirmations, and these files
# come from `image_generation` / `report_pdf`). So the route is STRIPPED, not
# dropped: the claim becomes the artifact it serves. 41 of 1,855 recorded
# turns carry such links; under the old drop they lost their only coverage.
# Sentinel distinguishing "caller did not capture a project id" from a
# captured None ("there WAS no project at spawn" — which must mean unscoped,
# not "read the mutable global again later").
# How long a workspace-removal mark explains a missing written file (same
# recency philosophy as `_locate_entry_page`'s freshness window).
_REMOVAL_MARK_FRESH_WINDOW_S = 900

_PROJECT_ID_UNCAPTURED = object()

#: `_no_verdict_reason` kinds that are the system working as designed.
_NO_VERDICT_BENIGN = frozenset({"member", "deferred", "landed"})


def _no_verdict_level(kind: str) -> str:
    """Log level of the finalize line for a `_no_verdict_reason` kind: a
    member turn, a verdict still coming and one that landed are routine; a
    verdict that was lost, came back empty or was skipped is a WARNING.
    §4OX: with the LLM judge off, "empty" is the ordinary outcome (the
    mechanical checks found nothing) — information."""
    if kind == "empty" and not verifier_judge_enabled():
        return "INFO"
    return "INFO" if kind in _NO_VERDICT_BENIGN else "WARNING"

# §4KS — the WEB-EXEC probe reads the outcome the browser tool DECLARES in
# its header (`tools/browser.py`): the line under `--- BROWSER RESULT ---`.
_WEB_EXEC_STATE_RE = re.compile(
    r"\A\s*--- BROWSER RESULT ---[ \t]*\r?\nSTATUS:[ \t]*([A-Z]+)")


def _web_exec_loaded(result) -> bool:
    """Did the browser tool declare this navigation a LOAD? True only for a
    `STATUS: OK` header on a result that is not a failed ToolOutcome.
    `STATUS: BLOCKED` (a 4xx/5xx or a challenge page), `STATUS: ERROR` and
    any shape without the header are not loads: an unknown shape must never
    read as clean."""
    m = _WEB_EXEC_STATE_RE.match(str(result or ""))
    _declared = str(getattr(getattr(result, "status", None), "value", "") or "")
    return bool(m) and m.group(1) == "OK" and _declared in ("", "ok")


_DOWNLOAD_ROUTE_PREFIXES =("/api/download/", "api/download/")


def _sandbox_shaped(name: str) -> bool:
    """Can this claimed path plausibly live inside the sandbox?

    ⚠ AN ALLOWLIST, deliberately. The previous filter was a denylist of
    host-path segments (`/usr/`, `/Users/`, …), and a denylist of "outside
    the sandbox" leaks by construction: `~/x.json`, `$HOME/a.txt`,
    `/Volumes/ext/z.csv` and the redaction artifact `/Data/AI/…` (born when
    `/Users/<user>` is redacted and the capture restarts mid-path) all
    walked past it, each becoming a claim about a file that cannot exist in
    the sandbox. The property is "inside the sandbox"; enumerate what IS,
    not what isn't:

      * a relative path (`report.md`, `webos/index.html`, `api/routes.py`);
      * a `/workspace/`-prefixed path — the container mount's own spelling;
      * a single-segment absolute (`/probe.py`) — the sandbox-ROOT spelling
        `_get_safe_path` heals, which real turns produce.

    A multi-segment absolute (`/etc/hosts.conf`, `/Users/v/notes.md`,
    `/Data/AI/…/checkpoint.json`) is a host path: there is no healed
    spelling that lands it in the sandbox. This also subsumes the old
    case-sensitivity hole (`/USR/x.md`) structurally — no tuple to drift.
    """
    if not name.startswith("/"):
        return True
    if name.startswith("/workspace/"):
        return True
    return "/" not in name[1:]          # "/probe.py" yes, "/etc/x.conf" no


def _claimed_deliverable_files(text) -> list:
    """Filenames the answer presents as a CREATED/SAVED deliverable.

    ⚠ These claims are checked for EMPTINESS ONLY, never absence (they ride
    the `soft` arm of `_verify_file_artifacts`). Every false FILE-ARTIFACT
    refute attested in the record came from this extractor — a host-path
    echo, a download link, a fragment of another tool's output — refuting a
    turn on the ABSENCE of a file the answer never really produced. The
    ledger's tool confirmations are the only absence-grade evidence; prose
    keeps the emptiness check (a claimed file that exists but is 0 bytes is
    a real defect) and loses the power to refute on what is not there.
    """
    if not text:
        return []
    out: list = []
    for m in _CLAIMED_FILE_RE.findall(str(text)):
        name = m.strip().strip("`'\"")
        if not name:
            continue
        if name.lower().startswith("file://"):
            # a file:// URL over a sandbox path IS a sandbox claim — the
            # browser tool itself teaches this spelling
            # (file:///workspace/...). Strip the scheme; the allowlist
            # judges what remains.
            name = name[7:]
        if not name or "://" in name:
            continue
        if name[:1] in ("~", "$"):
            continue                        # a home/env fragment, never ours
        for _pfx in _DOWNLOAD_ROUTE_PREFIXES:
            # case-insensitively: the claim regex is IGNORECASE, so the
            # capture can arrive as /API/DOWNLOAD/… — un-stripped, that
            # spelling fell to the allowlist as a multi-segment absolute and
            # silently lost its soft coverage.
            if name[:len(_pfx)].lower() == _pfx:
                name = name[len(_pfx):]     # the route -> the artifact
                break
        if not name or not _sandbox_shaped(name):
            continue
        if name not in out:
            out.append(name)
    return out[:8]


# ── Visual verification evidence ─────────────────────────────────────
# A text-only verifier cannot tell whether a reported VISUAL symptom
# ("the blocks look transparent", "the layout is broken") was actually
# fixed — the truth lives in the rendered pixels, not in the agent's
# self-claim. These helpers gate + gather the before/after screenshots so
# the verifier can look at the artifact and override an over-optimistic
# text CONFIRMED. See the visual-verify block in handle_chat.
_VISUAL_INTENT_RE = re.compile(
    r"\b(screenshot|screen[\s-]?grab|\bscreen\b|render(?:s|ed|ing)?|"
    r"transparen\w*|see[\s-]?through|invisible|blank|black\s+screen|"
    r"\bui\b|layout|css|displayed?|visual\w*|pixel\w*|graphic\w*|"
    r"looks?\s+(?:wrong|off|broken|weird|transparent)|appears?)\b",
    re.IGNORECASE,
)
_IMAGE_TOKEN_RE = re.compile(
    r"[\w./\\-]+\.(?:png|jpe?g|webp|gif|bmp)", re.IGNORECASE,
)


def _is_visual_intent(text: Optional[str]) -> bool:
    """Cheap (no-LLM) gate: does the user's request describe a VISUAL
    symptom or reference an image? Keeps the extra vision call off the
    ~99% of turns that aren't about how something looks."""
    if not text:
        return False
    if _IMAGE_TOKEN_RE.search(text):
        return True
    return bool(_VISUAL_INTENT_RE.search(text))


# ── Interaction-claim verification gap ───────────────────────────────
# A pointer/keyboard behavior ("dragging a window", "clicking the button")
# can only be confirmed by EXERCISING it. The WEB-EXEC probe proves the
# page loads without exceptions — nothing more — yet text entailment over
# a load-clean result happily CONFIRMED a still-broken drag fix at 100%
# (reqs AF/43, 2026-07-17). These helpers gate a confidence cap: the
# symptom is interaction-shaped AND no browser click/interact succeeded
# this turn → CONFIRMED is capped below the ≥0.7 consumption gates.
_INTERACTION_INTENT_RE = re.compile(
    r"\b(?:drag(?:ging|ged)?|resiz(?:e|ing|ed)|mov(?:e|ing|ed)|"
    r"scroll(?:ing)?|hover(?:ing)?|click(?:ing|ed)?|double[- ]click|"
    r"drop(?:ping|ped)?|typ(?:e|ing)|key(?:board|press)|swip(?:e|ing))\b"
    r".{0,60}?\b(?:window|element|button|icon|menu|item|panel|tab|card|"
    r"widget|handle|dialog|modal|slider|div|box)s?\b"
    r"|\b(?:window|element|button|icon|menu|item|panel|tab|card|widget|"
    r"handle|dialog|modal|slider)s?\b.{0,50}?"
    r"\b(?:drag|resiz|mov|click|scroll|hover|drop|swip)\w*\b",
    re.IGNORECASE | re.DOTALL,
)


def _is_interaction_intent(text: Optional[str]) -> bool:
    """Cheap (no-LLM) gate: the request describes a pointer/keyboard
    behavior on a UI element ("moving a window doesn't work")."""
    return bool(text and _INTERACTION_INTENT_RE.search(str(text)))


def _has_interaction_evidence(tools_run: Optional[list]) -> bool:
    """True when a browser click/interact op SUCCEEDED this turn — the
    only tool evidence that can support an interaction-behavior claim.
    Detection reads the tool result header (``STATUS: OK`` + ``OP: …``)
    because tools_run entries carry name+content, not arguments."""
    for tool in (tools_run or []):
        if not isinstance(tool, dict) or tool.get("_synthetic"):
            continue
        if str(tool.get("name", "")).lower() != "browser":
            continue
        content = str(tool.get("content", ""))
        if "STATUS: OK" not in content:
            continue
        if re.search(r"^OP: click\b", content, re.MULTILINE):
            return True
        if re.search(r"^OP: interact\b", content, re.MULTILINE) and (
                "⚠ NO EFFECT" not in content
                # §4NW: an interact counts unless EVERY click in it missed
                or re.search(r"^\s+\[\d+\] OK (?:click|dblclick|fill)\b[^\n]*\n(?!\s+⚠ NO EFFECT)",
                             content + "\n", re.MULTILINE)):
            return True
    return False


_BUG_REPORT_RE = re.compile(
    r"(nothing happens|doesn'?t work|does not work|not working|"
    r"isn'?t working|stopped working|won'?t (load|start|open|run)|"
    r"when i (click|press|open|run|load|type)\b.{0,60}"
    r"(nothing|fails?|error|crash|blank|stuck)|"
    r"\b(button|link|page|screen|app|game)\b.{0,40}"
    r"\b(broken|dead|stuck|frozen|blank)\b|"
    r"\bcrash(es|ed)?\b)",
    re.IGNORECASE | re.DOTALL,
)


def _msg_token_cost(m) -> int:
    """Token estimate for ONE message, INCLUDING native ``tool_calls`` args.

    §4N B-MAJOR-1: on the native-tools dialect an assistant message carries
    ``content=""`` and its arguments in ``msg["tool_calls"]`` — which the
    wire re-renders into text but every budget counter that read ``content``
    only scored as ZERO. A write-heavy native session then accumulated
    unbounded UNCOUNTED tokens: compaction fired late, the upstream 400'd,
    and destructive emergency recovery kicked in. One shared helper so the
    five counters can never diverge on this again. Never raises.
    """
    total = 0
    try:
        c = m.get("content", "")
        if isinstance(c, str):
            total += estimate_tokens(c)
        elif isinstance(c, list):
            for part in c:
                if isinstance(part, dict) and part.get("type") == "text":
                    total += estimate_tokens(str(part.get("text", "")))
        tcs = m.get("tool_calls")
        # §4N R2 MAJOR-1: count tool_calls args ONLY when they are NOT
        # already inline in content. On the live XML dialect the agent
        # keeps the raw `<tool_call>` XML in content AND the parsed calls
        # in `tool_calls`, but the wire translator emits ONE copy
        # (_render_assistant_with_tool_calls's `already_inline` short-
        # circuit) — so adding both double-counted (~2.14× measured),
        # firing compaction/lockdown at ~half the real occupancy every
        # write-heavy turn. On the native dialect content is "" and the
        # args live only in tool_calls, so this is where they must be
        # counted. Mirror the translator's own dedup condition.
        if tcs and "<tool_call>" not in (c if isinstance(c, str) else ""):
            total += estimate_tokens(json.dumps(tcs, ensure_ascii=False))
    except Exception:
        return total
    return total


def _estimate_messages_tokens(messages) -> int:
    """Rough token estimate over a message list (text parts + native
    tool_calls) — the shared basis for the occupancy-aware read budget and
    the context-pressure steers. Never raises."""
    total = 0
    try:
        for m in messages or []:
            total += _msg_token_cost(m)
    except Exception:
        return total
    return total


def _render_cwd_pin(project_id: Optional[str]) -> str:
    """The top-of-dynamic-state CWD pin for coding turns.

    Project-aware since 2026-07-18: the pin used to say "SHELL CWD IS
    /workspace" as static text even while a project was bound and the
    shell actually started in /workspace/projects/<id> — so the model
    trusted the pin over the (quieter) workspace note and ran
    `cd /workspace && git clone …`, planting a repo and the feasibility
    report at the sandbox ROOT where the project's manifest, briefing
    and cleanup never see them (observed live, request 6f14407f)."""
    if project_id:
        proj = f"/workspace/projects/{project_id}"
        return (
            f"⚠️  SHELL CWD IS {proj} — YOUR PROJECT WORKSPACE — DO NOT `cd` OUT OF IT  ⚠️\n"
            "The shell session ALREADY starts inside the project directory. "
            "Relative paths land INSIDE the project — exactly where its "
            "files belong. Anything written to /workspace/ outside "
            f"projects/{project_id}/ is OUTSIDE the project: invisible to "
            "its deliverables manifest, its briefing, and its cleanup. "
            "Paths like /sandbox, /home/user, /root, /app do NOT exist.\n"
            "  ✓  git clone <url> repo-src ; ls repo-src/\n"
            "  ✓  python3 parser.py ; cat output/report.md\n"
            f"  ✗  cd /workspace && …            (ESCAPES the project!)\n"
            f"  ✗  /workspace/some-dir/file.md   (outside the project)\n\n"
        )
    return (
        "⚠️  SHELL CWD IS /workspace — DO NOT USE `cd` ANYWHERE  ⚠️\n"
        "The shell session ALREADY starts in /workspace. "
        "Paths like /sandbox, /home/user, /root, /app, /tmp "
        "do NOT exist in this container and `cd` to any of "
        "them will fail with 'No such file or directory' "
        "and BURN A STRIKE. Run commands directly with "
        "relative paths:\n"
        "  ✓  python3 test_foo.py\n"
        "  ✓  python -m unittest tests.test_parser\n"
        "  ✓  ls subdir/ ; cat a/b.py\n"
        "  ✗  cd /home/user && python3 …   (FAILS)\n"
        "  ✗  cd /sandbox && …              (FAILS)\n\n"
    )


# `cd /workspace` as a token (not followed by /projects/), or an explicit
# /workspace/<seg> reference whose first segment is not projects/ — the two
# shapes by which a project-scoped shell escapes to the sandbox root.
_OFFPROJECT_CD_RE = re.compile(
    r"cd\s+/workspace(?:(?=[\s\"'&;|)])|/(?!projects/)|$)"
)
_OFFPROJECT_PATH_RE = re.compile(
    r"/workspace/(?!projects/)[\w.-]+"
)


def _offproject_target(fname, ptarget, a_hash, project_id) -> Optional[str]:
    """Return the offending path when a SUCCESSFUL tool call operated at the
    sandbox root while a project is bound, else None.

    The scoping machinery re-roots RELATIVE paths into projects/<id>/, and
    the /workspace→project heal fires only on file-not-found — so a call
    that succeeds with an explicit root-absolute path escapes every guard
    silently (observed live, request 6f14407f: `cd /workspace && git clone
    … prince-persia-repo` planted the repo and then the feasibility report
    at the root; the project dir stayed empty). This detector powers the
    once-per-request corrective steer in the dispatch pipeline."""
    if not project_id:
        return None
    if fname == "file_system":
        t = str(ptarget or "")
        if t.startswith("/workspace/") and not t.startswith(
                f"/workspace/projects/{project_id}"):
            if not t.startswith("/workspace/projects/"):
                return t
        return None
    if fname == "execute":
        blob = str(a_hash or "")
        m = _OFFPROJECT_CD_RE.search(blob)
        if m:
            return "cd /workspace (escapes the project scope)"
        m = _OFFPROJECT_PATH_RE.search(blob)
        if m:
            return m.group(0)
    return None


def _is_bug_report_intent(text: Optional[str]) -> bool:
    """Cheap (no-LLM) gate: the user is REPORTING a defect in something
    that already exists ("when I click X nothing happens"). These turns
    have a known best first move — reproduce and observe — and a known
    catastrophic first move — re-reading the source and hypothesizing
    (req 70: six wrong "I found it!" theories and a killed thinking loop
    before the first observation, which then named the bug instantly)."""
    if not text:
        return False
    return bool(_BUG_REPORT_RE.search(text))


def _extract_image_tokens(blob: Optional[str]) -> List[str]:
    """All image-file-looking tokens in a text blob, in order."""
    if not blob:
        return []
    return _IMAGE_TOKEN_RE.findall(str(blob))


def _resolve_image_path(token: str, sandbox_dir: Any) -> Optional[str]:
    """Resolve an image reference (which may be a container path like
    ``/sandbox/x.png`` or ``/workspace/projects/<id>/y.png``, or a bare
    filename) to an existing host path under ``sandbox_dir``. Mirrors the
    container→host + project-root fallbacks used by tools/vision.py.
    Returns ``None`` if nothing matching exists."""
    if not token or sandbox_dir is None:
        return None
    t = str(token).strip().strip("'\"")
    for pre in ("/api/download/", "/sandbox/", "/workspace/"):
        if t.startswith(pre):
            t = t[len(pre):]
    candidates: List[Path] = []
    try:
        p = Path(t)
        if p.is_absolute():
            candidates.append(p)
    except Exception:
        pass
    try:
        from ..tools.file_system import _get_safe_path
        candidates.append(_get_safe_path(sandbox_dir, t))
        if Path(sandbox_dir).parent.name == "projects":
            candidates.append(_get_safe_path(Path(sandbox_dir).parent.parent, t))
    except Exception:
        candidates.append(Path(sandbox_dir) / t)
    for c in candidates:
        try:
            if c.exists() and c.is_file():
                return str(c)
        except Exception:
            continue
    # Last resort: match the basename anywhere under the sandbox (newest wins).
    try:
        base = Path(t).name
        roots = [Path(sandbox_dir)]
        if Path(sandbox_dir).parent.name == "projects":
            roots.append(Path(sandbox_dir).parent.parent)
        matches: List[Path] = []
        for root in roots:
            matches.extend(root.rglob(base))
        # §4LM: never ANOTHER project's file — the root walk descends into
        # every projects/<id>/, and the verifier judged an unrelated
        # project's same-named chart.png as this turn's render.
        _is_project = Path(sandbox_dir).parent.name == "projects"
        _scope = Path(sandbox_dir).resolve()
        _projects = (Path(sandbox_dir).parent if _is_project
                     else Path(sandbox_dir) / "projects").resolve()

        def _in_scope(m: Path) -> bool:
            # the active project's own files, or shared root files — never a
            # project's when another (or none) is active
            r = m.resolve()
            return (_is_project and r.is_relative_to(_scope)) or not r.is_relative_to(_projects)
        matches = [m for m in matches if m.is_file() and _in_scope(m)]
        if matches:
            matches.sort(key=lambda m: m.stat().st_mtime, reverse=True)
            return str(matches[0])
    except Exception:
        pass
    return None


#: The name the attachment translator gives a pasted image (content hash).
#: Only that translator writes it, so the NAME is provenance: the file is the
#: user's own image, never a render the agent produced (§4LM).
_ATTACHMENT_NAME_RE = re.compile(r"^vision_[0-9a-f]{12}\.[a-z]{3,4}$")


def _attachment_filename(img_data: bytes, header: str = "") -> str:
    """`vision_<sha12>.<ext>` for a pasted image: the extension follows the
    bytes (or the data-URL header), so a PNG is not saved — and later typed —
    as `.jpg` (§4LM)."""
    from ..tools.vision import _sniff_image_mime
    mime = _sniff_image_mime(img_data[:16]) or ""
    if not mime:
        m = re.match(r"data:([\w.+/-]+)", header or "")
        mime = (m.group(1).lower() if m else "")
    ext = {"image/png": "png", "image/jpeg": "jpg", "image/gif": "gif", "image/bmp": "bmp",
           "image/tiff": "tiff", "image/webp": "webp", "image/svg+xml": "svg",
           "image/heic": "heic", "image/avif": "avif"}.get(mime, "jpg")
    return f"vision_{hashlib.sha256(img_data).hexdigest()[:12]}.{ext}"


def _user_attachment_names(messages: list, request_text: str = "") -> List[str]:
    """Attachment filenames of the images in THIS request's user message —
    the user message whose text parts are `request_text` (how handle_chat
    builds `last_user_content`). An image pasted requests ago is not this
    request's evidence (review: a photo from two turns back was judged as
    "the user's original screenshot" of a later, unrelated turn), so no
    match means no attachments."""
    import base64 as _b64

    def _norm(t: str) -> str:
        return " ".join(str(t or "").split())
    want = _norm(request_text)
    for msg in reversed(messages or []):
        if not isinstance(msg, dict) or msg.get("role") != "user":
            continue
        c = msg.get("content")
        parts = c if isinstance(c, list) else [{"type": "text", "text": c}]
        text = " ".join(i.get("text", "") for i in parts if isinstance(i, dict) and i.get("type") == "text")
        if _norm(text) != want:
            continue                       # a synthetic mid-turn row, or an older request
        names = []
        for item in parts:
            if not (isinstance(item, dict) and item.get("type") == "image_url"):
                continue
            url = str((item.get("image_url") or {}).get("url") or "")
            if url.startswith("data:") and "," in url:
                header, enc = url.split(",", 1)
                try:
                    names.append(_attachment_filename(_b64.b64decode(enc), header))
                except Exception:  # noqa: BLE001
                    continue
        return names
    return []


def _select_visual_evidence(messages: list, last_user_content: str,
                            sandbox_dir: Any) -> tuple:
    """Pick (before_image, after_image) host paths for visual verification.

    * before = an image the user referenced in their request (the symptom
      screenshot), if any — taken from ``last_user_content`` directly.
    * after  = a screenshot the agent produced this turn (a DIFFERENT image
      than the user's own). If the only image in play is the user's own,
      ``after`` is None — the agent never re-rendered, so there is no
      post-fix evidence and we must not judge.

    Scans ALL assistant/tool-role messages rather than "everything after the
    last user message": the agent loop injects synthetic user-role messages
    mid-turn (planning nudges, "### ACTIVE STRATEGY", AUTO-DIAGNOSTIC), so the
    last user message is often NOT the human's request and the screenshot can
    sit before it. The user's own before-image lives in a user-role message,
    so restricting to assistant/tool roles keeps before/after distinct.
    Among candidates the NEWEST file on disk wins — this turn's screenshot was
    just written, so it beats any stale image from an earlier turn.

    Returns ``(before|None, after|None)``."""
    before_img = None
    for tok in _extract_image_tokens(last_user_content):
        before_img = _resolve_image_path(tok, sandbox_dir)
        if before_img:
            break
    # A PASTED image's name never appears in the text-only user content, so
    # it is read from the raw message — and, being the user's, it is the
    # before image, never "the render after the agent's change" (§4LM).
    if not before_img:
        for _nm in _user_attachment_names(messages, last_user_content):
            before_img = _resolve_image_path(_nm, sandbox_dir)
            if before_img:
                break

    # Provenance beats name-matching (probe req 68033190): a screenshot the
    # AGENT wrote this turn is after-evidence even when its filename appears
    # in the user's message ("save it as functest_visual.png"). The old
    # `resolved != before_img` exclusion classified exactly that render as
    # "the user's own image" and skipped the whole visual check. Paths that
    # appear as an out_path in this turn's tool calls (native-JSON or XML
    # form) are RENDERED; only merely-referenced tokens keep the
    # user's-own-image exclusion.
    rendered: List[str] = []

    def _note_rendered(raw: Any) -> None:
        if not raw or not isinstance(raw, str):
            return
        resolved = _resolve_image_path(raw.strip(), sandbox_dir)
        if resolved and resolved not in rendered:
            rendered.append(resolved)

    candidates: List[str] = []
    # §4LN: a screenshot call that FAILED rendered nothing — its out_path
    # names yesterday's file, which then won "newest" as the post-fix image
    from .link_grounding import _failed_browser_result
    _failed_ids = {str(m.get("tool_call_id")) for m in messages
                   if isinstance(m, dict) and m.get("role") == "tool" and m.get("tool_call_id")
                   and _failed_browser_result(m.get("content"))}
    for msg in messages:
        if not isinstance(msg, dict):
            continue
        if msg.get("role") not in ("assistant", "tool"):
            continue
        if msg.get("role") == "tool" and _failed_browser_result(msg.get("content")):
            continue
        blob_parts: List[str] = []
        c = msg.get("content")
        if isinstance(c, str):
            blob_parts.append(c)
        tcs = msg.get("tool_calls")
        if isinstance(tcs, list):
            for tc in tcs:
                if isinstance(tc, dict) and str(tc.get("id")) in _failed_ids:
                    continue
                try:
                    blob_parts.append(json.dumps(tc))
                except Exception:
                    blob_parts.append(str(tc))
                # Structural out_path extraction: arguments may be a JSON
                # string or already a dict, and json.dumps above escapes
                # the inner quotes, so a regex over the blob misses them.
                try:
                    args = (tc.get("function") or {}).get("arguments")
                    if isinstance(args, str):
                        args = json.loads(args)
                    if isinstance(args, dict):
                        _note_rendered(args.get("out_path"))
                        acts = args.get("actions")
                        if isinstance(acts, list):
                            for a in acts:
                                if isinstance(a, dict):
                                    _note_rendered(a.get("out_path"))
                except Exception:
                    pass
        blob = " ".join(blob_parts)
        if msg.get("role") == "assistant":
            # XML tool-call form embeds parameters in content.
            for raw in re.findall(r'name="out_path">\s*([^<]+)<', blob):
                _note_rendered(raw)
        for tok in _extract_image_tokens(blob):
            resolved = _resolve_image_path(tok, sandbox_dir)
            if (resolved and resolved != before_img and resolved not in candidates
                    and not _ATTACHMENT_NAME_RE.match(Path(resolved).name)):
                candidates.append(resolved)

    if before_img and before_img in rendered:
        # The "user's image" is a file the agent wrote THIS turn — the user
        # was naming the output, not referencing a pre-existing symptom
        # shot. There is no genuine before; the render is after-evidence.
        before_img = None
    for r in rendered:
        if r not in candidates:
            candidates.append(r)

    after_img = None
    if candidates:
        try:
            after_img = max(candidates, key=lambda p: Path(p).stat().st_mtime)
        except Exception:
            after_img = candidates[-1]
    return before_img, after_img


# Per-request loop-detection accounting lives in core.strikes. These names
# are re-exported here because existing tests import them from
# ghost_agent.core.agent; the StrikeLedger (also in core.strikes) bundles
# the request-scoped state the turn loop used to track as bare locals.
from .strikes import (  # noqa: E402
    StrikeLedger,
    note_repeated_failure as _note_repeated_failure,
    note_repeated_action as _note_repeated_action,
    action_result_fingerprint as _action_result_fingerprint,
    breaker_fingerprint as _breaker_fingerprint,
    is_readwrite_loop_exempt as _is_readwrite_loop_exempt,
)


def _reconstruct_executed_code(
    messages: Optional[list],
    tool_msg: Optional[dict],
) -> str:
    """Walk `messages` backwards from the tool result to its matching
    assistant tool-call and return the code/command that was actually
    submitted to the tool.

    Previously the verifier gate at `handle_chat` called
    `verify_code_output(code=tool_name, ...)` — i.e. it passed the
    literal string "execute" as the code to audit. With nothing to
    reason about, the verifier hallucinated reasons the output didn't
    match ("appears to be a directory listing", "missing expected
    field", etc.) and REFUTED correct turns at high confidence. The
    fix: recover the actual code from the tool-call arguments via the
    `tool_call_id`, cap at 4000 chars, hand it to the verifier.

    Returns "" when the code can't be reconstructed — caller then
    falls back to `verify_claim` (no code slot, purely "does the
    evidence support the claim?" shape).
    """
    if not tool_msg or not messages:
        return ""
    tool_id = tool_msg.get("tool_call_id")
    if not tool_id:
        return ""
    for m in reversed(messages):
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        for tc in (m.get("tool_calls") or []):
            if not isinstance(tc, dict) or tc.get("id") != tool_id:
                continue
            fn = tc.get("function") or {}
            args_raw = fn.get("arguments")
            args: dict = {}
            if isinstance(args_raw, str):
                try:
                    args = json.loads(args_raw)
                except Exception:
                    # Not valid JSON — surface the raw string so the
                    # verifier has at least something to audit.
                    return args_raw[:4000]
            elif isinstance(args_raw, dict):
                args = args_raw
            # Common execute-tool arg shapes, in order of preference.
            for key in ("content", "code", "script_content", "text", "command", "cmd"):
                v = args.get(key)
                if isinstance(v, str) and v.strip():
                    return v[:4000]
            return ""
    return ""


def _vision_evidence_block(vv, image_path) -> str:
    """A DECISIVE vision verdict on the turn's generated image, as a labelled
    claim-evidence block — or "" (no verdict, or below 0.7)."""
    try:
        if vv is None or float(vv.confidence or 0) < 0.7:
            return ""
        v = getattr(vv.verdict, "value", vv.verdict)
        if v not in ("CONFIRMED", "REFUTED"):
            return ""
        name = os.path.basename(str(image_path or "")) or "the generated image"
        # The VERDICT only: vision was asked to compare the pixels with the
        # reply, so its reasoning restates the reply — figures and names the
        # binder would then count as "supported" (the echo class). A refute's
        # issues are kept: they can only weigh against the reply.
        # verdict only, for both outcomes: a refute's issues restate the reply
        # too (review R20) — and the scope is said, so it is never read as a
        # verdict on the reply's OTHER facts (web figures, names)
        # "MATCH / DO NOT MATCH", not the judge's own answer word (review R21)
        match = "the pixels MATCH the reply's description of this image" if v == "CONFIRMED" \
            else "the pixels DO NOT MATCH the reply's description of this image"
        # confidence in WORDS: "(90%)" supported a reply's "90%" in the number
        # audit (review R22)
        strength = "clearly" if float(vv.confidence) >= 0.9 else "probably"
        return (f"[vision_check] (an independent look at the pixels of {name}; it covers ONLY what "
                f"that image shows, never the reply's other facts) {strength}: {match}")
    except Exception:  # noqa: BLE001
        return ""


def _tool_call_summary(messages: Optional[list], tool_msg: Optional[dict]) -> str:
    """One line naming what a tool call was asked to do: the command/code
    when `_reconstruct_executed_code` recovers one, else the call's
    arguments (a file_system op, a path). Empty when unknown."""
    code = _reconstruct_executed_code(messages, tool_msg)
    if code:
        return code
    tool_id = (tool_msg or {}).get("tool_call_id")
    if not tool_id:
        return ""
    for m in reversed(messages or []):
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        for tc in (m.get("tool_calls") or []):
            if isinstance(tc, dict) and tc.get("id") == tool_id:
                args = (tc.get("function") or {}).get("arguments")
                return (args if isinstance(args, str) else json.dumps(args or {}, ensure_ascii=False))[:600]
    return ""


_EXEC_STEP_RE = re.compile(r"execute|postgres|file_system|shell|python")


def _turn_execution_transcript(messages: Optional[list], tools_run: Optional[list],
                               *, code_budget: int = 3500, output_budget: int = 4000) -> tuple:
    """(code_text, output_text) covering EVERY step the turn ran, in order,
    for the code-output lens — or ("", "") when the turn ran one step (the
    caller then keeps its single-command input, byte-identical).

    Refute audit 2026-09-25: the lens was handed the LAST tool's command and
    output only, so every create → measure → clean-up turn was judged on the
    clean-up: "failed to execute `echo alpha`" (the first call printed
    alpha), "never created or counted the file" (it did; the last call was
    `rm`), "the macro was never called" (only the final script was shown).
    6 of the route's 11 false refutes. Outputs are tail-weighted (the last
    step keeps the most) and every step is labelled so the judge can
    attribute a failure to one of them."""
    # Execution and file steps only — the ones a code turn's answer rests on.
    # An unrelated earlier page (a browser read, a search) stays out of this
    # lens, as it always has (test_code_path_keeps_single_output_view).
    steps = [t for t in (tools_run or []) if isinstance(t, dict) and not t.get("_synthetic")
             and _EXEC_STEP_RE.search(str(t.get("name", "")).lower())]
    if len(steps) < 2:
        return "", ""
    code_lines = []
    n = len(steps)

    _NOTE = "\n…[step output elided]…\n"

    def _cut(body: str, cap: int) -> str:
        if len(body) <= cap:
            return body
        keep = max(0, cap - len(_NOTE))           # the note counts toward the cap
        return body[: keep // 3] + _NOTE + body[len(body) - (keep - keep // 3):]

    for i, t in enumerate(steps, 1):
        name = str(t.get("name", "tool"))[:60]
        what = _tool_call_summary(messages, t).strip()
        code_lines.append(f"# --- step {i}/{n}: {name} ---\n{what}" if what else f"# --- step {i}/{n}: {name} ---")
    # The LAST step is never cut to make room (review R16: at 13+ steps the
    # tail — where a failure lands — was cut away while the earlier "ok"
    # steps stayed). It keeps half the budget; earlier steps share the rest,
    # newest first, and whatever does not fit is named, not silently dropped.
    last = steps[-1]
    last_part = f"[step {n}/{n}: {str(last.get('name', 'tool'))[:60]}]\n" + _cut(str(last.get("content", "")), output_budget // 2)
    room = output_budget - len(last_part) - 2
    earlier = []
    per = max(160, room // max(1, n - 1) - 40)
    for i in range(n - 1, 0, -1):                      # newest earlier step first
        t = steps[i - 1]
        part = f"[step {i}/{n}: {str(t.get('name', 'tool'))[:60]}]\n" + _cut(str(t.get("content", "")), per)
        if len(part) + 2 > room:
            earlier.insert(0, f"…[steps 1–{i} elided: output budget]…")
            break
        earlier.insert(0, part)
        room -= len(part) + 2
    # hard cap, the elision notice included (review R17: the uncounted
    # notice pushed the joined text past the cap and the consumer's [:4000]
    # cut the LAST step's tail). Only earlier parts are ever dropped.
    earlier = [e for e in earlier if not e.startswith("…[steps")]
    dropped = n - 1 - len(earlier)

    def _joined() -> str:
        head = [f"…[steps 1–{dropped} elided: output budget]…"] if dropped else []
        return "\n\n".join(head + earlier + [last_part])
    while earlier and len(_joined()) > output_budget:
        earlier.pop(0)
        dropped += 1
    out = _joined()
    if len(out) > output_budget:                      # only the notice + the last step remain
        out = out[len(out) - output_budget:]
    code_text = "\n".join(code_lines)
    if len(code_text) > code_budget:
        _cnote = "\n…[earlier steps elided]…\n"
        _ck = code_budget - len(_cnote)                 # the note counts toward the cap (review R19)
        code_text = code_text[: _ck // 3] + _cnote + code_text[len(code_text) - (_ck - _ck // 3):]
    return code_text, out


# ── The artifact the turn actually produced (§4GW, 2026-09-14) ───────
# req 0a017800 built `logslow.py` + a pytest file in the sandbox, ran both,
# and reported. The turn gate judged it twice 31 s apart — CONFIRMED 1.00,
# then REFUTED 0.90 "The agent did not provide the source code for
# `logslow.py` or `test_logslow.py`" — and the late verdict overwrote the
# turn as failed, scrubbed its lessons and queued a user-facing correction.
#
# The judge was right about what it could see. `_reconstruct_executed_code`
# hands the CODE slot the LAST tool call's command line, so a turn that
# WRITES three files and then runs one of them shows the auditor a single
# shell line — `python3 logslow.py sample.log` — and asks it whether the
# source was delivered. 7.9 kB of source, already on disk, already re-read
# by the FILE-ARTIFACT check two hundred lines below, were not in its view.
# A verdict that cannot distinguish "wrote the script" from "never wrote
# it" is a coin flip, and this one landed on both faces inside one turn.
# The slot is capped at 4000 downstream and the COMMAND shares it, so the
# block's budget is whatever the command leaves — never a fixed number that
# happens to fit the commands seen so far.
_AUDIT_SLOT_CAP = 8000           # == verifier.CODE_SLOT_CHARS, pinned
_AUDIT_COMMAND_FLOOR = 600       # the command is never squeezed below this
_AUDIT_SOURCE_BUDGET = 7200      # ceiling on the block, even with room spare
_AUDIT_SOURCE_MIN_SHARE = 700    # below this a file is noise, not evidence
_AUDIT_SOURCE_MAX_FILES = 4
_AUDIT_HEADER_RESERVE = 380      # a header + elision notice, worst case
_AUDIT_PATH_DISPLAY = 60         # so a deep path cannot outgrow the reserve
# Text the auditor can actually read. An image or a wheel contributes
# nothing but noise to a question about source.
_AUDIT_SOURCE_EXT_RE = re.compile(
    r"\.(?:py|js|mjs|ts|tsx|jsx|sh|bash|zsh|sql|rb|go|rs|c|h|cc|cpp|java|"
    r"php|pl|lua|r|jl|swift|kt|scala|md|markdown|txt|json|jsonl|ya?ml|"
    r"toml|ini|cfg|conf|html?|css|csv|tsv|xml|tex|ipynb)$", re.IGNORECASE)


# The block headers below are a TRUST SIGNAL in the audit prompt ("this
# file exists on disk with this content"), and the file bodies they wrap are
# model-authored. A file whose own text contains the header would forge
# evidence about files nobody wrote, so the marker is neutralised inside
# every body — the one place it can appear without having been earned.
_AUDIT_MARKER_RE = re.compile(r"^# --- (?=file this turn wrote|command this "
                              r"turn ran)", re.MULTILINE)


def _audit_source_budget(code_text: str) -> int:
    """Room left for the written-source block once the command has its own.

    The command is what `_reconstruct_executed_code` exists to protect, so it
    is served first; the block gets the remainder, capped."""
    return max(0, min(_AUDIT_SOURCE_BUDGET,
                      _AUDIT_SLOT_CAP - max(len(code_text or ""),
                                            _AUDIT_COMMAND_FLOOR)))


#: What a HEAD-ONLY cut cost, measured. The first pack cut each file at its
#: head; on the very turn that motivated this the judge then refuted with
#: "the test suite is missing the required test case for the missing-file
#: scenario" — about a test file cut at 1100 chars whose
#: `test_main_missing_file_returns_2` sits at char 2300. Saying "the rest
#: was elided" in the header did NOT stop it: measured again with a fuller
#: disclaimer and 1280 chars, the same complaint came back 2 times in 10.
#: A head cut systematically hides the END of a file, and the end of a
#: source file is where the later definitions live. `pack_claim` learned
#: this on the claim side in 2026-08 and the fix is the same one: keep both
#: ends and elide the middle, where a judge can spare it.
_AUDIT_HEAD_FRACTION = 0.55
_AUDIT_ELISION = ("\n[… {n} chars elided here by the audit packer, NOT the "
                  "end of the file — it continues below …]\n")


def _head_and_tail(body: str, take: int, missing: int = -1) -> str:
    """`body` cut to `take` chars keeping BOTH ends, with the seam marked.

    `missing` is how many chars of the FILE are not shown — which is not
    `len(body) - take` once `body` is itself a bounded read of a large file.
    Defaults to the old meaning for callers that hand over a whole file."""
    if missing < 0:
        missing = len(body) - take
    if take >= len(body) and missing <= 0:
        return body
    marker = _AUDIT_ELISION.format(n=missing)
    head_n = int(take * _AUDIT_HEAD_FRACTION)
    tail_n = take - head_n - len(marker)
    if tail_n <= 0:                      # no room for two ends: head only
        return body[:take]
    return body[:head_n] + marker + body[-tail_n:]


def _read_bounded(path, limit: int):
    """Return ``(text, size_on_disk)`` without reading more than ~2*limit.

    ⚠ `read_text()` here was unbounded, on the VERDICT path, over a filename
    the model chose. A turn that writes a 400 MB log and then runs anything
    would have had that log read whole into the agent's memory to build a
    prompt that shows at most 7 kB of it. Both ends are kept because the
    excerpt is what the auditor sees and the end of a source file is where
    the later definitions live."""
    size = path.stat().st_size
    with path.open("rb") as fh:
        if size <= 2 * limit:
            raw = fh.read()
        else:
            head = fh.read(limit)
            fh.seek(-limit, os.SEEK_END)
            raw = head + fh.read(limit)
    return raw.decode("utf-8", "replace"), size


#: §4OG-2 (b): the DOCUMENT deliverables a claim-lens turn wrote — read back
#: for the judge like code is for the code lens (a research report written
#: as a file was REFUTED "lacks the Sources section" the file had, §4OF)
# §4OV: scripts and code too — a reply that describes the script it wrote ("polls every
# 30 s, starts postgresql@17-…") was judged against an EARLIER read of the old one
_AUDIT_DOC_EXT_RE = re.compile(r"\.(?:md|markdown|txt|rst|html?|csv|tsv|json|ya?ml|tex"
                               r"|sh|bash|zsh|py|js|mjs|ts|css|sql|conf|ini|toml|service)$", re.IGNORECASE)
_AUDIT_DOC_BUDGET = 5000
_AUDIT_DOC_MAX_FILES = 2


_DELIVERED_MUTATIONS = ("write", "append", "edit", "replace")


def delivered_ok_from_calls(tool_calls, final_content) -> bool:
    """§4OG-2 (b): True when the turn's LAST `execute` exited clean, or when
    the reply names a file this turn wrote (a SUCCESS row) — the two shapes
    a delivered long task takes. The same-error shape rule yields to it: a
    delivered green build (§4OE probe, 23/23) and a written research report
    (§4OF probe) were both recorded FAILED by three earlier tool errors."""
    from .strikes import error_line
    calls = list(tool_calls or [])
    last_exec = next((tc for tc in reversed(calls)
                      if str(getattr(tc, "name", "") or "").lower() == "execute"), None)
    if last_exec is not None:
        res = str(getattr(last_exec, "full_result", "") or getattr(last_exec, "result", "") or "")
        from ..tools.tool_failure import exec_exit_code
        _code = exec_exit_code(res)
        if (not getattr(last_exec, "error", "") and not error_line(res, tool="execute")
                and not (_code is not None and int(_code) != 0)):
            return True
        return False                        # reader 2 M1: a FAILING last run vetoes the file arm
    from .reply_smoothing import strip_system_notes
    text = strip_system_notes(str(final_content or ""))     # §4OH reader M8: our notes hand nothing over
    if not text.strip():
        return False
    for tc in calls:
        if str(getattr(tc, "name", "") or "").lower() != "file_system":
            continue
        args = getattr(tc, "arguments", None) or {}
        if str(args.get("operation") or "").lower() not in _DELIVERED_MUTATIONS:
            continue
        if not str(getattr(tc, "result", "") or "").lstrip().startswith("SUCCESS"):
            continue
        path = str(args.get("path") or args.get("filename") or "").strip()
        base = path.replace("\\", "/").rsplit("/", 1)[-1]
        if base and _hands_over_file(text, base):
            return True
    return False


def _hands_over_file(text: str, base: str) -> bool:
    """The reply HANDS the file over — a download link, a markdown link, the
    name in a code span, or "written/saved to <name>" — not a mere mention
    ("I could not finish report.md", reader 2 M1)."""
    b = re.escape(base)
    return bool(re.search(r"/api/download/[^\s)]*" + b, text)
                or re.search(r"\]\([^)\s]*" + b + r"\)", text)
                or re.search(r"`[^`\n]*" + b + r"`", text)
                or re.search(r"(?i)\b(?:written|saved|exported|wrote|saved it|is) (?:to|at|in|as) [^\n]{0,80}" + b, text))


_DOC_LINK_EXT_RE = re.compile(r"\.(?:md|markdown|txt|rst|html?|tex)$", re.IGNORECASE)


def document_link_check_note(args: dict, tools_run) -> str:
    """§4OG-3 (d): a document this request WROTE (write/append of a .md/.txt/
    .html/.rst) cites URLs — list back the ones this request never fetched
    with an OK result, so the model fixes the citation itself (nothing is
    edited silently). "" when every link was read or the file is not a document."""
    from .link_grounding import unfetched_links, fetched_urls
    op = str((args or {}).get("operation") or "").lower()
    if op not in ("write", "append"):
        return ""
    path = str((args or {}).get("path") or (args or {}).get("filename") or "")
    if not _DOC_LINK_EXT_RE.search(path):
        return ""
    text = str((args or {}).get("content") or "")
    if "http" not in text:
        return ""
    missing = unfetched_links(text, fetched_urls(tools_run))
    if not missing:
        return ""
    shown = ", ".join(missing[:6]) + (f" (+{len(missing) - 6} more)" if len(missing) > 6 else "")
    from .receipt_marks import LINK_CHECK_HEAD as _LCH  # §4QO: one home for the literal
    return (f"\n{_LCH}{len(missing)} URL(s) in '{path}' were NOT fetched successfully this request: {shown}. "
            f"A report must cite only pages you actually read: open each with `browser` and keep it, or "
            f"edit the file (operation='edit') to remove it or replace it with a page you did read.")


def _read_doc_for_check(path: str, roots, limit: int = 2_000_000) -> str:
    """The text of a document this request wrote, read from the first root it
    resolves under (containment-checked); "" when absent or unreadable."""
    rel = str(path or "").strip().lstrip("/")
    for pfx in _FS_PATH_PREFIXES:
        if rel.startswith(pfx):
            rel = rel[len(pfx):].lstrip("/")
            break
    for root in roots or ():
        if not root:
            continue
        try:
            base = Path(str(root)).resolve()
            target = (base / rel).resolve()
            if not str(target).startswith(str(base) + os.sep) or not target.is_file():
                continue
            with target.open("rb") as fh:
                return fh.read(limit).decode("utf-8", "replace")
        except Exception:  # noqa: BLE001
            continue
    return ""


async def unfinished_parts_note(req_id) -> str:
    """§4OI (iii) + §4SH: the files this request left OPEN for parts (the last
    part left them open for more) are closed here and judged by their content.
    Only a file whose check finds something is named (census turn 065: a
    "complete, open it and play" over an unterminated file); one that passes
    says nothing (req cb27058e: a page tested three times in the browser was
    reported "incomplete and never checked" because of the flag alone)."""
    try:
        from ..tools.file_system import settle_open_parts
        settled = await settle_open_parts(req_id)
    except Exception:  # noqa: BLE001
        return ""
    lines = [f"⚠️ `{name}` was written in parts and was left open for more, but nothing "
             f"followed — {finding.rstrip('.')}." for name, finding in settled if finding]
    return ("\n\n" + "\n".join(lines[:4])) if lines else ""


def unopened_citation_note(tools_run, roots) -> str:
    """§4OH (a): the §4OG link check is advisory — the model may keep a URL it
    never opened (the §4OG research probe kept three). At the end of the
    request, the documents this request wrote are read back from disk and any
    cited URL with no OK fetch this request is DISCLOSED in the reply, so the
    owner knows which sources are unverified. Nothing is edited. "" when every
    cited link was read (or nothing was written)."""
    from .link_grounding import unfetched_links, fetched_urls
    docs: list = []
    written_by: dict = {}
    for t in tools_run or []:
        if not isinstance(t, dict) or t.get("_synthetic") or t.get("name") != "file_system":
            continue
        a = getattr(t.get("content"), "call_args", None)
        if not isinstance(a, dict):
            a = t.get("args") or t.get("call_args") or {}
        _op = str(a.get("operation") or "").lower()
        if _op not in ("write", "append", "edit", "replace"):          # r2 m5: the model adds to documents by edit
            continue
        if not str(t.get("content") or "").lstrip().startswith("SUCCESS"):
            continue
        p = str(a.get("path") or a.get("filename") or "").strip()
        if not (p and _DOC_LINK_EXT_RE.search(p)):
            continue
        m = re.search(r"Script-side path \(from sandbox cwd\): '(.+?)'\.", str(t.get("content") or ""))
        written = written_by.setdefault(p, {"alts": [], "text": ""})
        if m and m.group(1) not in written["alts"]:
            written["alts"].append(m.group(1))                    # reader m5: the tool's own spelling
        written["text"] += "\n" + str((a.get("content") if _op in ("write", "append") else
                                       (a.get("new_string") or a.get("new_text") or a.get("replace_with")
                                        or a.get("replacement") or a.get("new"))) or "")   # reader M9: only what THIS request wrote
        if p not in docs:
            docs.append(p)
    if not docs:
        return ""
    _FETCHERS = ("browser", "web_search", "deep_research", "darkweb_search", "darkweb_research")
    if not any(isinstance(t, dict) and not t.get("_synthetic")
               and (t.get("name") in _FETCHERS
                    or str(t.get("content") or "").lstrip().startswith("SUCCESS: Downloaded"))   # r3: a download is a fetch
               for t in tools_run or []):
        return ""      # r2 M4: a rewrite/revision request carries an EARLIER request's sources — 6 of 9 would be false
    fetched = fetched_urls(tools_run)
    found = []
    for p in docs[:4]:
        text = ""
        for cand in [p] + written_by[p]["alts"]:
            text = _read_doc_for_check(cand, roots)
            if text:
                break
        if "http" not in text:
            continue
        on_disk = {u for u in unfetched_links(text, fetched)}           # still in the file (the model may have fixed it)
        miss = [u for u in unfetched_links(written_by[p]["text"], fetched) if u in on_disk]
        if miss:
            found.append((p, miss))
    if not found:
        return ""
    total = sum(len(m) for _, m in found)
    # §4QA: say WHERE an unread link came from — live, 20 links copied from
    # this request's own search snippets were captioned "an earlier request
    # may have read them", which they could not have been
    from .link_grounding import search_result_urls, _cite_norm
    _snip = {_cite_norm(u) for u in search_result_urls(tools_run)}
    n_snip = sum(1 for _, m in found for u in m if _cite_norm(u) in _snip)
    # r9: a link a browser page or a research source block showed is in THIS
    # request's output too, not "an earlier request's" (file reads excluded:
    # an older document is an earlier request's sources)
    _seen_text = "\n".join(str(t.get("content") or "") for t in tools_run or []
                           if isinstance(t, dict) and not t.get("_synthetic")
                           and t.get("name") != "file_system")
    from .link_grounding import _URL_RE as _qa_url_re          # the same URL reader as `found` (r11 m2)
    _seen = {_cite_norm(m.group(0)) for m in _qa_url_re.finditer(_seen_text)}
    n_seen = sum(1 for _, m in found for u in m
                 if _cite_norm(u) not in _snip and _cite_norm(u) in _seen)
    n_other = total - n_snip - n_seen
    parts = []
    for p, miss in found:
        shown = ", ".join(miss[:6]) + (f" (+{len(miss) - 6} more)" if len(miss) > 6 else "")
        parts.append(f"`{p.replace(chr(92), '/').rsplit('/', 1)[-1]}`: {shown}")
    why = []
    if n_snip:
        why.append(f"{n_snip} only from this request's search-result snippets — the page itself was not read")
    if n_seen:
        why.append(f"{n_seen} only in the text of a page or result this request read — the link itself was not opened")
    if n_other:
        why.append(f"{n_other} in no result of this request (an earlier request may have read "
                   + ("it" if n_other == 1 else "them") + ")")
    return ("\n\n_Source check: " + str(total) + (" link" if total == 1 else " links")
            + " this request wrote into the file" + ("s" if len(found) > 1 else "")
            + " " + ("was" if total == 1 else "were") + " not opened during this request ("
            + "; ".join(why) + ") — "
            + "; ".join(parts) + "._")


def _persist_stream_stop_state(context, session_id, tools_snapshot, ask, role) -> bool:
    """§4OH (e): a streamed final that did not drain to its end (Stop, a closed
    client) leaves the conversation's STATE OF WORK, as a non-streamed cancel
    does — the §4OE persist ran in handle_chat's finally, before the drain.
    Owner only; nothing when no tool ran. Returns True when stored."""
    from .task_state import state_of_work_text, persist_state_of_work
    sid = str(session_id or "").strip()
    rows = list(tools_snapshot or [])
    if not sid or str(role or "") == "member" or not any(
            isinstance(r, dict) and not r.get("_synthetic") for r in rows):
        return False
    ok = persist_state_of_work(getattr(context, "scratchpad", None), sid,
                               state_of_work_text(rows, ask=str(ask or ""), why="the reply was stopped while it streamed"))
    if ok:
        pretty_log("State Of Work", f"persisted for session {sid[:24]} (the streamed reply was stopped)",
                   icon=Icons.BRAIN_CTX, durable_only=True)
    return ok


#: §4OV: the override tags of the arms that ground a refute in something
#: other than a judge's reading — a page that throws, a written file that is
#: missing, a reply with no answer, a broken turn constraint, a memory claim
#: against the stored profile, the pixels of an image.
_GROUNDED_REFUTE_TAGS = frozenset({"web-exec", "file-artifact", "reply-shape", "turn-state",
                                   "memory-claim", "visual"})


def refute_is_grounded(v_result) -> bool:
    """Whether a REFUTED verdict rests on a mechanical arm (its override
    chain names one), not on a judge's reading alone."""
    tags = str(getattr(v_result, "override", "") or "").lower().split("+")
    return any(t.strip() in _GROUNDED_REFUTE_TAGS for t in tags)


def verifier_judge_enabled() -> bool:
    """§4OW: GHOST_VERIFIER_JUDGE=1 turns the LLM judge back on (off by
    operator decision); the mechanical verifier arms run either way."""
    return os.getenv("GHOST_VERIFIER_JUDGE", "0").strip().lower() in ("1", "true", "on", "yes")


#: §4OX: the loop-exit wait for the mechanical verdict when the judge is off
MECHANICAL_REPAIR_BUDGET_DEFAULT_S = 15.0
MECHANICAL_REPAIR_BUDGET_MAX_S = 60.0


def mechanical_repair_budget_s() -> float:
    """GHOST_MECHANICAL_REPAIR_BUDGET seconds (default 15, 0 = do not wait,
    capped at 60): how long a reply waits for the mechanical checks so a
    refute can be repaired before it ships."""
    raw = (os.getenv("GHOST_MECHANICAL_REPAIR_BUDGET") or "").strip()
    try:
        v = float(raw) if raw else MECHANICAL_REPAIR_BUDGET_DEFAULT_S
    except ValueError:
        v = MECHANICAL_REPAIR_BUDGET_DEFAULT_S
    if v != v:                                  # "nan"
        v = MECHANICAL_REPAIR_BUDGET_DEFAULT_S
    return max(0.0, min(MECHANICAL_REPAIR_BUDGET_MAX_S, v))


def _first_js_error(err_block: str) -> str:
    """The first exception line of a WEB-EXEC error block ("• SyntaxError: …")."""
    for line in str(err_block or "").splitlines():
        t = line.strip().lstrip("•*-").strip()
        if t and not t.upper().startswith("UNCAUGHT JS EXCEPTION"):
            return t[:200]
    return ""


def _refute_is_image_only(v_result) -> bool:
    """§4OX: a refute whose only grounding is the pixel check of an image."""
    tags = [t.strip() for t in str(getattr(v_result, "override", "") or "").lower().split("+") if t.strip()]
    return bool(tags) and set(tags) <= {"visual", "image-unseen"}


def judge_refute_consequences_enabled() -> bool:
    """GHOST_JUDGE_REFUTE_CONSEQUENCES=1 restores the pre-§4OV behaviour: a
    judge-only refute marks the turn failed and runs every consequence."""
    return os.getenv("GHOST_JUDGE_REFUTE_CONSEQUENCES", "0").strip().lower() in ("1", "true", "on", "yes")


def _written_documents_for_audit(tools_run, host_dir, claim_text: str = "", budget: int = 0) -> str:
    """The document files this turn wrote, read back off disk, labelled —
    for the CLAIM lens's evidence ("" when none). §4OV: a file larger than
    its share keeps its head AND the part the claim refers to (a 43k webOS
    page was cut to its CSS, and "11 apps" was refuted as unseen)."""
    # r1 M1: a budget from the caller caps the pack (half the evidence budget) —
    # a pack larger than the evidence budget left the tool digest 28 chars
    return _written_sources_for_audit(tools_run, host_dir,
                                      budget=min(_AUDIT_DOC_BUDGET, budget) if budget > 0 else _AUDIT_DOC_BUDGET,
                                      max_files=_AUDIT_DOC_MAX_FILES, ext_re=_AUDIT_DOC_EXT_RE,
                                      claim_text=claim_text)


#: §4OV: how much of a written file the claim-aware cut may search
_AUDIT_CLAIM_READ = 300_000
_CLAIM_WORD_RE = re.compile(r"[^\W\d_]{5,}")


def _claim_names_text_past(body: str, start: int, claim_text: str) -> bool:
    """Whether a significant word of the claim (5+ letters) stands in the
    file past ``start`` — else the claim-aware cut has nothing to pull and
    the head-and-tail view is the honest one (r1)."""
    tail = body[start:].lower()
    words = {w.lower() for w in _CLAIM_WORD_RE.findall(str(claim_text or ""))}
    return any(w in tail for w in words)


def _written_sources_for_audit(tools_run, host_dir,
                               budget: int = _AUDIT_SOURCE_BUDGET,
                               max_files: int = _AUDIT_SOURCE_MAX_FILES,
                               ext_re=None, claim_text: str = "") -> str:
    """The source this turn WROTE, labelled, for the code lens's CODE slot.

    Reads the files back off disk rather than replaying the write-call
    arguments: what the user can open is the deliverable, and a write whose
    content never landed is exactly the failure the auditor should see.

    `budget` is the whole block's ceiling, headers included, and is divided
    between the files that fit — a file whose share would fall below
    `_AUDIT_SOURCE_MIN_SHARE` is dropped rather than cut into noise, and a
    file shorter than its share hands the remainder back. The caller sizes
    the budget from what the COMMAND leaves (`_audit_source_budget`):
    silently pushing the command out of the prompt would trade this blind
    spot for the one `_reconstruct_executed_code` was written to fix.
    Truncation is marked, never silent. Returns "" when the turn wrote
    nothing readable; never raises.
    """
    if not tools_run or not host_dir:
        return ""
    try:
        written = _files_mutated_this_turn(tools_run)
    except Exception:  # noqa: BLE001
        return ""
    if not written:
        return ""
    try:
        root = Path(str(host_dir)).resolve()
    except Exception:  # noqa: BLE001
        return ""
    # Pass 1 — WHAT is there. Reading first is what makes the share honest:
    # dividing the budget before knowing the sizes gives a 200-char README
    # the same room as a 4 kB module, and the module pays for it.
    files, seen = [], set()
    for name in written:
        if len(files) >= max_files:
            break
        rel = str(name).strip()
        for pfx in _FS_PATH_PREFIXES:
            if rel.startswith(pfx):
                rel = rel[len(pfx):]
                break
        rel = rel.lstrip("/")
        if not rel or not (ext_re or _AUDIT_SOURCE_EXT_RE).search(rel):
            continue
        key = _fs_norm(rel)
        if key in seen:
            continue
        seen.add(key)
        try:
            target = (root / rel).resolve()
            # Containment, for the same reason the artifact check scopes:
            # a written path is model-supplied text and `..` resolves.
            if not str(target).startswith(str(root) + os.sep):
                continue
            if not target.is_file():
                continue
            body, size = _read_bounded(target, _AUDIT_CLAIM_READ if claim_text else budget)
        except Exception:  # noqa: BLE001
            continue
        if not body.strip():
            continue
        files.append((rel, body, size))
    if not files:
        return ""

    # Pass 2 — WHO gets the room. The header counts against the budget too:
    # four elision notices are a kilobyte, and a budget that ignores its own
    # labels is how the command gets pushed out of a prompt that claims to
    # have reserved room for it. Drop the last file rather than cut every
    # file below the point where the pack stops being readable.
    while files and ((budget - len(files) * _AUDIT_HEADER_RESERVE)
                     // len(files)) < _AUDIT_SOURCE_MIN_SHARE:
        files.pop()
    if not files:
        return ""
    room = (budget - len(files) * _AUDIT_HEADER_RESERVE) // len(files)
    # A file shorter than its share hands the remainder back: two files, one
    # of 200 chars, must not leave the other cut at half the slot.
    spare = sum(room - len(b) for _, b, _sz in files if len(b) < room)
    over = sum(1 for _, b, _sz in files if len(b) >= room)
    bonus = spare // over if over else 0

    blocks = []
    for rel, body, size in files:
        take = min(len(body), room + (bonus if len(body) >= room else 0))
        # `size` is the file; `body` may already be a bounded read of it. The
        # auditor is told about the FILE, so the elided count is measured
        # against the file — not against however much of it we hold.
        _claim_cut = bool(claim_text) and take < len(body) and _claim_names_text_past(body, take // 2, claim_text)
        shown = _AUDIT_MARKER_RE.sub(
            "# -- ", _slice_evidence_body(body, take, claim_text) if _claim_cut
            else _head_and_tail(body, take, missing=max(0, size - take)))
        head = (f"# --- file this turn wrote: {rel[:_AUDIT_PATH_DISPLAY]} "
                f"({size} chars on disk)")
        # ⚠ `take` vs the FILE, not `len(shown)`: defanging a forged header
        # SHORTENS the text, so a whole file carrying one would otherwise be
        # announced as elided — a truncation notice on a complete file is the
        # same class of lie as a silent cut, pointing the other way.
        if take < size and _claim_cut:
            head += (f"; about {len(shown)} of them appear below — the head and the part the "
                     f"reply's claim refers to — the rest elided to fit this prompt")
        elif take < size:
            head += (f"; only {take} of them appear below, head and tail, "
                     f"with the middle elided by the audit packer to fit "
                     f"this prompt")
        blocks.append(head + " ---\n" + shown)
    return "\n\n".join(blocks)


def classify_thinking_budget(query: str,
                             has_coding_intent: bool = False,
                             is_meta_task: bool = False,
                             in_active_project: bool = False) -> str:
    """Pick the <think> block guidance for this turn.

    Returns either ``"tight"`` (the anti-paralysis directive used
    historically for everything; the 5-sentence cap it carried went with §4RK) or ``"extended"`` (step-by-step derivation; §4RK: no sentence cap
    for genuine multi-step reasoning). See ``prompts.THINK_BUDGET_*``
    for the prompt text each returns.

    Extended only fires when the query hints at multi-step reasoning
    AND the overall intent isn't a meta task (title/caption/rename —
    those are fundamentally single-shot).

    When ``in_active_project`` is True, we bias HARD toward tight.
    During long-running project work most turns are bookkeeping
    (mark task done, write next file, run a check) driven by the
    task tree rather than the user's last message. Extended thinking
    on those turns costs 15-25s and produces prose the task tree
    already encodes — the 2026-04-19 trace spent 8+ turns doing
    this. We still escalate to extended when the user's latest
    message is visibly a new complex ask (≥3 extended keywords) so
    genuine "now debug this tricky bug" follow-ups still get room.
    """
    if is_meta_task:
        return "tight"
    if not query:
        return "tight"
    lowered = query.lower()
    hits = sum(1 for kw in _EXTENDED_THINK_KEYWORDS if kw in lowered)
    if in_active_project:
        # Much higher bar inside a project: only escalate when the
        # user's current turn is unambiguously a new complex ask.
        return "extended" if hits >= 3 else "tight"
    if hits >= 2:
        return "extended"
    # Coding intent with a single strong keyword still warrants extended.
    if has_coding_intent and hits >= 1:
        return "extended"
    return "tight"


def render_think_budget_guidance(budget: str) -> str:
    """Return the guidance string to splice into QWEN_TOOL_PROMPT."""
    if budget == "extended":
        return THINK_BUDGET_EXTENDED
    return THINK_BUDGET_TIGHT


# Social / open-ended openers that should KEEP the warm conversational profile
# even though they ask a question (no single correct answer).
_CHITCHAT_MARKERS = (
    "how are you", "who are you", "what's up", "whats up", "tell me about yourself",
    "tell me a", "write a poem", "write a story", "what do you think",
    "your opinion", "how do you feel", "let's chat", "lets chat", "good morning",
    "good evening", "thank you", "thanks",
)
# Strong signals that the query expects ONE deterministic answer.
_FACTUAL_MARKERS = (
    "how many", "how much", "how long", "what is the", "what's the", "what are the",
    "compute", "calculate", "evaluate", "solve", "sum of", "product of", "count",
    "number of", "value of", "result of", "how do i", "what year", "what day",
    "which", "convert", "factorial", "prime", "divisible", "average", "median",
    "percentage", "square root", "list the", "define ",
)


def _is_factual_query(query: str) -> bool:
    """Heuristic: does this non-tool query have a single correct/deterministic
    answer (math, counting, lookup) rather than open-ended chit-chat?

    Conservative toward FACTUAL: a genuine question routes to near-greedy
    sampling; only clearly social/creative openers stay on the warm profile.
    """
    q = (query or "").strip().lower()
    if not q:
        return False
    if any(m in q for m in _CHITCHAT_MARKERS):
        return False
    if any(m in q for m in _FACTUAL_MARKERS):
        return True
    # a digit present alongside a question usually means a computed answer
    if any(ch.isdigit() for ch in q) and ("?" in q or q.split()[0] in (
            "what", "how", "which", "when", "calculate", "compute", "find")):
        return True
    # short interrogative that isn't a social opener → treat as factual
    if q.endswith("?") and len(q.split()) <= 24 and q.split()[0] in (
            "what", "which", "when", "who", "where", "is", "are", "does", "do",
            "can", "how"):
        return True
    return False


_TOOL_ACTIVITY_CONTENT_RE = re.compile(
    r"!\[[^\]]*\]\(/api/download/|<tool_call>|<tool_response|EXIT CODE:")
_TOOL_ACTIVITY_LOOKBACK = 12


def _history_shows_tool_activity(messages) -> bool:
    """Did the recent thread run tools? A `tool`-role row, an assistant
    row carrying `tool_calls`, or content that only a tool turn produces (an
    `/api/download/` image line, a tool-call/response marker, an EXIT CODE)
    inside the last `_TOOL_ACTIVITY_LOOKBACK` history rows BEFORE the
    pending user message. Slack forwards the bot's own earlier replies as
    plain history rows, so the content markers are what carry the signal
    there. A pure conversation (greetings, Q&A with no tools) is False."""
    try:
        rows = [m for m in (messages or []) if isinstance(m, dict)]
    except Exception:  # noqa: BLE001
        return False
    if rows and rows[-1].get("role") == "user":
        rows = rows[:-1]
    for m in rows[-_TOOL_ACTIVITY_LOOKBACK:]:
        role = str(m.get("role") or "")
        if role == "tool":
            return True
        if role == "assistant" and m.get("tool_calls"):
            return True
        c = m.get("content")
        if isinstance(c, list):                      # multimodal rows: text blocks
            c = " ".join(str(b.get("text") or "") for b in c if isinstance(b, dict))
        if role in ("assistant", "user") and isinstance(c, str) and _TOOL_ACTIVITY_CONTENT_RE.search(c):
            return True
    return False


def get_sampling_params(is_tool_turn: bool, query: str = "", is_coding: bool = False) -> dict:
    """Return the sampling profile for the current turn.

    Policy (matches the Qwen 3.6 35B-A3 model card):
    * Conversational turn (greetings, chit-chat, no tool expected) →
      GENERAL_SAMPLING_PARAMS: temperature=1.0, presence_penalty=0 (§4RG-b; was 1.5).
    * Any tool-using turn (coding OR a non-coding tool like
      update_profile / web_search / manage_tasks) → CODING_SAMPLING_PARAMS
      by default: temperature=1.0 (§4RG; was 0.6), presence_penalty=0.
    * Coding tool turns additionally get sub-classified
      (creative / precise / balanced) so algorithm design gets slightly
      higher temp and SQL / security / regex get lower temp.

    The old signature took a single ``is_coding`` flag and therefore
    left ALL non-coding tool turns on the temperature=1.0 conversational
    profile — that produced over-eager duplicate setter calls (e.g. a
    second `update_profile` on the same facts one turn after the first
    succeeded). Routing every tool turn through the precise profile
    removes that variance without costing conversational warmth.
    """
    if not is_tool_turn:
        # A non-tool turn is NOT automatically chit-chat. If the query has a
        # single deterministic answer, sample near-greedy with no presence
        # penalty — temp=1.0/pp=1.5 samples AWAY from the correct tokens.
        if _is_factual_query(query):
            return dict(FACTUAL_SAMPLING_PARAMS)
        return dict(GENERAL_SAMPLING_PARAMS)
    if is_coding:
        profile = _classify_coding_task(query)
        return dict(_CODING_TASK_PROFILES.get(profile, CODING_SAMPLING_PARAMS))
    # Non-coding tool turn — use the base precise profile (temp=0.6).
    return dict(CODING_SAMPLING_PARAMS)


# Streaming guards. When the upstream model enters a self-repeating thinking
# loop (re-deriving the same paragraph hundreds of times), the n-gram probe
# below kills the stream. §4SD (operator 10-29: "that older guard can go, it's
# from an old model family that misbehaved"): the 200K-char hard length abort
# (MAX_THINKING_CHARS_EXTENDED) and the 32K MAX_THINKING_CHARS are gone — at
# the 64k-token cap a whole-app draft is ~205-223K chars, and the abort threw
# it away as "runaway loop" where §4RF keeps it. Length is bounded by the
# turn's max_tokens; repetition by the probe.

# Upstream `max_tokens` cap for a single tool-using turn. Without this, the
# payload sends no max_tokens at all and the server default (often 1024 or
# 2048) silently truncates the assistant output mid-`<tool_call>`. The
# truncated XML then fails to parse and the agent burns 6 turns of its
# strike budget rebuilding the same almost-closed block. 8192 is generous
# for a thought + large code payload but small enough to fit comfortably
# inside a 65k-token context window with room for tool results.
#
# Raised from 8192 to 16384 for real workers that need room for a full
# solution script + reasoning preamble. The downside of a high cap
# ("16k tokens of `<tool_call>` spam instead of 8k") is bounded by the
# `_detect_tool_call_loop` streaming probe above, which aborts the
# stream after ~10 unclosed `<tool_call>` openings (tens of tokens of
# collapse, not tens of thousands). The cap and the detector are a
# pair: raise the cap without wiring the detector and a degenerate run
# turns 16k tokens of garbage; wire the detector and the cap is only
# reached by healthy verbose generations.
DEFAULT_TOOL_TURN_MAX_TOKENS = 16384
#: §4SD (operator 10-29: "16k tokens seems too low when it's writing big
#: files"): a tool turn may write up to this much when the server's window has
#: the room. Every 16k cut in the log (7 of 7,363 turns) was a whole app being
#: drafted inside the thinking; the median turn thinks 74 tokens.
TOOL_TURN_MAX_TOKENS_CEIL = 65536
#: tokens left free between the prompt estimate and the window: the chat
#: template's own tokens and tokenizer drift
TURN_ROOM_MARGIN_TOKENS = 4096
#: §4SD (operator 10-29: Slack requests get 30 min): a turn gets more than the
#: 16k floor only when the time its request may still run could hold a whole
#: room-sized turn — 64k at the 27B's ~15 tok/s is ~73 min. A Slack request
#: (30 min, never extended) keeps 16k, so one turn cannot run past it by an hour.
TURN_ROOM_MIN_TIME_LEFT_S = 4500.0


def turn_room_fits_time(ceiling_s, elapsed_s) -> bool:
    """§4SD: may this turn take more than the 16k floor? Yes with no deadline
    (``ceiling_s`` 0) or no ceiling (inf); else only when the longest the request
    may still run (its extension ceiling less the time spent) is at least
    ``TURN_ROOM_MIN_TIME_LEFT_S``."""
    try:
        ceil, spent = float(ceiling_s or 0.0), max(0.0, float(elapsed_s or 0.0))
    except (TypeError, ValueError):
        return False
    if ceil <= 0 or math.isinf(ceil):
        return True
    return ceil - spent >= TURN_ROOM_MIN_TIME_LEFT_S


#: §4SD: how often the hard-limit watch reads the request's clock (seconds)
HARD_LIMIT_POLL_S = 5.0
#: §4SD: the cancel reason a hard limit stops a turn with (the reply's note)
HARD_LIMIT_REASON = "this request reached its time limit"
#: §4SD open items (operator 10-30, "proceed with your recommendation"): tools a
#: hard limit never cuts — a project build sizes its calls by the request's
#: time and returns "out of time" on its own; cutting it mid-build set off six
#: review rounds of task-state and lost-file defects. The turn stops once it returns.
HARD_LIMIT_SPARED_TOOLS = frozenset({"manage_projects"})
#: §4SD: after a spared build returns past the limit, the report the loop forces
#: (tools off) gets this long before the turn is stopped — else the owner got
#: the cancel note and nothing about what the build did
HARD_LIMIT_REPORT_GRACE_S = 300.0
#: §4SD r7: a build still running this long past the limit is cut (a wedged
#: step held the one turn lock — web, CLI and idle loops — for hours)
HARD_LIMIT_SPARE_MAX_S = 1800.0


def _spared_running(turn) -> List[str]:
    """The spared tools `turn` is running right now ([] when none)."""
    stop = getattr(turn, "tool_stop", None)
    try:
        names = stop.running_tools() if stop is not None else []
    except Exception:  # noqa: BLE001
        names = []
    return [n for n in names if n in HARD_LIMIT_SPARED_TOOLS]


def hard_limit_applies(client_deadline_s) -> bool:
    """§4SD: a client that SENT a finite timeout (the Slack bot's 30 min) has
    a HARD limit — the turn running when it passes is stopped, not let finish
    (a 16k turn begun inside the report reserve ran ~13 min over). ``inf``
    (web, CLI) and no header (probes, background) keep the soft deadline."""
    try:
        d = float(client_deadline_s or 0.0)
    except (TypeError, ValueError):
        return False
    return 0.0 < d < math.inf


async def watch_hard_limit(req_id, registry, *, poll_s: float = HARD_LIMIT_POLL_S,
                           client_s: float = 0.0, report_grace_s: Optional[float] = None,
                           spare_max_s: float = HARD_LIMIT_SPARE_MAX_S) -> bool:
    """§4SD: wait until the request's deadline IN FORCE passes (earned
    extensions included — read each time), then stop the turn the way Stop
    does: the cooperative cancel (a generation reads it within
    ``CANCEL_POLL_S``) and the running tool calls' stop. Queued messages it
    had not read go to the conversation's leftovers. Never before the
    client's own timeout ``client_s`` (review r1: a 4 h non-streamed client
    under the server's 1 h cap was stopped at 1 h). A running project build
    (`HARD_LIMIT_SPARED_TOOLS`) is waited for, up to ``spare_max_s`` past the
    limit; the forced report then has ``report_grace_s`` from the build's end
    (r7: also a build that returned just BEFORE the limit — its report was
    cut at once) before the turn is stopped. The grace defaults to the
    request's own report reserve (`effective_report_floor`, never below
    HARD_LIMIT_REPORT_GRACE_S — r7: a fixed 300 s was under the measured
    report turn).
    Returns True when it stopped the turn; False when the request closed or
    has no deadline."""
    req_id = str(req_id or "")
    last_spared = past_since = None       # when a spared build was last seen; when the limit passed
    logged = False
    while True:
        rem = _glog.request_remaining_s(req_id)
        if rem is None:
            return False
        el = _glog.request_elapsed_s(req_id)
        if client_s and el is not None:
            rem = max(rem, float(client_s) - el)
        turn = registry.get(req_id)
        if turn is None or turn.cancelled:
            return False
        now = time.monotonic()
        spared = _spared_running(turn)
        if spared:
            last_spared = now
        wait = None
        if rem > 0:
            wait = rem
        else:
            past_since = now if past_since is None else past_since
            if spared and now - past_since < float(spare_max_s):
                wait = float(poll_s)
                if not logged:
                    logged = True
                    pretty_log("Client Deadline",
                               f"the limit passed during {', '.join(spared)} — the turn stops once it returns",
                               level="WARNING", icon=Icons.WARN)
            elif not spared and last_spared is not None:
                if report_grace_s is None:
                    try:
                        report_grace_s = max(HARD_LIMIT_REPORT_GRACE_S, effective_report_floor(
                            max(float(_glog.request_deadline_s(req_id) or 0.0), float(client_s or 0.0)), req_id))
                    except Exception:
                        report_grace_s = HARD_LIMIT_REPORT_GRACE_S
                if now < last_spared + float(report_grace_s):
                    wait = last_spared + float(report_grace_s) - now      # the report's grace
        if wait is None:
            break
        await asyncio.sleep(max(0.05, min(float(poll_s), float(wait))))
    limit = max(_glog.request_deadline_s(req_id), float(client_s or 0.0))     # r2 m1: the limit that fired
    # BEFORE the cancel (as the Stop route): `interrupt_tools` refuses a turn
    # already cancelled, and a running batch never reads the cooperative flag
    stopped = registry.interrupt_tools(req_id)
    res = registry.cancel(req_id, reason=f"{HARD_LIMIT_REASON} ({_span(limit)})")
    try:
        registry.add_leftovers(turn.session_id, turn.kind, res.get("undelivered_items") or [])
    except Exception:  # noqa: BLE001
        pass
    pretty_log("Client Deadline",
               f"the {_span(limit)} limit passed — stopping the turn"
               + (f" and its running {', '.join(stopped)}" if stopped else ""),
               level="WARNING", icon=Icons.STOP)
    return True


def hard_limit_files_line(tools_run) -> str:
    """§4SD: the files a turn stopped at its hard limit wrote, for its reply
    ("" when none)."""
    try:
        from .task_state import task_state_facts
        files = task_state_facts(tools_run or [])["files"]
    except Exception:  # noqa: BLE001
        return ""
    return ("Files written so far: " + ", ".join(f"`{p}`" for p in files) + ".") if files else ""


def turn_takes_room(payload, is_final_generation) -> bool:
    """§4SD: the per-turn room applies to a TOOL turn carrying the default
    cap — not a final answer or report (review: they would get up to 64k
    too), not an operator's own --tool-turn-max-tokens, not the forced
    report's 8k."""
    return (not is_final_generation and isinstance(payload, dict)
            and payload.get("max_tokens") == DEFAULT_TOOL_TURN_MAX_TOKENS)


def output_cap_for_tool_turn(prompt_tokens, window_tokens, floor=DEFAULT_TOOL_TURN_MAX_TOKENS,
                         ceil=TOOL_TURN_MAX_TOKENS_CEIL) -> int:
    """§4SD: a tool turn's ``max_tokens`` — what the server's window leaves
    after this turn's prompt (less a margin), never above ``ceil`` and never
    below ``floor``. Below the floor the prompt was already pruned to
    --max-context (the launcher keeps ~22k of the window for output) and a
    turn that reaches the window's end stops like a cap cut (§4RF/§4OB
    recover both). An unknown window → ``floor``, the pre-§4SD cap."""
    try:
        win, used = int(window_tokens or 0), max(0, int(prompt_tokens or 0))
        lo, hi = int(floor), int(ceil)
    except (TypeError, ValueError):
        return DEFAULT_TOOL_TURN_MAX_TOKENS
    if win <= 0:
        return lo
    return max(lo, min(hi, win - used - TURN_ROOM_MARGIN_TOKENS))

# When the upstream stops a *text* answer at its token cap
# (`finish_reason == "length"`), the partial reply is shipped mid-sentence
# and the verifier correctly REFUTES it (truncated output / explicit
# question left unanswered). Rather than surface a cut-off final answer, we
# transparently continue the generation from where it stopped, up to this
# many times, then accept whatever we have. Bounded so a model that emits
# "length" on every continuation (mis-reported finish_reason, runaway) can't
# loop forever — each continuation is a full upstream round-trip.
MAX_TRUNCATION_CONTINUATIONS = 3
#: §4SC-e: a stream cut INSIDE a call tag the template opens on its own line
#: (`<tool_call>` / `<function=`): the tail is a line-anchored PREFIX of one of
#: the two tag names — "…\n<tool_ca", "<tool_ca", "…\n<func", "…\n<" — and
#: never a `<` inside a line ("std::vector<int", "x<y", "if a <", "#include
#: <stdio") or another tag ("\n<br"), which §4SC-d's `<[a-z_]{0,9}$` also
#: caught: legitimate cut answers were not continued and lost their tail.
#: Case-sensitive on purpose: the template's tags are lowercase; the sibling
#: substring gates lower-case the text because a model may echo a tag freely.
_CALL_TAG_TAIL = re.compile(
    r"(?:^|\n)<(?:t(?:o(?:o(?:l(?:_(?:c(?:a(?:l(?:l)?)?)?)?)?)?)?)?"
    r"|f(?:u(?:n(?:c(?:t(?:i(?:o(?:n)?)?)?)?)?)?)?)?$")


def _in_open_fence(text: str) -> bool:
    """§4SC-g: the text ends inside an open code fence — LINE-START fences
    only, on think-stripped text: a mid-line ``` mention ("a block with ```
    and") or a fence quoted inside <think> is not a fence, and a raw count
    of them skipped the tag rule and appended a spurious closing fence."""
    return len(re.findall(r"(?m)^\s{0,3}```", _strip_think_blocks(text))) % 2 == 1
#: one continuation call's budget (§4MD M2). §4RK: 180 → 480 s — at the 27B's
#: ~23 tok/s a continuation of a few thousand tokens plus its prefill did not
#: fit 180 s, so the cut answer shipped with the "could not finish" note.
TRUNCATION_CONTINUATION_TIMEOUT_S = 480.0
#: the visible note on an answer the model server cut and the agent could not finish (§4MD M1)
TRUNCATED_ANSWER_NOTE = ("⚠️ This answer was cut off — the model server stopped in the middle of "
                         "the reply, so it is incomplete.")
#: the marker an upstream failure leaves on a reply: the outcome rules book it
#: FAILED; like every abort marker it is stripped from a channel MEMBER's
#: copy (the owner's reply and the trajectory keep it)
UPSTREAM_ABORT_MARKER = "[ATTEMPT_ABORTED_UPSTREAM]"
#: §4MS: a turn cut by a client disconnect or a process shutdown — not an
#: attempt that failed (outcome UNKNOWN; `trajectory_may_teach` refuses it)
from ..distill.outcome_heuristics import TURN_INTERRUPTED_MARKER  # noqa: E402

#: §4IB — the strike line showed the HEAD of a failing command's output (an
#: `ls` listing) while the failure sat in the tail. The preview is the first
#: line that names the failure, else the tail.
_FAILURE_PREVIEW_RE = re.compile(
    r"(?:Traceback \(most recent call last\)|\b[A-Za-z]*(?:Error|Exception)\b|"
    r"\bcannot\b|\bfailed\b|No module named|No such file|not found|\bKilled\b|"
    r"\bexit(?:\s*code)?\s*[=:]\s*[1-9]|SYSTEM (?:ERROR|BLOCK)|Permission denied)",
    re.IGNORECASE,
)


def failure_preview(body: str, limit: int = 200) -> str:
    """The part of a failed run's output worth one log line: the LAST
    line that names the failure (a traceback ends with the exception that
    matters; `*Error`, 'No module', 'Killed', a non-zero `exit=` echo …),
    else the last `limit` chars — where a failure lands when nothing names
    it. Whitespace-collapsed."""
    text = str(body or "")
    found = ""
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    # §4OE-2: a pytest run names its failing tests — the model used to get
    # only the summary line and had to find them in a 24 KB view
    _named = re.findall(r"^FAILED (\S+::\S+)", text, re.M)
    if _named:
        _more = f" (+{len(_named) - 3} more)" if len(_named) > 3 else ""
        found = ("FAILED: " + ", ".join(_named[:3]) + _more)[:limit]
        return found
    for s in lines:
        if _FAILURE_PREVIEW_RE.search(s):
            found = re.sub(r"\s+", " ", s)[:limit]
    if found:
        return found
    # A DECLARED failure (a `ToolOutcome` whose status is not ok/unresolved)
    # names its failure on its first line — a refusal banner is the
    # failure. Status first, prose second (outcome-consumers R3 rule).
    _st = getattr(body, "status", None)
    _sv = getattr(_st, "value", _st)
    if _sv is not None and str(_sv) not in ("ok", "unresolved") and lines:
        return re.sub(r"\s+", " ", lines[0])[:limit]
    flat = re.sub(r"\s+", " ", text).strip()
    return flat[-limit:] if len(flat) > limit else flat


#: §4IC — every breaker used to be a one-shot advisory; request 3a2afac2
#: ignored the futility steer and both edit-churn steers and rewrote
#: probe.py eight more times, then ran out of turns and handed the user
#: stitched narration. A SECOND trip of a breaker, or the last budget
#: turn, now forces a REPORT: tools off, the model writes what it tried,
#: what fails, and what would unblock it. A blocker report is a
#: deliverable; narration is not.
EDIT_CHURN_REPORT_AFTER_STEERS = _EDIT_CHURN_MAX_STEERS if "_EDIT_CHURN_MAX_STEERS" in globals() else 2
FUTILITY_REPORT_WRITES = 6
FUTILITY_REPORT_RUNS = 4
#: The last turn of the budget is reserved for the report from this many
#: turns in (a two-turn request should not lose half its budget to it).
REPORT_TURN_MIN_TURN = 3
#: §4OG-1 (k): the one extension a converging build gets at the turn budget
TURN_BUDGET_EXTENSION = 10
#: §4SD (operator 10-29: "remove the tool turn limit"): a request with a time
#: budget has no turn count — its deadline (extended only by coding progress)
#: and the breakers end it. One with no deadline (scheduled, job, bench,
#: internal) keeps this count: it is that request's only bound.
TURN_CAP_WITHOUT_DEADLINE = 40


def main_turn_cap(override, deadline_s, elapsed_s) -> int:
    """§4SD: the main loop's turn count. A sub-agent's or leaf's own
    ``max_turns_override`` wins; else no count (``sys.maxsize``) for a request
    with a deadline AND a running clock, ``TURN_CAP_WITHOUT_DEADLINE`` for any
    other (review: with no clock — ``elapsed_s`` None — the deadline report can
    never fire, so the count is the only bound left)."""
    if override:
        return int(override)
    try:
        timed = float(deadline_s or 0.0) > 0 and elapsed_s is not None
    except (TypeError, ValueError):
        timed = False
    return sys.maxsize if timed else TURN_CAP_WITHOUT_DEADLINE
#: …only when this much wall time is left beyond the report reserve
TURN_BUDGET_EXTENSION_MIN_S = 180.0


def build_is_converging(script_iter) -> bool:
    """True when the LAST attributed suite run of some code file this request
    IMPROVED on the run before it (failures fell or passes rose — a counted
    comparison, not a first run)."""
    try:
        return any(isinstance(r, dict) and r.get("runs", 0) >= 2 and r.get("improved") is True
                   for r in (script_iter or {}).values())
    except Exception:  # noqa: BLE001
        return False


def turn_budget_extension_fits(remaining_s, report_floor_s) -> bool:
    """No deadline, or enough wall time left for more tool turns AND the report."""
    try:
        if remaining_s is None:
            return True
        return float(remaining_s) - float(report_floor_s or 0.0) >= TURN_BUDGET_EXTENSION_MIN_S
    except (TypeError, ValueError):
        return False


#: §4RA: files whose successful writes count as coding progress — a coding
#: request still making it earns deadline extensions (utils/logging
#: `request_deadline_s`; the 27B at ~20 tok/s spent 22–30 min writing one
#: 44–78 KB web build, §4QZ, and a flat budget cut the larger builds mid-file)
CODE_PROGRESS_EXTS = (".py", ".sh", ".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx",
                      ".html", ".htm", ".css", ".json", ".go", ".rs", ".c", ".h",
                      ".cpp", ".java", ".rb", ".php", ".sql")
#: the file_system operations that WRITE code (not delete/download/move/copy — review m2)
CODE_WRITE_OPS = frozenset({"write", "append", "edit", "replace"})


def is_code_progress(fname, op, target, is_error, *, ran_written=False) -> bool:
    """§4RA: a successful write to a code file, or a successful run of a
    file this request wrote. Prose (.md/.txt), other operations and failed,
    refused or unresolved calls are not progress."""
    if is_error:
        return False
    if fname == "execute":
        return bool(ran_written)
    if fname != "file_system" or str(op or "").lower() not in CODE_WRITE_OPS:
        return False
    return str(target or "").lower().endswith(CODE_PROGRESS_EXTS)


def is_whole_rewrite(op, args) -> bool:
    """§4SD: a `write` that replaces the whole file — not ``append=true`` (the
    next part of a file written in parts)."""
    if str(op or "").strip().lower() != "write":
        return False
    app = (args or {}).get("append") if isinstance(args, dict) else None
    return not (app is True or str(app).strip().lower() in ("true", "1", "yes"))


def request_checkpoint_namespace(req_id) -> str:
    """The scratchpad scope a request's turn checkpoints live in."""
    return f"req:{str(req_id or '').strip() or 'anon'}"


#: §4JP: seconds before the CLIENT's deadline at which the loop stops
#: issuing tool turns and forces the state report (a report turn on the
#: main model runs ~10–60 s, its no-answer retry the same; 150 s leaves
#: both room). Req fd89fd6d: the web interface's 1800 s timeout cut a
#: 35-turn build mid-`sleep 60000` with 61 s left, and the reply that landed
#: was the stitched working narration.
#: §4ME F2: 150 s was checked only at a turn's START — a tool turn begun
#: with 160 s left ran past the deadline and the stitched notes shipped
#: (fd89fd6d again). 300 s covers one ordinary tool turn plus the report.
DEADLINE_REPORT_FLOOR_S = 300.0


def _max_reply_s(req_id) -> float:
    from .task_state import max_reply_seconds
    return max_reply_seconds(req_id)


def effective_report_floor(deadline_s, req_id=None) -> float:
    """The report reserve for a client deadline: DEADLINE_REPORT_FLOOR_S, but
    never more than a quarter of the whole deadline — a 300 s client timeout
    would otherwise force a report on its FIRST turn (§4ME review).
    §4OE-1: with a `req_id`, the reserve grows to twice THIS request's longest
    reply + slack — a constant 300 s was smaller than a measured report turn
    (240–253 s + a retry) and 0 of 5 forced reports landed before the client
    closed (§4OD)."""
    from .task_state import sized_report_floor
    try:
        d = float(deadline_s or 0.0)
    except (TypeError, ValueError):
        d = 0.0
    if req_id:
        floor = sized_report_floor(DEADLINE_REPORT_FLOOR_S, d, req_id)
        _glog.note_report_floor(str(req_id), floor)          # §4RA r2 M-A: the extension window sees it
        return floor
    if d <= 0:
        return DEADLINE_REPORT_FLOOR_S
    return min(DEADLINE_REPORT_FLOOR_S, max(30.0, 0.25 * d))


def _span(secs: float) -> str:
    secs = max(0.0, float(secs or 0.0))
    if math.isinf(secs):
        return "no limit"                                  # §4SD: the ceiling may be inf
    if secs >= 600 or (secs >= 120 and round(secs) % 60 == 0):
        return f"{secs / 60:.0f} min"
    return f"{secs:.0f} s"


def client_deadline_line(deadline_s, ceiling_s=0.0) -> str:
    """§4NV: the turn's time budget and the ACTUAL report reserve (it is
    capped at a quarter of the budget — a flat "5 min" was wrong for any
    budget under 20 min). §4RA: and the extension ceiling, when there is one."""
    line = (f"time budget {_span(deadline_s)} (the last {_span(effective_report_floor(deadline_s))} "
            "are kept for the final report)")
    try:
        if math.isinf(float(ceiling_s or 0.0)):
            line += "; no time limit while code is being written (§4SD: it stops after a stall)"
        elif float(ceiling_s or 0.0) > float(deadline_s or 0.0):
            line += f"; extendable to {_span(ceiling_s)} while code is being written"
    except (TypeError, ValueError):
        pass
    return line


def deadline_needs_report(remaining_s, floor_s: float, force_final_response, force_stop) -> bool:
    """True when the client's deadline is known and within ``floor_s`` on a
    request still running tools — the remaining time must go to a report."""
    try:
        if remaining_s is None or force_final_response or force_stop:
            return False
        return float(remaining_s) <= float(floor_s)
    except (TypeError, ValueError):
        return False


def declared_wait_s(fname: str, t_args) -> float:
    """How long a tool call DECLARES it will wait, in seconds — the browser's
    `sleep` / `settle_ms` actions (the fd89fd6d sleep) — or, for an image
    render, how long renders of its kind have taken (§4MO). Unknown → 0."""
    try:
        if fname == "image_generation" and isinstance(t_args, dict):   # the healed name (fname is canonical here)
            # §4MO: a render's duration is not declared but measured — the
            # longest of this node's last three of the same kind
            from ..tools.image_gen import expected_render_seconds
            # §4QG: the estimate reads the FULL call — `subjects` decides the
            # kind (and, ≥2 subjects, the collage re-render ladder). The tool
            # treats a `subject` string beside a prompt as the subjects list
            # (§4PB); estimated without it, a subjects render was timed as a
            # plain generate and the deadline check let it start too late.
            # (the shared rule: tools/subject_photos.py `subjects_arg`)
            from ..tools.subject_photos import subjects_arg
            _est_args = dict(t_args)
            _subj = subjects_arg(_est_args)
            if _est_args.get("subjects") is None and _subj is not None:
                _est_args["subjects"] = _subj
            return expected_render_seconds(_est_args)
        if fname != "browser" or not isinstance(t_args, dict):
            return 0.0
        total = float(t_args.get("settle_ms") or 0) / 1000.0
        for a in (t_args.get("actions") or []):
            if isinstance(a, dict) and str(a.get("action") or "").lower() == "sleep":
                total += float(a.get("ms") or 0) / 1000.0
        return max(0.0, total)
    except (TypeError, ValueError):
        return 0.0


#: §4OG-5 (f): the tools whose batch can run long enough to eat the reserve
_BATCH_WALL_TOOLS = frozenset({"browser", "deep_research", "darkweb_search", "darkweb_research",
                               "execute", "web_search", "image_generation", "vision_analysis",
                               "fact_check", "probe_model"})                    # §4PD; §4QA


def wait_crosses_deadline(wait_s: float, remaining_s, floor_s: float) -> bool:
    """A declared wait that would end inside the report floor (or past the
    deadline) is refused before it runs."""
    try:
        return (remaining_s is not None and float(wait_s) > 0
                and float(wait_s) > float(remaining_s) - float(floor_s))
    except (TypeError, ValueError):
        return False


def last_turn_needs_report(turn: int, max_turns: int, force_final_response,
                           force_stop) -> bool:
    """True on the final budget turn of a request that is still running
    tools — the turn that must be spent on a report, not one more call.
    Not before `REPORT_TURN_MIN_TURN` (short budgets keep their last turn)."""
    try:
        # (turn == max-1 with max > MIN already puts turn ≥ MIN; a separate
        # turn-floor clause was a dead twin — battery round 25 proved it.)
        # §4IG: TWO turns are reserved — the report turn and one retry
        # for it. Probe ifs19450…'s report turn answered with a tool call
        # and working narration; on the last turn the NO-ANSWER retry
        # path has nowhere to go and the narration shipped.
        return (int(max_turns) > REPORT_TURN_MIN_TURN
                and int(turn) == int(max_turns) - 2
                and not force_final_response and not force_stop)
    except (TypeError, ValueError):
        return False


def budget_exhausted_note(max_turns: int, *, report_forced: bool,
                          project_active: bool) -> str:
    """The prefix for a reply that reached the turn budget. Names what the
    text below it IS — a forced report (the last turn was reserved) or a
    working-state dump — and only promises "recorded findings" when a
    project ledger actually exists to hold them (3a2afac2 was promised a
    work log / ledger / notes with no project open)."""
    if report_forced:
        head = (f"[TURN BUDGET REACHED] I used all {max_turns} reasoning turns; "
                "the task is NOT finished. What follows is my report of where it "
                "stands — what I tried, what fails, and what would unblock it.")
    else:
        head = (f"[TURN BUDGET EXHAUSTED] I used all {max_turns} reasoning turns "
                "without completing this task — what follows is my working state, "
                "NOT a finished result.")
    tail = (" Ask me to continue and I will resume from the recorded findings "
            "(project work log / ledger / notes) instead of starting over."
            if project_active else
            " Ask me to continue and I will pick up from this state; nothing "
            "is recorded outside this conversation.")
    return head + tail + "\n\n"


#: §4OA: a run resets the per-cycle reminder count, so the request-wide
#: total is capped separately (review: otherwise unlimited reminders)
EDIT_CHURN_TOTAL_STEERS = 4


#: §4QB-c (operator 2026-10-20): prose has nothing to run — fixing 17 quotes
#: in one write-up was stopped as "edited again and again without being run"
EDIT_CHURN_EXEMPT_SUFFIXES = (".md", ".txt")


def _is_parts_continuation(args) -> bool:
    """§4RI: a `write` with `append` is the NEXT PART of one file written in
    parts (§4NU), not another edit of it. Request 43fe95a2: write + two
    appends of webos/index.html counted as "3 unverified edits" and the
    brake steered in the middle of the file."""
    if not isinstance(args, dict):
        return False
    if str(args.get("operation") or "").strip().lower() != "write":
        return False
    v = args.get("append")
    return bool(v) and str(v).strip().lower() not in ("false", "0", "no", "")


def edit_churn_decision(churn: dict, target: str) -> str:
    """Count one more unverified edit of `target` and say what the loop
    does about it: "" (nothing yet), "steer" (a verify nudge — at most
    `_EDIT_CHURN_MAX_STEERS` per request) or "report" (§4IC second tier:
    the steers are spent and the blind edits continue — once). Mutates
    `churn` (`counts`, `steers`, `reported`) exactly as the loop did.
    A .md/.txt target is never counted (:data:`EDIT_CHURN_EXEMPT_SUFFIXES`)."""
    if str(target or "").strip().lower().endswith(EDIT_CHURN_EXEMPT_SUFFIXES):
        return ""
    counts = churn.setdefault("counts", {})
    counts[target] = counts.get(target, 0) + 1
    if counts[target] < _EDIT_CHURN_STEER_AFTER:
        return ""
    if churn.get("steers", 0) >= EDIT_CHURN_REPORT_AFTER_STEERS:
        if churn.get("reported"):
            return ""
        churn["reported"] = True
        return "report"
    if churn.get("steers", 0) < _EDIT_CHURN_MAX_STEERS and churn.get("total_steers", 0) < EDIT_CHURN_TOTAL_STEERS:
        counts[target] = 0
        churn["steers"] = churn.get("steers", 0) + 1
        churn["total_steers"] = churn.get("total_steers", 0) + 1   # §4OA: runs reset `steers`; this does not
        return "steer"
    return ""


_FUTILITY_NAME_RE = re.compile(r"[\w.\-]+\.(?:py|sh|js|mjs|ts)\b", re.I)


def futility_key(name) -> str:
    """The key one code file is counted under by the futility breaker: its
    basename, lower-cased, with a trailing run of digits/underscores/dashes
    stripped from the stem. §4IG: probe6.py … probe19.py (14 files, one
    dead end) and oxford_grid2.py are the same script being rewritten under
    a new name; keyed literally they never reached the 3-write floor."""
    bn = str(name or "").replace("\\", "/").rsplit("/", 1)[-1].lower()
    stem, dot, ext = bn.rpartition(".")
    if not dot or not stem:
        return bn
    stripped = re.sub(r"[\d_\-]+$", "", stem)
    return f"{stripped or stem}.{ext}"


_FUTILITY_MODULE_RE = re.compile(r"(?<![\w-])-m\s+([\w.]+)")
#: a RUNNER INVOCATION at a command position (start, after `&&`/`||`/`;`/`|`,
#: or after env assignments) — `cat tox.ini`, `pip install pytest-cov`, `grep
#: nose setup.cfg` are not suite runs (reader M4)
_SUITE_CMD_RE = re.compile(
    r"(?:^|[;&|(]\s*|\n\s*)"
    r"(?:(?:[A-Za-z_][\w]*=\S*\s+|env\s+|timeout\s+\d+[smh]?\s+|nohup\s+|xvfb-run\s+(?:-\S+\s+)*"
    r"|uv\s+run\s+|poetry\s+run\s+|pipenv\s+run\s+|coverage\s+run\s+(?:-\S+\s+)*)*)"
    r"(?:(?:\S*/)?(?:python3?(?:\.\d+)?|py)\s+(?:-[A-Za-z]+(?:\s+\S+)?\s+)*-m\s+(?:pytest|unittest|nose2?|tox)\b"
    r"|(?:\S*/)?(?:pytest|py\.test|nose2?)\b(?!\s+--(?:co|collect-only|help|version|fixtures|markers)\b)"
    r"|tox\b(?!\s+-e\s+(?:lint|flake8|black|mypy|docs)\b)"
    r"|npm\s+(?:run\s+)?test\b|npx\s+(?:jest|vitest|mocha)\b|yarn\s+test\b"
    r"|go\s+test\b|cargo\s+test\b|node\s+--test\b|make\s+test\b)",
    re.I)


def is_suite_command(blob) -> bool:
    """§4OG-1 (a): a command that RUNS a test suite — it exercises every code
    file written this request, whatever it names."""
    return bool(_SUITE_CMD_RE.search(str(blob or "")))


def futility_keys_in_command(blob, written_keys=()) -> set:
    """Every code-file name a command mentions, as futility keys — plus the
    module of a `python -m pkg.mod` (§4OG-1 (a)), and, for a suite run, every
    code file written this request: `python -m pytest tests/ -q` names no file,
    so the §4OE-2 progress term never ran on the loop it was built for (§4OF)."""
    text = str(blob or "")
    keys = {futility_key(m) for m in _FUTILITY_NAME_RE.findall(text)}
    for mod in _FUTILITY_MODULE_RE.findall(text):
        if mod.lower() not in ("pytest", "unittest", "pip", "venv", "http.server", "json.tool"):
            keys.add(futility_key(mod.rsplit(".", 1)[-1] + ".py"))
    if is_suite_command(text):
        keys |= {str(k) for k in (written_keys or ())}
    return keys


_PYTEST_FAILED_RE = re.compile(r"(\d+) failed")
_PYTEST_PASSED_RE = re.compile(r"(\d+) passed")
_RUN_TIMING_RE = re.compile(r"\bin \d+(?:\.\d+)?s\b|\b\d+(?:\.\d+)?\s*(?:ms|s|sec|seconds)\b")


def note_run_outcome(rec: dict, *, ok: bool, output: str = "") -> None:
    """§4OE-2: the futility counters learn whether the run made PROGRESS —
    the breaker measured churn only (6 edits + 4 runs → forced report even
    when every run passed more tests, §4OD). With test counts in the output
    (review 4): progress = the failing count fell or the passing count rose
    (a loop that adds a feature and its tests each step is converging, even
    though every run prints "passed"); the first result is never "stalled".
    Without counts: a green run is progress only when its output — timings
    stripped — changed; the breaker's founding case (xrick) was exit-0 runs
    whose output stayed wrong."""
    text = str(output or "")
    def _num(rx):
        found = rx.findall(text)              # the LAST match is the summary line (review 5)
        return int(found[-1]) if found else None
    fails, passed = _num(_PYTEST_FAILED_RE), _num(_PYTEST_PASSED_RE)
    if passed is not None and fails is None:
        fails = 0                               # a green pytest run: no failures, not "unknown"
    prev_f, prev_p = rec.get("fails"), rec.get("passed")
    if fails is not None or passed is not None:
        if prev_f is None and prev_p is None:
            progress = True                     # the first result of this file: nothing to be stalled against
        else:
            progress = ((fails is not None and prev_f is not None and fails < prev_f)
                        or (passed is not None and prev_p is not None and passed > prev_p))
        rec["last_ok"], rec["last_out"] = None, None    # review 7: a count run ends any count-less failure streak
    else:
        from .strikes import normalise_volatile
        _flat = " ".join(_RUN_TIMING_RE.sub("", normalise_volatile(text)).split())   # timings, clocks, ids out
        fp = hashlib.sha1(_flat.encode("utf-8", "ignore")).hexdigest()[:12]
        if ok:
            progress = fp != rec.get("last_out")
        else:
            # §4PH (R1-2): a failing run IS the error it died with — its class
            # and line with the numbers out, not its whole output: an assertion
            # whose values move with every rewrite (`expected 372, got 369.5`,
            # then 371.2) is one dead end, and a traceback's line numbers move
            # with every edit. The whole-output fingerprint never repeated, so
            # the stall was never seen.
            try:
                from .strikes import error_line_fingerprint as _elf
                fp = _elf(text, tool="execute") or fp
            except Exception:  # noqa: BLE001
                pass
            # review 6: ONE count-less failure (a timeout, a crash) between converging
            # runs is transient; the same failure twice in a row is a stall
            progress = not (rec.get("last_ok") is False and fp == rec.get("last_out"))
        rec["last_out"], rec["last_ok"] = fp, bool(ok)
    rec["progress"] = progress
    rec["ok"] = bool(ok)                        # §4OG-1 (a): a GREEN counted run is never a stall
    rec["counted"] = fails is not None or passed is not None
    # §4OG-1 (k): an IMPROVEMENT is progress measured against a previous run (the
    # first run is "progress" only in the sense of "not stalled" — reader M6)
    rec["improved"] = bool(progress and (prev_f is not None or prev_p is not None
                                         or rec.get("last_out") is not None) and rec["counted"])
    if fails is not None:
        rec["fails"] = fails
    if passed is not None:
        rec["passed"] = passed


def futility_tier(script_iter: dict, steer_done: bool, report_done: bool):
    """Which futility tier fires for the rewrite/rerun counters, if any:
    ("steer", name, rec) on the 3rd rewrite + 2nd rerun of one code file
    (once), ("report", name, rec) once the steer was given and the cycle
    reached `FUTILITY_REPORT_WRITES`/`FUTILITY_REPORT_RUNS` (once) AND the
    last run made no progress (§4OE-2), else ("", None, None). Pure."""
    items = list((script_iter or {}).items())
    if steer_done and not report_done:
        for bn, rec in items:
            if (rec.get("writes", 0) >= FUTILITY_REPORT_WRITES
                    and rec.get("runs", 0) >= FUTILITY_REPORT_RUNS
                    and not rec.get("progress")
                    and not (rec.get("ok") and rec.get("counted"))):   # §4OG-1 (a): two green suite runs are not a stall
                                                                        # (a count-less green run with unchanged output still is: xrick)
                return ("report", bn, rec)
    if not steer_done:
        for bn, rec in items:
            if rec.get("writes", 0) >= 3 and rec.get("runs", 0) >= 2 and not rec.get("progress"):
                return ("steer", bn, rec)          # §4OG-1 (a): a converging loop is not steered (reader M3)
    return ("", None, None)


def thinking_disabled(payload: Any) -> bool:
    """§4KP: the payload switches the model's reasoning off — the chat-template
    flag or the `/no_think` soft switch on the last user message."""
    if not isinstance(payload, dict):
        return False
    if (payload.get("chat_template_kwargs") or {}).get("enable_thinking") is False:
        return True
    msgs = payload.get("messages") or []
    last = msgs[-1] if msgs and isinstance(msgs[-1], dict) else {}
    return last.get("role") == "user" and str(last.get("content") or "").rstrip().endswith("/no_think")


def reasoning_unparsed_frame(req_id: str, created: int, model: str) -> bytes:
    """§4KP: an empty-delta frame saying this reply's reasoning did not arrive
    on the reasoning channel (thinking was on), so its opening may be
    reasoning that ends in an orphan `</think>`. A client that cannot take
    output back — speech, a terminal — holds the reply until it is complete
    and strips it; the web display re-renders and needs nothing."""
    return ("data: " + json.dumps({
        "id": f"chatcmpl-{req_id}", "object": "chat.completion.chunk", "created": created, "model": model,
        "choices": [{"index": 0, "delta": {}, "finish_reason": None}],
        "ghost": {"reasoning_unparsed": True},
    }) + "\n\n").encode("utf-8")


def report_turn_payload(payload: dict) -> dict:
    """§4IF — the LLM payload for a breaker-forced / reserved report turn:
    thinking disabled by BOTH switches the model honours (the chat-template
    flag and the `/no_think` soft switch on a COPY of the last user
    message — history is never edited). Returns a new dict."""
    out = dict(payload or {})
    ctk = dict(out.get("chat_template_kwargs") or {})
    ctk["enable_thinking"] = False
    out["chat_template_kwargs"] = ctk
    msgs = list(out.get("messages") or [])
    if msgs and isinstance(msgs[-1], dict) and msgs[-1].get("role") == "user":
        last = dict(msgs[-1])
        text = str(last.get("content") or "")
        if not text.rstrip().endswith("/no_think"):
            last["content"] = f"{text.rstrip()} /no_think"
        msgs[-1] = last
    out["messages"] = msgs
    return out


#: §4KV: whose message a runtime alert is. Req slack-124c85b8's report turn
#: (thinking off) read "your reasoning entered a self-repeating loop … be
#: specific and honest" as the USER's complaint and answered it — "You're
#: absolutely right … you've successfully pointed out where my reasoning was
#: flawed" — instead of the user's message. The same defect as req 4dab5067's
#: repair turn (`_REPAIR_STANDALONE_SUFFIX`), on the breakers' path.
_ALERT_PROVENANCE = (
    "This alert is from the runtime, not from the user: the user did not "
    "write it and cannot see it — do not reply to it, agree with it or "
    "apologise for it. ")

_REPORT_ASK = "Write your FINAL answer now as a report: "
#: §4KV: a thinking loop is the one breaker with no blocker in the world —
#: the evidence in the conversation may already answer the request, and a
#: remark or a question deserves its answer, not a three-part work report.
#: Measured on the slack-12 report turn replayed 30× per text against the
#: live model: the report ask shipped a third-person work report 4×,
#: invented facts the search had not found 4× and a stale concession 1×
#: (9/30); this ask shipped none of those (0/30).
_ANSWER_FIRST_ASK = (
    "Write your FINAL reply to that request now, from what is already in "
    "this conversation: answer it directly, in the form it calls for. State "
    "as fact only what the conversation and its tool results support — where "
    "a search found nothing, say so; never invent details to fill a gap. "
    "Only if the request was a task that is not finished, write a report "
    "instead: ")
_REPORT_BODY = (
    "(1) what the user asked "
    "and what you delivered so far (name the files that exist); (2) what "
    "you tried and the exact error or gap that stopped you; (3) what "
    "would unblock it (a different library or approach, a version, "
    "information from the user). Be specific and honest — do not claim "
    "progress you did not verify, do not describe what you are "
    "'about to' do, and (4) do not predict outputs or counts you did "
    "not observe — code you never ran is labelled UNTESTED, never "
    "'the fix' or 'the complete solution'. If the system state still "
    "lists the task as pending or says you have turns left, that is "
    "expected — you will NOT act on it this turn; do not plan more work, "
    "do not think it through: "
)


def blocker_report_alert(kind: str, detail: str, pending_request="", *,
                         answer_first: bool = False) -> str:
    """The forced-report instruction shared by the breakers' second tier
    and the reserved last turn. ONE wording — the model reads the same
    ask wherever the loop gives up on tools.

    §4KV: every alert says whose message it is (`_ALERT_PROVENANCE`) and
    which request it serves (`_which_request_line` — `pending_request` is
    the loop's ``last_user_content``). ``answer_first`` is the thinking-loop
    breakers' ask (`_ANSWER_FIRST_ASK`)."""
    return (
        f"SYSTEM ALERT ({kind}): {detail}. Tools are OFF for this turn. "
        + _ALERT_PROVENANCE + _which_request_line(pending_request) + " "
        + (_ANSWER_FIRST_ASK if answer_first else _REPORT_ASK)
        + _REPORT_BODY
        # the last imperative must not contradict the ask (review, §4KV)
        + ("write your reply." if answer_first else "write the report.")
    )


#: §4KV: the sentence that makes a steer the thinking-loop ANSWER steer;
#: `loop_retry_is_no_think` keys on it.
_LOOP_ANSWER_STEER_MARK = "Your next output is the reply to that request itself"


def thinking_loop_answer_steer(pending_request) -> str:
    """§4KV — the steer after a thinking loop killed a turn BEFORE any tool
    ran, on a request that is not a coding task. The general steer orders
    "ONE grounding tool call" (a debugging loop is missing an observation);
    here nothing has been observed yet and the loop was the model drafting
    its reply, so a forced tool call invents work: replayed 15× on the
    slack-12 thread, that order produced a web search about a named
    person's marriage 14 times. This text, with thinking off for the one
    turn that reads it (`loop_retry_is_no_think`), produced 18 direct
    replies, 2 searches and no second loop in 20; with thinking left ON two
    wordings re-looped 5 times in 30."""
    return (
        "SYSTEM ALERT: Your previous turn entered a self-repeating thinking "
        "loop and was killed; that reasoning is discarded. This alert is from "
        "the runtime, not from the user: the user did not write it and cannot "
        f"see it. {_which_request_line(pending_request)} Do NOT start that "
        "reasoning again. "
        f"{_LOOP_ANSWER_STEER_MARK} — or exactly ONE tool call, only if the "
        "reply needs a fact you do not have or work you have not done. State "
        "as fact only what you know or a tool returned; never invent details "
        "to fill a gap.")


#: The assistant-role note left in the history where a killed thinking loop was.
_THINKING_ABORTED_NOTE = "[Internal thinking aborted: runaway loop detected.]"


def loop_retry_is_no_think(messages, pending_request) -> bool:
    """§4KV: is the turn about to be generated the one that answers a
    `thinking_loop_answer_steer`? True when the newest assistant message is
    the abort note and the user-role messages after it include that steer
    EXACTLY as built for this request — so it needs no flag, and a user who
    quotes the steer's words (a pasted log line) cannot switch their own
    turn's thinking off: a message cannot be the steer that quotes it.

    It holds until the assistant next adds a message to the history —
    normally one generation. A reply the loop DISCARDS without recording
    (the checklist nudge appends only its reminder) is regenerated under
    the same switch: still no thinking, still tools on (second review)."""
    # §4RZ step 2: the steer names what was delivered when it was built; a
    # message drained since must not unmatch it (the no-think retry was lost)
    from .queued_messages import delivered as _qd, set_delivered as _q_set
    _now = _qd()
    steers = []
    for _k in range(len(_now) + 1):
        _t = _q_set(_now[:_k])
        try:
            steers.append(thinking_loop_answer_steer(pending_request))
        finally:
            _queued_end_request(_t)
    seen = False
    for m in reversed(messages or []):
        if not isinstance(m, dict):
            return False
        if m.get("role") != "user":
            return (seen and m.get("role") == "assistant"
                    and m.get("content") == _THINKING_ABORTED_NOTE)
        if any(m.get("content") == _s for _s in steers):     # content may be a list
            seen = True
    return False


#: §4KM (a): the heads of a model-facing steer, and the tools a steer may name that
#: are always blocked for a member even when not registered in this process.
#: Every steer family: "SYSTEM <WORDS>" + ":", "(", "—" or "#" (ALERT, BLOCK, HINT,
#: ESCAPE HATCH, PREFLIGHT, PAUSE, OVERRIDE, INSTRUCTION, 3 PIVOT, …) and
#: AUTO-DIAGNOSTIC, also inside a translated `<tool_response …>` wrapper.
_MEMBER_STEER_HEAD_RE = re.compile(
    r"\A\s*(?:<tool_response[^>]*>\s*)?(?:SYSTEM [A-Z0-9][A-Z0-9 _-]{0,30}?\s*[:(\u2014#]|AUTO-DIAGNOSTIC:)")
_MEMBER_STEER_KNOWN_TOOLS = ("browser", "deep_research", "execute", "file_system", "workspace")
MEMBER_STEER_CAVEAT = (
    "\n(On this channel only " + ", ".join(sorted(set(_MEMBER_ALLOWED_TOOLS) - {"abort_attempt", "replan"}))
    + " exist — ignore any other tool named above and use what those give you.)")


def member_steer_caveat(text, blocked_names) -> str:
    """A member's copy of a steer: unchanged unless it is a steer (by its head)
    that names a tool the member lacks, which gets the caveat once."""
    s = str(text or "")
    if not _MEMBER_STEER_HEAD_RE.match(s) or MEMBER_STEER_CAVEAT in s:
        return text
    names = [re.escape(n) for n in blocked_names if n]
    if not names or not re.search(r"(?<![\w])(?:" + "|".join(names) + r")(?![\w])", s):
        return text
    return s + MEMBER_STEER_CAVEAT


#: §4KL R4: refused member calls in one request before the report is forced.
MEMBER_REFUSAL_REPORT_AT = 3


def member_search_yield_steer(run: int) -> str:
    """§4KL: the search-yield steer for a channel member's turn — the
    answer-from-snippets half only; the owner's text sends the model to
    `browser`, which a member cannot call."""
    return (
        f"SYSTEM ALERT: you have run {run} web searches in a row. On this request "
        "you cannot open pages or download files, so search snippets are all the "
        "text you will get, and another query of the same kind will not add "
        "any. Write your answer NOW from the snippets you already have: state what "
        "they support, and name plainly each part of the question you could NOT "
        "confirm and what would be needed to confirm it. Keep each statement with "
        "the result it came from: a snippet from another site is that site's claim, "
        "not the content of a page the user linked. Do NOT run another "
        "web_search or darkweb_search.")


def _manage_projects_closed_a_task(tool_name: str, result_text: str) -> bool:
    """True iff a ``manage_projects`` call actually closed a task to DONE.

    Used to enforce one-task-per-turn in the interactive loop: a single
    "start task 1" / "proceed" advances EXACTLY one task and then stops, so the
    agent doesn't grind the whole project tree in one request (observed live).

    The signal is the store read-back the tool returns — ``{"updated":[{"id":…,
    "status":"DONE"},…]}`` — NOT the requested status, so a DONE-gated/held
    update (status stays non-DONE pending verification) correctly does NOT
    trip the gate. Defensive: any parse problem returns False.
    """
    if tool_name != "manage_projects" or not result_text:
        return False
    # Cheap pre-check before paying for a JSON parse.
    if '"status": "DONE"' not in result_text:
        return False
    try:
        payload = json.loads(result_text)
    except Exception:
        return False
    updated = payload.get("updated") if isinstance(payload, dict) else None
    if not isinstance(updated, list):
        return False
    return any(isinstance(u, dict) and str(u.get("status", "")).upper() == "DONE"
               for u in updated)


def _scrub_host_sandbox_paths(text: str, sandbox_root) -> str:
    """Rewrite any HOST-absolute sandbox path leaking into the model's context
    to its container-visible ``/workspace`` form.

    A recalled memory, a scratchpad note, or a workspace narrative written in a
    PRIOR session can carry an absolute host path like
    ``/Users/x/Data/AI/Data/sandbox/projects/<id>/...``. The model runs shell
    commands INSIDE the container, where the sandbox root is bind-mounted at
    ``/workspace`` and that host path does NOT exist — so a ``cd`` to it ENOENTs
    and burns a strike (observed live 3× in one session: the model kept doing
    ``cd /Users/.../sandbox/projects/<id>/PetAI``). The container form is valid
    for both the shell and the file tools (``_get_safe_path`` accepts
    ``/workspace/...``). Best-effort; returns the text unchanged on any problem.
    """
    if not text or not sandbox_root:
        return text
    roots = []
    try:
        roots.append(str(Path(sandbox_root)))
        rp = str(Path(sandbox_root).resolve())
        if rp not in roots:
            roots.append(rp)
    except Exception:
        roots = [str(sandbox_root)]
    for r in roots:
        if r and r not in ("/", "") and r in text:
            text = text.replace(r, "/workspace")
    return text


#: the tail of the one-task-stop note: what the scrubbed call was is unknown
from .reply_smoothing import TASK_CLOSED_CALL_NOT_RUN, TASK_CLOSED_NOTE  # noqa: E402


def _unparsed_call_note(task_closed: bool) -> str:
    """The sentence appended after an answer whose tool call was scrubbed.

    §4QA: when the one-task-per-turn gate closed the turn, the scrubbed call
    is the model reaching for the NEXT task — the planned stop working, not a
    failure. "A tool call … was NOT executed" read as an error after every
    task of project 448d5afa86f0; say how to continue instead. Its last
    sentence still says the call did not run: the reply beside it may say
    "Saved …" (fresh-eye MAJOR-4) and nothing here can tell which call it was."""
    if task_closed:
        return _scrub_fallback_message("", True) + " " + TASK_CLOSED_CALL_NOT_RUN
    from .reply_smoothing import UNPARSED_TOOL_CALL_NOTE
    return UNPARSED_TOOL_CALL_NOTE


def _scrub_fallback_message(intended: str, task_closed: bool) -> str:
    """User-facing text when a text-only turn's tool_call was fully scrubbed.

    Two causes, two messages:
      * ``task_closed`` — the one-task-per-turn gate finalized the turn after a
        project task closed; the dropped tool_call was the model trying to start
        the NEXT task. Say so plainly — telling the user to "rephrase" a request
        that already succeeded is misleading.
      * otherwise — a genuine planner/model routing mismatch (the turn was
        routed text-only but the model still wanted a tool). Keep the generic
        prepared-a-tool-call guidance.
    """
    if task_closed:
        from .reply_smoothing import TASK_CLOSED_NOTE
        return TASK_CLOSED_NOTE
    tool = intended or "the command"
    from .reply_shape_check import FALLBACK_HEADS as _heads   # §4HW: one home
    msg = _heads["text_only"]
    if intended:
        msg += f" (Intended tool: `{intended}`.)"
    msg += f" Please rephrase your request — for example, `run {tool}` — or try again."
    return msg


def _challenge_output_prefixes(challenge_text) -> list:
    """Extract literal output-line prefixes a self-play challenge pins down.

    Challenges frequently specify their expected output as a backtick-quoted
    template with an explicit placeholder, e.g. ``Output:
    `TotalAllocatedQuantity: <sum>` ``. The literal label before the
    placeholder is a cheap, high-precision fingerprint of the required
    format: a correct solution's stdout MUST contain it verbatim.

    Only templates of the shape ``Label: <value>`` / ``Label = {value}``
    are mined — the label must end in ``:`` or ``=`` right before a
    ``<...>``/``{...}`` placeholder. Anything looser (a bare ``<value>``,
    a column sketch like `user_id net_balance`, code fragments with ``<``
    comparisons) is ignored: without an unambiguous literal we cannot
    tell format text from prose, and a false "literal" would wrongly veto
    the short-circuit. Conservative by construction — the result is used
    only to KEEP the confirmation turn, never to fail a run.
    """
    if not challenge_text:
        return []
    prefixes: list = []
    for span in re.findall(r"`([^`\n]{4,160})`", str(challenge_text)):
        m = re.match(r"^([^<{]{0,80}?[:=])\s*[<{]", span)
        if not m:
            continue
        literal = m.group(1).strip()
        # Require a real anchor: ≥3 chars including a letter, so a lone
        # ":" or "=" fragment can never become a veto token.
        if len(literal) >= 3 and re.search(r"[A-Za-z]", literal):
            if literal not in prefixes:
                prefixes.append(literal)
    return prefixes


def _json_args_cut_off(raw, err) -> bool:
    """§4NU (7140be61): a JSON-form tool call whose ARGUMENTS end before they
    close — the output cap severed it ("Unterminated string starting at …",
    or the decode error sits at the very end of the text). The XML-form
    detector (`_tool_call_truncated`) never saw this shape, so the model got
    a generic "Invalid JSON" and regenerated the same 16k-token write."""
    if not isinstance(err, json.JSONDecodeError):
        return False
    s = str(raw or "").rstrip()
    if len(s) < 200:            # a short malformed call is a syntax slip, not a cut
        return False
    # r2: a call that ends in "}" is complete text with a slip in it (a
    # trailing comma, an extra brace) — not a cut
    return err.msg.startswith("Unterminated string") or (err.pos >= len(s) - 2 and not s.endswith("}"))


_BLOCK_CLOSER_RE = re.compile(r"</(?:function(?:_name)?|tool_call)\s*>", re.IGNORECASE)


def _block_was_cut(block: str) -> bool:
    """§4NU r3: the block never closed — no EXACT closing tag (a prefix test
    matched `</FunctionList>` in a JSX body and let a cut write run), or a
    CDATA body opened and never closed (its masked text is invisible, so a
    literal closer inside it must not count)."""
    b = str(block or "")
    last_cdata = b.rfind("<![CDATA[")
    if last_cdata >= 0 and b.find("]]>", last_cdata) < 0:
        return True
    return not _BLOCK_CLOSER_RE.search(b)


_CUT_CONTENT_KEY_RE = re.compile(r'"content"\s*:\s*"')
_CUT_NEW_STRING_KEY_RE = re.compile(r'"new_string"\s*:\s*"')
#: §4NU r4: below this a cut write is not worth saving as a part
CUT_SALVAGE_MIN_CHARS = 1000


def _salvage_cut_write(raw):
    """§4NU r4 (probe-4nu-story): a native `file_system` write cut by the
    output cap carried 72 KB of good text up to the cut — discarded twice,
    4 minutes each, because the model cannot hold one call to a planned
    length. Recover the call: the keys before `content` (operation, path,
    append) and the content up to its last COMPLETE line. → the args for a
    real write of that part (more_parts=true, `cut_off_saved`), or None."""
    s = str(raw or "")
    m = None
    for m in _CUT_CONTENT_KEY_RE.finditer(s):
        pass
    if m is None:
        return _salvage_cut_add_edit(s)
    try:
        head = json.loads(s[:m.start()].rstrip().rstrip(",") + "}", strict=False)
    except Exception:  # noqa: BLE001
        return None
    if not isinstance(head, dict) or str(head.get("operation") or "").strip().lower() != "write":
        return None
    if not (head.get("path") or head.get("filename") or head.get("file")):
        return None
    body = s[m.end():]
    body = re.sub(r"\\u[0-9a-fA-F]{0,3}$", "", body)           # a cut \uXXXX escape
    if (len(body) - len(body.rstrip("\\"))) % 2:                 # a cut \x escape
        body = body[:-1]
    try:
        text = json.loads('"' + body + '"', strict=False)
    except Exception:  # noqa: BLE001
        return None
    cut = text.rfind("\n")
    text = text[:cut + 1] if cut >= 0 else ""
    if len(text) < CUT_SALVAGE_MIN_CHARS:
        return None
    return {**head, "operation": "write", "content": text, "more_parts": True}


def _decode_cut_json_string(body: str):
    """The JSON string value that starts at `body` and was cut: decoded up to
    the cut (a half escape dropped), or None."""
    body = re.sub(r"\\u[0-9a-fA-F]{0,3}$", "", body)
    if (len(body) - len(body.rstrip("\\"))) % 2:
        body = body[:-1]
    try:
        return json.loads('"' + body + '"', strict=False)
    except Exception:  # noqa: BLE001
        return None


def _salvage_cut_add_edit(s: str):
    """§4NZ: a cut `edit` that only ADDS after its anchor (new_string starts
    with old_string) — how the model grows a file 5 of 8 times — becomes an
    append of the added text up to its last complete line. The anchor
    travels out of band (`_tail_anchor`): the tool appends only if the file
    really ENDS with it (probe-ap-b lost a 79 KB cut edit)."""
    m = None
    for m in _CUT_NEW_STRING_KEY_RE.finditer(s):
        pass
    if m is None:
        return None
    try:
        head = json.loads(s[:m.start()].rstrip().rstrip(",") + "}", strict=False)
    except Exception:  # noqa: BLE001
        return None
    if not isinstance(head, dict) or str(head.get("operation") or "").strip().lower() != "edit":
        return None
    old, path = head.get("old_string"), head.get("path") or head.get("filename") or head.get("file")
    if not (isinstance(old, str) and old.strip() and path):
        return None
    text = _decode_cut_json_string(s[m.end():])
    if not isinstance(text, str) or not text.startswith(old):
        return None
    extra = text[len(old):]
    if not old.endswith("\n") and not extra.startswith(("\n", "\r\n")):
        return None          # review: it continues the anchor's own LINE — an append would split it
    cut = extra.rfind("\n")
    extra = extra[:cut + 1] if cut >= 0 else ""
    if len(extra) < CUT_SALVAGE_MIN_CHARS:
        return None
    return {"operation": "write", "path": path, "append": True, "more_parts": True,
            "content": extra, "_tail_anchor": old}


def _cut_call_must_not_run(tc) -> bool:
    """§4NU r1: a cut-off call whose partial arguments would WRITE or RUN
    something (a file write/edit, a script) — refused rather than run on a
    fragment. Reads are harmless to run."""
    try:
        fn = (tc or {}).get("function") or {}
        name = str(fn.get("name") or "")
        # r3: dispatch canonicalises aliases (`filesystem`, `fs`, `File_System`)
        name = GhostAgent._canonicalise_tool_name(name, ["file_system", "execute"]) or name
        args = fn.get("arguments")
        if isinstance(args, str):
            args = json.loads(args or "{}")
        args = args if isinstance(args, dict) else {}
    except Exception:  # noqa: BLE001
        return True
    if name == "file_system":
        return str(args.get("operation") or "").strip().lower() in (
            ("write", "edit", "replace") + FS_APPEND_ALIASES)       # §4NZ review: the alias writes too
    return name in ("execute",)


#: §4NZ: operation names a model uses for "add to the end" — the tool runs
#: them as write + append=true; the agent normalises them BEFORE its own
#: write/mutation checks (review: they slipped past every "write" list)
FS_APPEND_ALIASES = ("append", "append_file", "write_append")


def normalize_fs_append_alias(args):
    """In place: operation in FS_APPEND_ALIASES → write + append=true.
    Returns True when it changed something."""
    if isinstance(args, dict) and str(args.get("operation") or "").strip().lower() in FS_APPEND_ALIASES:
        args["operation"] = "write"
        args["append"] = True
        return True
    return False


#: §4OA: replies of a request that hit the output limit — req id → [count,
#: seconds], read by the cut note. §4RF: the lower limit a cut turned on for
#: the rest of the request (8k) is gone — on Qwen3.8 every cut was inside the
#: thinking, and the 8k replies after it were cut again inside the thinking
#: (5A, 6F: three cuts, ~18 min); every reply keeps 16k.
_LENGTH_STOPS: "dict[str, list]" = {}


def note_length_stop(req_id, secs) -> None:
    rid = str(req_id or "")
    if not rid:
        return
    if len(_LENGTH_STOPS) > 256 and rid not in _LENGTH_STOPS:
        for k in list(_LENGTH_STOPS)[:64]:
            _LENGTH_STOPS.pop(k, None)
    row = _LENGTH_STOPS.setdefault(rid, [0, 0.0])
    row[0] += 1
    row[1] += float(secs or 0.0)


def length_stops(req_id) -> tuple:
    row = _LENGTH_STOPS.get(str(req_id or ""))
    return (row[0], row[1]) if row else (0, 0.0)


_LIST_ITEM_RE = re.compile(r"^\s*(?:[\"'`].{12,}[\"'`],?\s*$|[-*•]\s+\S.{10,}|\d{1,4}[.)]\s+\S.{10,}|<li\b[^>]*>\s*\S.{10,}"
                           r"|\{\s*[\"'][^\"']*[\"']\s*:.{10,})")   # a one-line object `{"name": …},`
_OBJECT_OPEN_RE = re.compile(r"\s*\{\s*$")
_KEY_VALUE_LINE_RE = re.compile(r"""\s*["'][^"']*["']\s*:""")   # `"name": …` — one field of a dict, not a list item
_REQUESTED_COUNT_RE = re.compile(r"(?<![\d.,\-–x×])(\d{1,2},\d{3}|\d{2,5})(?![\d.,%:\-–x×])(?:\s*$|\s+(?!(?:kb|mb|gb|ms|s|sec|secs|seconds?|min|mins|minutes?|hours?|days?|weeks?|months?|years?|times|px|%|words?|lines?|chars?|characters|tokens|bytes|pages?|to)\b)\w)", re.I)


def list_item_stats(text: str, user_text: str) -> tuple:
    """(items, asked): the list items in `text` (quoted strings, bullets,
    numbered lines) and the counts the request names (years, ranges and
    dimensions excluded) — the §4OA note and the §4OB close mode read it."""
    lines = str(text or "").splitlines()
    items = [ln.strip() for ln in lines
             if _LIST_ITEM_RE.match(ln) and not _KEY_VALUE_LINE_RE.match(ln)
             and '"""' not in ln and "'''" not in ln]   # a dict entry or a docstring is not an item
    # probe-big: a list of dicts/objects — a lone `{` line followed by a `"key":` line
    # is ONE entry (an Allman-style code brace is followed by code, not a key)
    items += [ln.strip() for ln, nxt in zip(lines, lines[1:])
              if _OBJECT_OPEN_RE.match(ln) and _KEY_VALUE_LINE_RE.match(nxt)]
    nums = [(int(m.group(1).replace(",", "")), "," in m.group(1))
            for m in _REQUESTED_COUNT_RE.finditer(str(user_text or ""))]
    asked = sorted({n for n, comma in nums if 10 <= n <= 20000 and (comma or not 1900 <= n <= 2100)})
    return items, asked


def cut_round_note(req_id, saved_text: str, user_text: str) -> str:
    """§4OA: what the model is told about the cut it just had — which round,
    the time the cut replies took, and (probe-ap2-h: 717 facts for 300, one
    reply, never counted) how many list items the cut reply held and how
    many repeat, next to the counts the user asked for."""
    n, secs = length_stops(req_id)
    parts = []
    if n >= 1:
        parts.append(f"This is cut-off #{n} in this request — the cut replies took ~{secs / 60:.0f} min; "
                     f"send parts of at most ~15 KB.")
    items, asked = list_item_stats(saved_text, user_text)
    if len(items) >= 20:
        dup = len(items) - len(set(items))
        parts.append(f"The saved part holds {len(items)} list items"
                     + (f", {dup} of them repeated" if dup else "")
                     + (f"; numbers in the request: {', '.join(map(str, asked))}" if asked else "")
                     + " — count before you add more; if the request asked for a number of items, "
                       "stop at that number.")
    return ("\n" + " ".join(parts)) if parts else ""


def cut_off_call_message(tool_name: str, raw_len: int) -> str:
    """§4NU: what the model is told when its tool call was cut off."""
    return (
        f"SYSTEM ERROR: your '{tool_name}' call was CUT OFF — the reply hit the output limit "
        f"after {raw_len:,} characters of arguments, so the call never finished and NOTHING ran "
        "or was written. This is a LENGTH problem, not a syntax problem: re-sending the same call "
        "will be cut off again. " + BIG_FILE_GUIDANCE)


def cut_in_thinking_message(draft: str, note: str = "") -> str:
    """§4RF: what the model is told when its reply hit the output limit while
    it was still thinking — no answer, no tool call. Before this it was told
    it had "stopped abruptly" (a stall), which names the wrong cause: the
    live turn had drafted a whole web app inside 16k tokens of thinking, and
    the retry started from nothing (history keeps no thinking). The cut
    thinking now rides along verbatim as the model's draft, so the ~12 min
    it took become the start of the work (operator: "go with option 1").
    Only the cause is named; the thinking itself is not limited. `note` is
    the §4OA cut note (round, minutes)."""
    draft = str(draft or "")
    return (
        "SYSTEM ALERT: your reply hit the OUTPUT LIMIT while you were still thinking — "
        f"{len(draft):,} characters of thinking, then the cut, so no answer and no tool call "
        "came out. Your thinking up to the cut is below, verbatim, as YOUR DRAFT. Do not plan "
        "it again: build on it. Put the code or text it already holds straight into the tool "
        "call or the answer, then continue from where it stops. If you are writing a file: "
        + BIG_FILE_GUIDANCE + str(note or "")
        + "\n\n----- YOUR DRAFT (your own thinking up to the cut, verbatim) -----\n"
        + draft + "\n----- END OF YOUR DRAFT -----")


def _tool_call_truncated(content: str) -> bool:
    """Return True when `content` opens a <tool_call>/<function> block but
    never closes it.

    This catches the upstream-truncation case where the server's max_tokens
    cap severed the assistant's output mid-tool-call. We use it both (a) as
    a diagnostic signal fed back to the model ("your output was cut off,
    shorten or chunk") and (b) as a hint to the parser that it should
    emit whatever partial `<parameter>` body it DID capture rather than
    giving up with `system_parse_error`.
    """
    if not content:
        return False
    opens = len(re.findall(r'<tool_call\b', content, re.IGNORECASE))
    closes = len(re.findall(r'</tool_call\b', content, re.IGNORECASE))
    if opens > closes:
        return True
    fn_opens = len(re.findall(r'<function\b[^>]*>', content, re.IGNORECASE))
    fn_closes = len(re.findall(r'</function\b', content, re.IGNORECASE))
    if fn_opens > fn_closes:
        return True
    return False


# A REAL `<function ...>` opener in any accepted dialect: `name=`, bare `=`, or
# the `_name=` variant, with `name` optionally padded — the exact shapes the
# sloppy-attribute heals normalize. Deliberately NOT a bare `<function`
# substring: prose that merely MENTIONS the token ("the <function> keyword"),
# and a raw-JSON tool call whose arguments contain the literal string
# `<function`, must NOT be mistaken for an XML tool call. Routing either into
# the XML healer dropped native calls, dropped raw-JSON calls, and truncated
# prose replies (§ turn-loop R2). Used by BOTH the bare-`<function>` wrapper
# heal and the `has_tool_tag` routing gate so the two agree on "real tag."
_FN_TAG_RE = re.compile(r'<function(?:_name)?\s*(?:name\s*=|=)', re.IGNORECASE)


# --- prompt-bleed truncation (§ finalize/stream R1 A-F3) --------------------
# STRONG markers are prompt-section text that never appears in legitimate
# user-facing content — any one of them proves a system-prompt bleed and the
# reply is truncated at the earliest marker. WEAK markers are legitimate in
# real answers (`# Tools` is a routine README heading; a coding answer may
# quote an OpenAI tool-schema `{"type": "function"` example) — before this
# split, a single weak marker silently truncated the reply (a README draft
# lost its Tools+License sections; a schema example cut a coding answer to
# its first line, both delivered with Turn Outcome `ok`). A weak marker only
# truncates when corroborated: a strong marker present anywhere, or BOTH weak
# markers co-occurring (a real bleed dumps the tool list, so they do).
_BLEED_STRONG = ("<tools>", "You may call one or more functions",
                 "CRITICAL INSTRUCTION:", "SPECIALIST SUBSYSTEM ACTIVATED",
                 "ENGINEERING STANDARDS", "DYNAMIC SYSTEM STATE",
                 "[SYSTEM STATE UPDATE]",
                 # § R2 A-F3b: the native-path prompt renders the tool list as
                 # this pointer sentence (agent.py, native header) — a
                 # paraphrased bleed can carry it with no other marker.
                 "(Tool schemas are advertised via the native")
_BLEED_WEAK = ("# Tools", '{"type": "function"')


def reply_tap_unsafe(text: str) -> bool:
    """§4MP r2 M3: content that must never reach a client live — any call
    shape the parsers accept (`_TOOL_MARKUP_RE`, `_FN_TAG_RE`: `<tool_call>`,
    `<tool …>`, `<function=…>`, `<function_name=…>`), think tags, a tool
    result, a chat-template token, or prompt bleed (strong AND weak markers:
    stopping the live stream only costs the fast path). The reply tap's
    private copy missed four of these."""
    if not text:
        return False
    if _TOOL_MARKUP_RE.search(text) or _FN_TAG_RE.search(text):
        return True
    low = text.lower()
    if any(m in low for m in ("<think", "</think", "<tool_response", "<parameter", "<|im_", "<|endoftext")):
        return True
    return any(m in text for m in _BLEED_STRONG) or any(m in text for m in _BLEED_WEAK)


# --- stream-scrub hold-back classifier (§ finalize/stream R1 B-1, R2 C1/M4) --
_SCRUB_TAG_NAMES = ("tool_call", "tool_response", "tool", "function")


# (§ R4 D1) The close-end check must be NAME-AWARE: `_MODULE_SCRUB_RE`'s
# close arm is a BACKREFERENCE (`</\1`), so an unclosed <tool_call> whose
# eaten tail ends with an inner </function> — the CANONICAL native tool-call
# shape — is still being eaten by the \Z arm. A name-blind "any close tag"
# check read that as closed, unfroze the view, and plain appends leaked the
# block's internals to the client. Built per-match from group(1) in
# `_scrub_tail_is_open`.


# THE stream scrub pattern — single module-level source of truth used by the
# final-stream generator AND `_scrub_tail_is_open` (two inline copies would
# drift: the wrapper-split lesson). `(?<!\x60)`: a backtick-quoted mention of
# tool XML is legitimate prose (§ R1 B-1).
# The \Z arm carries a NAMED GROUP so consumers can ask WHICH ARM matched
# (§ R5: `_scrub_tail_is_open` used to test a text PROPERTY — "group(0) ends
# with its own close tag" — and a malformed opener with no '>' before its
# close tag swallowed that tag into `[^>]*>`-land: the match had really ended
# via \Z (still eating) while the suffix read "closed", unfreezing the view
# and leaking eaten internals to the client. Arm identity is exact;
# pin-identity-not-property, in code.)
#: The UI scrub: unparsed tool-call markup removed from text the USER will
#: read. One pattern, two sites (mid-flow `ui_content`, end-of-turn
#: `final_ai_content`) — they were two literals, and they had DRIFTED
#: (§4GT, 2026-09-14): the end-of-turn copy carries `(?<!`)` because inline
#: code is the user asking about the syntax, not a leak (§4FS), and the
#: mid-flow copy did not — so the same reply lost its backticked
#: `<tool_call>` example on one path and kept it on the other. The two
#: literals were pinned only by a source grep for their text, which cannot
#: see a difference between them.
#:
#: ⚠ `\Z`, never `$`: in non-MULTILINE mode `$` matches just before a
#: trailing newline, which let the newline escape the scrub.
#: The call DIALECTS only (§4IY, fresh-eye review): `<tool_call>`, `<tool
#: name=…>`, `<function=…>` / `<function name=…>` (and `<tool_response>` for
#: the module copy). "Run `ghost <tool name> --help`" and a repr "<function
#: tool_execute at 0x…>" in prose were leaks, and everything after them was
#: deleted. The opening tag captures its name so the close matches by name.
_CALL_OPEN = (r'<(?:(?P<tc>tool_call)\b[^>]*>|(?P<tn>tool)(?:\s*>|\s+name\s*=[^>]*>)'   # a bare `<tool>` is the old dialect; "<tool name>" in prose is not
              # `<function=…>` / `<function name=…>`, or ANY `<function …>` that a `</function>` closes
              # later (the r2 leak fixture); a repr "<function tool_execute at 0x…>" has no close → prose
              r'|(?P<fn>function)(?:(?:\s*=|\s+name\s*=)[^>]*>|\b[^>]*>(?=.*?</function\b)))')
#: …closed by the SAME tag (a `</function>` inside a `<tool_call>` block does
#: not end the block), via conditional groups on the captured opener.
_CALL_CLOSE = (r'(?(tc)</tool_call\b[^>]*>|(?(tn)</tool\b[^>]*>|(?(fn)</function\b[^>]*>|</tool_response\b[^>]*>)))')
_UI_SCRUB_RE = re.compile(
    r'(?<!`)' + _CALL_OPEN + r'.*?(?:' + _CALL_CLOSE + r'|\Z)',
    flags=re.DOTALL | re.IGNORECASE,
)

_MODULE_SCRUB_RE = re.compile(
    r'(?<!`)(?:' + _CALL_OPEN + r'|<(?P<tr>tool_response)\b[^>]*>).*?'
    r'(?:' + _CALL_CLOSE + r'|(?P<eof>\Z))',
    flags=re.DOTALL | re.IGNORECASE,
)


def _scrub_tail_is_open(buf: str) -> bool:
    """True when the LAST scrub match in `buf` is an unclosed block whose
    \\Z arm is consuming the tail — new '>'-less text is provably eaten and
    the scrubbed view is frozen (the incremental-scrub invariant).

    § R4 D1 + R5: closed means the CLOSE-TAG ARM matched — asked directly
    via the pattern's named `eof` group (arm identity), never inferred from a
    text suffix. The R4 suffix check ("group(0) ends with its own close
    tag") was a property proxy: a malformed opener with no '>' swallowed its
    own close tag into `[^>]*>`, the match really ended via \Z (eating), and
    the proxy read "closed" — unfreezing the view and leaking eaten
    internals."""
    last = None
    for m in _MODULE_SCRUB_RE.finditer(buf):
        last = m
    if last is None or last.end() != len(buf):
        return False
    return last.group('eof') is not None


def _frag_is_forming_tag(frag: str) -> bool:
    """True when `frag` (the lowercased text after an unresolved '<') could
    still become a scrub-target tag.

    § R3 A-D2: R2's 64-char release valve existed for prose like
    "<tool_threshold else …" — but releasing a GENUINE attribute-heavy
    opener at 64 chars leaked it and, once it completed and scrubbed,
    permanently swallowed the post-block text (the C1 swallow reborn through
    C1's own valve). The real discriminator is the tag-NAME BOUNDARY:
    "tool" followed by "_threshold" is a longer word (prose, release
    immediately — faster than the old 64-wait); "function name=…" is the
    exact name plus a boundary (a forming tag: hold however long its
    attributes run — never released, so never swallowed)."""
    if frag == "":
        return True
    if frag.startswith("/") and len(frag) <= 16:
        return True
    for name in _SCRUB_TAG_NAMES:
        if name.startswith(frag):        # partial name, still typing
            return True
        if frag.startswith(name):
            nxt = frag[len(name):len(name) + 1]
            if nxt == "" or not (nxt.isalnum() or nxt == "_"):
                return True              # exact name + boundary → forming tag
    return False


def _emit_safe_end(view: str, emitted: int) -> int:
    """Index up to which `view` is safe to emit to the client.

    Scans the un-emitted window for the FIRST '<' that (a) has no '>' after
    it, (b) is not backtick-quoted, and (c) opens a fragment that could still
    become a scrub-target tag (`_frag_is_forming_tag`). Holding from the LAST
    '<' (the R1 shape) was a proxy: a newer '<' released an earlier
    still-forming tag, and once that tag completed and scrubbed, the shrunken
    view sat below the emitted counter and legitimate post-block prose was
    silently swallowed (R2 C1)."""
    p = view.find('<', emitted)
    while p != -1:
        if '>' not in view[p:] and not (p > 0 and view[p - 1] == '`'):
            if _frag_is_forming_tag(view[p + 1:].lower()):
                return p
        p = view.find('<', p + 1)
    return len(view)


def _inline_think_open(buf: str) -> bool:
    """True while an inline ``<think>`` block is OPEN in `buf` — the gate for
    the cognitive watchdog and the content-channel n-gram probe.

    ASYMMETRIC by failure direction (§ R2 M1/M2, redesigned § R3 A-D1):

    * OPENER: a backtick-preceded ``<think`` is a code-span MENTION and is
      skipped — counting it opened the gate on a plain answer and the
      watchdog severed it (R2 M1). Only backticks skip: quote characters are
      ordinary prose and an apostrophe-preceded REAL opener must count.
    * CLOSER: EVERY ``</think`` occurrence counts, quoted or not. A real
      block routinely ends with a quoted string (``…"notes.md"</think>``) —
      R2's quote-skip treated that REAL closer as a mention, the gate stuck
      open, and the false sever the fix existed to kill came back. A
      mentioned closer at worst closes the gate early: probes off is the
      SAFE direction (under-protection), a false sever is not.

    Closer matches by PREFIX (``</think``) so ``</thinking>`` disarms — the
    opener already matches ``<thinking`` by prefix (R2 M2)."""
    i = buf.rfind('<think')
    while i > 0 and buf[i - 1] == '`':
        i = buf.rfind('<think', 0, i)
    return i > buf.rfind('</think')


def _find_unquoted(text: str, marker: str) -> int:
    """First occurrence of `marker` not immediately preceded by a quote or
    backtick — a quoted marker is the reply DISCUSSING the prompt, not the
    prompt bleeding (§ R2 A-F3a: a meta-answer quoting "CRITICAL
    INSTRUCTION:" was truncated to 19 chars)."""
    i = text.find(marker)
    while i > 0 and text[i - 1] in "`'\"":
        i = text.find(marker, i + 1)
    return i


def _truncate_prompt_bleed(text: str) -> str:
    if not text:
        return text
    strong_idxs = [i for m in _BLEED_STRONG
                   if (i := _find_unquoted(text, m)) != -1]
    weak_idxs = [i for m in _BLEED_WEAK
                 if (i := _find_unquoted(text, m)) != -1]
    if strong_idxs:
        return text[:min(strong_idxs + weak_idxs)]
    # § R2 M-3: two weak markers corroborate only when NEAR each other — a
    # real bleed dumps the schema JSON right after the `# Tools` heading. On
    # the multi-turn ASSEMBLED reply, a legitimate README `# Tools` section
    # plus a legitimate schema example hundreds of chars later co-occurred
    # and truncated the reply wholesale.
    if len(weak_idxs) >= 2 and (max(weak_idxs) - min(weak_idxs)) <= 600:
        return text[:min(weak_idxs)]
    return text


# A line ending in a task-status suffix. Stripped only in RUNS of >=3
# consecutive matching lines — that shape is a regurgitated task TREE, while
# one or two isolated lines ("- Ship the report (PENDING)") are legitimate
# content in a task-status answer, the exact format the agent's own task
# tooling teaches (§ finalize/stream R1 A-F3: the old unconditional line
# scrub deleted them, unlogged, on every non-streamed turn).
_TASK_STATUS_LINE_RE = re.compile(
    r'^.*?\((?:IN_PROGRESS|READY|PENDING|DONE|FAILED|BLOCKED)\)\s*$')


# § R3 B-D3: fence markers, BOTH dialects (``` and ~~~), line-anchored — the
# R2 fence walk counted bare "```" substrings, so tilde fences were invisible
# (a correction landed inside a ~~~markdown block) and inline ``` mentions
# miscounted.
_FENCE_MARK_RE = re.compile(r'(?m)^\s*(?:`{3,}|~{3,})')


# § R3 B-D2: the bracket arm requires task-ish interiors — a bare `^\s*\[`
# counted a markdown-link lead ("[README](docs/…) refreshed (DONE)") as
# task-shaped.
_TASK_SHAPE_RE = re.compile(
    r'task_\d+|^\s*(?:🔄|🟢|⏳|✅|❌|🛑|➖)'
    r'|^\s*\[(?:task_\d+|IN_PROGRESS|READY|PENDING|DONE|FAILED|BLOCKED)\b')


def _scrub_task_status_runs(text: str) -> str:
    if not text or "(" not in text:
        return text
    lines = text.split("\n")
    flags = [bool(_TASK_STATUS_LINE_RE.match(l)) for l in lines]
    out: list = []
    i, n = 0, len(lines)
    while i < n:
        if flags[i]:
            j = i
            while j < n and flags[j]:
                j += 1
            # § R2 M-4 + R3 B-D2: a run is stripped only when it is long
            # (>=3) AND MAJORITY task-shaped. `any()` let one task_NN id
            # mentioned in PROSE ("Fix the task_7 regression") poison a
            # legitimate workstream answer wholesale; a real regurgitated
            # tree carries its markers on (essentially) every line.
            _shaped = sum(1 for l in lines[i:j] if _TASK_SHAPE_RE.search(l))
            if j - i < 3 or _shaped * 2 < (j - i):
                out.extend(lines[i:j])
            i = j
        else:
            out.append(lines[i])
            i += 1
    return "\n".join(out)


# Streaming sanity guards live in core/stream_guards.py (the guard-module seam,
# IMPROVEMENTS.md #5) — new stream guards land THERE, not inline here. Re-export
# the names so existing references + tests in this module keep working.
from .stream_guards import (  # noqa: E402
    THINKING_LOOP_PROBE_EVERY, THINKING_LOOP_WINDOW, THINKING_LOOP_THRESHOLD,
    TOOL_CALL_LOOP_THRESHOLD, TOOL_CALL_LOOP_PROBE_EVERY,
    PARAGRAPH_LOOP_MIN_LINE, PARAGRAPH_LOOP_THRESHOLD,
    SENTENCE_RUN_THRESHOLD,
    TOOL_CALL_BATCH_CEILING, NATIVE_TOOL_CALL_REPEAT,
    _STREAM_STOP_MARKERS,
    _detect_thinking_loop, _tail_has_stop_marker, _detect_tool_call_loop,
    _detect_paragraph_loop, _detect_sentence_run_loop, _detect_block_loop,
    _detect_native_tool_call_flood,
    _native_call_identity,
)


def _render_assistant_with_tool_calls(content: str, tool_calls: list,
                                      native: bool = False) -> str:
    """Render an assistant message + its native ``tool_calls`` list as the
    inline XML string the upstream Qwen-style API expects to see in history.

    ``native=True`` renders the EQUALS dialect (``<function=name>`` /
    ``<parameter=key>`` with values on their own lines) — on the native
    path that is the dialect the model itself GENERATED (the server
    template parsed it into structured calls; re-rendering it as
    attribute-style ``<function name="…">`` showed the model a dialect it
    never wrote, a standing dual-dialect nudge in intra-request history
    that pushes later turns off the native channel onto the strike-prone
    text-parse lane — the 2026-07-31 corruption class, req 93/65d8cf76's
    drift). ``native=False`` keeps attribute style: the legacy XML path's
    QWEN_TOOL_PROMPT contract. Both dialects round-trip through
    ``_parse_assistant_tool_calls`` (pinned in tests).

    The previous implementation re-checked ``"<tool_call>" in ast_content``
    on every iteration of the render loop. After the FIRST call was
    appended, the substring became present and silently dropped calls
    2..N — producing the production bug where 4 parallel ``update_profile``
    calls were re-derived on the next turn (and blocked by the idempotency
    guard). Snapshot the inline-check ONCE before the loop.
    """
    ast_content = content or ""
    # Never render the synthetic `system_parse_error` marker entries —
    # they are strike bookkeeping, not calls. Pre-scrub (2026-08-01)
    # they were accidentally suppressed because the broken content
    # still contained '<tool_call'; once the retry scrub replaced that
    # text with a note, the suppression vanished and the serializer
    # taught the model a well-formed call to a nonexistent tool, in
    # the attribute dialect, right under the equals-dialect SYSTEM
    # ERROR hint (review catch).
    tool_calls = [
        tc for tc in (tool_calls or [])
        if (tc.get("function") or {}).get("name") != "system_parse_error"
    ]
    if not tool_calls:
        return ast_content.strip()
    already_inline = "<tool_call>" in ast_content or "<tool_call" in ast_content
    if already_inline:
        return ast_content.strip()
    for tc in tool_calls:
        tc_func = tc.get("function", {})
        tc_args = tc_func.get("arguments", "{}")
        if isinstance(tc_args, str):
            try:
                tc_args_dict = json.loads(tc_args)
            except Exception:
                tc_args_dict = {}
        else:
            tc_args_dict = tc_args
        if native:
            xml_call = f'\n<tool_call>\n<function={tc_func.get("name", "")}>\n'
        else:
            xml_call = f'\n<tool_call>\n<function name="{tc_func.get("name", "")}">\n'
        for k, v in tc_args_dict.items():
            if isinstance(v, (dict, list, bool, type(None))):
                v_rendered = json.dumps(v, ensure_ascii=False)
            else:
                v_rendered = str(v)
            if native:
                xml_call += f'<parameter={k}>\n{v_rendered}\n</parameter>\n'
            else:
                xml_call += f'<parameter name="{k}">\n{v_rendered}\n</parameter>\n'
        xml_call += "</function>\n</tool_call>\n"
        ast_content += xml_call
    return ast_content.strip()
from ..utils.token_counter import estimate_tokens
from ..tools.registry import get_available_tools, TOOL_DEFINITIONS, get_active_tool_definitions  # pylint: disable=unused-import  # §4NM: the planner was its last user here; ~58 tests still patch this module attribute
from ..tools.outcome import ToolOutcome as _TO
from ..tools.browser_support import browser_outcome_note as _browser_outcome_note  # §4RX

#: knowledge_base actions that clear stored memory. `reset_all` deletes every
#: id in the vector collection, resets the library index to `[]` and wipes the
#: graph — a strictly larger wipe than `forget`, and it returns a SUCCESS
#: string, so without this the turn's smart_memory / post_mortem / episode
#: write all run afterwards and repopulate the store that was just emptied.
_WIPE_ACTIONS = frozenset({"forget", "reset_all"})

_FORGET_ACTION_RE = re.compile(
    r'"action"\s*:\s*"\s*(?:forget|reset_all)\s*"', re.IGNORECASE)


#: The kwarg name in "got multiple values for keyword argument 'x'".
_DUPLICATE_KWARG_RE = re.compile(
    r"got multiple values for keyword argument '([^']+)'")


#: A shell-style envelope reporting a non-zero exit. `execute` has its own
#: rescue for this, gated on `fname == "execute"` — but 12 live calls from
#: other tools (`manage_projects`, `manage_composed_skills`, `jobs`,
#: `youtube_transcribe`, `create_skill`) carry the same banner and got none.
# `0*[1-9]` — any number containing a non-zero digit. A negative
# lookahead on a single `0` called "EXIT CODE: 00" a failure.


def describe_invocation_error(fname: str, exc: Exception) -> str:
    """The tool result for a call that could not even be entered.

    The blanket wording was "(Did you forget a required argument?)", which is
    the wrong instruction for the most common way this fires. Model arguments
    are splatted unfiltered into a dispatch lambda that already supplies the
    tool's context (`memory_system`, `sandbox_dir`, `llm_client`, …), so a
    model that passes one of those names by mistake gets

        TypeError: tool_knowledge_base() got multiple values for keyword
        argument 'model_name'

    and is then told to ADD an argument when the fix is to REMOVE one. The
    same class as the §4DK forget loop: an error whose advice cannot work.
    Name the offending argument and say to drop it.
    """
    text = str(exc)
    dup = _DUPLICATE_KWARG_RE.search(text)
    if dup:
        return (
            f"SYSTEM ERROR: '{dup.group(1)}' is MANDATORY to REMOVE from this "
            f"call — it is not a parameter you may pass to '{fname}'. The "
            f"system supplies it. Re-issue the call without it, keeping your "
            f"other arguments: {text}"
        )
    if isinstance(exc, TypeError) and "unexpected keyword argument" in text:
        return (
            f"SYSTEM ERROR: '{fname}' does not accept one of the arguments "
            f"you passed. Re-read the tool schema and re-issue with only the "
            f"parameters it advertises: {text}"
        )
    # A prefix `result_is_failure` recognises. "Error invoking tool …" matched
    # none of the prefixes the turn loop booked failures by, so every non-argument
    # exception from every tool was recorded as a CLEAN SUCCESS: no strike,
    # no classifier, no diagnostic, the success-decay streak advanced, and a
    # crashed idempotent setter had its hash stored as applied so the
    # model's retry was blocked with "the intended state is already
    # applied". The old awaited path was `f"Error: {result}"`, which matched.
    return (f"Error: invoking tool '{fname}' failed (did you forget a "
            f"required argument?): {text}")


def call_runs_a_memory_wipe(fname: str, raw_arguments, available=None) -> bool:
    """Will this tool call clear stored memory?

    Sets `forget_was_called`, which suppresses smart_memory, post_mortem and
    the episode write for the turn. Get it wrong in the False direction and
    the content the user just asked to forget is re-learned inside the same
    request — tombstone resurrection.

    So it matches what the DISPATCHER will see, not the raw string. Three
    ways the previous `args.get("action") == "forget"` missed a wipe that
    then ran:

    * `tool_knowledge_base` normalises with `str(action).strip().lower()`
      because models emit "Forget"; the XML argument parser strips only
      CR/LF, so `<parameter name="action"> forget </parameter>` arrives as
      `" forget "`.
    * `json.loads` defaults to `strict=True`, so one raw control character
      anywhere in the arguments raised here — while the parse 100 lines
      later, which passes `strict=False`, succeeded and the wipe went
      through.
    * If the JSON is unparseable for any other reason, a regex over the raw
      text still catches the action.

    Biased toward True on purpose. A false positive costs one turn of
    background bookkeeping; a false negative undoes the user's deletion.
    """
    # Resolve the TOOL name with the DISPATCHER'S OWN matcher, not a second
    # one. This predicate runs ~314 lines before `_canonicalise_tool_name`,
    # so a name the dispatcher heals but this does not means the wipe RUNS
    # with the flag False — the tombstone resurrection above.
    #
    # The first fix re-implemented the healing here (alias table + a difflib
    # pass at cutoff 0.85) and a review measured the residue: the dispatcher
    # matches at 0.70 against the whole tool list, so `knowledge` (ratio
    # 0.818) and `know_base` healed there and not here. Two implementations
    # of one decision drift by construction; the fix is to have one. Pass
    # `available` from the call site and this asks the same question the
    # dispatch will ask. Without it, the alias table alone still covers the
    # spellings actually observed (kb / knowledgebase / knowledge-base).
    name = None
    if available:
        try:
            name = GhostAgent._canonicalise_tool_name(fname, list(available))
        except Exception:  # noqa: BLE001 — never let name-healing break a turn
            name = None
    if name is None:
        norm = re.sub(r"[^a-z0-9]", "", str(fname or "").lower())
        try:
            name = GhostAgent._TOOL_ALIAS_TABLE.get(norm, norm)
        except Exception:  # noqa: BLE001
            name = norm
    if name == "forget":
        return True
    if name != "knowledge_base":
        return False
    text = raw_arguments if isinstance(raw_arguments, str) else ""
    try:
        args = (json.loads(raw_arguments, strict=False)
                if isinstance(raw_arguments, str) else raw_arguments)
        if isinstance(args, dict) \
                and str(args.get("action") or "").strip().lower() in _WIPE_ACTIONS:
            return True
    except Exception:  # noqa: BLE001 — the regex below is the backstop
        pass
    return bool(_FORGET_ACTION_RE.search(text))


from ..tools.tasks import tool_list_tasks
from ..memory.skills import SkillMemory

logger = logging.getLogger("GhostAgent")


def _compute_pure_trigger_tools():
    """Names of tools that take NO parameters — a call with empty args is a
    COMPLETE call for these (none since dream_mode was removed, §4SI), not a
    degenerate one. Derived from TOOL_DEFINITIONS so it stays in sync as the
    tool list changes (guard the thing, not a hardcoded list). Used by the
    usable-native gate: an empty-args native call is only allowed to win over a
    competing XML call when the tool is a pure trigger — otherwise empty args
    means the native call is degenerate and the XML call should be honored
    (§ turn-loop R3). NOTE: `execute` has params but no REQUIRED ones, so it is
    correctly EXCLUDED — an empty `execute {}` is degenerate, not a trigger."""
    trig = set()
    for _d in (TOOL_DEFINITIONS or []):
        _fn = _d.get("function") or {}
        _name = _fn.get("name")
        _props = ((_fn.get("parameters") or {}).get("properties")) or {}
        if _name and not _props:
            trig.add(_name)
    return frozenset(trig)


_PURE_TRIGGER_TOOLS = _compute_pure_trigger_tools()

# Names of the BUILT-IN tools — TOOL_DEFINITIONS plus the built-ins whose
# schemas are appended inside get_active_tool_definitions (vision_analysis,
# image_generation; § turn-loop R5: deriving from TOOL_DEFINITIONS alone
# misclassified those two as runtime tools, so a degenerate empty-args native
# `vision_analysis {}` shadowed a fully-specified XML call — a regression the
# R4 comment's "schema unknowable at import" claim did not actually cover).
# A dispatchable tool NOT in this set is runtime-registered (a composed macro
# via register_composed_skill_runners, or an acquired skill) — its schema
# really is unknowable at import, so the trigger set above can never contain
# it even when it genuinely takes no parameters (a zero-`$var` macro
# advertises `properties: {}`). The usable-native gate treats an empty-args
# call to such a tool as USABLE (§ turn-loop R4): dispatching it errors
# recoverably at worst if it did need args, whereas the alternative —
# executing content-XML of unknown provenance (possibly a mutating ECHO)
# while dropping the model's real native call — is the unrecoverable
# direction.
from ..tools.registry import CONDITIONALLY_ADVERTISED_BUILTIN_NAMES  # noqa: E402

_STATIC_TOOL_NAMES = frozenset(
    _n for _d in (TOOL_DEFINITIONS or [])
    for _n in [(_d.get("function") or {}).get("name")] if _n
) | CONDITIONALLY_ADVERTISED_BUILTIN_NAMES


# ============================================================================
# NATIVE TOOL-CALL DE-CORRUPTION
# ----------------------------------------------------------------------------
# With ``--native-tools`` on (default for Qwen 3.6+), the upstream server
# parses the model's tool-call XML itself and hands us structured
# ``message.tool_calls`` — bypassing our own robust XML parser. Some servers
# mis-handle a MULTI-tool reply (especially the equals-format
# ``<function=name>`` / ``<parameter=name>`` shape): they close the first
# ``<parameter>`` correctly but then leak the ENTIRE serialized XML of every
# FOLLOWING tool call into the first argument's string value, e.g.
#
#   {"action": "summary</parameter>\n</function>\n</tool_call>\n
#              <tool_call>\n<function=list_lessons>\n<parameter=scope>\nall",
#    "limit": 10}
#
# The value the model actually intended is ``"summary"``; everything from the
# first framing token on is another tool call. Left uncorrected, ``action``
# fails validation ('action' must be one of [...]) and the whole turn is
# wasted — the exact "introspect keeps erroring on a valid action" symptom.
#
# We detect the leak by its unambiguous CLOSE-then-CONTINUATION signature (a
# ``</parameter>`` / ``</function>`` / ``</tool_call>`` close FOLLOWED by a NEW
# ``<tool_call>`` / ``<function=...>`` opening OR a sibling ``<parameter=...>``)
# then truncate the value at the first framing token and reconstruct intent:
#  - a leaked sibling ``<parameter=...>`` folds back into the SAME call's args
#    (e.g. manage_tasks: ``action="stop</parameter><parameter=task_identifier>…"``
#    → ``{action: stop, task_identifier: …}``);
#  - a leaked ``<function=...>`` naming a KNOWN tool is recovered as a separate
#    call; and when the whole value is framing (no clean prefix) the phantom
#    primary is dropped and the first recovered call promoted.
# Content that merely *mentions* framing text (code, docs) has no ordered
# close-then-continuation pair — or names no real tool and carries no sibling
# param — so it is never mangled.
# ============================================================================
_TC_NEXT_CALL_RE = re.compile(r'<tool_call\b|<function\s*=|<function\s+name\s*=', re.IGNORECASE)
# Leak-continuation tokens: a NEW tool call (function/tool_call) OR a sibling
# `<parameter …>` of the SAME call. The upstream native parser can merge either
# shape into the first argument's value — e.g. manage_tasks got
# `{"action": "stop</parameter>\n<parameter=task_identifier>\ntask_123"}` where
# the second PARAMETER leaked into the first, not a whole new call.
_TC_NEXT_LEAK_RE = re.compile(
    r'<tool_call\b|<function\s*=|<function\s+name\s*=|<parameter\s*=|<parameter\s+name\s*=',
    re.IGNORECASE)
_TC_CLOSE_RE = re.compile(r'</parameter\s*>|</function\s*>|</tool_call\s*>', re.IGNORECASE)
_TC_FIRST_FRAME_RE = re.compile(
    r'</parameter\s*>|</function\s*>|</tool_call\s*>|<tool_call\b|<function\s*=|<function\s+name\s*=',
    re.IGNORECASE,
)
_TC_FUNC_OPEN_RE = re.compile(
    r'<function(?:\s+name\s*=\s*["\']?|\s*=\s*["\']?)\s*([a-zA-Z0-9_]+)', re.IGNORECASE)
_TC_PARAM_RE = re.compile(
    r'<parameter(?:\s+name\s*=\s*["\']?|\s*=\s*["\']?)\s*([a-zA-Z0-9_]+)["\']?\s*>'
    r'(.*?)(?=</parameter>|<parameter[\s=]|<function[\s=]|</function>|</tool_call>|<tool_call\b|$)',
    re.DOTALL | re.IGNORECASE,
)


def _html_attr(value: str) -> str:
    """A quoted XML attribute value from a text-dialect tool call, decoded:
    inside ``value="…"`` a quote can only be written ``&quot;`` (§4RD). The
    ONLY decode a tool argument gets — element bodies and native calls are
    literal, so an entity there is the model's own text (an HTML escape
    table, a `&lt;` the page must show)."""
    import html as _html
    return _html.unescape(value)


def _value_has_leaked_framing(value) -> bool:
    """True when a string argument value carries the CLOSE-then-LEAK signature
    of an upstream-merged reply: a ``</parameter>``/``</function>``/``</tool_call>``
    close followed by a new tool call OR a sibling ``<parameter …>`` (see block
    comment). Content that merely mentions framing text lacks the ordered pair."""
    if not isinstance(value, str):
        return False
    close = _TC_CLOSE_RE.search(value)
    if not close:
        return False
    return _TC_NEXT_LEAK_RE.search(value, close.end()) is not None


def _recover_calls_from_tail(tail: str, available_names) -> list:
    """Recover ``[(name, args_dict), ...]`` for each ``<function ...>`` opening
    in the leaked ``tail``, keeping only functions in ``available_names``."""
    calls = []
    opens = list(_TC_FUNC_OPEN_RE.finditer(tail))
    for i, fm in enumerate(opens):
        fname = fm.group(1)
        if available_names and fname not in available_names:
            continue
        seg_start = fm.end()
        seg_end = opens[i + 1].start() if i + 1 < len(opens) else len(tail)
        segment = tail[seg_start:seg_end]
        args = {}
        for pm in _TC_PARAM_RE.finditer(segment):
            args[pm.group(1)] = pm.group(2).strip().strip('"').strip("'")
        calls.append((fname, args))
    return calls


def _repair_one_native_tool_call(tc: dict, available_names):
    """Return ``(primary_tc, [recovered_tcs])``. When no leak is present (or
    the leaked tail names no known tool), returns ``(tc, [])`` unchanged."""
    fn = tc.get("function") or {}
    raw = fn.get("arguments")
    if isinstance(raw, str):
        try:
            args = json.loads(raw, strict=False)
        except Exception:
            return tc, []
    elif isinstance(raw, dict):
        args = dict(raw)
    else:
        return tc, []
    if not isinstance(args, dict):
        return tc, []

    def _mk(name, a):
        return {"id": f"call_{uuid.uuid4().hex[:8]}", "type": "function",
                "function": {"name": name, "arguments": json.dumps(a)}}

    for k, v in list(args.items()):
        if not (isinstance(v, str) and _value_has_leaked_framing(v)):
            continue
        m = _TC_FIRST_FRAME_RE.search(v)
        if not m:
            continue
        tail = v[m.start():]
        # Split the tail at the first NEW-CALL opening. Everything before it is
        # sibling <parameter …> of THIS call that leaked into the value; from
        # the opening on are separate merged tool calls.
        call_open = _TC_NEXT_CALL_RE.search(tail)
        pre = tail[:call_open.start()] if call_open else tail
        post = tail[call_open.start():] if call_open else ""
        sibling = {}
        for pm in _TC_PARAM_RE.finditer(pre):
            sibling[pm.group(1)] = pm.group(2).strip().strip('"').strip("'")
        recovered = _recover_calls_from_tail(post, available_names) if post else []
        # Positively identify a leak: we must have recovered a known call OR
        # extracted at least one sibling parameter. Otherwise it's content we
        # can't attribute to the parser — leave it untouched.
        if not recovered and not sibling:
            continue
        # Guard (2026-07-20 H6): a large, multi-line value is a CONTENT body,
        # not a short leaked argument. This agent routinely writes files whose
        # content SHOWS tool-call XML (docs/tests about its own tool format),
        # which matches the leaked-framing signature and silently truncated
        # the file at the first `</parameter>` example, reporting SUCCESS. A
        # genuine merged leak recovers a known SECOND tool call; sibling
        # params alone (which a documentation example also yields) are not
        # strong enough to truncate a body-sized value. Only truncate a large
        # value when a real second call was recovered.
        if not recovered and (len(v) > 400 or "\n" in v[:m.start()]):
            continue
        recovered_tcs = [_mk(name, a) for name, a in recovered]
        if m.start() > 0:
            # A clean prefix survives before the framing: truncate the primary's
            # value to it, fold in any leaked sibling params (without clobbering
            # an existing key), and append the recovered separate calls.
            new_args = dict(args)
            new_args[k] = v[:m.start()].rstrip().strip('"').strip("'")
            for sk, sv in sibling.items():
                new_args.setdefault(sk, sv)
            primary = {**tc, "function": {**fn, "arguments": json.dumps(new_args)}}
            return primary, recovered_tcs
        # m.start() == 0: the value is ENTIRELY framing (no clean prefix). The
        # native parser dumped the whole merged reply into this one argument.
        if recovered_tcs:
            # The primary call is a phantom whose real content IS the first
            # recovered call — promote it rather than dispatch raw tag-soup
            # (that struck as an invalid-arg failure — seen live on file_system).
            return recovered_tcs[0], recovered_tcs[1:]
        # Only leaked sibling params, no recovered call, no clean prefix: attach
        # them to the primary (dropping the tag-soup value for this key).
        new_args = {kk: vv for kk, vv in args.items() if kk != k}
        for sk, sv in sibling.items():
            new_args.setdefault(sk, sv)
        return {**tc, "function": {**fn, "arguments": json.dumps(new_args)}}, []
    return tc, []


def _repair_native_tool_calls(tool_calls: list, available_names=None):
    """Repair upstream native ``tool_calls`` corrupted by the server's own
    multi-call XML parser. Returns ``(new_tool_calls, repaired: bool)``.
    Clean calls pass through byte-for-byte."""
    out, repaired = [], False
    for tc in (tool_calls or []):
        primary, extras = _repair_one_native_tool_call(tc, available_names)
        out.append(primary)
        out.extend(extras)
        # A repair happened if we recovered extra calls OR rewrote the primary
        # (the pure-framing "phantom" case promotes a recovered call in place,
        # with no extras).
        if extras or primary is not tc:
            repaired = True
    return out, repaired


# ============================================================================
# <think> STRIPPING
# ----------------------------------------------------------------------------
# A single lazy regex `<think>.*?(?:</think>|(?=<tool_call|function)|$)` was
# used to strip reasoning blocks before tool-call parsing. The `(?=<tool_call>)`
# alternation exists for the pathological case where the model opens `<think>`
# and runs straight into a REAL tool call without ever emitting `</think>`.
# But with a lazy `.*?`, that lookahead also fires on a `<tool_call>` merely
# MENTIONED inside the reasoning — e.g. the model quoting the guidance
# "emit exactly one `<tool_call>` per turn". It cut the block at the quoted
# mention, leaving `<tool_call>` per turn.\n\n</think>\n<tool_call>…` as the
# parse target, which the tool parser then mis-read as a malformed call →
# `system_parse_error`, a wasted turn, and an execution strike (seen recurring
# in the live log on coding tasks). The fix PREFERS a real `</think>`: closed
# blocks are removed whole (a quoted `<tool_call>` inside them can no longer
# truncate anything), and only a genuinely UNCLOSED `<think>` is stripped up
# to the first real tool-call opening (wrapped `<tool_call><function>` or a
# named `<function …>`), never a bare quoted mention.
# ============================================================================
# `<thinking>` too (§4IU R2, probe-b83968f4): the model wrote a
# `<thinking>…</thinking>` preamble and `\b` after "think" let it through to
# the user — the stream gate (`_inline_think_open`) already matched the
# prefix, the strip did not.
# `(?<!\x60)`: a backtick-quoted mention ("emits `<thinking>` blocks") is prose
# about the tag, not a block (fresh-eye review §4IX: the widened tag ate the
# rest of every prompt-engineering answer). The unclosed shape must OPEN a
# line — a mid-sentence "<thinking> tags" is a mention too.
_THINK_CLOSED_RE = re.compile(r'(?<!\x60)<think(?:ing)?\b[^>]*>(?:(?!<think(?:ing)?\b).)*?</think(?:ing)?\s*>', re.DOTALL | re.IGNORECASE)   # never from a mention to a later block's closer (§4IY)
# The unclosed-think lookahead must also recognize the LESIONED opener
# shape `<tool_call>function=…` (dropped '<', req 65d8cf76) — otherwise
# the strip-to-EOS branch swallows the whole call silently (no strike,
# no recovery hint, an empty turn) whenever the lesion follows an
# unclosed <think>. The lesion alternative mirrors the parser heal's
# exact condition (`function…=`), so a bare prose mention of
# "<tool_call> function" cannot anchor it.
_THINK_UNCLOSED_RE = re.compile(
    r'(?:(?<=\n)|\A)[ \t]*(?<!\x60)<think(?:ing)?\b[^>]*>.*?(?=<tool_call\b[^>]*>\s*<function\b'
    r'|<tool_call\b[^>]*>\s*function(?:_name)?\s*(?:=|\s+name\s*=)'
    r'|<function\s+name\b|<function\s*=)'
    r'|(?:(?<=\n)|\A)[ \t]*(?<!\x60)<think(?:ing)?\b[^>]*>.*$',
    re.DOTALL | re.IGNORECASE,
)
_FENCE_SPAN_RE = re.compile(r"```.*?```", re.DOTALL)
# An ORPHAN close (live 2026-09-29, probe-f6): the chat template opens the think
# block in the prompt, so a turn's content can carry reasoning that ends in a bare
# `</think>` — "…Let me look it up.\n</think>\n\nI cannot…". In every leak on record
# (3 of 3,232 final replies) the tag stands at the START of its own line followed by
# a blank line; prose ("closes with </think>", "- close: </think>"), an indented code
# line, or a reply that merely ENDS with the tag never has that shape. Applied to the USER-VISIBLE text only, after the
# tool-call markup is scrubbed — never to the parser's target (§4KN review).
_THINK_ORPHAN_CLOSE_RE = re.compile(
    r'\A.*?(?:\A|\n)</think(?:ing)?[ \t]*>[ \t]*\r?\n[ \t]*\r?\n',
    re.DOTALL | re.IGNORECASE)
# On a call turn the visible text may END with the tag (nothing after it but the
# scrubbed call) — the one place the end of the text also counts.
_THINK_ORPHAN_CLOSE_AT_END_RE = re.compile(
    r'\A.*?(?:\A|\n)</think(?:ing)?[ \t]*>\s*\Z', re.DOTALL | re.IGNORECASE)
_TILDE_FENCE_SPAN_RE = re.compile(r"~~~.*?~~~", re.DOTALL)

def _head_insert_below_start_with(block: str, reply: str, sw_active_phrase) -> str:
    """§4EC — the `_head_insert` closure of `_finalize_and_return`, extracted so
    its fence walk is a PURE function with an input-space table
    (tests/test_4ec_head_insert.py). Finalize-added material (verifier note,
    clarify question, digests, deferred correction) goes at the head of the
    reply — unless an active start-with constraint leads it (§4BZ R1 A-F2), in
    which case it goes AFTER the phrase-led first segment, never inside a code
    fence (§4BZ R2 M-1, R3 B-D3): the first paragraph break outside any fence;
    else the first line break when the reply has no fences at all; else it is
    appended below a `---` rule (a reply that is one fenced block, or ends
    inside a fence, takes a plain prepend)."""
    if not block:
        return reply
    if not sw_active_phrase:
        return block + reply
    if len(_FENCE_MARK_RE.findall(reply)) % 2 == 1:
        return block + reply
    _cut = reply.find("\n\n")
    while _cut != -1 and len(
            _FENCE_MARK_RE.findall(reply[:_cut])) % 2 == 1:
        # an odd count before `_cut` with an even total means a closing
        # mark ALWAYS exists after it — no `is None` arm (§4EC R2 review:
        # the old closure's arm was unreachable)
        _fm = _FENCE_MARK_RE.search(reply, _cut)
        _cut = reply.find("\n\n", _fm.end())
    if _cut != -1:
        _cut += 2
        return reply[:_cut] + block + reply[_cut:]
    _cut = reply.find("\n")
    if _cut != -1 and not _FENCE_MARK_RE.search(reply):
        _cut += 1
        return reply[:_cut] + "\n" + block + reply[_cut:]
    _tail = block
    if _tail.endswith("\n\n---\n\n"):
        _tail = _tail[:-len("\n\n---\n\n")]
    return reply.rstrip() + "\n\n---\n\n" + _tail


_CDATA_RE = re.compile(r'<!\[CDATA\[(.*?)\]\]>', re.DOTALL)


def _mask_cdata(text):
    """§4EC F1/F2 — replace every `<![CDATA[body]]>` span with an opaque token.

    The tool-call parser's structural regexes (the <tool_call> block split,
    the truncation counters, Formats 1-5b, the bare-tag harvester) all run
    over ONE working copy of the assistant text. CDATA bodies are opaque by
    contract (prompts.py CDATA ESCAPE HATCH: "literal </parameter>, <, >,
    JSON…"), so they leave that copy BEFORE any regex sees it and come back
    into the extracted argument values at the parser's single exit
    (`_unmask_cdata_calls`). Returns (masked_text, {token: body}). Tokens are
    per-call random (a body cannot forge one) and contain no `<>{}"` or
    whitespace, so no structural regex can match inside them.
    """
    if not text or "<![CDATA[" not in text:
        return text, {}
    salt = uuid.uuid4().hex[:8]
    tokens = {}

    def _sub(m):
        tok = f"CDATA-{salt}-{len(tokens)}-ATADC"
        tokens[tok] = m.group(1)
        return tok

    return _CDATA_RE.sub(_sub, text), tokens


def _unmask_value(v, tokens):
    if isinstance(v, str):
        for tok, body in tokens.items():
            if tok in v:
                v = v.replace(tok, body)
        return v
    if isinstance(v, dict):
        return {k: _unmask_value(x, tokens) for k, x in v.items()}
    if isinstance(v, list):
        return [_unmask_value(x, tokens) for x in v]
    return v


def _unmask_cdata_calls(tool_calls, tokens):
    """Restore CDATA bodies inside every parsed call's arguments (the JSON
    string form the parser emits, or a dict). No-op without tokens."""
    if not tokens:
        return tool_calls
    out = []
    for tc in tool_calls:
        fn = (tc or {}).get("function") or {}
        args = fn.get("arguments")
        # The parser's contract: `arguments` is ALWAYS a JSON string (every
        # append site json.dumps it). A non-JSON string cannot carry a token
        # (tokens are minted inside the JSON-bearing text), so the only work
        # is parse → restore → dump. (§4EC fix battery: the former dict/list
        # and raw-string arms were unreachable and are gone.)
        if isinstance(args, str):
            try:
                parsed = json.loads(args)
            except Exception:
                parsed = None
            if isinstance(parsed, (dict, list)):
                fn = dict(fn, arguments=json.dumps(_unmask_value(parsed, tokens)))
        out.append(dict(tc, function=fn))
    return out


# §4KO: the RAW text of a streamed final (record, retry base, verifier claim, a
# persisted session) still holds call markup and inline <think> blocks, so the
# visible-text rule cannot run on it. This one cuts only a PURE-PROSE prefix: no
# call opener, no think opener, no fence before the orphan close (leaked reasoning
# always comes first and is plain prose). The close is followed by a blank line,
# or — the call-turn shape — directly by a call opener.
_RAW_ORPHAN_CLOSE_RE = re.compile(
    r'\A(.*?)(?:\A|\n)</think(?:ing)?[ \t]*>[ \t]*'
    r'(?:\r?\n[ \t]*\r?\n|\r?\n(?=[ \t]*<(?:tool_call\b|tool\b|function\b)))',
    re.DOTALL | re.IGNORECASE | re.ASCII)          # ASCII `\b`, as in the JS mirror
_RAW_PREFIX_NOT_PROSE_RE = re.compile(r'<(?:tool_call|tool|function|think)\b|```|~~~',
                                      re.IGNORECASE | re.ASCII)


def strip_raw_orphan_reasoning(text: str) -> str:
    """§4KO: ``text`` without a leaked pure-prose reasoning prefix that ends in
    an orphan `</think>`; unchanged whenever the prefix is anything but prose."""
    if not isinstance(text, str) or '</think' not in text.lower():
        return text
    m = _RAW_ORPHAN_CLOSE_RE.match(text)
    if not m or _RAW_PREFIX_NOT_PROSE_RE.search(m.group(1)):
        return text
    return text[m.end():]


def _strip_orphan_think_close(text: str, *, call_turn: bool = False) -> str:
    """§4KN: the user-visible text without reasoning that ends in an orphan
    `</think>` (at the start of its own line, then a blank line). ``` and ~~~
    fences are shielded; a raw-JSON body and text without the tag are
    returned unchanged."""
    if (not isinstance(text, str) or '</think' not in text.lower()
            or text.lstrip().startswith("{")):          # a raw-JSON call is not prose
        return text
    fences: list = []

    def _shield(m):
        fences.append(m.group(0))
        return f"\x00FENCE{len(fences) - 1}\x00"
    shielded = _TILDE_FENCE_SPAN_RE.sub(_shield, _FENCE_SPAN_RE.sub(_shield, text))
    out = _THINK_ORPHAN_CLOSE_RE.sub('', shielded, count=1)
    if call_turn and out == shielded:
        out = _THINK_ORPHAN_CLOSE_AT_END_RE.sub('', shielded, count=1)
    for i in range(len(fences) - 1, -1, -1):          # outer shields hold inner ones
        out = out.replace(f"\x00FENCE{i}\x00", fences[i])
    return out


def _strip_think_blocks(text: str) -> str:
    """Remove `<think>…</think>` reasoning, preferring the real close tag so a
    quoted `<tool_call>` mention inside the reasoning can't truncate the block
    (see block comment). Handles an unclosed `<think>` by stripping to the
    first real tool-call opening or EOS. Returns the input unchanged when there
    is no think block (cheap fast-path). An orphan `</think>` is NOT handled here
    — this also strips the parser's target, where a call's own content may hold
    the tag; see `_strip_orphan_think_close` for the user-visible text."""
    if not isinstance(text, str) or '<think' not in text.lower():
        return text
    # a block written inside a ``` fence is documentation (review §4IY): shield the fences,
    # strip, then restore them
    fences: list = []
    def _shield(m):
        fences.append(m.group(0))
        return f"\x00FENCE{len(fences) - 1}\x00"
    text = _FENCE_SPAN_RE.sub(_shield, text)
    text = _THINK_CLOSED_RE.sub('', text)
    if '<think' in text.lower():
        text = _THINK_UNCLOSED_RE.sub('', text)
    for i, f in enumerate(fences):
        text = text.replace(f"\x00FENCE{i}\x00", f)
    return text


# Tool-call XML shapes the retry-history scrub must cover. This set must
# stay a SUPERSET of the shapes the parser can strike out on — the parser
# heals `<tool>` and `<function_name…` into parseable forms, so a
# parse-FAILING emission can arrive in any of them (review catch: the
# first cut only matched `<tool_call`/`<function`, so a failed `<tool>`
# hallucination was replayed verbatim — the exact imitation loop this
# scrub exists to kill). `(?<!\x60)` skips backtick-quoted mentions:
# retry turns routinely QUOTE `<tool_call>` from the SYSTEM ERROR hint
# while reasoning about it, and eating the surrounding analysis throws
# away legitimate prose (observed live 2026-08-01). NB `<tool\b` cannot
# match `<tool_call`/`<tool_response` — `_` is a word char, no boundary.
_SCRUB_TOOL_XML_RES = (
    re.compile(r'(?<!`)<tool_call\b.*?(?:</tool_call\s*>|\Z)', re.DOTALL | re.IGNORECASE),
    re.compile(r'(?<!`)<tool\b[^>]*>.*?(?:</tool\s*>|\Z)', re.DOTALL | re.IGNORECASE),
    re.compile(r'(?<!`)<function(?:_name)?\b.*?(?:</function\s*>|\Z)', re.DOTALL | re.IGNORECASE),
)


def _scrub_unparsed_tool_call_text(text: str, reason: str = "") -> str:
    """Replace tool-call XML in an assistant message that failed to parse
    with a short bracketed note, before the message is replayed into the
    retry history.

    Why: replaying the malformed block verbatim TEACHES the model its own
    mistake — req 65d8cf76 (2026-08-01) emitted one lesioned call
    ('<tool_call>function=…', dropped '<'), the raw text was replayed as
    the assistant turn, and the model then copied the exact broken shape
    on every retry (temp 0.6 imitation beat four recovery hints) until
    the strike cap aborted the request. The next-turn SYSTEM ERROR
    message carries the correct format; the history only needs to record
    THAT a call was attempted, not preserve the broken bytes.

    The CALLER must gate on an actual parse failure (a
    `system_parse_error` entry in the parsed tool_calls) — the reason
    string alone is not enough: "truncated" is stamped by pre-parse
    open/close counting and can accompany a fully parsed and EXECUTED
    call, and scrubbing that would tell the model to re-emit a mutation
    that already ran (review catch).

    Output is HARD-bounded: only the first ``_SCRUB_MAX_NOTES`` regions
    become notes, every further region is deleted outright — a
    degenerate thousand-block reply (the 4056-strike trace shape) must
    shrink, not amplify, in the retry path. Replacement is a callable,
    so no character of `note`/`reason` is ever interpreted as a regex
    template (a '\\1' in a future reason string would otherwise crash
    the replay).
    """
    if not isinstance(text, str) or not text:
        return text
    note = "[malformed tool_call removed — it did not parse"
    if reason:
        note += f" ({reason})"
    note += "; re-emit it in the format shown in the SYSTEM ERROR below]"
    _SCRUB_MAX_NOTES = 2
    emitted = 0

    def _repl(_m):
        nonlocal emitted
        emitted += 1
        return note if emitted <= _SCRUB_MAX_NOTES else ""

    out = text
    for pat in _SCRUB_TOOL_XML_RES:
        out = pat.sub(_repl, out)
    # Collapse adjacent duplicate notes (multi-block failures) so the
    # replayed message doesn't repeat the note.
    out = re.sub(
        re.escape(note) + r'(?:\s*' + re.escape(note) + r')+',
        lambda _m: note, out,
    )
    return out.strip()


def _tool_call_format_example(native: bool, param: str = "arg1", value: str = "value1") -> str:
    """The tool-call skeleton to show in parse-failure recovery hints.

    Path-aware on purpose: the native path's server template
    (froggeric-v21.3) teaches and parses the EQUALS dialect
    (`<function=name>` / `<parameter=key>` with values on their own
    lines) — teaching attribute-style `<function name="…">` there
    re-introduces the dual-dialect corruption root-caused on
    2026-07-31 ("the agent was teaching a second dialect"), and it
    demonstrably failed to break the req 65d8cf76 retry loop. The
    legacy XML path keeps attribute style — its QWEN_TOOL_PROMPT
    contract. Both dialects parse in the agent's fallback parser; the
    point is to show the model ONE dialect: the one its own prompt
    path already speaks.
    """
    if native:
        return (
            "<tool_call>\n<function=the_tool_name>\n"
            f"<parameter={param}>\n{value}\n</parameter>\n"
            "</function>\n</tool_call>"
        )
    return (
        "<tool_call>\n  <function name=\"the_tool_name\">\n"
        f"    <parameter name=\"{param}\">{value}</parameter>\n"
        "  </function>\n</tool_call>"
    )


# ============================================================================
# ARCHITECTURAL OPTIMISATION #7: TOOL-SCHEMA CACHE
# ----------------------------------------------------------------------------
# `_json_to_xml_schema` used to be defined and executed inside the turn loop
# (one fresh string-build per turn even when the tool list was identical).
# These module-level helpers hoist the conversion out and memoize it on a
# stable signature of the (frozen) function definitions.
# ============================================================================
def _freeze_funcs(funcs: list) -> tuple:
    """Convert a list of mutable tool function dicts into a hashable tuple
    of immutable views suitable for `lru_cache` keys."""
    out = []
    for f in funcs:
        params = f.get("parameters") or {}
        properties = params.get("properties") or {}
        required = tuple(sorted(params.get("required") or []))
        prop_items = []
        for p_name, p_data in properties.items():
            enum_val = p_data.get("enum")
            prop_items.append((
                p_name,
                p_data.get("type", "string"),
                p_data.get("description", ""),
                tuple(enum_val) if isinstance(enum_val, list) else (),
            ))
        out.append((
            f.get("name", ""),
            f.get("description", ""),
            tuple(prop_items),
            required,
        ))
    return tuple(out)


def _xml_schema_key(tool_defs: list) -> str:
    """Stable cache key from a list of {function: {...}} dicts."""
    names = sorted(t.get("function", {}).get("name", "") for t in tool_defs)
    return "|".join(names)


import functools as _ft


@_ft.lru_cache(maxsize=128)
def _json_to_xml_schema_cached(frozen_funcs: tuple) -> str:
    """Memoized XML-schema serialiser. Keyed on the frozen tuple produced
    by `_freeze_funcs`. The output is deterministic per tool list, so a
    cache hit means zero string concatenation per turn.

    Uses REAL newlines (``\\n``) between XML elements, not the
    two-character escape sequence ``\\\\n`` that the previous version
    accidentally shipped. Literal ``\\n`` strings inflate the tokenizer
    output (one extra token per occurrence) and add zero information —
    with 21 tools and ~10 newlines each, that was ~210 wasted tokens
    per coding turn on top of whatever gain cache_prompt delivers.
    """
    parts = []
    for name, description, prop_items, required in frozen_funcs:
        parts.append(f'<tool_def>\n<function name="{name}">\n')
        if description:
            parts.append(f'<description>{description}</description>\n')
        if prop_items:
            for p_name, p_type, p_desc, p_enum in prop_items:
                is_req = "true" if p_name in required else "false"
                parts.append(f'<parameter name="{p_name}" type="{p_type}" required="{is_req}">\n')
                if p_desc:
                    parts.append(f'<description>{p_desc}</description>\n')
                if p_enum:
                    parts.append(f'<enum>{", ".join(p_enum)}</enum>\n')
                parts.append('</parameter>\n')
        parts.append('</function>\n</tool_def>\n')
    return "".join(parts).strip()

def _is_think_tag_fragment(token: str, accumulated_with_token: str) -> bool:
    """Display-stream filter: is this streamed token a fragment of a
    literal ``<think>`` / ``</think>`` tag (arriving split across
    chunks), rather than prose?

    The old check dropped ANY token whose stripped form was "think" or
    ">" — which deleted the literal word "think" from every rendered
    thought ("Let me think about…" rendered as "Let me about…", observed
    consistently in production logs; the model emits " think" as its own
    token). A bare "think"/"think>"/">" token is only a tag fragment
    when the stream immediately before it ends with the matching tag
    opener, so the check is now contextual: `accumulated_with_token` is
    the stream INCLUDING this token (both call sites append before
    filtering).

    This filter is cosmetic-only — it gates what `_emit_thinking` shows
    the operator; the accumulated content is never modified.
    """
    t = token.strip().lower()
    if t in ("<", "</", "<think", "<think>", "</think", "</think>"):
        return True
    if token.lower() != t:
        # Surrounding whitespace → can't be part of a contiguous tag.
        return False
    before = accumulated_with_token[: len(accumulated_with_token) - len(token)]
    if t in ("think", "think>"):
        return before.endswith(("<", "</"))
    if t == ">":
        return before.lower().endswith(("<think", "</think"))
    return False


class ThinkTagDisplayFilter:
    """Stateful front of `_is_think_tag_fragment` for ONE displayed stream.

    §4KS: the per-token rule drops every lone ``<`` / ``</`` as a possible
    tag opener — but whether it opens a tag is only known from the NEXT
    token. The model emits `` <`` as its own token in ordinary reasoning, so
    "x < 71" was logged as "x 71" and "value < 0" as "value 0" (2026-09-30,
    three of three uses). The opener is HELD for one token: dropped when the
    next token continues a think tag, shown when it does not. Display-only,
    like the rule it fronts: the accumulated stream is never touched.
    """

    _OPENERS = ("<", "</")
    _CONTINUATIONS = ("think", "think>")

    def __init__(self):
        self._held = ""

    def feed(self, token: str, accumulated_with_token: str) -> str:
        """The text to DISPLAY for this token ('' to show nothing yet)."""
        t = token.strip().lower()
        if t in self._OPENERS:
            # a second opener releases the first ("a < < b")
            out, self._held = self._held, token
            return out
        held, self._held = self._held, ""
        if _is_think_tag_fragment(token, accumulated_with_token):
            # the held opener belonged to this tag only when the token
            # CONTINUES one; a whole tag token ("<think>") stands alone
            return "" if t in self._CONTINUATIONS else held
        return held + token

    def flush(self) -> str:
        """The opener still held when the stream ends (it opened nothing)."""
        out, self._held = self._held, ""
        return out


def _scan_json_braces(t: str) -> int:
    """Opens minus closes, counting only braces OUTSIDE string literals.

    A brace inside a value (`"desc": "use {this}"`) must not register, or a
    complete object reads as truncated and vice versa.
    """
    depth = 0
    in_str = False
    esc = False
    for ch in t or "":
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
    return depth


def _unclosed_braces(t: str) -> int:
    """How many `{` were never closed by a string-aware scan. >0 means the
    text was cut off — OR that a stray quote inside a string desynced the
    scan; ``_ends_like_closed_json`` tells the two apart."""
    return max(0, _scan_json_braces(t))


_CLOSING_FENCE_RE = re.compile(r"\s*```\s*$")


def _ends_like_closed_json(t: str) -> bool:
    """True when the text's last non-blank character (ignoring a trailing
    code fence) is `}` or `]` — the shape of an object that was finished,
    whatever the brace scan says about it."""
    tail = _CLOSING_FENCE_RE.sub("", (t or "").rstrip())
    return tail.rstrip().endswith(("}", "]"))


_INLINE_CODE_RE = re.compile(r'`[^`\n]+`')


def _has_bare_json_braces(t: str) -> bool:
    """Braces that are NOT inside an inline code span.

    The discriminator between "this reply contains JSON that failed to parse"
    and "this reply is prose that mentions braces". ⚠ A QUOTED-KEY test was
    tried first and was WRONG: `{ thought: missing-quotes, next_action_id:
    !!! }` — a model emitting the plan with unquoted keys — is a genuine
    malformation worth warning about, and it is structurally identical to
    `{ z-index: 1001 }`. Nothing inside the braces separates them; the
    CONTEXT does. Both live false positives were CSS inside backticks
    (``#session-modal.modal-overlay { z-index: 1001 }``), where the span
    starts well before the brace — so mask the span, not the brace.

    Fenced ```json blocks are deliberately NOT masked: a fence is an explicit
    claim that JSON follows, and one that fails to parse is exactly the
    warning this exists for.
    """
    return '{' in _INLINE_CODE_RE.sub('', t or "")


def _repair_truncated_json(t: str) -> dict:
    """Best-effort parse of a JSON object cut off mid-generation.

    Strategy per attempt: close an unterminated string, drop a trailing
    comma, complete a dangling ``"key":`` with ``null``, append the
    missing closers, and parse. On failure, chop back to the previous
    comma/opener and retry (bounded). Returns ``{}`` when nothing
    salvageable remains — same contract as ``extract_json_from_text``.
    """
    import json
    cur = (t or "").strip()
    for _ in range(8):
        if not cur or cur[0] != '{':
            return {}
        stack = []
        in_str = False
        esc = False
        for ch in cur:
            if in_str:
                if esc:
                    esc = False
                elif ch == '\\':
                    esc = True
                elif ch == '"':
                    in_str = False
            else:
                if ch == '"':
                    in_str = True
                elif ch in '{[':
                    stack.append(ch)
                elif ch in '}]':
                    if stack:
                        stack.pop()
        cand = cur + ('"' if in_str else '')
        cand = re.sub(r'[\s,]+$', '', cand)
        if cand.endswith(':'):
            cand += ' null'
        cand += ''.join('}' if op == '{' else ']' for op in reversed(stack))
        try:
            res = json.loads(cand, strict=False)
            if isinstance(res, dict):
                return res
        except json.JSONDecodeError:
            pass
        cut = max(cur.rfind(','), cur.rfind('{'), cur.rfind('['))
        if cut <= 0:
            return {}
        cur = cur[:cut]
    return {}


def extract_json_from_text(text: str, repair_truncated: bool = False) -> dict:
    """Safely extracts JSON from LLM outputs, ignoring conversational filler and markdown blocks.

    Returns ``{}`` on every failure mode (missing JSON, malformed JSON, etc.)
    — the empty-dict contract is load-bearing for the dozens of call sites
    that do `result = extract_json_from_text(...).get("score", 0)` style
    access.

    ``repair_truncated=True`` additionally salvages objects cut off at a
    max_tokens cap (see ``_repair_truncated_json``). It is OPT-IN and must
    only be set on background extraction paths (memory consolidation,
    graph triplets, judges) where a partial result beats none. NEVER set
    it when parsing tool-call ARGUMENTS: repairing a truncated
    ``{"path": …, "content": …`` would execute the tool with half its
    payload instead of triggering the parse-error retry loop.

    Distinguishing "no JSON present" from "JSON was malformed" is useful for
    debugging the planner / smart memory / post-mortem flows. We log a
    WARNING (not DEBUG) when the input clearly *contained* something that
    looked like JSON but could not be parsed, so the operator notices
    silent extraction failures in production logs.
    """
    import re, json, ast
    # Contract: return {} on EVERY failure mode. A non-str input (e.g. a
    # backend that returned `content: null`) must not raise out of the
    # re.sub below, which runs before the try/except guard.
    if not isinstance(text, str):
        return {}
    # Qwen Syntax Healing: Fix {"name"="tool"...} or {"name"= "tool"...} hallucinations.
    # Also heal `"key"=` → `"key":` for ANY field, not just `name` (the previous
    # version only fixed the `name` field).
    text = re.sub(r'(?<=[{,\s])"([\w_]+)"\s*=\s*', r'"\1": ', text)

    # Match a quoted string literal OR a bare JSON keyword. Strings are the
    # first alternative, so a `true`/`false`/`null` INSIDE a string is
    # consumed as part of the string match and never rewritten — the old
    # `\btrue\b` sweep corrupted keyword-like words inside value strings
    # despite the comment claiming otherwise.
    _JSON_KW_RE = re.compile(
        r'''"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?P<kw>true|false|null)\b'''
    )
    _KW_MAP = {"true": "True", "false": "False", "null": "None"}

    def _kw_sub(m):
        kw = m.group("kw")
        return _KW_MAP[kw] if kw is not None else m.group(0)

    def _parse(t):
        try:
            return json.loads(t, strict=False)
        except json.JSONDecodeError:
            try:
                # AST Fallback for models that output Python dicts instead of
                # strict JSON. Only the standalone keywords are rewritten;
                # occurrences inside string literals are left intact.
                pt = _JSON_KW_RE.sub(_kw_sub, t)
                res = ast.literal_eval(pt)
                if isinstance(res, dict): return res
            except Exception as e:
                logger.debug(f"JSON AST fallback failed: {type(e).__name__}")
            return {}

    looked_like_json = False
    try:
        match = re.search(r'```(?:json)?\s*(\{.*?\})\s*```', text, re.DOTALL | re.IGNORECASE)
        if match:
            looked_like_json = True
            p = _parse(match.group(1))
            if p:
                return p

        start = text.find('{')
        end = text.rfind('}')
        if start != -1:
            # An opening brace alone counts: output truncated at max_tokens
            # often has NO closing brace, and the old `end != -1` gate
            # skipped exactly those.
            looked_like_json = True
            if end > start:
                p = _parse(text[start:end + 1])
                if p:
                    return p

        result = _parse(text)
        if not result and repair_truncated and start != -1:
            # TRUNCATION REPAIR (opt-in): background consolidation calls
            # can hit their max_tokens cap mid-object. Salvage every
            # complete key/value pair instead of dropping the extraction.
            repaired = _repair_truncated_json(text[start:])
            if repaired:
                logger.info("extract_json_from_text: salvaged truncated JSON "
                            f"({len(repaired)} top-level keys)")
                return repaired
        if not result and looked_like_json:
            # We saw braces but couldn't parse them. ⚠ TWO REFINEMENTS,
            # 2026-08-11, after this line sent a reader hunting a parser bug
            # that did not exist (req 6e9efd6a: 7 of these in one request).
            #
            # (1) BRACES ARE NOT EVIDENCE OF JSON. The gate was `'{' in text`,
            #     so a prose reply quoting a CSS rule — `#session-modal
            #     { z-index: 1001 }` — logged a WARNING about malformed JSON
            #     when the turn's real payload rode `tool_calls` and no JSON
            #     was ever intended. A quoted key is the cheap discriminator.
            # (2) TRUNCATED IS NOT MALFORMED. The other 7 were the model cut
            #     off at max_tokens mid-object; "malformed" describes a syntax
            #     error and points the reader at the parser instead of at the
            #     token budget that actually failed. Unbalanced braces name it.
            preview = text[:200].replace("\n", " ")
            if not _has_bare_json_braces(text):
                logger.debug("extract_json_from_text: braces appear only "
                             "inside inline code spans — prose, not JSON. "
                             f"Preview: {preview}")
            elif _unclosed_braces(text) > 0 and _ends_like_closed_json(text):
                # (3) UNBALANCED IS NOT TRUNCATED EITHER (2026-09-03, §4EI).
                #     Four retry outputs in request 463111ad ended with
                #     `"ledger":"…"}` + a closing fence, the server reported
                #     truncated=0, and this branch still printed "cut off at
                #     max_tokens" — sending the reader to the token budget
                #     when the defect was inside a string. A text that ENDS
                #     with `}` was not cut; its brace count is off because a
                #     quote/escape inside a string desynced the scan.
                logger.warning(
                    "extract_json_from_text: UNBALANCED JSON — "
                    f"{_unclosed_braces(text)} unclosed brace(s) by a "
                    f"string-aware scan of {len(text)} chars that END with a "
                    f"closing brace: a quote or escape inside a string most "
                    f"likely desynced the scan. This is NOT a max_tokens cut — "
                    f"inspect the raw output (coding_executor keeps rejected "
                    f"specs under $GHOST_HOME/system/coding_executor_failures/). "
                    f"Preview: {preview}")
            elif _unclosed_braces(text) > 0:
                logger.warning(
                    "extract_json_from_text: TRUNCATED JSON — "
                    f"{_unclosed_braces(text)} unclosed brace(s), {len(text)} "
                    f"chars. The generation was cut off (check max_tokens / "
                    f"finish_reason), NOT a parser fault. "
                    f"Preview: {preview}")
            else:
                logger.warning(f"extract_json_from_text: malformed JSON-like content failed to parse. Preview: {preview}")
        return result
    except Exception as e:
        logger.warning(f"extract_json_from_text raised {type(e).__name__}: {e}")
        return {}


_CODING_KEYWORDS = [r"\bpython\b", r"\bbash\b", r"\bsh\b", r"\bscript\b", r"\bcode\b", r"\bdef\b", r"\bimport\b", r"\bhtml\b", r"\bcss\b", r"\bjs\b", r"\bjavascript\b", r"\btypescript\b", r"\breact\b", r"\bweb\b", r"\bfrontend\b"]
_CODING_ACTIONS = [r"\bwrite\b", r"\brun\b", r"\bexecute\b", r"\bdebug\b", r"\bfix\b", r"\bcreate\b", r"\bgenerate\b", r"\bcount\b", r"\bcalculate\b", r"\banalyze\b", r"\bscrape\b", r"\bplot\b", r"\bgraph\b", r"\bbuild\b", r"\bdevelop\b"]
_DBA_KEYWORDS = [r"\bsql\b", r"\bpostgres\b", r"\bpostgresql\b", r"\bpsql\b", r"\bdatabase\b", r"\bpg_stat\b", r"\bexplain analyze\b", r"\bquery\b", r"\bcte\b", r"\brdbms\b", r"\bdba\b", r"\bschema\b", r"\bvacuum\b", r"\bmvcc\b"]
_META_KEYWORDS = [r"\btitle\b", r"\bname this\b", r"\brename\b", r"\bsummary\b", r"\bsummarize\b", r"\bcaption\b", r"\bdescribe\b"]
# Pushback markers for the follow-up inheritance rule below. Deliberately
# narrow: questions ("why did you…") and acknowledgements must NOT match.
_CORRECTION_MARKERS = [
    r"\bwrong\b", r"\bincorrect\b", r"\bnot optimal\b", r"\bmistake\b",
    r"\bbroken\b", r"\bdoesn'?t work\b", r"\bnot working\b",
    r"\byou forgot\b", r"\byou(?:'re| are) not using\b",
]


def detect_coding_intent(lc: str, messages: Optional[List[Dict]] = None) -> tuple:
    """Classify the current user turn: ``(has_coding_intent, is_meta_task)``.

    `lc` is the lowercased last user message. `messages` (the full chat
    history) powers the FOLLOW-UP INHERITANCE rule: a correction of a
    prior coding/SQL answer ("that is wrong — the insert belongs after
    the swap") usually carries no coding keyword of its own, so it used
    to fall through to the conversational sampling profile (temp 1.0)
    and silently drop the specialist persona mid-task. If the user is
    pushing back and the previous assistant turn shipped a fenced code
    block, the turn stays in coding mode.
    """
    has_coding_intent = False
    if any(re.search(k, lc) for k in _CODING_KEYWORDS):
        if any(re.search(a, lc) for a in _CODING_ACTIONS):
            has_coding_intent = True
    if any(ext in lc for ext in [".py", ".js", ".html", ".css", ".ts", ".tsx", ".jsx", ".sh"]) or re.search(r'\bscript\b', lc):
        has_coding_intent = True
    # §4MO: a DBA word counts unless it only names a FILE
    # ("remove the ingested document postgresql-19-A4.pdf") or the message
    # is a moving-target LOOKUP ("what is the latest version of postgresql?")
    # — both loaded the long specialist persona: +8 s of prefill, no gain
    _dba_lc = re.sub(r"\S+\.(?:pdf|txt|md|csv|json|docx?|xlsx?|html?|zip|tar|gz)\b", " ", lc)
    if any(re.search(k, _dba_lc) for k in _DBA_KEYWORDS):
        try:
            from ..memory.episodes import is_moving_target_question as _mtq
            _lookup = _mtq(lc)
        except Exception:  # noqa: BLE001
            _lookup = False
        if not _lookup:
            has_coding_intent = True

    is_meta_task = any(re.search(k, lc) for k in _META_KEYWORDS)
    if re.match(r'^[\d\s\+\-\*\/\(\)\=\?]+$', lc):
        has_coding_intent = False

    if not has_coding_intent and not is_meta_task and messages:
        if any(re.search(k, lc) for k in _CORRECTION_MARKERS):
            prev_assistant = next(
                (m.get("content", "") for m in reversed(messages[:-1])
                 if isinstance(m, dict) and m.get("role") == "assistant"),
                "",
            )
            if isinstance(prev_assistant, str) and "```" in prev_assistant:
                has_coding_intent = True

    return has_coding_intent, is_meta_task


async def _timed_tool_coro(coro, sink: list, idx: int):
    """Await `coro`, writing its wall-clock duration into ``sink[idx]``.

    Lets the parallel tool-dispatch path capture a per-tool duration (for the
    trajectory row and the batch wall) without changing how results
    are gathered. Never lets the timing bookkeeping affect the result.
    """
    import time as _t
    _t0 = _t.monotonic()
    try:
        return await coro
    finally:
        try:
            sink[idx] = _t.monotonic() - _t0
        except Exception:
            pass


def _close_unstarted(coro) -> None:
    """Close a tool coroutine that a §4RZ step-5 stop keeps from starting,
    and the coroutines it wraps (`_stoppable_call` → `_timed_tool_coro` → the
    tool), so none is left "never awaited"."""
    try:
        fr = getattr(coro, "cr_frame", None)
        inner = [v for v in (fr.f_locals.values() if fr is not None else ()) if asyncio.iscoroutine(v)]
    except Exception:  # noqa: BLE001
        inner = []
    try:
        coro.close()
    except Exception:  # noqa: BLE001
        pass
    for v in inner:
        _close_unstarted(v)


async def _stoppable_call(idx: int, tool: str, coro, stop):
    """§4RZ step 5: one batch call under the batch's stop. Never starts once
    the stop is requested (an `_in_order` call still waiting on its
    predecessor, a file call after the one in progress); binds the stop for
    this call alone — its task and worker threads see it, the loop's own
    context never does; notes when the call really ran."""
    from ..utils import tool_stop as _ts
    if stop.requested():
        _close_unstarted(coro)
        return _ts.Interrupted(False)
    toks = _ts.bind_call(stop, idx)
    stop.enter(idx, tool)
    try:
        return await coro
    finally:
        stop.leave(idx)
        _ts.unbind_call(toks)


def _fallback_head_key(content, looks_failed: bool) -> str:
    """The empty-reply fallback's head for its last tool result: stopped by
    the user (§4RZ step 5), still running, failed, or success. The OBJECT,
    and the predicate that knows both UNRESOLVED producers —
    `is_promoted_result` is execute-only text, so a still-running swarm await
    was reported under the success head; a stopped call fell
    through to the same success head (s5-r3)."""
    try:
        from ..utils.tool_stop import is_user_interrupted
        if is_user_interrupted(content):
            return "stopped"
        from ..distill.outcome_heuristics import is_unresolved_tool_result
        if is_unresolved_tool_result(content):
            return "running"
    except Exception:  # noqa: BLE001
        pass
    return "failed" if looks_failed else "success"


async def _gather_stoppable(items, stop) -> list:
    """`gather(*coros, return_exceptions=True)` over ``[(idx, coro)]`` that a
    §4RZ step-5 tool stop can cut short: calls that finished keep their
    results; the rest are cancelled and come back as `tool_stop.Interrupted`.
    ``stop`` None (queued messages off) = exactly the plain gather."""
    coros = [c for _, c in items]
    if stop is None:
        return await asyncio.gather(*coros, return_exceptions=True)
    from ..utils import tool_stop as _ts
    if stop.requested():                     # stopped before this group began
        for c in coros:
            _close_unstarted(c)
        return [_ts.Interrupted(False) for _ in coros]
    tasks = [asyncio.ensure_future(c) for c in coros]
    stopped: set = set()
    try:
        pending = set(tasks)
        while pending and not stop.requested():
            _, pending = await asyncio.wait(pending, timeout=_ts.STOP_POLL_S)
        if pending:
            stopped = set(pending)
            for t in pending:
                t.cancel()
            _, late = await asyncio.wait(pending, timeout=_ts.STOP_GRACE_S)
            for t in late:                   # abandoned: still unwinding (a held lock)
                t.add_done_callback(lambda f: f.cancelled() or f.exception())
    except asyncio.CancelledError:           # the turn itself was cancelled: gather parity
        # §4SB: the stop first — cancelling the tasks never reaches a worker
        # thread's docker exec / yt-dlp / browser runner; only the killers do
        stop.request()
        for t in tasks:
            t.cancel()
        raise
    out = []
    for (idx, _), t in zip(items, tasks):
        if t in stopped or not t.done() or stop.hit(idx):
            # a call the stop reached is stopped, whatever it returned — one
            # that swallowed its cancel, one killed inside the poll gap
            # (its raw "stopped by the user" error), one that raised Cancelled
            out.append(_ts.Interrupted(stop.started(idx)))
        elif t.cancelled():
            out.append(asyncio.CancelledError())
        else:
            out.append(t.exception() if t.exception() is not None else t.result())
    return out


class GhostContext:
    def __init__(self, args, sandbox_dir, memory_dir, tor_proxy):
        self.args = args
        self.sandbox_dir = sandbox_dir
        self.memory_dir = memory_dir
        self.tor_proxy = tor_proxy
        self.llm_client = None
        self.memory_system = None
        self.profile_memory = None
        self.graph_memory = None
        self.skill_memory = None
        self.scratchpad = None
        self.sandbox_manager = None
        self.scheduler = None
        self.memory_bus = None
        self.biological_task = None
        self.last_activity_time = datetime.datetime.now()
        self.cached_sandbox_state = None
        # Long-term project state. `project_store` is lazily initialized by
        # main.py (or tests) so GhostContext itself stays cheap to
        # construct; `current_project_id` tracks which project the agent
        # is currently scoped to (None == free chat / one-shot mode).
        self.project_store = None
        self.current_project_id = None
        # Stage-1 self-improvement wiring. Populated by main.py during
        # lifespan when the corresponding features are enabled; left as
        # None otherwise so deployments without the trajectory pipeline
        # can run unchanged.
        self.trajectory_collector = None
        # Workspace continuity facade — world-model counterpart to
        # selfhood. Populated by main.py during lifespan; left as None
        # otherwise so callers that touch ``context.workspace_model``
        # before initialisation see a clean None rather than AttributeError.
        self.workspace_model = None
        # Most-recent user message for the current turn. Stashed by
        # handle_chat right after it extracts it from the request body so
        # tools can inspect user intent without re-parsing the message
        # list. Empty string when no user turn is in flight (e.g.
        # background tasks).
        self.last_user_content = ""
        # Metacog uplift bundle. None when ``--enable-metacog`` is off
        # (the default), keeping legacy behaviour unchanged. main.py's
        # lifespan populates it (the validator-block counter, §4PT).
        self.metacog = None

# Async-critic deferred-correction bounds (see _record_late_verdict /
# _consume_pending_corrections). The agent is a process-wide singleton, so
# these keep a late REFUTED verdict from one conversation leaking into an
# unrelated one and from accumulating without bound:
#   * MAX — hard cap on queued corrections (newest win) so a busy multi-
#     conversation process can't pile up a runaway banner chain.
#   * TTL — a correction that its OWN conversation never returns to consume is
#     dropped after this many seconds instead of lingering forever.
_CORRECTION_MAX = 3
_CORRECTION_TTL = 900.0  # seconds
#: §4LK: a correction BOUND to the answer it corrects (`|r<tag>`) cannot open
#: the wrong reply, so it can wait for the owner's next message in that chat —
#: the median gap was 21 min and 11 of 27 expired at 15 min
_CORRECTION_TTL_BOUND = 86400.0
_PENDING_CORRECTIONS_FILE = "pending_corrections.json"


def _correction_ttl(c) -> float:
    return _CORRECTION_TTL_BOUND if "|r" in str((c or {}).get("conv", "")) else _CORRECTION_TTL

# Promised-notification finish-line guard (2026-07-13, req 11fe11d8): the
# user asked "notify me in slack when you're done", the model PLANNED the
# notify_operator call in its reasoning, then emitted the final response
# without ever calling the tool — the one explicit delivery requirement in
# the request was silently dropped (and the verifier confirmed the turn:
# the deliverable itself was fine). These patterns detect an explicit
# notify-me ask in the USER text so the turn loop can steer once toward
# notify_operator before letting the final response ship. Kept narrow on
# purpose — a false fire injects a bogus SYSTEM ALERT into casual chat.
_NOTIFY_INTENT_RE = re.compile(
    # Direct ask: "notify me", "ping me", "alert me".
    r"\b(?:notify|ping|alert)\s+me\b"
    # Communication verb bound to a Slack destination within one clause:
    # "let me know / tell me / report back / update me / message me /
    # dm me … in|on|via|over slack". A bare "in slack" or "slack message"
    # deliberately does NOT match — questions ABOUT Slack ("how do I
    # format a slack message?") must not arm the guard.
    r"|\b(?:let\s+me\s+know|tell\s+me|report\s+back|update\s+me|"
    r"message\s+me|dm\s+me|write\s+me)\b[^.!?\n]{0,40}?"
    r"\b(?:in|on|via|over|through)\s+slack\b"
    # "send me a notification / dm / slack message".
    r"|\bsend\s+me\s+a\s+(?:notification|dm|slack\s+(?:message|dm|notification))\b",
    re.IGNORECASE,
)
_NOTIFY_NEGATION_RE = re.compile(
    r"\b(?:don'?t|do\s+not|no\s+need\s+to|without|stop)\s+"
    r"(?:notify(?:ing)?|ping(?:ing)?|alert(?:ing)?|messag(?:e|ing))",
    re.IGNORECASE,
)


_NOTIFY_CLAUSE_SPLIT_RE = re.compile(r"[.!?;\n]+|,?\s+\b(?:but|however|though|although|except)\b\s*",
                                     re.IGNORECASE)


def _user_asked_for_notification(user_text) -> bool:
    """True when the user's request explicitly asks for an out-of-band
    notification ("notify me in slack when you're done") and doesn't
    negate it ("don't notify me"). Long pasted documents are truncated
    before matching so an incidental 'slack' deep inside one can't arm
    the guard."""
    t = str(user_text or "")[:4000]
    if not t:
        return False
    # PER CLAUSE (§4LD): "Stop pinging me so often, but notify me when the
    # build is done" — a negation anywhere cancelled the real ask
    for clause in _NOTIFY_CLAUSE_SPLIT_RE.split(t):
        if _NOTIFY_INTENT_RE.search(clause) and not _NOTIFY_NEGATION_RE.search(clause):
            return True
    return False


_JOB_ID_RE = re.compile(r"\bjob-[0-9a-f]{6,12}\b")


def _launched_background_jobs(tools_run) -> list:
    """The job ids this turn's tool results report as STARTED (a command
    promoted to a background job). §4LD: a "notify me
    when it's done" turn that only LAUNCHED the work sent "Done — I've
    started the benchmark…" while it ran; the job's own completion is the
    notice."""
    ids = []
    for t in tools_run or []:
        if isinstance(t, dict) and str(t.get("name") or "") in (
                "execute", "jobs", "file_system"):
            for jid in _JOB_ID_RE.findall(str(t.get("content") or "")):
                if jid not in ids:
                    ids.append(jid)
    return ids


def _notify_when_jobs_finish(context, job_ids, req_id) -> int:
    """Arm the job registry to notify the owner when each still-running
    background job finishes.
    Sandbox jobs already wake a turn that reports their result. Returns the
    number armed."""
    try:
        from .jobs import get_job_registry, STATUS_RUNNING
        reg = get_job_registry(context)
    except Exception:  # noqa: BLE001
        return 0
    armed = 0
    for jid in job_ids:
        job = reg.get(jid)
        if job is None or job.status != STATUS_RUNNING:
            continue
        job.meta["notify_owner_req"] = str(req_id or "")
        armed += 1
    return armed


def _notify_promise_backstop(context, *, last_user_content, tools_run,
                             final_content, req_id,
                             had_failures: bool) -> bool:
    """Deliver the notification the user EXPLICITLY asked for when the turn
    is ending WITHOUT a notify_operator call — by writing the notify record
    directly, model not involved.

    The in-loop finish-line guard steers the MODEL once, but it deliberately
    stands down on force-finalising ends (strike cap, think-loop halt) — and
    that is exactly when the promise matters most: req 50855398 died at
    strike 6/6 after 1789s and "notify me in slack when you're done" never
    fired; the verifier late-refuted the turn for that alone. A promised
    notification is a DELIVERY REQUIREMENT, not a suggestion — on any end
    where the model didn't make the call (aborted OR simply ignored the
    steer), the agent keeps the promise itself, honestly labelled. Respects
    notify_tool's rate limit; never raises; returns True when a record was
    written."""
    if requester_is_member():
        return False        # a member never writes into the owner's notification feed (R7)
    try:
        # a probe never pages the owner — not by the tool, not by this
        # backstop (§4LZ review: the dry run made the backstop send instead)
        from ..utils.logging import is_probe_request_id, request_kind
        if is_probe_request_id(str(req_id or "")) or request_kind() == "probe":
            return False
    except Exception:  # noqa: BLE001
        pass
    try:
        if not _user_asked_for_notification(last_user_content):
            return False
        # only a notify that really WENT OUT suppresses the backstop (§4LZ
        # B2: a pre-flight-blocked or disabled call read as delivered)
        if any(_notify_delivered(t) for t in tools_run or []):
            return False
        from ..tools.notify_tool import (
            PHASE as _NOTIFY_PHASE, _note_sent, _rate_limited,
        )
        from .autonomous_activity import (
            SEVERITY_NOTIFY, get_activity_log, summarize_turn_content,
        )
        log = get_activity_log(context)
        if log is None or _rate_limited():
            return False
        # §4LD: the turn LAUNCHED the work — "Done" would be false. The jobs
        # notify on finishing (sandbox jobs wake
        # a turn that reports the real result)
        _launched = _launched_background_jobs(tools_run)
        # only when a finish notice was actually ARMED (§4LI review: a turn
        # that merely listed a finished job, or ran a sandbox job — another
        # registry — armed nothing and the promised notice was lost)
        if _launched and not had_failures and _notify_when_jobs_finish(context, _launched, req_id) > 0:
            return False
        head = summarize_turn_content(final_content, limit=260)
        msg = (("Task stopped early after repeated failures — "
                if had_failures else "Done — ")
               + (head or "(no summary produced)"))[:500]
        # req_id stamped unconditionally: the same-turn digest filters on
        # meta.req_id == current req_id, so an unstamped record would echo
        # back as "while you were away" in the very reply that produced it.
        meta = {"auto": "finish-line backstop"}
        if req_id:
            meta["req_id"] = str(req_id)
        ok = log.record(_NOTIFY_PHASE, msg, severity=SEVERITY_NOTIFY, **meta)
        if ok:
            _note_sent()
            pretty_log(
                "Notify Guard",
                "auto-delivered the promised notification (turn ended "
                "without a notify_operator call)",
                level="WARNING", icon=Icons.NOTIFY_OUT,
            )
        return bool(ok)
    except Exception:
        logger.debug("notify promise backstop skipped", exc_info=True)
        return False


# Trailing-promise detection (2026-07-14). A final reply whose LAST sentence
# promises imminent action ("…Let me fix it.") means the model narrated an
# action instead of doing it — the turn ends and nothing runs afterwards
# (observed live: a mid-repair turn shipped exactly that, the user believed
# the fix was applied). "let me know…" is conversational and excluded.
_ACTION_PROMISE_RE = re.compile(
    r"\b(?:let\s+me\s+(?!know\b)|i['’]ll\s+|i\s+will\s+"
    r"|i\s+am\s+going\s+to\s+|now\s+i['’]m\s+going\s+to\s+|gonna\s+)",
    re.IGNORECASE,
)


def _ends_with_action_promise(text) -> str:
    """Return the final sentence of ``text`` when it promises imminent
    action, else "". Only the LAST sentence counts — promises earlier in a
    reply are usually followed by the action's actual result."""
    t = str(text or "").strip()
    if not t:
        return ""
    last_sentence = re.split(r"(?<=[.!?])\s+|\n+", t)[-1].strip()
    if not last_sentence or len(last_sentence) > 120:
        return ""
    if _ACTION_PROMISE_RE.search(last_sentence):
        return last_sentence
    return ""


#: Tools whose dropped-at-the-finish-line call means user-visible work was
#: silently skipped (vs. terminal-tool re-calls, which are dropped by
#: design). Used for the honesty note when force_final_response eats a call.
_MUTATING_TOOLS_FOR_DROP_NOTE = frozenset({
    "file_system", "execute", "manage_services", "manage_projects", "database",
})


def _dropped_mutation_note(dropped_names, paths=(), landed=(), creating=(),
                           deleting=()) -> str:
    """Return the not-applied honesty note when ``dropped_names`` contains a
    mutating tool, else "". Appended to the final reply so a fix the turn
    closure swallowed is never presented as done.

    ⚠ IT MUST NOT DISCLAIM WHAT DID LAND (§4KC, req 76b3602e). The turn's
    ONE edit succeeded at +40 s; a redundant second `file_system` call was
    dropped at the finish line; the note then told the user "nothing
    described above as written … was actually written" over a file that
    was, verifiably, changed. ``landed`` (from `_files_mutated_this_turn`,
    i.e. the tool results' own SUCCESS lines, not prose) names what did
    land, and the note then disclaims only the dropped action.

    ⚠ IT MUST CONTRADICT THE PAST TENSE, NOT ONLY THE FUTURE (§4GN). The
    note used to say "any change described above as about to happen has NOT
    been applied" — and the reply that prompted this fix said, flatly, "The
    report is saved to /workspace/…md". A future-tense disclaimer does not
    touch a past-tense claim, so the user read a sentence stating the file
    existed and a footnote about pending work, with nothing joining them.
    ``paths`` (parsed from the dropped call's OWN arguments, so it is exact
    rather than prose-matched) names the file that does not exist.
    """
    muts = sorted({str(n) for n in (dropped_names or [])
                   if str(n) in _MUTATING_TOOLS_FOR_DROP_NOTE})
    if not muts:
        return ""
    done_all = [str(x) for x in (landed or []) if str(x).strip()]
    done_keys = {_fs_norm(x) for x in done_all}
    # A dropped path that ALSO landed this turn is not "missing": the
    # dropped call was a second action on a file an earlier call changed.
    _del_keys = {_fs_norm(str(x)) for x in (deleting or [])}
    named, _seen = [], set()
    for x in (paths or []):
        x = str(x)
        k = _fs_norm(x)
        # a dropped DELETE of a file that landed this turn is still a real
        # pending action on a real file — name it (r5)
        if not x.strip() or (k in done_keys and k not in _del_keys) or k in _seen:
            continue
        _seen.add(k)
        named.append(x)
    named = named[:3]
    creating_keys = {_fs_norm(str(x)) for x in (creating or [])}
    deleting_keys = {_fs_norm(str(x)) for x in (deleting or [])}
    missing = [x for x in named if _fs_norm(x) in creating_keys
               and _fs_norm(x) not in done_keys]
    # a file that landed and had a dropped delete: it exists, the delete is
    # the pending action — say "not deleted", never "does NOT exist" (r6)
    undeleted = [x for x in named if _fs_norm(x) in deleting_keys
                 and (_fs_norm(x) not in creating_keys or _fs_norm(x) in done_keys)]
    changed = [x for x in named if _fs_norm(x) not in creating_keys
               and _fs_norm(x) not in deleting_keys]
    where = ""
    if missing:
        where += (" — `" + "`, `".join(missing) + "` "
                  + ("does" if len(missing) == 1 else "do") + " NOT exist")
    if undeleted:
        where += ((";" if where else " —") + " `" + "`, `".join(undeleted)
                  + "` " + ("was" if len(undeleted) == 1 else "were")
                  + " not deleted")
    if changed:
        where += ((";" if where else " —") + " `" + "`, `".join(changed)
                  + "` " + ("was" if len(changed) == 1 else "were")
                  + " not changed")
    done = done_all[:3]
    if done:
        return (
            f"\n\n{_DROPPED_NOTE_HEAD} "
            f"{', '.join(muts)} action(s) could run. The change(s) confirmed "
            f"above by a tool result — `" + "`, `".join(done) + "` — DID "
            f"land on disk; only that final pending action was not "
            f"applied{where}. Ask me to continue to apply it."
        )
    return (
        f"\n\n{_DROPPED_NOTE_HEAD} "
        f"{', '.join(muts)} action(s) could run — nothing described above as "
        f"written, saved or created was actually written{where}. Ask me to "
        "continue to apply it."
    )


def _with_abort_note(final_ai_content: str, note: str) -> str:
    """Put an ABORT explanation into the reply whatever else accumulated.

    ⚠ IT USED TO BE WRITTEN ONLY WHEN THE REPLY WAS EMPTY (§4GO,
    2026-09-14). `if not final_ai_content:` is "no TEXT yet", and the turn
    loop accumulates every iteration's visible text — so on any turn that
    narrated at all, the abort explanation was dropped and the working
    narration shipped as the answer. Measured on req f76620e1: the loop
    breaker aborted after the third identical `browser` load, 1120 chars of
    "Let me take a screenshot of the single message view…" went out as the
    reply, and the turn was recorded `ok · confidence 0.74`. The user was
    never told the attempt stopped.

    Two consumers depended on the marker that was never written: the reader
    (who sees a reply that simply ends), and `outcome_heuristics`, whose
    STRONGEST signal is `[ATTEMPT_ABORTED_*]` in the final response — no
    marker, no UNKNOWN→FAILED promotion, no lesson from an aborted attempt.
    It searches anywhere in the text, so appending serves it.
    """
    body = (final_ai_content or "").strip()
    if not body:
        return note
    if note[:48] in body:                      # idempotent across re-entry
        return final_ai_content
    return final_ai_content.rstrip() + "\n\n" + note


#: `file_system` operations that CHANGE the workspace — the only ones a
#: dropped-call note may disclaim. A dropped verify-`read` used to produce
#: the full "nothing was written" disclaimer (fresh-eye §4KC round 2).
_DROP_NOTE_MUTATING_FS_OPS = frozenset({
    "write", "edit", "replace", "delete", "download", "copy", "rename",
    "move",
})
#: The subset that CREATES a file — for these "does NOT exist" is the right
#: disclaimer; a dropped `edit`/`replace`/`delete` targets a file that
#: exists and was merely not changed. For copy/rename/move the CREATED path
#: is the DESTINATION (`path` is the source, which exists — §4KC r3).
_DROP_NOTE_CREATING_FS_OPS = frozenset({"write", "download", "copy",
                                        "rename", "move"})
_DROP_NOTE_DEST_OPS = frozenset({"copy", "rename", "move"})


#: §4KD: tools whose one call costs MINUTES of a shared resource (the image
#: node's only GPU). A one-token or unintelligible follow-up after a turn
#: that ran one must be clarified, never re-run: on 2026-09-23 a Slack
#: member's `emp1` after an image turn produced a second image, because the
#: tool result ended with a ready next action and the generic "if you lack
#: information, ASK" prompt line lost.
COSTLY_TOOLS = frozenset({"image_generation"})
_COSTLY_TURN_TTL_S = 3600.0
_COSTLY_TURNS_MAX = 256
#: the image tool's own link shape, root OR project-scoped
#: (`/api/download/projects/<id>/gen_….png`) — the first version missed the
#: project form, i.e. every project conversation (§4KD review)
_COSTLY_RESULT_RE = re.compile(r"/api/download/(?:projects/[^/\s)]+/)?gen_[0-9a-f]{8}\.png")
_ALPHA_RUN_RE = re.compile(r"[^\W\d_]{3,}", re.UNICODE)


#: §4QG: ONE real word — letters only (any script), ≥3 of them, an inner
#: hyphen/apostrophe allowed ("hyper-real", "don't") — is an instruction:
#: "watercolor", "bigger", "darker", "Stalin", "ακουαρέλα". The live review
#: (2026-10-21) found every single word after an image turn blocked as
#: "unintelligible", including the user's ANSWER to the guard's own question.
#: §4QG-b: a letter is `isalpha()` OR a combining mark (category M*) after
#: one — "नमस्ते" (Devanagari vowel signs/virama are marks) was "not a word".
#: Checked by a plain scan, no regex.
_WORD_INNER_SEPARATORS = frozenset("'’-")


def _is_word_char(ch) -> bool:
    return ch.isalpha() or unicodedata.category(ch).startswith("M")


def _strip_word_edges(w) -> str:
    """§4QG-b: drop leading/trailing characters that are neither
    alphanumeric nor a combining mark. A two-index scan — LINEAR; the old
    `^[\\W_]+|[\\W_]+$` sub was quadratic ("a" + "-"*50000 + "a": 7 s on
    the event loop), since `$` fails at every inner position of the run."""
    w = str(w or "")
    i, j = 0, len(w)
    while i < j and not (w[i].isalnum() or unicodedata.category(w[i]).startswith("M")):
        i += 1
    while j > i and not (w[j - 1].isalnum() or unicodedata.category(w[j - 1]).startswith("M")):
        j -= 1
    return w[i:j]


def _is_letters_word(w) -> bool:
    """§4QG-b: letter runs (letters + their combining marks, each run
    starting with a letter) joined by single inner `'`/`’`/`-`."""
    if not w:
        return False
    run_start = True
    for ch in w:
        if ch in _WORD_INNER_SEPARATORS:
            if run_start:
                return False                     # leading or doubled separator
            run_start = True
        elif run_start:
            if not ch.isalpha():
                return False
            run_start = False
        elif not _is_word_char(ch):
            return False
    return not run_start                         # no trailing separator


def _filler_key(w) -> str:
    """§4QG-b: the lookup key for `_NON_INSTRUCTION_WORDS` — casefolded,
    accents/diacritics removed (Greek tonos too: "ναί" → "ναι"), letter
    runs collapsed ("yesss" → "yes", "hmmmmm" → "hm", "okk" → "ok") and a
    whole-word repeated syllable reduced ("hahaha" → "ha", "lolol" → "lol",
    "χαχα" → "χα"). Linear (inputs over 40 chars are not fillers)."""
    low = "".join(c for c in unicodedata.normalize("NFD", str(w or "").casefold())
                  if not unicodedata.combining(c)).replace("’", "'")
    if len(low) > 40:
        return low
    low = re.sub(r"(.)\1+", r"\1", low)
    m = re.fullmatch(r"(.{2,3}?)\1+(.{0,2})", low)
    if m and m.group(1).startswith(m.group(2)):
        low = m.group(1) + m.group(2) if m.group(2) else m.group(1)
    return low


#: §4QG: single words that carry no instruction — fillers, thanks,
#: reactions, praise. (Acknowledgements and go-aheads are read by `_is_ack` /
#: `_is_go_ahead`, which also keep them low-information so those rules see
#: them.) §4QG-b: matched by `_filler_key` (case, accents, repeated
#: letters/syllables normalised) — a list of spellings missed "yess",
#: "okk", "hahaha", "ναί", "τέλειο"; EN/EL plus common ES/FR/DE/IT thanks/ok.
_NON_INSTRUCTION_WORDS_RAW = (
    # EN fillers / reactions / acknowledgements / praise
    "now", "please", "pls", "plz", "thanks", "thank", "thank-you", "thankyou", "thx", "tysm", "ty", "lol", "lmao", "rofl",
    "hm", "hmm", "huh", "meh", "wow", "nice", "cool", "great", "good", "fine", "awesome",
    "perfect", "hey", "hello", "hiya", "hi", "what", "why", "how", "well", "and", "test",
    "yes", "yea", "yeah", "yep", "yup", "yay", "ok", "okay", "okey", "kk", "no", "nope", "nah",
    "alright", "allright", "sure", "fine", "amazing", "lovely", "beautiful", "gorgeous",
    "brilliant", "excellent", "fantastic", "wonderful", "superb", "bravo",
    "congrats", "ha", "hah", "heh", "hehe", "lol", "omg", "oh", "ooh", "ah", "aha", "uh", "um",
    "umm", "ack", "noted", "gotcha", "cheers", "exactly", "indeed",
    # EL
    "τώρα", "ευχαριστώ", "ευχαριστούμε", "ευχαριστω", "ωραία", "ωραίο", "ωραίος", "τέλεια",
    "τέλειο", "τέλειος", "μπράβο", "υπέροχο", "υπέροχα", "καταπληκτικό", "φοβερό", "χα", "χαχα",
    "τι", "γιατί", "πώς", "εεε", "χμ", "χμμ", "ναι", "οκ", "όχι", "εντάξει", "ντάξει", "καλό",
    "καλά", "σωστά", "γεια", "μερσί",
    # ES / FR / DE / IT thanks / ok / reactions
    "gracias", "vale", "bueno", "genial", "merci", "d'accord", "dac", "super", "danke",
    "bitte", "gut", "prima", "grazie", "bene", "perfetto", "si", "oui", "ja", "jaja",
)
_NON_INSTRUCTION_WORDS = frozenset(_filler_key(x) for x in _NON_INSTRUCTION_WORDS_RAW)


def _is_one_real_word(token) -> bool:
    """§4QG: a single token that is a real word (see `_is_letters_word`),
    not a filler from `_NON_INSTRUCTION_WORDS`, an acknowledgement or a
    go-ahead (those keep their own rules)."""
    w = _strip_word_edges(token)
    if not w or not _is_letters_word(w):
        return False
    if sum(1 for ch in w if ch.isalpha()) < 3:
        return False
    key = _filler_key(w)
    if key in _NON_INSTRUCTION_WORDS:
        return False
    return not any(_is_ack(x) or _is_go_ahead(x) for x in (w, key))


def _is_low_information_message(text) -> bool:
    """One token, or nothing that reads as a word in any script: `emp1`,
    `?`, `...`, `ok`, `k`. Not a judgement on the user — a statement that
    the message cannot carry an instruction worth minutes of GPU.
    §4QG: one REAL word ("watercolor", "bigger", "ακουαρέλα") is not low
    information — it names what the user wants."""
    t = str(text or "").strip()
    if not t:
        return True
    tokens = [x for x in re.split(r"\s+", t) if x]
    if len(tokens) <= 1:
        return not _is_one_real_word(t)
    return not _ALPHA_RUN_RE.search(t)


#: user-role rows the LOOP appends — only consulted when the user's own row
#: cannot be found by its text
_LOOP_USER_ROW_RE = re.compile(r"^\s*\[?(?:SYSTEM|AUTO-DIAGNOSTIC|REMINDER|MULTI-STEP OUTCOME)\b")


def _msg_text(m) -> str:
    """A message's text; a list content joins its text parts."""
    c = m.get("content")
    if isinstance(c, list):
        c = " ".join(i.get("text", "") for i in c if isinstance(i, dict) and i.get("type") == "text")
    return str(c or "")


def _last_assistant_text(messages, user_text=None) -> str:
    """The assistant message before the CURRENT user turn, as text; "" when
    there is none. §4NT r3: the turn is the user row holding `user_text`
    (the loop appends its own user-role rows — SYSTEM ALERT, AUTO-DIAGNOSTIC,
    REMINDER, MULTI-STEP OUTCOME — after which "the last user row" was the
    model's own text of THIS request); without a match, the last user row."""
    hist = [m for m in (messages or []) if isinstance(m, dict)]

    def _text(m):
        c = m.get("content")
        if isinstance(c, list):
            # the call site's own join (text parts only) so the anchor matches
            c = " ".join(i.get("text", "") for i in c if isinstance(i, dict) and i.get("type") == "text")
        return str(c or "")
    users = [i for i, m in enumerate(hist) if m.get("role") == "user"]
    idx = -1
    if user_text is not None:
        want = str(user_text).strip()
        idx = max((i for i in users if _text(hist[i]).strip() == want), default=-1)
    if idx < 0:
        # §4RZ step 3: the marked request row
        idx = next((i for i in users if hist[i].get("_request")), -1)
    if idx < 0:
        # no exact row (compaction rewrote it): the last row the USER wrote,
        # never one the loop appended (r4), nor one sent mid-turn (§4RZ)
        idx = max((i for i in users if not _LOOP_USER_ROW_RE.match(_text(hist[i]))
                   and not hist[i].get("_queued")),
                  default=max(users, default=-1))
    prior = hist[:idx] if idx >= 0 else hist
    for m in reversed(prior):
        if m.get("role") == "assistant":
            return _text(m)
    return ""


_GREEK_LETTER_RE = re.compile(r"[\u0370-\u03ff\u1f00-\u1fff]")
_LATIN_LETTER_RE = re.compile(r"[A-Za-z]")


#: §4NT r4: trailing decoration after a closing "?" — emoji, markdown
#: emphasis, closing brackets — "Want another? 🙂", "**Θέλεις κι άλλη;**"
_TRAILING_DECOR_RE = re.compile(r"[\s*_~`)\]>»\u200b\ufe0f\U0001F000-\U0001FAFF\u2600-\u27BF]+$")


def _previous_turn_asked_a_question(messages, user_text=None) -> bool:
    tail = _TRAILING_DECOR_RE.sub("", _last_assistant_text(messages, user_text).rstrip())
    last = tail.rsplit("\n", 1)[-1].strip()
    if tail.endswith(("?", "\u037e")) or last.endswith(("?", "\u037e")):
        return True
    # §4NT: Greek writes the question mark as ";" — counted only for a final
    # sentence that is Greek (more Greek letters than Latin ones)
    if not tail.endswith(";"):
        return False
    sent = re.split(r"[.!?\n]", tail[:-1])[-1]
    return len(_GREEK_LETTER_RE.findall(sent)) > len(_LATIN_LETTER_RE.findall(sent))


#: §4NT: a short INSTRUCTION to go ahead — "do it", "go ahead", "proceed",
#: "κάνε το", "προχώρα" — the whole message, punctuation aside. It is never an
#: acknowledgement: "ok" / "yes" / "ναι" / "👍" after a picture are, so they
#: still ask unless our reply asked a question (r3: deciding from the
#: assistant's prose whether it "offered an image" was a lexical proxy that
#: leaked both ways — "I can make further tweaks to the picture", negations,
#: offers about scripts — the user's own instruction is the signal).
_GO_AHEAD_RE = re.compile(
    r"^(?:(?:ok|okay|yes|yeah|yep|sure|ναι|οκ|εντάξει)\s+)?"
    r"(?:do it|do that|go|go on|go on then|go for it|go ahead|proceed|make it|try it|run it|"
    r"continue|again|retry|redo|regenerate|another|another one|one more|more|next|new|new one|"
    r"νέα|νεα|καινούργια|καινουργια|"
    r"κάνε το|κανε το|κάντο|καντο|προχώρα|προχωρα|φτιάξε το|φτιαξε το|πάμε|παμε|συνέχισε|συνεχισε|ξανά|ξανα)"
    r"(?:\s+(?:please|pls|plz|now|then))?$",
    re.IGNORECASE)


#: §4NT r4: an acknowledgement — the only low-information reply that ANSWERS
#: our question. Junk (`emp1`, `?`) never does (review r3: after any reply
#: ending in "?" — and the guard's own question always does — a repeated
#: `emp1` ran the image, the §4KD incident again).
_ACK_RE = re.compile(
    r"^(?:ok|okay|yes|yeah|yep|yup|y|sure|please|yes please|ok please|ναι|οκ|εντάξει|ντάξει|👍)$",
    re.IGNORECASE)


def _is_ack(text) -> bool:
    t = re.sub(r"[\s.!,;:…]+", " ", str(text or "")).strip()
    return bool(t) and bool(_ACK_RE.match(t))


def _is_go_ahead(text) -> bool:
    t = re.sub(r"[\s.!,;:…]+", " ", str(text or "")).strip()
    return bool(t) and bool(_GO_AHEAD_RE.match(t))


def _previous_turn_was_costly(messages, costly_record: bool, user_text=None) -> bool:
    """Read from the conversation ITSELF (the image tool's own link in the
    last assistant message) OR the in-process per-conversation record —
    the client may resend text only, and the record dies with a restart."""
    if costly_record:
        return True
    prev = _last_assistant_text(messages, user_text)
    return bool(_COSTLY_RESULT_RE.search(prev)) or _is_our_clarify_question(prev)


_GENERATED_IMAGE_LINE_RE = re.compile(r"!\[generated image\]\(/api/download/([^)\s]+)\)")
_DOWNLOAD_LINK_RE = re.compile(r"(!?\[[^\]]*\]\()?/api/download/([^)\s\"'>]+)\)?")


def _scrub_member_download_links(text, allowed) -> str:
    """Drop every `/api/download/<name>` link (markdown image, markdown link
    or bare path) whose basename is not in `allowed` — the images generated
    for a member. Never raises; non-strings pass through."""
    if not isinstance(text, str) or "/api/download/" not in text:
        return text
    allowed_base = {os.path.basename(str(a)) for a in (allowed or ())}

    def _sub(m):
        name = m.group(2)
        return m.group(0) if ("/" not in name and name in allowed_base) else "[file not available]"
    try:
        return _DOWNLOAD_LINK_RE.sub(_sub, text)
    except Exception:  # noqa: BLE001
        return text


def _result_failure_shaped(str_res: str, res_is_error: bool, outcome) -> bool:
    """Does this tool result get a FAILURE BANNER (and a fallback hint)? The
    loop's verdict, an `Error` head, or "SYSTEM ERROR" anywhere — except in a
    DECLARED success: a caption of a poster reading "SYSTEM ERROR" got the
    banner, and the banner hid the look from the inspected-image gate (§4LM)."""
    from ..tools.outcome import OutcomeStatus
    return bool(
        res_is_error
        or str_res.lstrip().startswith("Error")
        or ("SYSTEM ERROR" in str_res
            and not (getattr(outcome, "declared", False)
                     and getattr(outcome, "status", None) is OutcomeStatus.OK)))


def _salvage_vision_args(block: str) -> dict:
    """`target` / `action` / `prompt` of a malformed vision_analysis call,
    each read from its OWN tag or JSON key; {} when no target is found."""
    out: dict = {}
    for key in ("target", "action", "prompt"):
        m = (re.search(rf"<{key}>(.*?)</{key}>", block or "", re.DOTALL | re.IGNORECASE)
             # each quote style closes only on ITS OWN quote: "Is the user's
             # avatar visible?" kept its apostrophe (review)
             or re.search(rf"[\"']{key}[\"']\s*:\s*\"((?:[^\"\\]|\\.)*)\"", block or "", re.DOTALL)
             or re.search(rf"[\"']{key}[\"']\s*:\s*'((?:[^'\\]|\\.)*)'", block or "", re.DOTALL))
        if m and m.group(1).strip():
            out[key] = m.group(1).strip()
    return out if out.get("target") else {}


def _drop_missing_download_links(text, sandbox_root) -> tuple:
    """(text, dropped names): every `/api/download/<rel>` link (markdown
    image, markdown link or bare path) whose file does not exist — not at
    `<rel>` under the sandbox, and (lenient) no file of that NAME anywhere in
    it — is replaced with a plain notice. A live reply (08-21, req 654f4b01)
    embedded `![generated image](/api/download/gen_d7f2a1b3.png)` and
    described it, in a turn that generated nothing (§4LM). Lenient by
    design: a real file is never unlinked. Never raises."""
    if not isinstance(text, str) or "/api/download/" not in text or sandbox_root is None:
        return text, []
    try:
        root = Path(sandbox_root)
    except TypeError:
        return text, []
    dropped: List[str] = []

    import glob as _glob
    from urllib.parse import unquote as _unquote

    def _readings(rel: str) -> List[str]:
        """Every name the link could mean: as written, URL-decoded, and with
        prose punctuation the regex swallowed (`plot.png.`, `x.png|`, `a.png\``)."""
        rel = rel.split("?", 1)[0].split("#", 1)[0]
        out = []
        for r in (rel, rel.split("|", 1)[0].rstrip(".,;:!?`*'\"")):
            for v in (r, _unquote(r)):
                if v and v not in out:
                    out.append(v)
        return out

    def _as_written(rel: str) -> bool:
        try:
            return any(".." not in r and (root / r).is_file() for r in _readings(rel))
        except Exception:  # noqa: BLE001 — unknown is "exists"
            return True

    def _by_basename(rel: str):
        """(reading, files) — the files under the root with this link's basename
        as root-relative paths, and the reading of the link that matched them
        (§4OE-5: a link written with its folder dropped used to be KEPT because
        the basename existed somewhere — and then answered 404)."""
        try:
            for r in _readings(rel):          # every reading: `plot.png.` is `plot.png` + a full stop
                base = os.path.basename(r)
                if not base:
                    continue
                found: List[str] = []
                for m in root.rglob(_glob.escape(base)):
                    if m.is_file():
                        rp = str(m.relative_to(root))
                        if rp not in found:
                            found.append(rp)
                if found:
                    return r, sorted(found)
            return rel, []
        except Exception:  # noqa: BLE001
            return rel, []

    repaired: List[str] = []

    def _sub(m):
        name = m.group(2)
        if _as_written(name):
            return m.group(0)
        core, cands = _by_basename(name)
        if len(cands) == 1:
            repaired.append(f"{name} → {cands[0]}")
            # keep whatever prose punctuation followed the real name (`plot.png.` → `sub/plot.png.`)
            suffix = name[len(core):] if name.startswith(core) else ""
            tail = ")" if m.group(0).endswith(")") else ""
            new_path = cands[0]
            if name != _unquote(name):                    # the link was URL-encoded: keep it so
                from urllib.parse import quote as _quote
                new_path = _quote(new_path, safe="/")
            return f"{m.group(1) or ''}/api/download/{new_path}{suffix}{tail}"
        if len(cands) > 1:
            return m.group(0)             # several files share the name: leave the model's link
        dropped.append(name)
        # a bare path's match can swallow the `)` that closes the sentence
        tail = ")" if (m.group(1) is None and m.group(0).endswith(")")) else ""
        return f"[no such file: {os.path.basename(name)} — it was not created]{tail}"
    try:
        out = _DOWNLOAD_LINK_RE.sub(_sub, text)
        if repaired:
            pretty_log("Link Repaired", "; ".join(r[:120] for r in repaired[:3]), icon=Icons.WARN, level="WARNING")
        return out, dropped
    except Exception:  # noqa: BLE001
        return text, []


def idle_attempt_result_for_dream(outcome) -> str:
    """§4MI r2: the heartbeat a dream tick that wrote nothing records — a
    SKIP is "declined" (suppresses the DEAD alarm; the loop is healthy), an
    ERROR is "failed" (keeps it armed: a worker that is down forever must
    not look alive)."""
    if isinstance(outcome, dict) and outcome.get("phase") == "error":
        return "failed"
    return "declined"


def _designed_stop_result(outcome) -> bool:
    """§4MI: is this tool outcome a designed stop (see
    `distill.outcome_heuristics.is_designed_stop`)? Never raises."""
    try:
        from ..distill.outcome_heuristics import is_designed_stop
        return bool(is_designed_stop(outcome))
    except Exception:  # noqa: BLE001
        return False


def _late_verdict_to_work_log(context, traj, reason: str) -> None:
    """§4MI: append a work_log row naming the late refute on the project
    the turn was bound to (`extra["project_id"]`, stamped at record
    time). Append-only store, so the original "completed" row stays and
    the briefing reads the newer verdict. Never raises."""
    try:
        _pid = str(((getattr(traj, "extra", None) or {}).get("project_id")) or "")
        store = getattr(context, "project_store", None)
        if not _pid or store is None or not hasattr(store, "add_work_log"):
            return
        store.add_work_log(
            _pid,
            request=str(getattr(traj, "user_request", "") or "")[:200],
            outcome="verifier:failed (late)",
            note=("the verifier refuted this reply after it was sent: "
                  + str(reason or "")[:300]),
        )
        logger.info("late verdict → work_log of project %s", _pid[:12])
    except Exception as e:  # noqa: BLE001
        logger.debug("late verdict work_log skipped: %s: %s", type(e).__name__, e)


class _SkipMemberCorrection(Exception):
    """Control flow: a member's turn skips the correction hooks."""


def _real_tool_rows(tools_run_this_turn) -> int:
    """Tool rows that actually ran — the loop's synthetic rows (a REJECTED
    block, a parse error) are not evidence."""
    return sum(1 for t in (tools_run_this_turn or [])
               if isinstance(t, dict) and not t.get("_synthetic"))


def _turn_generated_images(tools_run_this_turn) -> List[str]:
    """Download names of the images `image_generation` produced this
    request, in order — read off the tool's own SUCCESS result (the
    markdown line it tells the model to echo)."""
    out: List[str] = []
    for t in (tools_run_this_turn or []):
        try:
            if not isinstance(t, dict) or t.get("_synthetic"):
                continue
            # by CONTENT, not name: a row carries the raw name the model used
            # (an alias like `imagegen`), and only the image tool writes this
            # success head (R7)
            body = str(t.get("content") or "")
            if not body.lstrip().startswith("SUCCESS: Image generated"):
                continue
            for m in _GENERATED_IMAGE_LINE_RE.finditer(body):
                name = m.group(1).strip()
                if name and name not in out:
                    out.append(name)
        except Exception:  # noqa: BLE001
            continue
    return out


def _foreign_image_note(text, tools_run_this_turn, sandbox_root=None, include_missing: bool = True) -> str:
    """§4MM: a note when the reply SHOWS a generated image (`gen_*`) and this
    request generated NONE, else "". Turn 40 described an image no tool made
    (its link pointed at nothing); turn 43 showed an earlier turn's image
    under a new description — and the verifier confirmed it. A request that
    DID generate one is left alone (an edit shows before AND after — r2).
    Run before missing links are dropped. ``include_missing=False``: links to
    files that do not exist are left to the caller's own missing-file note
    (the streamed path — r2: two notes for one link)."""
    try:
        if _turn_generated_images(tools_run_this_turn):
            return ""
        earlier, missing = [], []
        for m in _DOWNLOAD_LINK_RE.finditer(str(text or "")):
            name = os.path.basename(m.group(2).split("?", 1)[0])
            if not name.startswith("gen_") or name in earlier or name in missing:
                continue
            exists = True
            if sandbox_root is not None:
                _, _gone = _drop_missing_download_links(f"![x](/api/download/{name})", sandbox_root)
                exists = not _gone
            (earlier if exists else missing).append(name)
        if not include_missing:
            missing = []
        if not (earlier or missing):
            return ""
        parts = []
        if earlier:
            parts.append(", ".join(f"`{n}`" for n in earlier[:3])
                         + (" is" if len(earlier) == 1 else " are") + " from an earlier request")
        if missing:
            parts.append(", ".join(f"`{n}`" for n in missing[:3])
                         + (" does" if len(missing) == 1 else " do") + " not exist")
        return "\n\nℹ️ No image was generated in this request — " + "; ".join(parts) + "."
    except Exception:  # noqa: BLE001
        return ""


def _unshown_image_note(text, tools_run_this_turn, sandbox_root=None) -> str:
    """The markdown line for the LAST image generated this request when the
    reply DISPLAYS none of them, else "" (§4MG). Live 2026-10-07: the time
    budget ran out after two ~10-minute renders; the forced report linked
    no image, so the user saw prose about three pictures and none of them.

    Displayed = an `/api/download/…<name>` link, not the bare name: "saved
    as gen_a.png" shows nothing, and on the streamed path the raw text still
    holds tool-call markup the user never saw (review) — callers pass the
    VISIBLE text. A file that no longer exists is not linked."""
    try:
        gen = _turn_generated_images(tools_run_this_turn)
        if not gen:
            return ""
        shown = {os.path.basename(m.group(2).split("?", 1)[0])
                 for m in _DOWNLOAD_LINK_RE.finditer(str(text or ""))}
        if any(os.path.basename(g) in shown for g in gen):
            return ""
        note = f"\n\n![generated image](/api/download/{gen[-1]})"
        if sandbox_root is not None:
            _, dropped = _drop_missing_download_links(note, sandbox_root)
            if dropped:
                return ""
        return note
    except Exception:  # noqa: BLE001
        return ""


#: §4QG: the image tool's all-attempts-were-panels NOTE (both of its
#: wordings — "another attempt could not be rendered" and "… PANELS N
#: times" — carry this phrase; tools/image_gen.py `_collage_note`)
_TWO_PANEL_RESULT_MARK = "came out as separate side-by-side PANELS"
#: the reply already says so. §4QJ: STRICT on purpose — a miss only shows
#: the note twice, a false match hides it. Three review rounds each found a
#: looser form matching ordinary replies: bare "side by side" / "δίπλα
#: δίπλα" (how people stand, echoed from the collage check's scene line),
#: "came out … side by side", bare "panel" ("a panel of judges", "control
#: panel"), "side-by-side photo" (the user's own request), "δύο εικόνες",
#: "collage of postcards". Only an unmistakable two-panel phrase counts.
_TWO_PANEL_SAID_RE = re.compile(
    r"\b(?:two|2)[\s-]+(?:separate[\s-]+)?(?:side[\s-]*by[\s-]*side[\s-]+)?(?:panels?|halves)\b|"
    r"\btwo[\s-]panel\b|\bside[\s-]*by[\s-]*side\s+panels\b|\bdiptych\b|"
    r"δύο\s+(?:ξεχωριστ\w+\s+)?(?:πάνελ|κομμάτια\s+δίπλα)|δίπτυχο",
    re.IGNORECASE)
TWO_PANEL_NOTE = ("\n\nℹ️ Note: this picture came out as two side-by-side panels, not one "
                  "continuous scene. Say if you want another attempt.")
TWO_PANEL_NOTE_EL = ("\n\nℹ️ Σημείωση: η εικόνα βγήκε σε δύο πάνελ δίπλα-δίπλα, όχι ως μία "
                     "ενιαία σκηνή. Πες μου αν θέλεις άλλη προσπάθεια.")


#: §4QG: the image-markdown guard's one steer (its head marks "already sent")
_UNBACKED_IMAGE_ALERT_HEAD = "SYSTEM ALERT — image link not found:"
_IMG_MD_LINK_RE = re.compile(r"!\[[^\]\n]*\]\(([^)\s]+)\)")


def _conversation_haystack(messages) -> str:
    """Every message's text plus every tool call's arguments — the whole
    conversation as it was given (uploads named in a user row, a vision
    call's `target`, an earlier reply's image line)."""
    parts = []
    for m in (messages or []):
        if not isinstance(m, dict):
            continue
        _t = _msg_text(m)
        if not _t.startswith(_UNBACKED_IMAGE_ALERT_HEAD):     # our own steer names the link: not backing
            parts.append(_t)
        for tc in (m.get("tool_calls") or []):
            try:
                a = (tc.get("function") or {}).get("arguments")
                parts.append(a if isinstance(a, str) else json.dumps(a, ensure_ascii=False))
            except Exception:  # noqa: BLE001
                continue
    return "\n".join(parts)


def _unbacked_image_links(text, messages, sandbox_root=None) -> List[str]:
    """§4QG: the image-markdown links in ``text`` that nothing backs — not
    in ANY earlier message of this conversation (as written, or by file
    name), and (``sandbox_root`` given: the owner's turn) no such file in
    the sandbox. The old guard accepted only links in the last 4 messages,
    so re-showing an earlier picture — or an uploaded photo after
    vision_analysis — ordered an unrequested multi-minute render."""
    out = []
    links = _IMG_MD_LINK_RE.findall(str(text or ""))
    if not links:
        return out
    hay = _conversation_haystack(messages)
    for link in links:
        if link in out:
            continue
        rel = link.split("?", 1)[0].split("#", 1)[0]
        base = os.path.basename(rel.rstrip("/"))
        if link in hay or (base and len(base) >= 5 and base in hay):
            continue
        if sandbox_root is not None and "/api/download/" in rel:
            _, _gone = _drop_missing_download_links(f"![x]({rel})", sandbox_root)
            if not _gone:
                continue
        out.append(link)
    return out


def _image_markdown_alert(clean_ui, messages, sandbox_root=None) -> Optional[str]:
    """§4QG: the one steer for image markdown in a turn where no image tool
    ran: None when every link is backed (`_unbacked_image_links`) or the
    steer was already sent this request. It never ORDERS a render — whether
    the user asked for a new picture is the model's reading of the user's
    words; an unbacked link left in the reply is dropped/labelled at
    finalize (`_drop_missing_download_links`, `_foreign_image_note`)."""
    bad = _unbacked_image_links(clean_ui, messages, sandbox_root)
    if not bad:
        return None
    if any(isinstance(m, dict) and m.get("role") == "user"
           and _msg_text(m).startswith(_UNBACKED_IMAGE_ALERT_HEAD) for m in (messages or [])):
        return None
    shown = ", ".join(f"`{b}`" for b in bad[:3])
    return (f"{_UNBACKED_IMAGE_ALERT_HEAD} your reply shows {shown}, which appears nowhere in this "
            "conversation and is not a file in the workspace — no tool made it, so it shows "
            "nothing. Remove that image line. Only if the user's own message asks for a NEW "
            "picture, call image_generation; otherwise answer without it.")


def _two_panel_note(text, tools_run_this_turn, user_text=None) -> str:
    """§4QG (493f8587): the image tool KNEW its picture was two panels — its
    collage check said so on every attempt and its result told the model to
    "tell the user plainly" — and the reply said "Generated a scene … as
    requested". When an image this request generated carries the tool's
    panels NOTE, the reply SHOWS that image, and it says nothing about
    panels / side-by-side, the fixed sentence (Greek for a Greek message or
    reply, as `clarify_first_reply`). Else "". Never raises."""
    try:
        body = str(text or "")
        if _TWO_PANEL_SAID_RE.search(body):
            return ""
        shown = {os.path.basename(m.group(2).split("?", 1)[0])
                 for m in _DOWNLOAD_LINK_RE.finditer(body)}
        hit = False
        for t in (tools_run_this_turn or []):
            if not isinstance(t, dict) or t.get("_synthetic"):
                continue
            c = str(t.get("content") or "")
            if not c.lstrip().startswith("SUCCESS: Image generated") or _TWO_PANEL_RESULT_MARK not in c:
                continue
            if any(os.path.basename(m.group(1).strip()) in shown
                   for m in _GENERATED_IMAGE_LINE_RE.finditer(c)):
                hit = True
                break
        if not hit:
            return ""
        greek = (bool(_GREEK_LETTER_RE.search(str(user_text or "")))
                 or len(_GREEK_LETTER_RE.findall(body)) > len(_LATIN_LETTER_RE.findall(body)))
        return TWO_PANEL_NOTE_EL if greek else TWO_PANEL_NOTE
    except Exception:  # noqa: BLE001
        return ""


def _owned_look_rows(tools_run_this_turn) -> List[tuple]:
    """§4QX: (image basenames, the system's line) for each image result whose
    tool told the model "the SYSTEM shows the user that line itself"
    (`LOOK_OWNED_NOTE` directly after the one-line look), in order. One
    reader for the note that appends the line and the verdict that strips it."""
    from .receipt_marks import IMAGE_SEEN_HEAD, IMAGE_SUCCESS_HEAD, LOOK_OWNED_NOTE, LOOK_OWNED_LABEL
    out: List[tuple] = []
    for t in (tools_run_this_turn or []):
        try:
            if not isinstance(t, dict) or t.get("_synthetic"):
                continue
            c = str(t.get("content") or "")
            if not c.lstrip().startswith(IMAGE_SUCCESS_HEAD):
                continue
            i = c.find("\n" + IMAGE_SEEN_HEAD)
            if i < 0:
                continue
            start = i + 1 + len(IMAGE_SEEN_HEAD)
            end = c.find("\n", start)
            if end < 0 or not c.startswith("\n" + LOOK_OWNED_NOTE, end + 1):
                continue
            look = c[start:end].strip()
            names = [os.path.basename(m.group(1).strip()) for m in _GENERATED_IMAGE_LINE_RE.finditer(c[:i])]
            if look and names:
                out.append((names, LOOK_OWNED_LABEL + look))
        except Exception:  # noqa: BLE001
            continue
    return out


def _owned_line_re(line: str):
    """The system's line as a line of its own (r1 M2: a model sentence that
    merely STARTS with the label and the look is the model's)."""
    return re.compile(r"(?:^|\n)" + re.escape(line) + r"[ \t]*(?=\n|$)")


def _without_owned_look_lines(text, tools_run_this_turn):
    """§4QX (r2 M1): ``text`` without the look lines the system appends — the
    LAST whole-line copy of each, so the verifier judges only the model's
    words (a CONFIRMED of the vision line against its own picture booked an
    image-only reply as verified; a REFUTED queued a "my previous reply"
    correction for a line the system wrote). Model text is never cut
    mid-sentence. ``text`` unchanged when nothing matches. Never raises."""
    try:
        if not isinstance(text, str) or not text:
            return text
        out = text
        for _names, line in _owned_look_rows(tools_run_this_turn):
            hits = list(_owned_line_re(line).finditer(out))
            if hits:
                h = hits[-1]
                out = out[:h.start()] + out[h.end():]
        return re.sub(r"\n{3,}", "\n\n", out).strip() if out != text else text
    except Exception:  # noqa: BLE001
        return text


def _owned_look_note(text, tools_run_this_turn) -> str:
    """§4QX: the look line the SYSTEM shows under a picture — for each image
    this request generated whose tool result told the model "the SYSTEM shows
    the user that line itself" (`LOOK_OWNED_NOTE`, directly after the look
    line), whose picture the reply SHOWS, and whose line the reply does not
    already carry: "\n\nWhat the picture shows: <the look>". Else "".
    The model was told not to describe the picture (61 of 131 replies that
    had the look copied the request into it); the line is the vision model's
    own sentence, one line (scene_look collapses whitespace), so nothing
    after it in the tool result can be spelt by the picture. Never raises."""
    try:
        body = str(text or "")
        shown = {os.path.basename(m.group(2).split("?", 1)[0]) for m in _DOWNLOAD_LINK_RE.finditer(body)}
        out: List[str] = []
        for names, line in _owned_look_rows(tools_run_this_turn):
            if not any(n in shown for n in names):
                continue
            # already carried = the exact line as a line of its own (a retry, the census re-read)
            if line in out or _owned_line_re(line).search(body):
                continue
            out.append(line)
        return "".join("\n\n" + ln for ln in out)
    except Exception:  # noqa: BLE001
        return ""


#: §4MG: the image tool's record of the photos a render was built from
#: (`subjects`) — "REFERENCE PHOTO: <file> — [left to right: ]<A> (<a.jpg>), …. THIS WAS A NEW SCENE"
_SUBJECT_REFERENCE_RE = re.compile(r"^REFERENCE PHOTO: (\S+) — (?:left to right: )?(.+?)\. THIS WAS A NEW SCENE",
                                   re.MULTILINE)
#: §4PB: a plain edit's record of the picture it started from — "EDITED FROM: <file>"
_EDIT_REFERENCE_RE = re.compile(r"^EDITED FROM: (\S+)\s*$", re.MULTILINE)


def pivot_steer_message(pivot_num: int, failures: int, last_error, tool_names, recovery_hint: str = "",
                        prev_error: str = "") -> str:
    """§4RI: the SYSTEM 3 PIVOT steer the model gets after repeated failures —
    in the conversation, so the planner is the main model with the full
    context (it used to be two side calls that displaced the KV slot, see the
    trigger site). §4PC: the tool list is spelled out so no invented tool is
    proposed; a dead tool or service is not retried."""
    names = sorted({str(n) for n in (tool_names or []) if n})
    err = " ".join(str(last_error or "").split())[:600]
    parts = [f"SYSTEM 3 PIVOT #{int(pivot_num)}: {int(failures)} tool calls in a row have failed"
             + (f" — the last: {err}" if err else "") + ". Stop repeating that approach."]
    if int(pivot_num) >= 2 and str(prev_error or "").strip():
        parts.append("The approach you took after the first pivot failed too"
                     f" ({' '.join(str(prev_error).split())[:400]}); choose something different from both.")
    parts.append("Before your next tool call, in your reasoning lay out three DIFFERENT ways forward — "
                 "A: the most standard, direct method; B: a defensive, edge-case-aware method; "
                 "C: a creative or native-tool-heavy method — using ONLY these tools: "
                 + (", ".join(names) if names else "(none listed — steps that need no tool)")
                 + ". Never invent a tool; a tool or service that is unavailable is not retried. "
                 "Pick the one with the best chance of success and the lowest risk of looping, say which "
                 "in one sentence, then ACT on it now.")
    if str(recovery_hint or "").strip():
        parts.append(str(recovery_hint).strip())
    return "\n\n".join(parts)


class _UrlProvenance:
    """§4PC: which addresses THIS request was GIVEN (the user's text, every
    tool result — search results, page text, the LINKS block) and on which
    hosts a COMPOSED address already came back 404. The brake refuses the
    NEXT composed address on such a host; a given one always passes."""
    _URL_RE = re.compile(r"https?://[^\s<>\"'\]\)]+", re.IGNORECASE)

    def __init__(self):
        self.given: set = set()
        self.hosts_404: set = set()

    @staticmethod
    def norm(u: str) -> str:
        u = str(u or "").strip().rstrip(".,;:)")
        u = u.split("#", 1)[0]
        return u[:-1] if u.endswith("/") and u.count("/") > 3 else u

    @staticmethod
    def host(u: str) -> str:
        try:
            from urllib.parse import urlparse
            return (urlparse(str(u)).hostname or "").lower().lstrip("www.")
        except Exception:  # noqa: BLE001
            return ""

    def note_text(self, text) -> None:
        for m in self._URL_RE.findall(str(text or "")):
            n = self.norm(m)
            if n:
                self.given.add(n)
                self.given.add(n + "/")

    def is_given(self, url) -> bool:
        n = self.norm(url)
        return n in self.given or (n + "/") in self.given

    @staticmethod
    def _urls_of(args: dict):
        out = []
        if isinstance(args, dict):
            if args.get("url"):
                out.append(str(args["url"]))
            for a in (args.get("actions") or []) if isinstance(args.get("actions"), list) else []:
                if isinstance(a, dict) and a.get("action") == "goto" and a.get("url"):
                    out.append(str(a["url"]))
        return out

    def note_failure(self, args: dict, result_text) -> None:
        """A browser result for a COMPOSED address that was a 404 marks the host."""
        if "HTTP 404" not in str(result_text or "") and "HTTP 410" not in str(result_text or ""):
            return
        for u in self._urls_of(args):
            if not self.is_given(u):
                h = self.host(u)
                if h:
                    self.hosts_404.add(h)

    def refusal(self, cname: str, args: dict):
        if cname != "browser" or not isinstance(args, dict):
            return None
        from ..tools.browser import _INTERACT_ONLY_ACTIONS     # §4SH: these run AS interact
        _op = str(args.get("operation") or "")
        if _op not in ("navigate", "extract_text", "screenshot", "click", "interact") and _op not in _INTERACT_ONLY_ACTIONS:
            return None
        for u in self._urls_of(args):
            h = self.host(u)
            if h and h in self.hosts_404 and not self.is_given(u):
                return (f"SYSTEM: {u} is a COMPOSED address on {h}, where a composed address already "
                        "came back 404 this request. Addresses are not guessed: open a URL that appeared "
                        "in your search results or in a page's LINKS block, or run "
                        f"web_search(query='site:{h} <what you are looking for>') to get the real one. "
                        "Nothing was fetched.")
        return None


def _turn_edit_reference(tools_run_this_turn):
    """The file the LAST image generated this request was EDITED from, else
    None — the visual check then sees before AND after instead of judging
    the result cold (§4PB)."""
    last = None
    for t in (tools_run_this_turn or []):
        try:
            if not isinstance(t, dict) or t.get("_synthetic"):
                continue
            body = str(t.get("content") or "")
            if not body.lstrip().startswith("SUCCESS: Image generated"):
                continue
            m = _EDIT_REFERENCE_RE.search(body)
            last = m.group(1).strip() if m else None
        except Exception:  # noqa: BLE001
            continue
    return last


def _turn_subject_reference(tools_run_this_turn):
    """(reference file, "A, B") for the LAST image generated this request
    when it was built from `subjects` photos, else None — the visual check
    then compares the picture with those photos (§4MG)."""
    last = None
    for t in (tools_run_this_turn or []):
        try:
            if not isinstance(t, dict) or t.get("_synthetic"):
                continue
            body = str(t.get("content") or "")
            if not body.lstrip().startswith("SUCCESS: Image generated"):
                continue
            m = _SUBJECT_REFERENCE_RE.search(body)
            last = None
            if m:
                names = re.sub(r"\s*\([^()]*\)", "", m.group(2)).strip()
                last = (m.group(1).strip(), names)
        except Exception:  # noqa: BLE001
            continue
    return last


_VISION_OK_RESULT_RE = re.compile(r"^\s*(?:VISION ANALYSIS RESULT|UI VERIFICATION RESULT)")


def _turn_looked_images(tools_run_this_turn) -> set:
    """§4QP (r1 M2): basenames of the pictures this request generated whose
    result carries the look head — the collage check's scene (§4QJ) or the
    render look — so the blind second-render guard does not tell the model
    "you have not seen it" over a result that says the vision model did."""
    from .receipt_marks import IMAGE_SEEN_HEAD
    out: set = set()
    for t in (tools_run_this_turn or []):
        try:
            if not isinstance(t, dict) or t.get("_synthetic"):
                continue
            body = str(t.get("content") or "")
            if not body.lstrip().startswith("SUCCESS: Image generated") or IMAGE_SEEN_HEAD not in body:
                continue
            for m in _GENERATED_IMAGE_LINE_RE.finditer(body):
                out.add(os.path.basename(m.group(1).strip()))
        except Exception:  # noqa: BLE001
            continue
    return out


def _images_inspected_this_turn(messages) -> set:
    """Basenames the model passed to `vision_analysis` this request AND
    got an answer for: the call is read off the assistant rows' tool_calls
    (where the arguments live) and counts only when a `tool` row with the
    same `tool_call_id` carries a vision RESULT — a call the node answered
    empty (`vision_thinking_cap` / `vision_empty_result`) is not a look
    (R2 review: today's own failure mode would have unlocked the guard)."""
    answered: set = set()
    for m in (messages or []):
        if isinstance(m, dict) and m.get("role") == "tool" and m.get("tool_call_id"):
            if _VISION_OK_RESULT_RE.search(str(m.get("content") or "")):
                answered.add(str(m.get("tool_call_id")))
    seen: set = set()
    for m in (messages or []):
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        for tc in (m.get("tool_calls") or []):
            try:
                if str(tc.get("id") or "") not in answered:
                    continue
                fn = tc.get("function") or {}
                if not re.sub(r"[^a-z]", "", str(fn.get("name") or "").lower()).startswith("vision"):
                    continue                     # vision_analysis and its aliases (R6)
                args = fn.get("arguments")
                if isinstance(args, str):
                    args = json.loads(args)
                if not isinstance(args, dict):
                    continue
                for key in ("target", "path", "image", "file", "image_path", "url"):
                    v = args.get(key)
                    if isinstance(v, str) and v.strip():
                        seen.add(os.path.basename(v.strip()))
            except Exception:  # noqa: BLE001
                continue
    return seen


#: §4QG: request fecd88b3 — the block said "present it NOW … or inspect it
#: first" and never that the call did NOT run: the model believed the blocked
#: call had produced a second image, hunted for its file, then presented the
#: FIRST picture as "the requested interaction". The refusal leads with the fact.
_BLIND_REGEN_NOT_RUN = ("SYSTEM BLOCK — BLOCKED: this image_generation call did NOT run; "
                        "nothing new was generated. ")


def _blind_regeneration_block(fname, tools_run_this_turn, messages, user_text,
                              *, repair_active: bool = False, batch_images: int = 0) -> Optional[str]:
    """The SYSTEM BLOCK for a second `image_generation` this request whose
    earlier output was not inspected by an ANSWERED `vision_analysis` call,
    else None. No reading of the user's words (R4 review: the multi-image
    ask regex misclassified a third of realistic asks in two languages — a
    lexical proxy); a user who wants several images pays one fast caption
    between them. A verifier repair re-entry may regenerate (its own pixel
    check was the inspection), and a second image in the SAME batch is
    blind by construction."""
    if str(fname or "") != "image_generation":
        return None
    prior = _turn_generated_images(tools_run_this_turn)
    if batch_images > 0:
        # a second image in the SAME batch is blind, repair or not (R6)
        return (_BLIND_REGEN_NOT_RUN
                + "One image per batch: present or inspect the first one before generating "
                "another; each generation occupies the image node for minutes.")
    # §4QP r2 M2 / r3 M1+m3: the tool's own hold ("Do NOT render again" — the
    # collage ladder spent its attempts, had no time for another, or could not
    # render one) is the USER's call: neither a looked-at result nor a verifier
    # repair re-entry unlocks that re-roll. The hold is read from the ladder's
    # machine-readable MARK on a line of its own BEFORE the markdown line —
    # never from the scene sentence (it follows the markdown line and is the
    # vision model's words) and never from a filename (`_plain` strips brackets).
    from .receipt_marks import NO_RERENDER_MARK
    for t in reversed(tools_run_this_turn or []):
        if not isinstance(t, dict) or t.get("_synthetic"):
            continue
        body = str(t.get("content") or "")
        if not body.lstrip().startswith("SUCCESS: Image generated"):
            continue
        head_part = re.split(r"^!\[generated image\]\(", body, 1, flags=re.M)[0]   # r4 m1: the markdown LINE, not a name quoting it
        _hm = re.search(r"^" + re.escape(NO_RERENDER_MARK) + r" ([^\]\n]{1,80})\]$", head_part, re.M)
        if _hm:
            names = [os.path.basename(m.group(1).strip()) for m in _GENERATED_IMAGE_LINE_RE.finditer(body)]
            return (_BLIND_REGEN_NOT_RUN
                    + "The earlier call's result says not to render again on your own"
                    + (f" ({names[-1]} is a two-panel picture: {_hm.group(1)})" if names else f" ({_hm.group(1)})")
                    + ": present that picture with its markdown line, say plainly it is a two-panel picture, "
                    "and ask the user whether they want another attempt. Each generation occupies the image node for minutes.")
        break                                            # only the NEWEST render's note counts
    if repair_active:
        return None
    if not prior:
        return None
    inspected = _images_inspected_this_turn(messages) | _turn_looked_images(tools_run_this_turn)
    # §4QP r2 m1: the guard is about the NEWEST picture — when that one was
    # looked at (or inspected), an older un-looked one is not a reason to block
    # and must not be named as "the newest image"
    newest = os.path.basename(prior[-1])
    if newest in inspected:
        return None
    first = newest
    return (
        _BLIND_REGEN_NOT_RUN
        + f"The newest image of this request is {first}, from an EARLIER call; this call "
        "made no file — do not look for one. You have not looked at it. Either present it NOW "
        f"with the markdown line ![generated image](/api/download/{first}) and one line on "
        "what THAT earlier call asked for (its own prompt, not this blocked one's; not what "
        "it shows — you have not seen it), or inspect it first "
        f"— vision_analysis(action='describe_picture', "
        f"target='{first}') — and only then decide whether a second take is needed. "
        "Each generation occupies the image node for minutes."
    )


_MISSING_SUBJECT_HEAD = "ERROR: no usable photo found for "
_MISSING_SUBJECT_TAIL = "\n[subjects: "


#: §4QG: a word of the user's own text, any script (a name's token)
_USER_NAME_TOKEN_RE = re.compile(r"[^\W\d_]{3,}")


def _request_with_added(first, req_id) -> str:
    """§4RZ step 4: the request text plus what the user added mid-turn (by
    request id — the recorders run after the turn's ContextVars reset). The
    request alone when nothing was added."""
    try:
        from ..utils.provenance import added_user_messages
        added = added_user_messages(str(req_id or ""))
    except Exception:  # noqa: BLE001
        added = []
    return "\n".join([str(first or "")] + list(added)) if added else first


def _users_own_texts(messages, last_user_content=None, limit: int = 4) -> List[str]:
    """The user's OWN recent messages (newest first): the current one, then
    earlier user rows — never a row the loop appended (SYSTEM ALERT …) nor
    another Slack member's line the bot labelled (§4KY)."""
    from ..utils.logging import FOREIGN_MESSAGE_LABELS
    out = [str(last_user_content)] if last_user_content else []
    for m in reversed(list(messages or [])):
        if len(out) >= limit:
            break
        if not isinstance(m, dict) or m.get("role") != "user":
            continue
        t = _msg_text(m)
        if m.get("_queued"):
            continue                         # §4RZ s4-r4: feeds a photo search's name — the request's words only
        if not t.strip() or _LOOP_USER_ROW_RE.match(t) or t in out:
            continue
        if any(lbl in t for lbl in FOREIGN_MESSAGE_LABELS):
            continue
        out.append(t)
    return out


def _subject_spelling_fix(name, user_texts) -> Optional[str]:
    """§4QG (7d6617ad): the user wrote "Konstantopoulou", the model passed
    "Zoe Konstantinou", the photo search found nothing, and the reply said no
    photo exists for "Konstantopoulou". When the name's LAST token (the
    surname) is not in the user's own words but a close variant is — the
    same first three letters, similarity ≥ 0.7 — the name with the user's
    spelling of that token; else None. Narrow on purpose: one token, the
    closest variant, the user's exact letters."""
    from difflib import SequenceMatcher
    from ..tools.subject_photos import slug
    toks = _USER_NAME_TOKEN_RE.findall(str(name or ""))
    if not toks:
        return None
    sur = toks[-1]
    s_sur = slug(sur)
    if len(s_sur) < 4:
        return None
    words = []
    for t in (user_texts or []):
        for w in _USER_NAME_TOKEN_RE.findall(str(t or "")):
            if w not in words:
                words.append(w)
    if any(slug(w) == s_sur for w in words):
        return None                                  # the user's own spelling
    best, best_r = None, 0.0
    for w in words:
        s_w = slug(w)
        if len(s_w) < 4 or s_w[:3] != s_sur[:3]:
            continue
        if s_w.startswith(s_sur) or s_sur.startswith(s_w):
            continue                                 # an inflection ("Bidens"), not a respelling
        r = SequenceMatcher(None, s_sur, s_w).ratio()
        if r >= 0.7 and r > best_r:
            best, best_r = w, r
    if best is None:
        return None
    i = str(name).rfind(sur)
    return str(name)[:i] + best + str(name)[i + len(sur):]


#: the subjects list in our own spelling hint (`_missing_subject_spelling_hint`)
_SPELLING_HINT_SUBJECTS_RE = re.compile(r"SYSTEM NOTE — spelling: [^\n]*? subjects=(\[[^\n]*?\]) — and only")


def _missing_subject_spelling_hint(result_text, user_texts) -> str:
    """§4QG: the tool's no-photo result with ONE corrective line inserted
    before its machine-readable `[subjects: …]` tail (the missing-subject
    block parses that tail as the row's LAST line): retry once with the
    user's spelling. Unchanged when no missing name has a close variant in
    the user's own words. Never raises."""
    try:
        body = str(result_text or "")
        if not body.lstrip().startswith(_MISSING_SUBJECT_HEAD):
            return result_text
        k = body.rfind(_MISSING_SUBJECT_TAIL)
        if k < 0:
            return result_text
        rec = json.loads(body[k + len(_MISSING_SUBJECT_TAIL):].rstrip().rstrip("]"))
        found = [str(n) for n in rec.get("found") or []]
        fixes = [(str(m), _subject_spelling_fix(m, user_texts)) for m in rec.get("missing") or []]
        fixes = [(m, f) for m, f in fixes if f]
        if not fixes:
            return result_text
        # §4QG-b: the suggested list holds only what a retry may pass — the
        # found names and the FIXED ones. Repeating an unfixed name unchanged
        # made following the hint exactly hit "the same name will return
        # nothing again"; dropping it silently is the §4MG stand-in render.
        fixed = {m for m, _ in fixes}
        unfixed = [str(m) for m in rec.get("missing") or [] if str(m) not in fixed]
        subj = found + [f for _, f in fixes]
        said = ("; ".join(f"{m!r} but the user wrote {f.split()[-1]!r}" for m, f in fixes))
        if not unfixed:
            line = ("\n\nSYSTEM NOTE — spelling: you passed " + said
                    + ". This is NOT yet a missing photo. Retry image_generation ONCE with the user's "
                    + "spelling — subjects=" + json.dumps(subj, ensure_ascii=False)
                    + " — and only if that also finds no photo, ask the user.")
        else:
            who = ", ".join(repr(m) for m in unfixed)
            line = ("\n\nSYSTEM NOTE — spelling: you passed " + said
                    + f". No close spelling of {who} is in the user's words, and a picture "
                    + f"without them is not allowed: do NOT retry now. Ask the user NOW about {who} "
                    + "(upload a photo, correct the spelling, or confirm a generic stand-in), and "
                    + "mention the user's spelling of the others — subjects="
                    + json.dumps(subj, ensure_ascii=False)
                    + " — and only render after the user answers.")
        # plain text: the dispatch wraps `safe_res` in its ToolOutcome after this
        return body[:k] + line + body[k:]
    except Exception:  # noqa: BLE001
        return result_text


def _missing_subject_block(fname, raw_args, tools_run_this_turn) -> Optional[str]:
    """The SYSTEM BLOCK for an `image_generation` call that drops — or
    replaces — a subject the tool found no photo for EARLIER IN THIS
    REQUEST, else None (§4MG, operator 2026-10-07: "stop and ask"). Live
    probe-4mg-missing: told "only if they agree to a generic stand-in", the
    agent re-rendered without the subject in the same request.

    Reads the tool's machine-readable `[subjects: {"missing", "found"}]`
    tail, only on a row that IS that error (review: a page quoting the
    error text armed the block, and parsing names out of the prose broke on
    a name containing "), " or "; "). A retry passes only when every found
    subject is kept and every missing one has a close respelling (review: a
    count-only rule let `["Alexis Tsipras", "a man"]` through). The user's
    answer is a new request, which this never blocks."""
    if str(fname or "") != "image_generation":
        return None
    missing, found = [], []
    suggested = []                   # §4QG: the user's spelling, from our own hint line
    no_photo_rows = 0
    for t in (tools_run_this_turn or []):
        if not isinstance(t, dict) or t.get("_synthetic"):
            continue
        body = str(t.get("content") or "").lstrip()
        if not body.startswith(_MISSING_SUBJECT_HEAD):
            continue
        no_photo_rows += 1
        k = body.rfind(_MISSING_SUBJECT_TAIL)
        if k < 0:
            continue
        try:
            rec = json.loads(body[k + len(_MISSING_SUBJECT_TAIL):].rstrip().rstrip("]"))
        except Exception:  # noqa: BLE001
            continue
        missing += [str(n) for n in rec.get("missing") or [] if str(n) not in missing]
        found += [str(n) for n in rec.get("found") or [] if str(n) not in found]
        _hm = _SPELLING_HINT_SUBJECTS_RE.search(body[:k])
        if _hm:
            try:
                suggested += [str(n) for n in json.loads(_hm.group(1))]
            except Exception:  # noqa: BLE001
                pass
    if not missing:
        return None
    try:
        args = json.loads(raw_args) if isinstance(raw_args, str) else dict(raw_args or {})
    except Exception:  # noqa: BLE001
        args = {}
    from difflib import SequenceMatcher
    from ..tools.subject_photos import normalise_subjects, slug, subjects_arg
    # §4QG: a singular `subject` beside a prompt IS the subjects list (the
    # tool's rule, shared) — read as "no subjects", it dropped every subject
    subj = normalise_subjects(subjects_arg(args) if isinstance(args, dict) else None)
    new = {slug(s): s for s in subj}
    kept = all(slug(f) in new for f in found)
    rest = [slug(s) for s in subj if slug(s) not in {slug(f) for f in found}]

    # §4QG-b: each missing name is paired with ITS OWN suggestion — the
    # hint's fix re-derived from the hint's suggested names (they hold the
    # user's spelling, so `_subject_spelling_fix` finds the same word). One
    # suggestion anywhere in the retry used to count every missing name as
    # respelled, and a retry dropping a second, unfixed subject rendered.
    _found_slugs = {slug(f) for f in found}
    _sugg_words = [n for n in suggested if slug(n) not in _found_slugs]

    def _respelled(name):
        # (no one-to-one consumption: the rows of a respelling chain —
        # "Quintavius" then "Quintavus" — are ONE person, answered by one name)
        fix = _subject_spelling_fix(name, _sugg_words) if _sugg_words else None
        if fix and slug(fix) in rest:
            return True
        return any(SequenceMatcher(None, slug(name), r).ratio() >= 0.75 for r in rest)
    who = ", ".join(missing)
    if any(slug(m) in new for m in missing):
        # r2 review: the SAME name again is not a respelling — the search
        # returns the same nothing, and since the no-photo stop draws no
        # strike, nothing else would end the loop
        return (f"SYSTEM BLOCK — the photo search for {who} already returned nothing in this "
                "request; the same name will return nothing again. Reply to the user NOW: ask "
                "them to upload a photo or to confirm a generic stand-in. (Only a CORRECTED "
                "spelling may be tried, once.)")
    unhandled = [m for m in missing if not _respelled(m)]
    if kept and not unhandled:
        if no_photo_rows >= 2:
            # §4MR: "a corrected spelling, ONCE" was only text — each failed
            # respelling is a fresh no-photo row with no strike, and a probe
            # ran 6 photo searches on variants of one name
            return (f"SYSTEM BLOCK — a corrected spelling was already tried and also found no photo "
                    f"of {who}. Do NOT try another spelling. Reply to the user NOW: ask them to "
                    "upload a photo or to confirm a generic stand-in.")
        return None
    # §4QG-b: name the subjects still unanswered (all of them when a found
    # one was dropped)
    who = ", ".join(unhandled) if kept and unhandled else who
    return (f"SYSTEM BLOCK — ask the user first: no photo of {who} was found earlier in this "
            "request, and the user has not agreed to a stand-in. Do NOT render a picture without "
            f"{who} or with someone else in their place. Reply to the user NOW: say that no "
            f"photo of {who} could be found, and ask them to upload one or to confirm that a "
            "generic stand-in is fine.")


def _clarify_first_block(fname, user_text, messages, costly_record: bool):
    """The SYSTEM BLOCK for a costly tool call that a one-token follow-up
    cannot justify, else None."""
    if str(fname or "") not in COSTLY_TOOLS:
        return None
    if not _is_low_information_message(user_text):
        return None
    if (_is_ack(user_text) and _previous_turn_asked_a_question(messages, user_text)
            and not _is_our_clarify_question(_last_assistant_text(messages, user_text))):
        return None                      # "ok" / "yes" answers OUR question
    if _is_go_ahead(user_text):
        return None                      # §4NT: "do it" is an instruction
    if not _previous_turn_was_costly(messages, costly_record, user_text):
        return None
    return (
        f"SYSTEM BLOCK — clarify first: the user's message ({str(user_text or '')[:40]!r}) "
        f"is a single token or not intelligible, and an earlier turn of this "
        f"conversation already ran '{fname}', which occupies the image node for minutes. Do NOT run "
        f"'{fname}' on a guess. Reply to the user in ONE short sentence asking "
        f"what they would like (a change to the last image, another one, or "
        f"something else). Nothing was generated."
    )


def _dropped_fs_calls(tool_calls) -> list:
    """[(op, path)] for every dropped `file_system` call whose op MUTATES;
    `path` is the file the call would have CREATED or CHANGED (the
    destination for copy/rename/move). Never raises: a malformed argument
    blob costs the note its detail."""
    out = []
    for tc in (tool_calls or []):
        try:
            fn = (tc or {}).get("function") or {}
            if fn.get("name") != "file_system":
                continue
            args = fn.get("arguments")
            if isinstance(args, str):
                args = json.loads(args or "{}")
            if not isinstance(args, dict):
                continue
            op = str(args.get("operation") or "").strip().lower()
            if op not in _DROP_NOTE_MUTATING_FS_OPS:
                continue
            if op in _DROP_NOTE_DEST_OPS:
                path = (args.get("destination") or args.get("new_name")
                        or args.get("target") or args.get("new_path"))
            else:
                # the dispatcher's own alias chain (path/filename/file)
                path = (args.get("path") or args.get("filename")
                        or args.get("file") or args.get("file_path"))
            out.append((op, path.strip() if isinstance(path, str) else ""))
        except Exception:  # noqa: BLE001
            continue
    return out


#: §4OE-1b: the `file_system` operations that can BE the report
_REPORT_WRITE_OPS = frozenset({"write", "append"})


def _report_write_allowed(tool_calls, ctx, *, turn, max_turns) -> bool:
    """§4OE-1b: on a BREAKER-forced report turn a reply that is nothing but
    `file_system` write/append calls IS the report (the tight §4OE probe wrote
    its 13 KB report as a file on the tools-off turn; the drop discarded it
    and the fallback shipped at 457 s). Once per request, and only while a
    further turn exists to answer in — the call runs through the ordinary
    dispatcher, every guard intact."""
    try:
        if getattr(ctx, "_breaker_forced_final", False) is not True:
            return False
        if getattr(ctx, "_report_write_used", False):
            return False
        if int(turn) >= int(max_turns) - 1:
            return False
        return bool(_report_write_calls(tool_calls))
    except Exception:  # noqa: BLE001
        return False


def _report_write_calls(tool_calls) -> list:
    """[(op, path)] when EVERY call is a `file_system` write/append with a
    path; [] otherwise (one search beside the write makes it work, not the
    report). `append` is not in the dropped-note mutating set, so this
    reads the calls itself."""
    out = []
    for tc in (tool_calls or []):
        fn = (tc or {}).get("function") or {}
        if fn.get("name") != "file_system":
            return []
        args = fn.get("arguments")
        if isinstance(args, str):
            try:
                args = json.loads(args or "{}")
            except Exception:  # noqa: BLE001
                return []
        if not isinstance(args, dict):
            return []
        op = str(args.get("operation") or "").strip().lower()
        path = (args.get("path") or args.get("filename") or args.get("file") or args.get("file_path"))
        if op not in _REPORT_WRITE_OPS or not isinstance(path, str) or not path.strip():
            return []
        out.append((op, path.strip()))
    return out


def _report_writes_landed(paths, tools_run) -> list:
    """The subset of ``paths`` the request's file ledger shows as produced
    and still in place — a refused, blocked or failed write is not a
    written report."""
    try:
        landed = {_fs_norm(p) for p in _files_mutated_this_turn(tools_run)}
    except Exception:  # noqa: BLE001
        return []
    return [p for p in (paths or []) if _fs_norm(p) in landed]


def report_written_alert(paths, pending_request="") -> str:
    """§4OE-1b: the turn after the report was written as a file — answer in
    text, with the file's link, instead of the no-answer retry."""
    names = [str(p) for p in (paths or []) if str(p or "").strip()][:4]
    shown = ", ".join(f"`{p}`" for p in names) or "the report file"
    links = ", ".join(f"/api/download/{p.lstrip('/')}" for p in names)
    return ("SYSTEM ALERT (report written): your report turn wrote " + shown
            + " and that write RAN — the file exists now. Tools are OFF for this turn. "
            + _ALERT_PROVENANCE + _which_request_line(pending_request)
            + " Write your FINAL reply now as text: a short summary of what the file "
              "holds and where the work stands"
            + (f", and its download link ({links})" if links else "")
            + ". Do NOT rewrite the file; do NOT call tools.")


def _dropped_entries(tool_calls, tools_seen: int) -> list:
    """What site 2 needs to reconcile a drop LATER: `(name, op, path,
    tools_seen)` per dropped mutating call, where `tools_seen` is how many
    tool results the turn had at the moment of the drop."""
    out = []
    for tc in (tool_calls or []):
        try:
            fn = (tc or {}).get("function") or {}
            name = str(fn.get("name") or "?")
            if name != "file_system":
                out.append((name, "", "", tools_seen))
                continue
            for op, p in _dropped_fs_calls([tc]):
                out.append((name, op, p, tools_seen))
        except Exception:  # noqa: BLE001
            continue
    return out


def _confirmed_paths_any_op(content: str, kind: str = "any") -> set:
    """Keys of every path a `file_system` SUCCESS line names as PRODUCED /
    COPIED-MOVED TO (``kind="produced"``) or DELETED / MOVED AWAY
    (``kind="deleted"``) — the reconcile signal for a dropped call. r5:
    kind-aware, because a dropped WRITE was being retired by a later
    `Deleted` of the same name (the file is GONE — the note must stand)."""
    raw = str(content or "").lstrip()
    if raw.startswith("[FAILURE BANNER]"):
        raw = raw.split("\n", 1)[1] if "\n" in raw else ""
    head = raw.split("\n", 1)[0][:4000].strip()
    produced, deleted = set(), set()
    produced |= {_fs_norm(p) for p in _written_paths_from_confirmation(raw)}
    m = _FS_DEST_RE.match(head)
    if m:
        produced.add(_fs_norm(m.group(1)))
    m = _FS_MOVED_RE.match(head)
    if m:
        produced.add(_fs_norm(m.group(2)))
        deleted.add(_fs_norm(m.group(1)))
    m = _FS_RETIRE_RE.match(head)
    if m:
        deleted.add(_fs_norm(m.group(1)))
    if kind == "produced":
        keys = produced
    elif kind == "deleted":
        keys = deleted
    else:
        keys = produced | deleted
    return {k for k in keys if k}


def _still_pending_drops(entries, tools_run) -> list:
    """The dropped entries NOT followed by a later `file_system` SUCCESS.

    A write dropped on a forced-final miss is routinely RE-DONE by the
    verifier repair re-entry; the list was never cleared, so the shipped
    reply still said "that final pending action was not applied" over a
    file the re-entry had just written (§4KC r3). A non-file_system tool
    (execute, manage_services…) has no such signal and stays pending."""
    runs = list(tools_run or [])
    out = []
    for e in entries or []:
        try:
            name, _op, path, seen = e
        except (TypeError, ValueError):
            out.append(e)
            continue
        if name == "file_system":
            # The SAME file, by the ledger's own key — a later SUCCESS on an
            # unrelated file must not retire this one. Any op's confirmation
            # counts (produced, copied/moved to, deleted); an entry with no
            # path can only be retired by nothing.
            key = _fs_norm(path) if path else ""
            later = [t for t in runs[int(seen or 0):]
                     if isinstance(t, dict) and str(t.get("name", "")) == "file_system"]
            _kind = "deleted" if _op == "delete" else "produced"
            if key and any(key in _confirmed_paths_any_op(t.get("content", ""), _kind)
                           for t in later):
                continue
        out.append(e)
    return out


def _dropped_write_paths(tool_calls) -> list:
    """Paths the DROPPED mutating `file_system` calls were about to touch.

    Read from the call's own arguments, so the note names the exact file
    rather than pattern-matching the prose that claims it.
    """
    return [p for _op, p in _dropped_fs_calls(tool_calls) if p]


def _dropped_mutating_names(tool_calls) -> list:
    """Tool names of the dropped calls that would have CHANGED something:
    every non-file_system tool by name (the note's own allow-list decides),
    and `file_system` only when its operation mutates."""
    out = []
    for tc in (tool_calls or []):
        try:
            fn = (tc or {}).get("function") or {}
            name = str(fn.get("name") or "?")
            if name != "file_system":
                out.append(name)
                continue
            if _dropped_fs_calls([tc]):
                out.append(name)
        except Exception:  # noqa: BLE001
            continue
    return out


def _dropped_write_admitted(reply: str) -> bool:
    """Does this reply carry its OWN note saying a file write was eaten?

    Absence-grade evidence, and the only prose that is: everywhere else a
    claimed-but-missing file may simply predate the turn, which is why prose
    claims ride the emptiness-only arm. Here the turn states that its
    `file_system` call never ran, so a file it also claims to have produced
    is missing for a reason this turn is responsible for.
    """
    i = (reply or "").find(_DROPPED_NOTE_HEAD)
    if i < 0:
        return False
    return "file_system" in reply[i:i + 400]


#: The dropped-mutation note's head (its one home is reply_smoothing, whose
